struct SystemActionPreset: Identifiable, Hashable {
    let id: String
    let titleDE: String
    let titleEN: String
    let subtitleDE: String
    let subtitleEN: String
    let symbol: String

    var requiresAccessibility: Bool {
        [
            "mediaPrevious", "mediaPlayPause", "mediaNext",
            "brightnessUp", "brightnessDown", "lockScreen",
            "forceQuit", "spotlight", "logout",
            "windowLeftHalf", "windowRightHalf", "windowTopLeft", "windowTopRight",
            "windowBottomLeft", "windowBottomRight", "windowMaximize", "windowCenter", "windowRestore"
        ].contains(id)
    }

    var requiresScreenRecording: Bool { id == "ocrCapture" }

    var isWindowManagement: Bool {
        [
            "windowLeftHalf", "windowRightHalf", "windowTopLeft", "windowTopRight",
            "windowBottomLeft", "windowBottomRight", "windowMaximize", "windowCenter", "windowRestore"
        ].contains(id)
    }

    func title(language: AppLanguage?) -> String { qoText(titleDE, titleEN, language: language) }
    func subtitle(language: AppLanguage?) -> String { qoText(subtitleDE, subtitleEN, language: language) }

    func orbitItem(language: AppLanguage?) -> OrbitItem {
        OrbitItem(
            title: title(language: language),
            symbol: symbol,
            type: isWindowManagement ? .windowManagement : (id.hasPrefix("timer") ? .timer : .systemAction),
            target: id,
            enabled: true
        )
    }

    static let all: [SystemActionPreset] = [
        .init(id: "emojiPalette", titleDE: "Emoji-Palette", titleEN: "Emoji palette", subtitleDE: "Komplette macOS Emoji- und Symbolauswahl öffnen", subtitleEN: "Open the complete macOS emoji and symbol picker", symbol: "face.smiling"),
        .init(id: "copyTimestamp", titleDE: "Zeitstempel", titleEN: "Timestamp", subtitleDE: "Datum und Uhrzeit als ISO-Text kopieren oder herausziehen", subtitleEN: "Copy or drag the current date and time as ISO text", symbol: "calendar.badge.clock"),
