    private var selectedEmoji: String? {
        guard let selectedTarget, selectedTarget.hasPrefix("emojiInsert:") else { return nil }
        let value = String(selectedTarget.dropFirst("emojiInsert:".count))
        return value.isEmpty ? nil : value
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 18) {
            VStack(alignment: .leading, spacing: 4) {
                Text("Emoji")
                    .font(.title3.weight(.semibold))
                Text(qoText("Ein Emoji auswählen und direkt in die Zwischenablage kopieren.", "Choose an emoji and copy it straight to the clipboard.", language: language))
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
            }

            HStack(spacing: 10) {
                Button {
                    onSelect(OrbitItem(title: qoText("Emoji-Palette", "Emoji palette", language: language), symbol: "face.smiling", type: .emoji, target: "emojiPalette", enabled: true))
                } label: {
                    Label(qoText("Komplette Palette", "Full palette", language: language), systemImage: "face.smiling")
                        .frame(maxWidth: .infinity)
                }
                .quickOrbitGlassButton(prominent: selectedTarget == "emojiPalette")

                HStack(spacing: 8) {
                    TextField("🙂", text: $customEmoji)
                        .textFieldStyle(.plain)
                        .font(.system(size: 22))
                        .frame(width: 54)
                        .multilineTextAlignment(.center)
                        .onSubmit { applyCustomEmoji() }

                    Button(qoText("Emoji übernehmen", "Use emoji", language: language)) {
                        applyCustomEmoji()
                    }
                    .quickOrbitGlassButton(prominent: selectedEmoji != nil)
                }
            }

            ScrollViewReader { proxy in
                HStack(spacing: 7) {
                    emojiCategoryArrow("chevron.left", direction: -1, proxy: proxy)

                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 7) {
                            ForEach(EmojiCategory.allCases) { category in
                                Button {
                                    selectedCategory = category
                                } label: {
                                    Label(category.title(language: language), systemImage: category.symbol)
                                        .font(.caption.weight(.semibold))
                                        .padding(.horizontal, 10)
                                        .frame(height: 32)
                                        .background(
                                            selectedCategory == category ? Color.primary.opacity(0.14) : Color.primary.opacity(0.045),
                                            in: Capsule()
                                        )
                                        .overlay {
                                            Capsule().stroke(Color.primary.opacity(selectedCategory == category ? 0.24 : 0.09), lineWidth: 0.8)
                                        }
                                }
                                .buttonStyle(.plain)
                                .id(category.id)
                                .quickOrbitPickerHover()
                            }
                        }
                    }

                    emojiCategoryArrow("chevron.right", direction: 1, proxy: proxy)
                }
            }

            LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 8), count: 8), spacing: 8) {
                ForEach(selectedCategory.emojis, id: \.self) { emoji in
                    Button {
                        customEmoji = emoji
                        copyEmoji(emoji)
                        onSelect(makeEmojiItem(emoji))
                    } label: {
                        Text(emoji)
                            .font(.system(size: 27))
                            .frame(maxWidth: .infinity)
                            .frame(height: 48)
                            .contentShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                    }
                    .buttonStyle(.plain)
                    .background {
                        if selectedEmoji == emoji {
                            RoundedRectangle(cornerRadius: 14, style: .continuous)
                                .fill(Color.accentColor.opacity(0.10))
                        }
                    }
                    .overlay(alignment: .topTrailing) {
                        if selectedEmoji == emoji {
                            Image(systemName: "doc.on.clipboard.fill")
                                .font(.system(size: 9, weight: .bold))
                                .foregroundStyle(Color.green)
                                .padding(6)
                        }
                    }
                    .quickOrbitGlass(cornerRadius: 14, interactive: true)
                    .quickOrbitGlassIdentity("emoji-\(emoji)", in: glassNamespace, matched: false)
                    .quickOrbitPickerHover()
                }
            }
        }
        .onAppear {
            if let selectedEmoji { customEmoji = selectedEmoji }
        }
    }

    private func applyCustomEmoji() {
        let trimmed = customEmoji.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let character = trimmed.first else {
            QuickOrbitNoticeCenter.shared.show(qoText("Bitte ein Emoji eingeben.", "Enter an emoji first.", language: language))
            return
        }
        let emoji = String(character)
        customEmoji = emoji
        copyEmoji(emoji)
        onSelect(makeEmojiItem(emoji))
    }

    private func copyEmoji(_ emoji: String) {
        if copyQuickOrbitText(emoji) {
            QuickOrbitNoticeCenter.shared.show(qoText("\(emoji) in die Zwischenablage kopiert", "\(emoji) copied to the clipboard", language: language))
        }
    }

    private func emojiCategoryArrow(_ symbol: String, direction: Int, proxy: ScrollViewProxy) -> some View {
        Button {
            let categories = EmojiCategory.allCases
            guard let index = categories.firstIndex(of: selectedCategory) else { return }
            let next = min(max(index + direction, 0), categories.count - 1)
            selectedCategory = categories[next]
            withAnimation(.easeOut(duration: 0.16)) {
                proxy.scrollTo(categories[next].id, anchor: .center)
            }
        } label: {
            Image(systemName: symbol)
                .font(.system(size: 11, weight: .bold))
                .frame(width: 28, height: 28)
                .background(Color.primary.opacity(0.07), in: Circle())
        }
        .buttonStyle(.plain)
    }

    private func makeEmojiItem(_ emoji: String) -> OrbitItem {
        OrbitItem(title: emoji, symbol: "face.smiling", type: .emoji, target: "emojiInsert:\(emoji)", enabled: true)
    }
}

struct SystemActionPicker: View {
    let language: AppLanguage?
    let selectedTarget: String?
    let onSelect: (OrbitItem) -> Void
    @Namespace private var glassNamespace

    private var groups: [(String, String, [SystemActionPreset])] {
        let available = SystemActionPreset.all.filter {
            $0.id != "emojiPalette"
                && $0.id != "chargingStatus"
                && $0.id != "batteryWarning"
                && $0.id != "smartSuggestion"
                && !$0.id.hasPrefix("timer")
                && !$0.isWindowManagement
        }
        let definitions: [(String, String, [String])] = [
            (qoText("Text & Werkzeuge", "Text & tools", language: language), qoText("Auswählen, umwandeln und sicher kopieren", "Select, transform, and copy securely", language: language), ["translateText", "ocrCapture", "clipboardHistory", "orbitDropBox", "colorSampler", "copyTimestamp", "calculator"]),
            (qoText("Planen", "Plan", language: language), qoText("Anzeigen oder direkt in Apple-Apps anlegen", "View or create directly in Apple apps", language: language), ["showAgenda", "newReminder", "newCalendarEvent"]),
            (qoText("Systemstatus", "System status", language: language), qoText("Messwerte werden nur im geöffneten Orbit live aktualisiert", "Readings update live only while Orbit is open", language: language), ["liveClock", "liveDate", "cpuStatus", "memoryStatus", "networkStatus", "storageStatus", "batteryStatus", "wifiStatus", "uptimeStatus", "thermalStatus", "activityMonitor"]),
            (qoText("Medien & Ton", "Media & sound", language: language), qoText("Musik und Lautstärke", "Music and volume", language: language), ["volumeStatus", "mediaPrevious", "mediaPlayPause", "mediaNext", "volumeDown", "volumeMute", "volumeUp"]),
            (qoText("System", "System", language: language), qoText("Bildschirm, Energie und Sicherheit", "Display, energy and security", language: language), ["focus", "lowPowerMode", "screenSaver", "brightnessUp", "brightnessDown", "lockScreen", "displaySleep", "logout", "forceQuit"]),
            (qoText("Einstellungen", "Settings", language: language), qoText("Direkt zum richtigen Bereich", "Jump to the right pane", language: language), ["wifiSettings", "bluetoothSettings", "notificationsSettings", "soundSettings", "displaySettings", "privacySettings"]),
            (qoText("Ordner", "Folders", language: language), qoText("Wichtige Finder-Ziele", "Important Finder destinations", language: language), ["downloads", "desktopFolder", "homeFolder", "trashFolder"])
        ]
        let presetsByID = Dictionary(uniqueKeysWithValues: available.map { ($0.id, $0) })
        return definitions.map { title, subtitle, ids in
            (title, subtitle, ids.compactMap { presetsByID[$0] })
        }.filter { !$0.2.isEmpty }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 18) {
            VStack(alignment: .leading, spacing: 4) {
                Text(qoText("Mac-Steuerung", "Mac controls", language: language))
                    .font(.title3.weight(.semibold))
                Text(qoText("Nützliche Systemfunktionen direkt als QuickOrbit-Kachel.", "Useful system features directly as QuickOrbit tiles.", language: language))
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
            }

            if let smart = SystemActionPreset.preset(for: "smartSuggestion") {
                VStack(alignment: .leading, spacing: 8) {
                    HStack(spacing: 6) {
                        Image(systemName: "sparkles")
                        Text(qoText("INTELLIGENT", "SMART", language: language))
                    }
                    .font(.caption2.weight(.bold))
                    .foregroundStyle(Color.accentColor)
                    .tracking(0.7)

                    presetButton(smart)
                }
            }

            if !AXIsProcessTrusted() {
                Button {
                    QuickOrbitAccessibilityGuide.openSystemAccess()
                } label: {
                    Label(
                        qoText("Orange Hand: Bedienungshilfe fehlt · Zum Aktivieren klicken", "Orange hand: Accessibility access is missing · Click to enable", language: language),
                        systemImage: "hand.raised.fill"
                    )
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(Color.orange)
                    .padding(.horizontal, 11)
                    .padding(.vertical, 8)
                    .background(Color.orange.opacity(0.10), in: RoundedRectangle(cornerRadius: 11, style: .continuous))
                }
                .buttonStyle(.plain)
                .help(QuickOrbitAccessibilityGuide.helpText(language: language))
            }

            ForEach(Array(groups.enumerated()), id: \.offset) { _, group in
                VStack(alignment: .leading, spacing: 10) {
                    VStack(alignment: .leading, spacing: 2) {
                        Text(group.0).font(.subheadline.weight(.bold))
                        Text(group.1).font(.caption2).foregroundStyle(.secondary)
                    }
                    LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 12), count: 3), spacing: 12) {
                        ForEach(group.2) { preset in presetButton(preset) }
                    }
                }
            }
        }
    }

    private func presetButton(_ preset: SystemActionPreset) -> some View {
        let tint = presetTint(preset.id)
        return Button {
            onSelect(preset.orbitItem(language: language))
        } label: {
            VStack(alignment: .leading, spacing: 9) {
                HStack {
                    Image(systemName: preset.symbol)
                        .font(.system(size: 19, weight: .semibold))
                        .foregroundStyle(selectedTarget == preset.id ? Color.accentColor : tint)
                        .frame(width: 38, height: 38)
                        .background(tint.opacity(0.10), in: RoundedRectangle(cornerRadius: 11, style: .continuous))
                    Spacer()
                    if selectedTarget == preset.id {
                        Image(systemName: "checkmark.circle.fill").foregroundStyle(Color.green)
                    }
                    if preset.requiresAccessibility && !AXIsProcessTrusted() {
                        Image(systemName: "hand.raised.fill")
                            .font(.system(size: 12, weight: .bold))
                            .foregroundStyle(Color.orange)
                            .help(QuickOrbitAccessibilityGuide.helpText(language: language))
                            .onTapGesture {
                                QuickOrbitAccessibilityGuide.openSystemAccess()
                            }
                    }
                    if preset.requiresScreenRecording && !CGPreflightScreenCaptureAccess() {
                        Image(systemName: "display.trianglebadge.exclamationmark")
                            .font(.system(size: 12, weight: .bold))
                            .foregroundStyle(Color.orange)
                            .help(qoText("macOS fragt beim ersten Verwenden nach Bildschirmaufnahme.", "macOS asks for Screen Recording the first time you use it.", language: language))
                    }
                }
                Text(preset.title(language: language))
                    .font(.subheadline.weight(.semibold))
                    .lineLimit(1)
                Text(preset.subtitle(language: language))
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .lineLimit(2)
            }
            .padding(13)
            .frame(maxWidth: .infinity, minHeight: 112, alignment: .topLeading)
            .contentShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        }
        .buttonStyle(.plain)
        .background {
            if selectedTarget == preset.id {
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .fill(Color.accentColor.opacity(0.06))
            }
        }
        .quickOrbitGlass(cornerRadius: 16, interactive: true)
        .overlay {
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .stroke(selectedTarget == preset.id ? Color.green.opacity(0.48) : Color.primary.opacity(0.055), lineWidth: selectedTarget == preset.id ? 1.3 : 0.6)
        }
        .quickOrbitGlassIdentity("mac-control-\(preset.id)", in: glassNamespace, matched: false)
        .quickOrbitPickerHover()
    }

    private func presetTint(_ id: String) -> Color {
        if id.hasPrefix("media") || id.hasPrefix("volume") { return .purple }
        if ["liveClock", "liveDate", "batteryStatus", "chargingStatus", "cpuStatus", "memoryStatus", "networkStatus", "storageStatus", "uptimeStatus", "thermalStatus", "wifiStatus", "activityMonitor"].contains(id) { return .cyan }
        if id == "smartSuggestion" { return .blue }
        if ["ocrCapture", "translateText", "clipboardHistory", "spotlight", "calculator", "newReminder", "newCalendarEvent"].contains(id) { return .blue }
        if id == "colorSampler" { return .green }
        if id.hasPrefix("window") { return .orange }
        if ["focus", "lowPowerMode", "screenSaver", "brightnessUp", "brightnessDown", "lockScreen", "displaySleep", "logout", "forceQuit", "batteryWarning"].contains(id) { return .orange }
        if id.hasSuffix("Settings") { return .blue }
        if ["downloads", "desktopFolder", "homeFolder", "trashFolder"].contains(id) { return .orange }
        return .gray
    }
}

