private struct AcceleratingStepperButton: View {
    let symbol: String
    let accessibilityLabel: String
    let helpText: String
    let action: () -> Void
    @State private var isPressed = false
    @State private var repeatWorkItem: DispatchWorkItem?

    var body: some View {
        Image(systemName: symbol)
            .font(.system(size: 13, weight: .bold))
            .frame(width: 42, height: 42)
            .background(Color.primary.opacity(isPressed ? 0.11 : 0.06), in: RoundedRectangle(cornerRadius: 11, style: .continuous))
            .scaleEffect(isPressed ? 0.97 : 1)
            .contentShape(RoundedRectangle(cornerRadius: 11, style: .continuous))
            .gesture(
                DragGesture(minimumDistance: 0)
                    .onChanged { _ in beginPress() }
                    .onEnded { _ in endPress() }
            )
            .quickOrbitPickerHover()
            .accessibilityAddTraits(.isButton)
            .accessibilityLabel(accessibilityLabel)
            .help(helpText)
            .onDisappear { endPress() }
    }

    private func beginPress() {
        guard !isPressed else { return }
        isPressed = true
        action()
        scheduleRepeat(after: 0.44, startedAt: Date())
    }

    private func scheduleRepeat(after delay: TimeInterval, startedAt: Date) {
        repeatWorkItem?.cancel()
        let work = DispatchWorkItem {
            guard isPressed else { return }
            action()
            let elapsed = Date().timeIntervalSince(startedAt)
            let nextDelay: TimeInterval = elapsed > 2.4 ? 0.055 : (elapsed > 1.2 ? 0.095 : 0.16)
            scheduleRepeat(after: nextDelay, startedAt: startedAt)
        }
        repeatWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: work)
    }

    private func endPress() {
        isPressed = false
        repeatWorkItem?.cancel()
        repeatWorkItem = nil
    }
}

struct TimerActionPicker: View {
    let language: AppLanguage?
    let selectedTarget: String?
    let onSelect: (OrbitItem) -> Void
    @ObservedObject private var store = OrbitStore.shared

    private let fixedSeconds = [300, 1_500, 1_800, 3_000]

    var body: some View {
        VStack(alignment: .leading, spacing: 18) {
            VStack(alignment: .leading, spacing: 4) {
                Text(qoText("Timer auswählen", "Choose a timer", language: language))
                    .font(.title3.weight(.semibold))
                Text(qoText("Timer und Stoppuhr sind zwei eigene Felder. Die Timerdauer stellst du hier direkt selbst ein.", "Timer and stopwatch are separate tiles. Set the timer duration directly here.", language: language))
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
            }

            LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 12), count: 2), spacing: 12) {
                customTimerTile

                timerButton(
                    target: "stopwatch",
                    title: qoText("Stoppuhr", "Stopwatch", language: language),
                    subtitle: qoText("Eigenes Feld · Start, Pause und Reset", "Separate tile · Start, pause, and reset", language: language),
                    symbol: "stopwatch.fill"
                )

                ForEach(fixedSeconds, id: \.self) { seconds in
                    timerButton(
                        target: "timerSeconds\(seconds)",
                        title: focusTimerTitle(seconds: seconds),
                        subtitle: [1_500, 3_000].contains(seconds)
                            ? qoText("Fokusblock mit Ton und Hinweis", "Focus block with sound and alert", language: language)
                            : qoText("Ton und Hinweis am Ende", "Sound and alert at the end", language: language),
                        symbol: [1_500, 3_000].contains(seconds) ? "timer.circle.fill" : "timer"
                    )
                }

            }

            Label(
                qoText("Am Ende ertönt der Ton dreimal. Der Hinweis bleibt sichtbar, bis du ihn schließt.", "The sound plays three times at the end. The alert stays visible until you close it.", language: language),
                systemImage: "speaker.wave.2.fill"
            )
            .font(.caption)
            .foregroundStyle(.secondary)
        }
    }

    private func selectCustomTimer() {
        let seconds = store.config.customTimerSeconds ?? 300
        selectTimer(target: "timerCustom", title: qoText("Timer \(quickOrbitDurationLabel(seconds: seconds, language: .german))", "\(quickOrbitDurationLabel(seconds: seconds, language: .english)) timer", language: language), symbol: "slider.horizontal.3")
    }

    private var customTimerTile: some View {
        let seconds = store.config.customTimerSeconds ?? 300
        return VStack(alignment: .leading, spacing: 9) {
            Button(action: selectCustomTimer) {
                VStack(alignment: .leading, spacing: 9) {
                    HStack {
                        Image(systemName: "slider.horizontal.3")
                            .font(.system(size: 22, weight: .semibold))
                            .foregroundStyle(selectedTarget == "timerCustom" ? Color.green : Color.primary)
                        Spacer()
                        Image(systemName: selectedTarget == "timerCustom" ? "checkmark.circle.fill" : "circle")
                            .foregroundStyle(selectedTarget == "timerCustom" ? Color.green : Color.secondary)
                    }
                    Text(qoText("Eigene Dauer", "Custom duration", language: language)).font(.subheadline.weight(.semibold))
                    Text(quickOrbitDurationLabel(seconds: seconds, language: language))
                        .font(.system(size: 29, weight: .bold, design: .rounded))
                        .monospacedDigit()
                        .foregroundStyle(Color.green)
                        .minimumScaleFactor(0.72)
                        .lineLimit(1)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            HStack(spacing: 7) {
                AcceleratingStepperButton(
                    symbol: "minus",
                    accessibilityLabel: qoText("Zeit verringern", "Decrease time", language: language),
                    helpText: qoText("Gedrückt halten, um schneller zu verringern", "Hold to decrease faster", language: language)
                ) { adjustCustomTimer(by: -1) }

                Button(action: selectCustomTimer) {
                    Label(qoText("Auswählen", "Select", language: language), systemImage: "checkmark")
                        .font(.caption.weight(.bold)).frame(maxWidth: .infinity).frame(height: 34)
                }
                .buttonStyle(.plain)
                .foregroundStyle(selectedTarget == "timerCustom" ? Color.white : Color.green)
                .background(selectedTarget == "timerCustom" ? Color.green : Color.green.opacity(0.13), in: RoundedRectangle(cornerRadius: 10, style: .continuous))

                AcceleratingStepperButton(
                    symbol: "plus",
                    accessibilityLabel: qoText("Zeit erhöhen", "Increase time", language: language),
                    helpText: qoText("Gedrückt halten, um schneller zu erhöhen", "Hold to increase faster", language: language)
                ) { adjustCustomTimer(by: 1) }
            }
        }
        .padding(14)
        .frame(maxWidth: .infinity, minHeight: 150, alignment: .topLeading)
        .quickOrbitGlass(cornerRadius: 16)
        .overlay { RoundedRectangle(cornerRadius: 16, style: .continuous).stroke(selectedTarget == "timerCustom" ? Color.green.opacity(0.28) : Color.primary.opacity(0.08), lineWidth: 0.8).allowsHitTesting(false) }
        .contentShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        .quickOrbitPickerHover()
    }

    private func timerButton(target: String, title: String, subtitle: String, symbol: String) -> some View {
        Button {
            selectTimer(target: target, title: title, symbol: symbol)
        } label: {
            HStack(spacing: 12) {
                Image(systemName: symbol)
                    .font(.system(size: 24, weight: .semibold))
                    .foregroundStyle(selectedTarget == target ? Color.green : Color.primary)
                    .frame(width: 42, height: 42)
                    .background(Color.green.opacity(0.10), in: RoundedRectangle(cornerRadius: 12, style: .continuous))
                VStack(alignment: .leading, spacing: 3) {
                    Text(title).font(.headline)
                    Text(subtitle).font(.caption).foregroundStyle(.secondary)
                }
                Spacer()
                Image(systemName: selectedTarget == target ? "checkmark.circle.fill" : "circle")
                    .foregroundStyle(selectedTarget == target ? Color.green : Color.secondary)
            }
            .padding(14)
            .frame(maxWidth: .infinity, minHeight: 150)
            .contentShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        }
        .buttonStyle(.plain)
        .quickOrbitGlass(cornerRadius: 16, interactive: true)
        .quickOrbitPickerHover()
    }

    private func selectTimer(target: String, title: String, symbol: String) {
        onSelect(OrbitItem(title: title, symbol: symbol, type: .timer, target: target, enabled: true))
    }

    private func focusTimerTitle(seconds: Int) -> String {
        guard [1_500, 3_000].contains(seconds) else {
            return quickOrbitDurationLabel(seconds: seconds, language: language)
        }
        return qoText(
            "Fokus · \(quickOrbitDurationLabel(seconds: seconds, language: .german))",
            "Focus · \(quickOrbitDurationLabel(seconds: seconds, language: .english))",
            language: language
        )
    }

    private func adjustCustomTimer(to seconds: Int) {
        store.setCustomTimerSeconds(seconds)
        guard selectedTarget == "timerCustom" else { return }
        selectCustomTimer()
    }

    private func adjustCustomTimer(by direction: Int) {
        let current = store.config.customTimerSeconds ?? 300
        let step = current >= 60 ? 60 : 5
        adjustCustomTimer(to: min(10_800, max(5, current + direction * step)))
    }
}

enum OrbitLayout: String, Codable, CaseIterable, Identifiable {
    case automatic = "Automatisch"
    case fan = "Fächer oben"
    case circle = "Kreis"
    case lowerFan = "Fächer unten"
    case horizontal = "Reihe"
    case vertical = "Spalte"
    case grid = "Raster"
    case compactArc = "Kompakter Bogen"

    var id: String { rawValue }

    func title(language: AppLanguage?) -> String {
        switch self {
        case .automatic: return qoText("Automatisch", "Automatic", language: language)
        case .fan: return qoText("Fächer oben", "Upper fan", language: language)
        case .circle: return qoText("Kreis", "Circle", language: language)
        case .lowerFan: return qoText("Fächer unten", "Lower fan", language: language)
        case .horizontal: return qoText("Reihe", "Row", language: language)
        case .vertical: return qoText("Spalte", "Column", language: language)
        case .grid: return qoText("Raster", "Grid", language: language)
        case .compactArc: return qoText("Kompakter Bogen", "Compact arc", language: language)
        }
    }

    var symbol: String {
        switch self {
        case .automatic: return "wand.and.stars"
        case .fan: return "fan"
        case .circle: return "circle.grid.cross"
        case .lowerFan: return "fan"
        case .horizontal: return "rectangle.split.3x1"
        case .vertical: return "rectangle.split.1x2"
        case .grid: return "square.grid.3x3"
        case .compactArc: return "circle.dotted"
        }
    }
}

