private func qoText(_ de: String, _ en: String, language: AppLanguage?) -> String {
    language == .english ? en : de
}

private func quickOrbitDurationLabel(minutes: Int, language: AppLanguage?) -> String {
    let safeMinutes = max(minutes, 0)
    let minuteUnit = language == .english ? "min" : "Min"
    guard safeMinutes >= 60 else { return "\(safeMinutes) \(minuteUnit)" }
    let hours = safeMinutes / 60
    let remainingMinutes = safeMinutes % 60
    let hourText = language == .english ? "\(hours) hr" : "\(hours) Std"
    return remainingMinutes == 0 ? hourText : "\(hourText) \(remainingMinutes) \(minuteUnit)"
}

private func quickOrbitCompactDurationLabel(minutes: Int) -> String {
    let safeMinutes = max(minutes, 0)
    guard safeMinutes >= 60 else { return "\(safeMinutes)m" }
    let hours = safeMinutes / 60
    let remainingMinutes = safeMinutes % 60
    return remainingMinutes == 0 ? "\(hours)h" : String(format: "%dh%02d", hours, remainingMinutes)
}

private func quickOrbitDurationLabel(seconds: Int, language: AppLanguage?) -> String {
    let safeSeconds = max(seconds, 0)
    let secondUnit = language == .english ? "sec" : "Sek"
    if safeSeconds < 60 { return "\(safeSeconds) \(secondUnit)" }

    if safeSeconds >= 3_600 {
        let hours = safeSeconds / 3_600
        let remainingMinutes = (safeSeconds % 3_600) / 60
        let remainingSeconds = safeSeconds % 60
        let hourText: String
        if language == .english {
            hourText = hours == 1 ? "1 hr" : "\(hours) hrs"
        } else {
            hourText = hours == 1 ? "1 Stunde" : "\(hours) Stunden"
        }

        var components = [hourText]
        if remainingMinutes > 0 { components.append("\(remainingMinutes) \(language == .english ? "min" : "Min")") }
        if remainingSeconds > 0 { components.append("\(remainingSeconds) \(secondUnit)") }
        if components.count == 2 {
            return components.joined(separator: language == .english ? " " : " und ")
        }
        return components.joined(separator: " ")
    }

    let minutes = safeSeconds / 60
    let remainingSeconds = safeSeconds % 60
    let minuteUnit = language == .english ? "min" : "Min"
    return remainingSeconds == 0 ? "\(minutes) \(minuteUnit)" : "\(minutes) \(minuteUnit) \(remainingSeconds) \(secondUnit)"
}

private func quickOrbitCompactDurationLabel(seconds: Int) -> String {
    seconds < 60 ? "\(max(seconds, 0))s" : String(format: "%d:%02d", seconds / 60, seconds % 60)
}

@discardableResult
private func copyQuickOrbitText(_ text: String) -> Bool {
    guard !text.isEmpty else { return false }
    NSPasteboard.general.clearContents()
    let copied = NSPasteboard.general.setString(text, forType: .string)
    if !copied {
        Task { @MainActor in
            QuickOrbitNoticeCenter.shared.show(QuickOrbitDiagnosticCode.clipboardFailed.message(language: OrbitStore.shared.config.language), diagnostic: .clipboardFailed)
        }
    }
    return copied
}

private var quickOrbitVersionLabel: String {
    let value = Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String
    let cleaned = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    // A one-file preview has no Info.plist version. Keep the UI release-like there,
    // while normal Xcode builds continue to use their configured bundle version.
    return cleaned.isEmpty ? "v56" : (cleaned.lowercased().hasPrefix("v") ? cleaned : "v" + cleaned)
}

private let quickOrbitWebsiteAddress = "https://nicot-111.github.io/QuickOrbit-Website/"
private let quickOrbitReleaseRepository = "NicoT-111/QuickOrbit-App"

private var quickOrbitWebsiteURL: URL? {
    let value = quickOrbitWebsiteAddress.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !value.isEmpty,
          let components = URLComponents(string: value),
          ["https", "http"].contains(components.scheme?.lowercased() ?? ""),
          components.host?.isEmpty == false else { return nil }
    return components.url
}

@MainActor
private var quickOrbitAppIcon: NSImage {
    // Prefer the compiled AppIcon asset. The bundle fallback keeps Dock, About,
    // onboarding and every in-app logo synchronized in standalone builds too.
    if let appIcon = NSImage(named: NSImage.Name("AppIcon")) {
        return appIcon
    }

    let bundledIcon = NSWorkspace.shared.icon(forFile: Bundle.main.bundlePath)
    if bundledIcon.size.width > 0, bundledIcon.size.height > 0 {
        return bundledIcon
    }

    return NSApp.applicationIconImage
}

enum QuickEditModifier: String, Codable, CaseIterable, Identifiable {
    case control = "Control"
    case option = "Option"
    case controlOption = "Control + Option"

    var id: String { rawValue }

    func display(language: AppLanguage?) -> String {
        switch self {
        case .control: return qoText("⌃ Control", "⌃ Control", language: language)
        case .option: return qoText("⌥ Option", "⌥ Option", language: language)
        case .controlOption: return qoText("⌃⌥ Control + Option", "⌃⌥ Control + Option", language: language)
        }
    }

    var display: String { display(language: nil) }

    var requiredFlags: CGEventFlags {
        switch self {
        case .control: return [.maskControl]
        case .option: return [.maskAlternate]
        case .controlOption: return [.maskControl, .maskAlternate]
        }
    }

    func matchesExactly(_ flags: CGEventFlags) -> Bool {
        let relevant: CGEventFlags = [.maskControl, .maskAlternate, .maskCommand, .maskShift]
        return flags.intersection(relevant) == requiredFlags
    }
}

enum OrbitActivationModifier: String, Codable, CaseIterable, Identifiable {
    case control = "Control"
    case option = "Option"
    case command = "Command"
    case shift = "Shift"

    var id: String { rawValue }

    func display(language: AppLanguage?) -> String {
        switch self {
        case .control: return "⌃ Control"
        case .option: return "⌥ Option"
        case .command: return "⌘ Command"
        case .shift: return "⇧ Shift"
        }
    }

    var requiredFlag: CGEventFlags {
        switch self {
        case .control: return .maskControl
        case .option: return .maskAlternate
        case .command: return .maskCommand
        case .shift: return .maskShift
        }
    }

    func matchesExactly(_ flags: CGEventFlags) -> Bool {
        let relevant: CGEventFlags = [.maskControl, .maskAlternate, .maskCommand, .maskShift]
        return flags.intersection(relevant) == requiredFlag
    }
}

struct OrbitItem: Identifiable, Codable, Equatable {
    var id = UUID()
    var title = "Leer"
    var symbol = "plus"
    var type: OrbitActionType = .app
    var target = ""
    var enabled = false
    // App Sandbox grants picker access temporarily. Persist a security-scoped
    // bookmark so a user-selected file or app still works after relaunch.
    var securityScopedBookmark: Data? = nil

    // Kept for compatibility with older QuickOrbit files.
    var keyCode: Int = 0
    var command = false
    var option = false
    var shift = false
    var control = false

    static func empty(_ index: Int) -> OrbitItem {
        OrbitItem(title: "Feld \(index + 1)", symbol: "plus", enabled: false)
    }

    var isLiveClock: Bool {
        enabled && type == .systemAction && target == "liveClock"
    }

    var insertedEmoji: String? {
        guard enabled, (type == .systemAction || type == .emoji), target.hasPrefix("emojiInsert:") else { return nil }
        let value = String(target.dropFirst("emojiInsert:".count))
        return value.isEmpty ? nil : value
    }

    var isEmojiInsert: Bool { insertedEmoji != nil }

    var editorCategory: OrbitActionType {
        if isEmojiInsert || target == "emojiPalette" { return .emoji }
        if type == .timer || target.hasPrefix("timer") || target == "stopwatch" { return .timer }
        return type
    }

    var isLiveSystemTile: Bool {
        guard enabled && (type == .systemAction || type == .timer) else { return false }
        if target == "volumeStatus" { return true }
        return ["liveClock", "liveDate", "batteryStatus", "chargingStatus", "batteryWarning", "cpuStatus", "memoryStatus", "networkStatus", "storageStatus", "uptimeStatus", "thermalStatus", "wifiStatus", "smartSuggestion", "stopwatch"].contains(target)
            || target.hasPrefix("timer")
    }

    var requiresAccessibility: Bool {
        guard type == .systemAction || type == .windowManagement else { return false }
        return SystemActionPreset.preset(for: target)?.requiresAccessibility == true
    }
}

private struct QuickOrbitResolvedResource {
    let url: URL
    let isSecurityScopeActive: Bool

    func stopAccessing() {
        if isSecurityScopeActive { url.stopAccessingSecurityScopedResource() }
    }
}

private func quickOrbitBookmark(for url: URL) -> Data? {
    try? url.bookmarkData(
        options: .withSecurityScope,
        includingResourceValuesForKeys: nil,
        relativeTo: nil
    )
}

private func quickOrbitResolvedResource(for item: OrbitItem) -> QuickOrbitResolvedResource? {
    if let bookmark = item.securityScopedBookmark {
        var stale = false
        if let url = try? URL(
            resolvingBookmarkData: bookmark,
            options: [.withSecurityScope, .withoutUI],
            relativeTo: nil,
            bookmarkDataIsStale: &stale
        ) {
            return QuickOrbitResolvedResource(
                url: url,
                isSecurityScopeActive: url.startAccessingSecurityScopedResource()
            )
        }
    }

    guard !item.target.isEmpty else { return nil }
    return QuickOrbitResolvedResource(
        url: URL(fileURLWithPath: item.target),
        isSecurityScopeActive: false
    )
}

