struct OrbitProfile: Identifiable, Codable, Equatable {
    var dwellTime: Double? = nil
    var id = UUID()
    var name: String
    var itemCount: Int
    var items: [OrbitItem]
    var scope: OrbitProfileScope = .allApps
    // `apps` is retained only to decode profiles saved by older releases.
    // Included and excluded rules now own separate lists so switching the rule
    // can never silently reuse an app from the opposite rule.
    var apps: [OrbitProfileApp] = []
    var includedApps: [OrbitProfileApp]? = nil
    var excludedApps: [OrbitProfileApp]? = nil
    var sizePreset: OrbitSizePreset? = .comfortable
    var layout: OrbitLayout? = .fan
    var radius: Double? = 155
    var tileScale: Double? = 1.0
    var itemSpacing: Double? = 1.0
    var highlightScale: Double? = 1.12
    var showLabels: Bool? = true
    var color: OrbitProfileColor? = .gray
    var showGuide: Bool? = true
    var showOuterGuide: Bool? = false
    var showProfileDots: Bool? = true
    var profileDotsHorizontalOffset: Double? = 200.0
    var customTimerMinutes: Int? = 20
    var customTimerSeconds: Int? = 300

    var appsForCurrentScope: [OrbitProfileApp] {
        switch scope {
        case .allApps: return []
        case .selectedApps: return includedApps ?? apps
        case .excludedApps: return excludedApps ?? apps
        }
    }

    static func empty(name: String, color: OrbitProfileColor = .gray) -> OrbitProfile {
        OrbitProfile(
            name: name,
            itemCount: 0,
            items: (0..<16).map { OrbitItem.empty($0) },
            color: color
        )
    }
}


