    var appearance: QuickOrbitAppearance? = .system
    var designStyle: QuickOrbitDesignStyle? = .settings
    var orbitAnimationLevel: OrbitAnimationLevel? = .subtle
    var orbitAnimationDuration: Double? = 0.38
    var circleOpeningRotation: Bool? = true
    var emojiProfileInstalled: Bool? = false
    // Reduces QuickOrbit's own visual and background work. This deliberately does
    // not modify macOS power settings and therefore needs no additional permission.
    var energySavingMode: Bool? = false
    var lowBatteryWarningEnabled: Bool? = false
    var lowBatteryWarningThreshold: Int? = 20
    var onboardingCompleted: Bool? = false
    var userDisplayName: String? = nil
    var acceptedTermsVersion: String? = nil
