    var showLabels = true
    var showCenterDot = true
    var showGuide = true
    var showOuterGuide: Bool? = false
    // Optional classic glass circles behind Orbit items. Apps gain the circle when selected.
    var orbitTileGlassEnabled: Bool? = true
