    var profileDotsHorizontalOffset: Double? = 200.0
    var showDeadZone: Bool? = true
    var haptics = true
    var middleClickEnabled = true
    var suppressMiddleClick = true

    // Press and hold the primary trackpad click to open QuickOrbit.
    // Optional values keep older saved configurations compatible.
    var trackpadHoldEnabled: Bool? = false
    var trackpadHoldDuration: Double? = 3.0

    // Long primary click with a normal mouse. Kept separate in the UI from the
    // trackpad option, while sharing the same safe movement-cancel behavior.
    var mouseHoldEnabled: Bool? = false
    var mouseHoldDuration: Double? = 2.0

    // Optional extra way to open QuickOrbit: tap Control once briefly.
    var controlTapOpenEnabled: Bool? = false
    // Control remains the default, but the user can choose another single
    // modifier without changing the independent Quick Edit gesture.
    var tapOpenModifier: OrbitActivationModifier? = .control

    var quickEditEnabled = true
    var quickEditModifier: QuickEditModifier = .control
    var quickEditTravel: Double = 22

    var menuBarEnabled = true
    var menuBarMainSymbol: String? = "circle.grid.cross"
    // Re-enables the new single menu-bar icon once. A later manual toggle off stays off.
    var singleMenuBarIconMigrationDone: Bool? = false

    // Up to three independent quick actions shown as separate icons in the macOS menu bar.
    // Optional keeps older saved configurations decodable.
    var menuBarQuickItems: [OrbitItem]? = nil
    var menuBarDefaultsInstalled: Bool? = nil
    var menuBarMailDefaultMigrationDone: Bool? = false

    // One-time migration marker for the built-in Mac Tools profile.
    // Optional keeps older saved configurations decodable and allows users to delete
    // the profile later without it being recreated on every launch.
    var macToolsProfileInstalled: Bool? = false

    // One-time migration marker for the built-in Media profile.
    // Kept optional so older saved configurations decode without changes.
    var mediaProfileInstalled: Bool? = false

    // Optional so old v2 JSON/UserDefaults configurations still decode.
    var autoProfileSwitchEnabled: Bool? = true

    // Optional preferred/default profile. App-linked profiles always have priority.
    var mainProfileID: UUID? = nil
    var mainProfileReturnMode: MainProfileReturnMode? = .time
    var mainProfileReturnDelay: Double? = 60
    var mainProfileReturnActivationCount: Int? = 2

    // Duration used by the configurable timer system tile.
    var customTimerMinutes: Int? = 20
    var customTimerSeconds: Int? = 300
    // Sets General as the initial main profile once without overriding later choices.
    var defaultMainProfileMigrationDone: Bool? = false

    // Adaptive activation: a fast, confident flick may use a much shorter dwell.
    // Optional keeps existing v4 configurations decodable.
    var smartFlickEnabled: Bool? = false
    var smartFlickVelocity: Double? = 980
    var smartFlickDwell: Double? = 0.16

    // Keeps the manually selected profile active until the user unlocks it.
    var profileLockEnabled: Bool? = false

