// MARK: - Store

@MainActor
final class OrbitStore: @preconcurrency ObservableObject {
    static let shared = OrbitStore()

    // Config is intentionally NOT @Published. SwiftUI can call Binding setters while
    // it is still updating a view. Publishing synchronously from those setters causes
    // the purple "Publishing changes from within view updates" runtime warning.
    // We therefore coalesce config changes and publish them on the next main-loop turn.
    let objectWillChange = ObservableObjectPublisher()

    var config: QuickOrbitConfig {
        didSet {
            scheduleSave()
            scheduleConfigPublish()
        }
    }

    private var configPublishScheduled = false
    private var saveWorkItem: DispatchWorkItem?
    private var mainProfileReturnWorkItem: DispatchWorkItem?
    private var mainProfileReturnDueAt: Date?
    private var pendingAutomaticBundleIdentifier: String?
    private var activationsSinceProfileChange = 0
    private(set) var orbitSessionActive = false

    private func scheduleConfigPublish() {
        guard !configPublishScheduled else { return }
        configPublishScheduled = true
        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            self.configPublishScheduled = false
            self.objectWillChange.send()
            StatusBarController.shared.refresh()
        }
    }

    func binding<Value>(_ keyPath: WritableKeyPath<QuickOrbitConfig, Value>) -> Binding<Value> {
        let fallback = config[keyPath: keyPath]
        return Binding(
            get: { [weak self] in
                self?.config[keyPath: keyPath] ?? fallback
            },
            set: { [weak self] newValue in
                self?.config[keyPath: keyPath] = newValue
            }
        )
    }

    @Published var selectedSlot = 0
    @Published var editorSlot: Int?
    @Published var newlyCreatedEditorSlot: Int?
    @Published var actionEditorIsOpen = false

    private let storageKey = "QuickOrbit.Rebuilt.v1"
    private let oldStorageKey = "QuickOrbit.Simple.OneFile.v1"

    private init() {
        if let data = UserDefaults.standard.data(forKey: storageKey),
           let decoded = try? JSONDecoder().decode(QuickOrbitConfig.self, from: data) {
            config = Self.fixed(decoded)
            return
        }

        if let oldData = UserDefaults.standard.data(forKey: oldStorageKey),
           let legacy = try? JSONDecoder().decode(LegacyFieldConfig.self, from: oldData) {
            var migrated = QuickOrbitConfig.fresh
            migrated.itemCount = min(max(legacy.itemCount, 2), 16)
            migrated.items = Self.normalizedItems(legacy.items, count: migrated.itemCount)

            var general = OrbitProfile(
                name: "Allgemein",
                itemCount: migrated.itemCount,
                items: migrated.items,
                scope: .allApps,
                color: .blue
            )
            general.items = Self.normalizedItems(general.items, count: general.itemCount)
            let leisure = OrbitProfile.empty(name: "Freizeit", color: .green)
            let school = OrbitProfile.empty(name: "Schule", color: .purple)
            migrated.profiles = [general, leisure, school]
            migrated.activeProfileID = general.id
            config = Self.fixed(migrated)
            return
        }

        config = QuickOrbitConfig.fresh
    }

    var profiles: [OrbitProfile] {
        config.profiles ?? []
    }

    var activeProfileIndex: Int {
        guard let id = config.activeProfileID,
              let index = profiles.firstIndex(where: { $0.id == id }) else { return 0 }
        return index
    }

    var activeProfile: OrbitProfile? {
        guard profiles.indices.contains(activeProfileIndex) else { return nil }
        var profile = profiles[activeProfileIndex]
        profile.itemCount = config.itemCount
        profile.items = config.items
        return profile
    }

    var visibleItems: [OrbitItem] {
        Array(config.items.prefix(config.itemCount))
    }

    var occupiedCount: Int {
        visibleItems.filter(\.enabled).count
    }

    var savedBetaCommands: [SavedBetaCommandReference] {
        let snapshot = snapshotWithCurrentProfile(config)
        return (snapshot.profiles ?? []).flatMap { profile in
            Array(profile.items.prefix(profile.itemCount)).enumerated().compactMap { slot, item in
                guard item.enabled, item.type == .shellCommand else { return nil }
                return SavedBetaCommandReference(
                    id: item.id,
                    profileID: profile.id,
                    profileName: profile.name,
                    slot: slot,
                    title: item.title,
                    command: item.target
                )
            }
        }
    }

    @discardableResult
    func updateSavedBetaCommand(id: UUID, title: String, command: String) -> Bool {
        let cleanTitle = title.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanCommand = command.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanTitle.isEmpty,
              QuickOrbitBetaCommandPolicy.status(cleanCommand, language: config.language).valid else { return false }

        var next = snapshotWithCurrentProfile(config)
        guard var profiles = next.profiles else { return false }
        for profileIndex in profiles.indices {
            let count = min(max(profiles[profileIndex].itemCount, 0), 16)
            guard let slot = profiles[profileIndex].items.prefix(count).firstIndex(where: { $0.id == id && $0.type == .shellCommand }) else { continue }
            profiles[profileIndex].items[slot].title = cleanTitle
            profiles[profileIndex].items[slot].target = cleanCommand
            if profiles[profileIndex].id == next.activeProfileID,
               next.items.indices.contains(slot) {
                next.items[slot] = profiles[profileIndex].items[slot]
            }
            next.profiles = profiles
            config = next
            return true
        }
        return false
    }

    @discardableResult
    func deleteSavedBetaCommand(id: UUID) -> Bool {
        var next = snapshotWithCurrentProfile(config)
        guard var profiles = next.profiles else { return false }
        for profileIndex in profiles.indices {
            let count = min(max(profiles[profileIndex].itemCount, 0), 16)
            var items = Array(profiles[profileIndex].items.prefix(count))
            guard let slot = items.firstIndex(where: { $0.id == id && $0.type == .shellCommand }) else { continue }
            items.remove(at: slot)
            if !items.contains(where: \.enabled) {
                items = [Self.starterEditItem(language: next.language)]
            }
            profiles[profileIndex].itemCount = items.count
            profiles[profileIndex].items = Self.normalizedItems(items, count: items.count)
            if profiles[profileIndex].id == next.activeProfileID {
                next.itemCount = profiles[profileIndex].itemCount
                next.items = profiles[profileIndex].items
                selectedSlot = min(selectedSlot, max(next.itemCount - 1, 0))
            }
            next.profiles = profiles
            config = next
            return true
        }
        return false
    }

    func item(at index: Int) -> OrbitItem? {
        guard visibleItems.indices.contains(index) else { return nil }
        return visibleItems[index]
    }

    func ensureActiveProfileIsUsable() {
        guard config.itemCount == 0 || occupiedCount == 0 else { return }
        installStarterEditTile()
    }

    private func installStarterEditTile() {
        var next = config
        next.itemCount = 1
        next.items = Self.normalizedItems([
            Self.starterEditItem(language: next.language)
        ], count: 1)
        config = next
        selectedSlot = 0
        editorSlot = nil
        newlyCreatedEditorSlot = nil
    }

    func setItem(_ item: OrbitItem, at index: Int) {
        guard config.items.indices.contains(index) else { return }
        config.items[index] = item
        selectedSlot = index
    }

    func clear(_ index: Int) {
        removeSlot(index)
    }

    func addSlot() {
        guard config.itemCount < 16 else { return }
        let index = config.itemCount
        config.items[index] = .empty(index)
        config.itemCount += 1
        selectedSlot = index
        newlyCreatedEditorSlot = index
        DispatchQueue.main.async { [weak self] in
            self?.editorSlot = index
        }
    }

    func openEditor(for index: Int) {
        guard index >= 0, index < config.itemCount, config.items.indices.contains(index) else { return }
        selectedSlot = index
        // Set nil first so clicking the same empty field again always presents the sheet.
        editorSlot = nil
        DispatchQueue.main.async { [weak self] in
            self?.editorSlot = index
        }
    }

    func removeLastSlot() {
        guard config.itemCount > 0 else { return }
        guard config.itemCount > 1 else {
            installStarterEditTile()
            return
        }
        let last = config.itemCount - 1
        config.items[last] = .empty(last)
        config.itemCount -= 1
        selectedSlot = min(selectedSlot, max(config.itemCount - 1, 0))
    }

    func removeSlot(_ index: Int) {
        guard config.itemCount > 0, index >= 0, index < config.itemCount else { return }
        guard config.itemCount > 1 else {
            installStarterEditTile()
            return
        }
        if index < config.itemCount - 1 {
            for i in index..<(config.itemCount - 1) {
                config.items[i] = config.items[i + 1]
            }
        }
        let last = config.itemCount - 1
        config.items[last] = .empty(last)
        config.itemCount -= 1
        selectedSlot = min(index, max(config.itemCount - 1, 0))
        editorSlot = nil
        if let pending = newlyCreatedEditorSlot {
            if pending == index {
                newlyCreatedEditorSlot = nil
            } else if pending > index {
                newlyCreatedEditorSlot = pending - 1
            }
        }
    }

    func reorderSlot(from source: Int, to target: Int) {
        guard source != target,
              source >= 0, source < config.itemCount,
              target >= 0, target < config.itemCount else { return }
        var visible = Array(config.items.prefix(config.itemCount))
        let moved = visible.remove(at: source)
        visible.insert(moved, at: target)
        for index in 0..<config.itemCount { config.items[index] = visible[index] }
        selectedSlot = target
        if let pending = newlyCreatedEditorSlot {
            if pending == source {
                newlyCreatedEditorSlot = target
            } else if source < pending && target >= pending {
                newlyCreatedEditorSlot = pending - 1
            } else if source > pending && target <= pending {
                newlyCreatedEditorSlot = pending + 1
            }
        }
    }

    func moveSlot(_ index: Int, by delta: Int) {
        let target = index + delta
        guard index >= 0, index < config.itemCount,
              target >= 0, target < config.itemCount else { return }
        config.items.swapAt(index, target)
        selectedSlot = target
    }

    func duplicate(_ index: Int) {
        guard config.items.indices.contains(index), config.itemCount < 16 else { return }
        var copy = config.items[index]
        copy.id = UUID()
        config.items[config.itemCount] = copy
        selectedSlot = config.itemCount
        config.itemCount += 1
    }

    // MARK: Menu bar quick actions

    var menuBarQuickItems: [OrbitItem] {
        Self.normalizedMenuBarItems(config.menuBarQuickItems ?? [])
    }

    func menuBarItem(at index: Int) -> OrbitItem {
        let items = menuBarQuickItems
        guard items.indices.contains(index) else { return .empty(index) }
        return items[index]
    }

    func setMenuBarItem(_ item: OrbitItem, at index: Int) {
        guard (0..<3).contains(index) else { return }
        var items = menuBarQuickItems
        items[index] = item
        config.menuBarQuickItems = items
    }

    func clearMenuBarItem(_ index: Int) {
        guard (0..<3).contains(index) else { return }
        var items = menuBarQuickItems
        items[index] = .empty(index)
        config.menuBarQuickItems = items
    }

    func moveMenuBarItem(_ index: Int, by delta: Int) {
        let target = index + delta
        guard (0..<3).contains(index), (0..<3).contains(target) else { return }
        var items = menuBarQuickItems
        items.swapAt(index, target)
        config.menuBarQuickItems = items
    }

    func copyOrbitItemToMenuBar(slot: Int, menuBarIndex: Int) {
        guard visibleItems.indices.contains(slot), (0..<3).contains(menuBarIndex) else { return }
        var copy = visibleItems[slot]
        copy.id = UUID()
        setMenuBarItem(copy, at: menuBarIndex)
    }

    // MARK: Profiles

    func switchProfile(to id: UUID, scheduleMainReturn _: Bool = true) {
        var next = snapshotWithCurrentProfile(config)
        guard let profiles = next.profiles,
              let target = profiles.first(where: { $0.id == id }) else { return }

        next.activeProfileID = id
        next.itemCount = target.itemCount
        next.items = Self.normalizedItems(target.items, count: target.itemCount)
        next.sizePreset = target.sizePreset ?? .comfortable
        next.layout = target.layout ?? .fan
        next.radius = target.radius ?? 155
        next.tileScale = target.tileScale ?? 1.0
        next.itemSpacing = target.itemSpacing ?? 1.0
        next.highlightScale = target.highlightScale ?? 1.12
        next.showLabels = target.showLabels ?? true
        next.showGuide = target.showGuide ?? true
        next.showOuterGuide = target.showOuterGuide ?? false
        next.showProfileDots = target.showProfileDots ?? true
        next.profileDotsHorizontalOffset = target.profileDotsHorizontalOffset ?? 200.0
        next.customTimerMinutes = target.customTimerMinutes ?? 20
        next.dwellTime = target.dwellTime ?? next.dwellTime
        next.customTimerSeconds = target.customTimerSeconds ?? ((target.customTimerMinutes ?? 20) * 60)
        next.profileColor = target.color ?? .gray
        config = next
        selectedSlot = min(selectedSlot, max(config.itemCount - 1, 0))
        editorSlot = nil
        activationsSinceProfileChange = 0
        // Selecting or editing a profile must never start a return countdown.
        // The countdown is armed exclusively when an open Orbit is closed.
        cancelMainProfileReturnCountdown()
    }

    var mainProfileID: UUID? { config.mainProfileID }

    var mainProfileReturnMode: MainProfileReturnMode { .time }

    func setMainProfile(_ id: UUID?) {
        var next = snapshotWithCurrentProfile(config)
        next.mainProfileID = id
        if let id, var list = next.profiles, let index = list.firstIndex(where: { $0.id == id }) {
            let main = list.remove(at: index)
            list.insert(main, at: 0)
            next.profiles = list
        }
        config = next
        cancelMainProfileReturnCountdown()
    }

    func setMainProfileReturnMode(_ mode: MainProfileReturnMode) {
        // Kept only for older saved configs. Main-profile return is time based now.
        config.mainProfileReturnMode = .time
        cancelMainProfileReturnCountdown()
    }

    func setMainProfileReturnDelay(_ seconds: Double) {
        if seconds <= 0 {
            config.mainProfileReturnDelay = 0
            mainProfileReturnWorkItem?.cancel()
            mainProfileReturnWorkItem = nil
            mainProfileReturnDueAt = nil
        } else {
            config.mainProfileReturnDelay = min(max(seconds, 0.3), 600)
            cancelMainProfileReturnCountdown()
        }
    }

    func setMainProfileReturnActivationCount(_ count: Int) {
        config.mainProfileReturnActivationCount = min(max(count, 1), 10)
        activationsSinceProfileChange = 0
    }

    func noteSuccessfulActivation(from sourceProfileID: UUID?) {
        // Main-profile return is intentionally time based only.
        // The timer starts when the user switches away from the main profile.
    }

    private func preferredAutomaticProfile(for bundleIdentifier: String?) -> OrbitProfile? {
        preferredAutomaticProfile(in: eligibleProfiles(for: bundleIdentifier))
    }

    private func preferredAutomaticProfile(in eligible: [OrbitProfile]) -> OrbitProfile? {
        if let selected = eligible.first(where: { $0.scope == .selectedApps }) {
            return selected
        }
        return eligible.first(where: { $0.scope == .excludedApps })
    }

    private func matchingAutomaticProfileForCurrentApp() -> OrbitProfile? {
        guard let bundleID = NSWorkspace.shared.frontmostApplication?.bundleIdentifier,
              bundleID != Bundle.main.bundleIdentifier else { return nil }
        return preferredAutomaticProfile(for: bundleID)
    }

    private func scheduleMainProfileReturnIfNeeded() {
        mainProfileReturnWorkItem?.cancel()
        mainProfileReturnWorkItem = nil
        mainProfileReturnDueAt = nil
        guard let mainID = config.mainProfileID,
              config.activeProfileID != mainID,
              profiles.contains(where: { $0.id == mainID }),
              matchingAutomaticProfileForCurrentApp() == nil else { return }

        let configuredDelay = config.mainProfileReturnDelay ?? 60
        guard configuredDelay > 0 else { return }
        let delay = min(max(configuredDelay, 0.3), 600)
        mainProfileReturnDueAt = Date().addingTimeInterval(delay)
        let work = DispatchWorkItem { [weak self] in
            guard let self else { return }
            self.returnToMainProfileIfAllowed()
        }
        mainProfileReturnWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: work)
    }


    func scheduleMainProfileReturnAfterOrbitClosed() {
        // Always restart the countdown from the exact moment QuickOrbit closes.
        // If the active profile is already the main profile, or an app-specific
        // profile currently has priority, no countdown is needed.
        scheduleMainProfileReturnIfNeeded()
    }

    func setOrbitSessionActive(_ active: Bool) {
        guard orbitSessionActive != active else { return }
        orbitSessionActive = active
        objectWillChange.send()
        if active { cancelMainProfileReturnCountdown() }
    }

    func cancelMainProfileReturnCountdown() {
        mainProfileReturnWorkItem?.cancel()
        mainProfileReturnWorkItem = nil
        mainProfileReturnDueAt = nil
    }

    func applyPendingMainProfileReturnForOrbitIfNeeded() {
        guard let due = mainProfileReturnDueAt, due <= Date() else { return }
        returnToMainProfileIfAllowed()
    }

    private func returnToMainProfileIfAllowed() {
        // Never change the profile underneath an open field editor. Keep the due
        // return pending; closing the editor applies it safely afterwards.
        if orbitSessionActive || actionEditorIsOpen || editorSlot != nil || newlyCreatedEditorSlot != nil || NSApp.isActive { return }

        guard matchingAutomaticProfileForCurrentApp() == nil,
              let mainID = config.mainProfileID,
              config.activeProfileID != mainID,
              profiles.contains(where: { $0.id == mainID }) else {
            mainProfileReturnDueAt = nil
            return
        }
        mainProfileReturnDueAt = nil
        switchProfile(to: mainID, scheduleMainReturn: false)
    }

    var autoProfileSwitchEnabled: Bool {
        config.autoProfileSwitchEnabled ?? true
    }

    var profileLockEnabled: Bool {
        config.profileLockEnabled ?? false
    }

    var smartFlickEnabled: Bool {
        config.smartFlickEnabled ?? false
    }

    func setAutoProfileSwitchEnabled(_ enabled: Bool) {
        config.autoProfileSwitchEnabled = enabled
    }

    func setProfileLockEnabled(_ enabled: Bool) {
        config.profileLockEnabled = enabled
    }

    func applySizePreset(_ preset: OrbitSizePreset) {
        var next = config
        next.sizePreset = preset
        switch preset {
        case .compact:
            next.radius = 126
            next.tileScale = 0.90
            next.itemSpacing = 0.92
            next.highlightScale = 1.08
        case .comfortable:
            next.radius = 158
            next.tileScale = 1.00
            next.itemSpacing = 1.00
            next.highlightScale = 1.10
        case .large:
            next.radius = 192
            next.tileScale = 1.08
            next.itemSpacing = 1.06
            next.highlightScale = 1.12
        }
        config = next
    }

    func eligibleProfiles(for bundleIdentifier: String?) -> [OrbitProfile] {
        let all = snapshotProfiles()
        guard let bundleIdentifier, !bundleIdentifier.isEmpty else {
            // Without a real foreground application there is no automatic app
            // context. Keep only always-available profiles instead of guessing.
            return all.filter { $0.scope == .allApps }
        }
        return all.filter { profile in
            let ruleApps = profile.appsForCurrentScope
            let contains = ruleApps.contains { $0.bundleIdentifier == bundleIdentifier }
            switch profile.scope {
            case .allApps: return true
            case .selectedApps: return contains
            // An empty exception list is an unfinished rule, not a rule that
            // should unexpectedly take over every foreground application.
            case .excludedApps: return !ruleApps.isEmpty && !contains
            }
        }
    }

    func autoSelectProfile(for bundleIdentifier: String?) {
        // App changes caused by pickers or sheets must not replace the profile
        // whose field is currently being edited.
        guard !actionEditorIsOpen, editorSlot == nil else {
            pendingAutomaticBundleIdentifier = bundleIdentifier
            return
        }
        pendingAutomaticBundleIdentifier = nil
        guard autoProfileSwitchEnabled else { return }
        let eligible = eligibleProfiles(for: bundleIdentifier)
        if eligible.isEmpty {
            let all = snapshotProfiles()
            let fallback = config.mainProfileID.flatMap { mainID in all.first(where: { $0.id == mainID }) }
                ?? all.first(where: { $0.scope == .allApps })
                ?? all.first
            if let fallback, config.activeProfileID != fallback.id {
                switchProfile(to: fallback.id, scheduleMainReturn: false)
            }
            return
        }

        if let preferred = preferredAutomaticProfile(in: eligible) {
            if config.activeProfileID != preferred.id { switchProfile(to: preferred.id, scheduleMainReturn: false) }
            return
        }

        if let activeID = config.activeProfileID, eligible.contains(where: { $0.id == activeID }) {
            return
        }
        if let mainID = config.mainProfileID, eligible.contains(where: { $0.id == mainID }) {
            switchProfile(to: mainID, scheduleMainReturn: false)
        } else if let first = eligible.first, config.activeProfileID != first.id {
            switchProfile(to: first.id)
        }
    }

    func applyPendingAutomaticProfileIfNeeded() {
        guard !actionEditorIsOpen, editorSlot == nil,
              let bundleIdentifier = pendingAutomaticBundleIdentifier else { return }
        pendingAutomaticBundleIdentifier = nil
        autoSelectProfile(for: bundleIdentifier)
    }

    func addProfile() {
        guard profiles.count < 9 else { return }
        var next = snapshotWithCurrentProfile(config)
        var list = next.profiles ?? []
        let number = list.count + 1
        let palette: [OrbitProfileColor] = [.blue, .purple, .orange, .cyan, .pink, .green, .red, .yellow]
        var color = palette[(number - 1) % palette.count]
        if color == list.last?.color, let index = palette.firstIndex(of: color) {
            color = palette[(index + 1) % palette.count]
        }
        var profile = OrbitProfile.empty(name: "Profil \(number)", color: color)
        // A new profile remains immediately usable outside the settings. Its one
        // starter tile opens Quick Edit and can be replaced like every other tile.
        profile.itemCount = 1
        profile.items = (0..<16).map { OrbitItem.empty($0) }
        profile.items[0] = OrbitItem(
            title: qoText("Bearbeiten", "Edit", language: config.language),
            symbol: "slider.horizontal.3",
            type: .edit,
            target: "profiles",
            enabled: true
        )
        profile.dwellTime = 0.72
        list.append(profile)
        next.profiles = list
        next.activeProfileID = profile.id
        next.itemCount = profile.itemCount
        next.items = profile.items
        next.sizePreset = profile.sizePreset ?? .comfortable
        next.dwellTime = 0.72
        config = next
        selectedSlot = 0
        editorSlot = nil
        newlyCreatedEditorSlot = nil
    }

    func moveProfile(_ sourceID: UUID, before targetID: UUID) {
        guard sourceID != targetID else { return }
        var next = snapshotWithCurrentProfile(config)
        guard var list = next.profiles,
              let sourceIndex = list.firstIndex(where: { $0.id == sourceID }),
              let targetIndex = list.firstIndex(where: { $0.id == targetID }) else { return }

        // The main profile is pinned to slot 0. It cannot be dragged away and
        // no other profile may be inserted above it.
        if sourceID == next.mainProfileID { return }
        let moved = list.remove(at: sourceIndex)
        var destination = max(0, min(targetIndex, list.count))
        if next.mainProfileID != nil { destination = max(1, destination) }
        list.insert(moved, at: destination)

        if let mainID = next.mainProfileID,
           let mainIndex = list.firstIndex(where: { $0.id == mainID }), mainIndex != 0 {
            let main = list.remove(at: mainIndex)
            list.insert(main, at: 0)
        }
        next.profiles = list
        config = next
    }

    func deleteActiveProfile() {
        var next = snapshotWithCurrentProfile(config)
        guard var list = next.profiles, list.count > 1,
              let activeID = next.activeProfileID,
              let index = list.firstIndex(where: { $0.id == activeID }) else { return }

        QuickOrbitTimerCenter.shared.cancel(profileID: activeID)
        list.remove(at: index)
        if next.mainProfileID == activeID {
            next.mainProfileID = nil
            mainProfileReturnWorkItem?.cancel()
            mainProfileReturnWorkItem = nil
        }
        let targetIndex = min(index, list.count - 1)
        let target = list[targetIndex]
        next.profiles = list
        next.activeProfileID = target.id
        next.itemCount = target.itemCount
        next.items = target.items
        next.sizePreset = target.sizePreset ?? .comfortable
        next.layout = target.layout ?? .fan
        next.radius = target.radius ?? 155
        next.tileScale = target.tileScale ?? 1.0
        next.itemSpacing = target.itemSpacing ?? 1.0
        next.highlightScale = target.highlightScale ?? 1.12
        next.showLabels = target.showLabels ?? true
        next.showGuide = target.showGuide ?? true
        next.showOuterGuide = target.showOuterGuide ?? false
        next.showProfileDots = target.showProfileDots ?? true
        next.profileDotsHorizontalOffset = target.profileDotsHorizontalOffset ?? 200.0
        next.dwellTime = target.dwellTime ?? 0.72
        next.profileColor = target.color ?? .gray
        config = next
        selectedSlot = 0
        editorSlot = nil
    }

    func renameActiveProfile(_ name: String) {
        updateActiveProfileMetadata { profile in
            profile.name = String(name.prefix(28))
        }
    }

    func setActiveProfileScope(_ scope: OrbitProfileScope) {
        updateActiveProfileMetadata { profile in
            profile.scope = scope
            if profile.includedApps == nil { profile.includedApps = [] }
            if profile.excludedApps == nil { profile.excludedApps = [] }
        }
    }

    func addAppsToActiveProfile(urls: [URL]) {
        let candidates: [OrbitProfileApp] = urls.compactMap { url in
            guard url.pathExtension.lowercased() == "app",
                  let bundle = Bundle(url: url),
                  let identifier = bundle.bundleIdentifier else { return nil }

            let displayName = (bundle.object(forInfoDictionaryKey: "CFBundleDisplayName") as? String)
                ?? (bundle.object(forInfoDictionaryKey: "CFBundleName") as? String)
                ?? url.deletingPathExtension().lastPathComponent
            return OrbitProfileApp(name: displayName, bundleIdentifier: identifier, path: url.path)
        }
        guard !candidates.isEmpty else { return }

        updateActiveProfileMetadata { profile in
            switch profile.scope {
            case .allApps:
                return
            case .selectedApps:
                var apps = profile.includedApps ?? []
                for app in candidates where !apps.contains(where: { $0.bundleIdentifier == app.bundleIdentifier }) {
                    apps.append(app)
                }
                profile.includedApps = apps
            case .excludedApps:
                var apps = profile.excludedApps ?? []
                for app in candidates where !apps.contains(where: { $0.bundleIdentifier == app.bundleIdentifier }) {
                    apps.append(app)
                }
                profile.excludedApps = apps
            }
        }
    }

    func removeAppFromActiveProfile(_ app: OrbitProfileApp) {
        updateActiveProfileMetadata { profile in
            switch profile.scope {
            case .allApps:
                return
            case .selectedApps:
                var apps = profile.includedApps ?? []
                apps.removeAll { $0.bundleIdentifier == app.bundleIdentifier }
                profile.includedApps = apps
            case .excludedApps:
                var apps = profile.excludedApps ?? []
                apps.removeAll { $0.bundleIdentifier == app.bundleIdentifier }
                profile.excludedApps = apps
            }
        }
    }

    private func updateActiveProfileMetadata(_ update: (inout OrbitProfile) -> Void) {
        var next = snapshotWithCurrentProfile(config)
        guard var list = next.profiles,
              let id = next.activeProfileID,
              let index = list.firstIndex(where: { $0.id == id }) else { return }
        update(&list[index])
        next.profiles = list
        config = next
    }

    private func snapshotProfiles() -> [OrbitProfile] {
        snapshotWithCurrentProfile(config).profiles ?? []
    }

    private func snapshotWithCurrentProfile(_ source: QuickOrbitConfig) -> QuickOrbitConfig {
        var value = source
        guard var list = value.profiles,
              let id = value.activeProfileID,
              let index = list.firstIndex(where: { $0.id == id }) else { return value }
        list[index].itemCount = value.itemCount
        list[index].dwellTime = value.dwellTime
        list[index].items = Self.normalizedItems(value.items, count: value.itemCount)
        list[index].sizePreset = value.sizePreset
        list[index].layout = value.layout
        list[index].radius = value.radius
        list[index].tileScale = value.tileScale
        list[index].itemSpacing = value.itemSpacing
        list[index].highlightScale = value.highlightScale
        list[index].showLabels = value.showLabels
        list[index].showGuide = value.showGuide
        list[index].showOuterGuide = value.showOuterGuide
        list[index].showProfileDots = value.showProfileDots
        list[index].profileDotsHorizontalOffset = value.profileDotsHorizontalOffset
        list[index].customTimerMinutes = min(max(value.customTimerMinutes ?? 20, 1), 180)
        list[index].customTimerSeconds = min(max(value.customTimerSeconds ?? ((value.customTimerMinutes ?? 20) * 60), 5), 10_800)
        list[index].color = value.profileColor
        value.profiles = list
        return value
    }

    func applySelectionTimeToAllProfiles() {
        var next = snapshotWithCurrentProfile(config)
        if var list = next.profiles {
            for index in list.indices { list[index].dwellTime = next.dwellTime }
            next.profiles = list
        }
        config = next
    }

    func setShowLabels(_ enabled: Bool) {
        var next = snapshotWithCurrentProfile(config)
        next.showLabels = enabled

        if var list = next.profiles,
           let id = next.activeProfileID,
           let index = list.firstIndex(where: { $0.id == id }) {
            list[index].showLabels = enabled
            next.profiles = list
        }

        config = next
    }

    func setCustomTimerMinutes(_ minutes: Int) {
        let safeMinutes = min(max(minutes, 1), 180)
        var next = snapshotWithCurrentProfile(config)
        next.customTimerMinutes = safeMinutes
        if var list = next.profiles,
           let id = next.activeProfileID,
           let index = list.firstIndex(where: { $0.id == id }) {
            list[index].customTimerMinutes = safeMinutes
            next.profiles = list
        }
        config = next
    }

    func setCustomTimerSeconds(_ seconds: Int) {
        let safeSeconds = min(max(seconds, 5), 10_800)
        var next = snapshotWithCurrentProfile(config)
        next.customTimerSeconds = safeSeconds
        if var list = next.profiles,
           let id = next.activeProfileID,
           let index = list.firstIndex(where: { $0.id == id }) {
            list[index].customTimerSeconds = safeSeconds
            next.profiles = list
        }
        config = next
    }

    func setShowOuterGuide(_ enabled: Bool) {
