    }

    func setShowProfileDots(_ enabled: Bool) {
        var next = snapshotWithCurrentProfile(config)
        next.showProfileDots = enabled

        if var list = next.profiles,
           let id = next.activeProfileID,
           let index = list.firstIndex(where: { $0.id == id }) {
            list[index].showProfileDots = enabled
            next.profiles = list
        }

        config = next
    }

    func setProfileDotsHorizontalOffset(_ offset: Double) {
        let raw = min(max(offset, -240), 240)
        // Magnetic center: when the slider comes close to zero it locks exactly
        // to the orbit center instead of leaving an imprecise value such as 3 pt.
        let clamped = abs(raw) <= 18 ? 0.0 : raw
        var next = snapshotWithCurrentProfile(config)
        next.profileDotsHorizontalOffset = clamped

        if var list = next.profiles,
           let id = next.activeProfileID,
           let index = list.firstIndex(where: { $0.id == id }) {
            list[index].profileDotsHorizontalOffset = clamped
            next.profiles = list
        }

        config = next
    }

    func reset() {
        // A real factory reset: profiles, settings, language, legal confirmation,
        // onboarding, statistics and every running per-profile tool are cleared.
        QuickOrbitTimerCenter.shared.cancelAll()
        QuickOrbitUsageStatsCenter.shared.reset()
        QuickOrbitClipboardHistoryCenter.shared.clear()
        QuickOrbitDiagnostics.shared.clear()
        QuickOrbitDiagnostics.shared.enabled = true
        UNUserNotificationCenter.current().removePendingNotificationRequests(withIdentifiers: ["quickorbit.low-battery"])
        UNUserNotificationCenter.current().removeDeliveredNotifications(withIdentifiers: ["quickorbit.low-battery"])
        saveWorkItem?.cancel()
        saveWorkItem = nil
        UserDefaults.standard.removeObject(forKey: storageKey)
        UserDefaults.standard.removeObject(forKey: oldStorageKey)
        config = QuickOrbitConfig.fresh
        selectedSlot = 0
        editorSlot = nil
        newlyCreatedEditorSlot = nil
        cancelMainProfileReturnCountdown()
        QuickOrbitMenuDockStore.shared.reset()
        StatusBarController.shared.resetQuickDockPosition()
    }

    func setLanguage(_ language: AppLanguage) {
        var value = config
        value.language = language

        func translatedProfileName(_ name: String) -> String {
            switch (language, name) {
            case (.english, "Allgemein"): return "General"
            case (.english, "Freizeit"): return "Leisure"
            case (.english, "Schule"): return "School"
            case (.english, "Medien"): return "Media"
            case (.german, "General"): return "Allgemein"
            case (.german, "Leisure"): return "Freizeit"
            case (.german, "School"): return "Schule"
            case (.german, "Media"): return "Medien"
            default: return name
            }
        }

        func translatedItemTitle(_ title: String) -> String {
            var deToEn = [
                "Fotos": "Photos", "Nachrichten": "Messages", "Notizen": "Notes",
                "Musik": "Music", "Kalender": "Calendar", "Dateien": "Files",
                "Schreibtisch": "Desktop", "Papierkorb": "Trash", "Benutzerordner": "Home folder",
                "Rechner": "Calculator", "Leer": "Empty", "Webseite": "Website"
            ]
            for preset in SystemActionPreset.all {
                deToEn[preset.titleDE] = preset.titleEN
            }
            if language == .english { return deToEn[title] ?? title }
            let enToDe = Dictionary(uniqueKeysWithValues: deToEn.map { ($0.value, $0.key) })
            return enToDe[title] ?? title
        }

        var profiles = value.profiles ?? []
        for p in profiles.indices {
            profiles[p].name = translatedProfileName(profiles[p].name)
            for i in profiles[p].items.indices where profiles[p].items[i].enabled {
                profiles[p].items[i].title = translatedItemTitle(profiles[p].items[i].title)
            }
        }
        value.profiles = profiles
        for i in value.items.indices where value.items[i].enabled {
            value.items[i].title = translatedItemTitle(value.items[i].title)
        }
        if var menuItems = value.menuBarQuickItems {
            for i in menuItems.indices where menuItems[i].enabled {
                menuItems[i].title = translatedItemTitle(menuItems[i].title)
            }
            value.menuBarQuickItems = menuItems
        }
        config = value
    }

    private func scheduleSave() {
        saveWorkItem?.cancel()
        let work = DispatchWorkItem { [weak self] in
            guard let self else { return }
            self.saveWorkItem = nil
            self.saveNow()
        }
        saveWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.32, execute: work)
    }

    func flushPendingSave() {
        guard saveWorkItem != nil else { return }
        saveWorkItem?.cancel()
        saveWorkItem = nil
        saveNow()
    }

    private func saveNow() {
        let snapshot = snapshotWithCurrentProfile(config)
        guard let data = try? JSONEncoder().encode(snapshot) else { return }
        UserDefaults.standard.set(data, forKey: storageKey)
    }

    private static func normalizedItems(_ source: [OrbitItem], count: Int) -> [OrbitItem] {
        var result = source.map(removingDeprecatedAction)
        while result.count < 16 { result.append(.empty(result.count)) }
        result = Array(result.prefix(16))

        return result
    }

    private static func starterEditItem(language: AppLanguage?) -> OrbitItem {
        OrbitItem(
            title: qoText("Bearbeiten", "Edit", language: language),
            symbol: "slider.horizontal.3",
            type: .edit,
            target: "profiles",
            enabled: true
        )
    }

    private static func compactedItems(_ source: [OrbitItem], count: Int) -> [OrbitItem] {
        Array(source.prefix(min(max(count, 0), 16)))
            .map(removingDeprecatedAction)
            .filter(\.enabled)
    }

    private static func normalizedMenuBarItems(_ source: [OrbitItem]) -> [OrbitItem] {
        var result = source.map(removingDeprecatedAction)
        while result.count < 3 { result.append(.empty(result.count)) }
        result = Array(result.prefix(3))
        return result
    }

    private static func removingDeprecatedAction(_ item: OrbitItem) -> OrbitItem {
        // Old profiles may still contain either retired password tile. Replace
        // both before rendering or saving, without touching Keychain data.
        if ["securePassword", "passwordVault"].contains(item.target) {
            var empty = OrbitItem.empty(0)
            empty.id = item.id
            return empty
        }
        switch item.type {
        case .shortcut, .clipboard, .windowLeft, .windowRight:
            var empty = OrbitItem.empty(0)
            empty.id = item.id
            return empty
        default:
            var migrated = item
            if migrated.type == .systemAction && migrated.target.hasPrefix("timer") {
                migrated.type = .timer
            } else if migrated.type == .systemAction,
                      SystemActionPreset.preset(for: migrated.target)?.isWindowManagement == true {
                migrated.type = .windowManagement
            }
            return migrated
        }
    }

    private static func fixed(_ source: QuickOrbitConfig) -> QuickOrbitConfig {
        var value = source
        let compactedCurrent = compactedItems(value.items, count: value.itemCount)
        value.itemCount = compactedCurrent.count
        value.items = normalizedItems(compactedCurrent, count: value.itemCount)

        var list = value.profiles ?? []
        if list.isEmpty {
            let starter = QuickOrbitConfig.fresh
            list = starter.profiles ?? []
            value.activeProfileID = starter.activeProfileID
            value.macToolsProfileInstalled = true
            value.mediaProfileInstalled = true
        }

        // Install the new Mac Tools starter profile once for existing users.
        // The marker is then set permanently, so deleting the profile remains respected.
        if value.macToolsProfileInstalled != true, list.count < 9 {
            let starter = QuickOrbitConfig.fresh
            if let macTools = starter.profiles?.first(where: { $0.name == "Mac Tools" }) {
                list.append(macTools)
            }
            value.macToolsProfileInstalled = true
        }

        // Install the Media starter profile once for existing users. If the profile
        // list is already full, remember the migration so QuickOrbit doesn't retry forever.
        if value.mediaProfileInstalled != true {
            if list.count < 9 {
                let starter = QuickOrbitConfig.fresh
                if var media = starter.profiles?.first(where: { $0.name == "Medien" || $0.name == "Media" }) {
                    if value.language == .english {
                        media.name = "Media"
                        for index in media.items.indices where media.items[index].enabled {
                            if let preset = SystemActionPreset.preset(for: media.items[index].target) {
                                media.items[index].title = preset.title(language: .english)
                            }
                        }
                    }
                    list.append(media)
                }
            }
            value.mediaProfileInstalled = true
        }

        if value.emojiProfileInstalled != true {
            let hasEmojiProfile = list.contains { profile in
                let enabled = profile.items.prefix(profile.itemCount).filter(\.enabled)
                return !enabled.isEmpty && enabled.allSatisfy { $0.type == .emoji }
            }
            if !hasEmojiProfile, list.count < 9 { list.append(QuickOrbitEmojiTemplate.profile) }
            value.emojiProfileInstalled = true
        }

        for index in list.indices {
            if list[index].includedApps == nil && list[index].excludedApps == nil {
                switch list[index].scope {
                case .selectedApps:
                    list[index].includedApps = list[index].apps
                    list[index].excludedApps = []
                case .excludedApps:
                    list[index].includedApps = []
                    list[index].excludedApps = list[index].apps
                case .allApps:
                    list[index].includedApps = []
                    list[index].excludedApps = []
                }
            } else {
                if list[index].includedApps == nil { list[index].includedApps = [] }
                if list[index].excludedApps == nil { list[index].excludedApps = [] }
            }
            list[index].apps = []

            let compacted = compactedItems(list[index].items, count: list[index].itemCount)
            if compacted.isEmpty {
                list[index].itemCount = 1
                list[index].items = normalizedItems([starterEditItem(language: value.language)], count: 1)
            } else {
                list[index].itemCount = compacted.count
                list[index].items = normalizedItems(compacted, count: list[index].itemCount)
            }
            if list[index].sizePreset == nil { list[index].sizePreset = .comfortable }
            if list[index].layout == nil { list[index].layout = .fan }
            if list[index].radius == nil { list[index].radius = 155 }
            if list[index].tileScale == nil { list[index].tileScale = 1.0 }
            if list[index].itemSpacing == nil { list[index].itemSpacing = 1.0 }
            if list[index].highlightScale == nil { list[index].highlightScale = 1.12 }
            if list[index].showLabels == nil { list[index].showLabels = true }
            if list[index].showGuide == nil { list[index].showGuide = true }
            if list[index].showOuterGuide == nil { list[index].showOuterGuide = list[index].showGuide ?? false }
            if list[index].showProfileDots == nil { list[index].showProfileDots = true }
            if list[index].profileDotsHorizontalOffset == nil { list[index].profileDotsHorizontalOffset = 200.0 }
            if list[index].customTimerMinutes == nil { list[index].customTimerMinutes = 20 }
            list[index].dwellTime = min(max(list[index].dwellTime ?? value.dwellTime, 0.24), 3)
            list[index].customTimerMinutes = min(max(list[index].customTimerMinutes ?? 20, 1), 180)
            if list[index].customTimerSeconds == nil { list[index].customTimerSeconds = (list[index].customTimerMinutes ?? 20) * 60 }
            list[index].customTimerSeconds = min(max(list[index].customTimerSeconds ?? 300, 5), 10_800)
            list[index].profileDotsHorizontalOffset = min(max(list[index].profileDotsHorizontalOffset ?? 0.0, -240), 240)
            if list[index].color == nil { list[index].color = OrbitProfileColor.allCases[index % OrbitProfileColor.allCases.count] }

            let loweredName = list[index].name.lowercased()
            if loweredName == "allgemein" || loweredName == "general" {
                list[index].color = .blue
            } else if loweredName == "freizeit" || loweredName == "leisure" {
                list[index].color = .green
            } else if loweredName == "schule" || loweredName == "school" {
                list[index].color = .purple
            } else if loweredName == "mac tools" {
                list[index].color = .cyan
            }
        }
        list = Array(list.prefix(9))
        value.profiles = list

        if value.activeProfileID == nil || !list.contains(where: { $0.id == value.activeProfileID }) {
            value.activeProfileID = list.first?.id
        }

        if let id = value.activeProfileID, let active = list.first(where: { $0.id == id }) {
            value.itemCount = active.itemCount
            value.items = active.items
            value.sizePreset = active.sizePreset ?? .comfortable
            value.layout = active.layout ?? .fan
            value.radius = active.radius ?? 155
            value.tileScale = active.tileScale ?? 1.0
            value.itemSpacing = active.itemSpacing ?? 1.0
            value.highlightScale = active.highlightScale ?? 1.12
            value.showLabels = active.showLabels ?? true
            value.showGuide = active.showGuide ?? true
            value.showOuterGuide = active.showOuterGuide ?? false
            value.showProfileDots = active.showProfileDots ?? true
            value.profileDotsHorizontalOffset = active.profileDotsHorizontalOffset ?? 200.0
            value.customTimerMinutes = active.customTimerMinutes ?? 20
            value.dwellTime = active.dwellTime ?? value.dwellTime
            value.customTimerSeconds = active.customTimerSeconds ?? ((active.customTimerMinutes ?? 20) * 60)
            value.profileColor = active.color ?? .gray
        }

        value.menuBarQuickItems = normalizedMenuBarItems(value.menuBarQuickItems ?? [])
        if value.menuBarDefaultsInstalled != true {
            if value.menuBarQuickItems?.contains(where: { $0.enabled }) != true {
                value.menuBarQuickItems = [
                    OrbitItem(title: "QuickOrbit", symbol: "circle.grid.cross", type: .app, target: Bundle.main.bundlePath, enabled: true),
                    OrbitItem(title: "Kalender", symbol: "calendar", type: .app, target: "/System/Applications/Calendar.app", enabled: true),
                    OrbitItem(title: "Mail", symbol: "envelope.fill", type: .app, target: "/System/Applications/Mail.app", enabled: true)
                ]
            }
            value.menuBarDefaultsInstalled = true
        }
        if value.menuBarMailDefaultMigrationDone != true {
            var quickItems = normalizedMenuBarItems(value.menuBarQuickItems ?? [])
            if quickItems.indices.contains(2), !quickItems[2].enabled {
                quickItems[2] = OrbitItem(title: "Mail", symbol: "envelope.fill", type: .app, target: "/System/Applications/Mail.app", enabled: true)
                value.menuBarQuickItems = quickItems
            }
            value.menuBarMailDefaultMigrationDone = true
        }
        if value.trackpadHoldEnabled == nil { value.trackpadHoldEnabled = false }
        if value.trackpadHoldDuration == nil { value.trackpadHoldDuration = 3.0 }
        value.trackpadHoldDuration = min(max(value.trackpadHoldDuration ?? 3.0, 1.0), 6.0)
        if value.mouseHoldEnabled == nil { value.mouseHoldEnabled = false }
        if value.mouseHoldDuration == nil { value.mouseHoldDuration = 2.0 }
        value.mouseHoldDuration = min(max(value.mouseHoldDuration ?? 2.0, 0.8), 5.0)
        if value.appearance == nil { value.appearance = .system }
        if value.designStyle == nil { value.designStyle = .settings }
        if value.orbitAutoSelect == nil { value.orbitAutoSelect = true }
        if value.orbitAnimationLevel == nil { value.orbitAnimationLevel = .subtle }
        if value.orbitAnimationDuration == nil { value.orbitAnimationDuration = 0.38 }
        if value.energySavingMode == nil { value.energySavingMode = false }
        if value.lowBatteryWarningEnabled == nil { value.lowBatteryWarningEnabled = false }
        // The Orbit tile deliberately has one clear behavior instead of another
        // hidden setting: on means one warning at 20% per discharge cycle.
        value.lowBatteryWarningThreshold = 20
        value.orbitAnimationDuration = min(max(value.orbitAnimationDuration ?? 0.38, 0.16), 1.20)
        // Older builds exposed internal switches that are no longer part of the
        // interface. Keep profile automation predictable instead of allowing a
        // hidden saved value to disable or override foreground-app rules.
        value.autoProfileSwitchEnabled = true
        value.profileLockEnabled = false
        if value.singleMenuBarIconMigrationDone != true {
            value.menuBarEnabled = true
            value.singleMenuBarIconMigrationDone = true
        }
        if value.controlTapOpenEnabled == nil { value.controlTapOpenEnabled = false }
        if value.tapOpenModifier == nil { value.tapOpenModifier = .control }
        if value.orbitTileGlassEnabled == nil { value.orbitTileGlassEnabled = true }
        if value.profileDotsPosition == nil { value.profileDotsPosition = .right }
        if value.profileDotsScale == nil { value.profileDotsScale = 1.0 }
        if value.showProfileDots == nil { value.showProfileDots = true }
        if value.profileDotsHorizontalOffset == nil { value.profileDotsHorizontalOffset = 200.0 }
        if value.customTimerMinutes == nil { value.customTimerMinutes = 20 }
        value.customTimerMinutes = min(max(value.customTimerMinutes ?? 20, 1), 180)
        if value.customTimerSeconds == nil { value.customTimerSeconds = (value.customTimerMinutes ?? 20) * 60 }
        value.customTimerSeconds = min(max(value.customTimerSeconds ?? 300, 5), 10_800)
        if value.defaultMainProfileMigrationDone != true {
            value.mainProfileID = list.first(where: {
                let name = $0.name.lowercased()
                return name == "allgemein" || name == "general"
            })?.id ?? list.first?.id
            value.defaultMainProfileMigrationDone = true
        }
        value.selectedSafeDefaults()
        return value
    }
}

private extension QuickOrbitConfig {
    mutating func selectedSafeDefaults() {
        radius = min(max(radius, 95), 260)
        tileScale = min(max(tileScale, 0.72), 1.42)
        itemSpacing = min(max(itemSpacing, 0.68), 1.45)
        highlightScale = min(max(highlightScale, 1.0), 1.40)
        dwellTime = min(max(dwellTime, 0.24), 3.0)
        deadZone = min(max(deadZone, 24), 90)
        quickEditTravel = min(max(quickEditTravel, 12), 70)
        smartFlickVelocity = min(max(smartFlickVelocity ?? 980, 450), 2200)
        smartFlickDwell = min(max(smartFlickDwell ?? 0.16, 0.10), 0.30)
        profileDotsScale = min(max(profileDotsScale ?? 1.0, 0.72), 1.55)
        profileDotsHorizontalOffset = min(max(profileDotsHorizontalOffset ?? 0.0, -240), 240)
    }
}

// MARK: - Launch at login

@MainActor
final class LoginItemManager: ObservableObject {
    static let shared = LoginItemManager()

    @Published private(set) var status: SMAppService.Status = SMAppService.mainApp.status
    @Published private(set) var lastError: String?

    var isEnabled: Bool { status == .enabled }
    var isRequested: Bool { status == .enabled || status == .requiresApproval }

    func statusText(language: AppLanguage?) -> String {
        switch status {
        case .enabled: return qoText("Aktiv", "On", language: language)
        case .notRegistered: return qoText("Aus", "Off", language: language)
        case .requiresApproval: return qoText("Bestätigung in Systemeinstellungen nötig", "Approval required in System Settings", language: language)
        case .notFound: return qoText("Nicht verfügbar", "Unavailable", language: language)
        @unknown default: return qoText("Unbekannt", "Unknown", language: language)
        }
    }

    func refresh() {
        status = SMAppService.mainApp.status
    }

    func setEnabled(_ enabled: Bool) {
        lastError = nil
        do {
            if enabled {
                try SMAppService.mainApp.register()
            } else {
                try SMAppService.mainApp.unregister()
            }
        } catch {
            lastError = error.localizedDescription
        }
        refresh()
    }

    func openSettings() {
        SMAppService.openSystemSettingsLoginItems()
    }

    func enableByDefaultOnce() {
        let key = "QuickOrbit.didSetLoginDefault"
        guard !UserDefaults.standard.bool(forKey: key) else {
            refresh()
            return
        }
        UserDefaults.standard.set(true, forKey: key)
        if status == .notRegistered {
            setEnabled(true)
        } else {
            refresh()
        }
    }
}

// MARK: - Native HUD Glass appearance helpers

/// One fixed visual language for the whole app.
/// MAT-001 = background glass, MAT-002 = stronger within-window glass.
struct HUDGlass: NSViewRepresentable {
    let emphasized: Bool
    let blendingMode: NSVisualEffectView.BlendingMode

    init(
        emphasized: Bool = false,
        blendingMode: NSVisualEffectView.BlendingMode = .behindWindow
    ) {
        self.emphasized = emphasized
        self.blendingMode = blendingMode
    }

    func makeNSView(context: Context) -> NSVisualEffectView {
        let view = NSVisualEffectView()
        view.material = material
        view.blendingMode = blendingMode
        view.state = .active
        view.isEmphasized = emphasized
        return view
    }

    func updateNSView(_ nsView: NSVisualEffectView, context: Context) {
        if nsView.material != material { nsView.material = material }
        if nsView.blendingMode != blendingMode { nsView.blendingMode = blendingMode }
        if nsView.state != .active { nsView.state = .active }
        if nsView.isEmphasized != emphasized { nsView.isEmphasized = emphasized }
    }

    private var material: NSVisualEffectView.Material {
        (OrbitStore.shared.config.designStyle ?? .settings) == .home ? .popover : .hudWindow
    }
}

/// Keeps the normal macOS title bar and traffic-light buttons.
/// The window can only be moved from the native title bar, not from arbitrary content.
struct QuickOrbitWindowConfigurator: NSViewRepresentable {
    func makeNSView(context: Context) -> NSView {
        let view = NSView(frame: .zero)
        DispatchQueue.main.async { configure(view.window) }
        return view
    }

    func updateNSView(_ nsView: NSView, context: Context) {
        DispatchQueue.main.async { configure(nsView.window) }
    }

    private func configure(_ window: NSWindow?) {
        guard let window else { return }

        // The content now extends behind the native title bar. This removes the
        // separate dark strip while keeping Apple's real red/yellow/green buttons.
        window.styleMask.insert(.fullSizeContentView)
        window.isOpaque = false
        window.backgroundColor = .clear
        window.titleVisibility = .hidden
        window.titlebarAppearsTransparent = true
        window.isMovableByWindowBackground = false
        window.hasShadow = true
        window.styleMask.remove(.resizable)

        if #available(macOS 11.0, *) {
            window.titlebarSeparatorStyle = .none
        }

        // The HUD is designed for a compact desktop window. Full screen makes the
        // layout look sparse and breaks its intended proportions, so the green
        // full-screen/zoom control is hidden while edge resizing stays available.
        window.standardWindowButton(.closeButton)?.isHidden = false
        window.standardWindowButton(.miniaturizeButton)?.isHidden = false
        window.standardWindowButton(.zoomButton)?.isHidden = true
        window.standardWindowButton(.zoomButton)?.isEnabled = false
        window.collectionBehavior.insert(.fullScreenNone)
        // The compact HUD layout is intentionally fixed: it stays proportioned,
        // cannot be enlarged into an empty full-screen-like canvas, and can still
        // be moved through the native title bar as before.
        let fixedSize = NSSize(width: 1180, height: 800)
        window.minSize = fixedSize
        window.maxSize = fixedSize

        // Keep the titlebar host transparent as well. SwiftUI's SystemBackdrop can
        // then paint the same HUD material all the way to the top edge.
        window.contentView?.wantsLayer = true
        window.contentView?.layer?.backgroundColor = NSColor.clear.cgColor

        // SwiftUI/AppKit can leave an opaque hosting layer around the traffic lights
        // even with a transparent title bar. Clear that native frame host as well so
        // the same HUD material remains visible right up to the top window edge.
        var host = window.standardWindowButton(.closeButton)?.superview
        while let current = host, current !== window.contentView {
            current.wantsLayer = true
            current.layer?.backgroundColor = NSColor.clear.cgColor
            host = current.superview
        }
    }
}

