        let fill = prominent
            ? (colorScheme == .dark ? Color.white.opacity(configuration.isPressed ? 0.22 : 0.28) : Color.black.opacity(configuration.isPressed ? 0.36 : 0.43))
            : (colorScheme == .dark ? Color.white.opacity(configuration.isPressed ? 0.12 : 0.17) : Color.black.opacity(configuration.isPressed ? 0.07 : 0.10))
        configuration.label
            .modifier(QuickOrbitButtonLabel())
            .foregroundStyle(prominent ? Color.white : Color.primary.opacity(0.92))
            .background(fill, in: RoundedRectangle(cornerRadius: 10, style: .continuous))
            .overlay {
                RoundedRectangle(cornerRadius: 10, style: .continuous)
                    .stroke(prominent ? Color.white.opacity(homeStyle ? 0.34 : 0.24) : Color.primary.opacity(homeStyle ? 0.26 : 0.16), lineWidth: homeStyle ? 1.0 : 0.8)
            }
            .shadow(color: Color.black.opacity(prominent ? 0.10 : 0.035), radius: prominent ? 4 : 2, y: 1)
            .contentShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
            .opacity(configuration.isPressed ? 0.90 : 1)
            .modifier(QuickOrbitButtonFeedback(pressed: configuration.isPressed))
    }
}

