private struct QuickOrbitSelectionChoice: View {
    let title: String
    let language: AppLanguage?
    @Binding var automatic: Bool
    var showPreview = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var previewProgress = 0.0
    @State private var previewDone = false
    @State private var previewTask: Task<Void, Never>?

    var body: some View {
        VStack(alignment: .leading, spacing: 7) {
            Text(title).font(.subheadline.weight(.semibold))
            HStack(spacing: 10) {
                selectionButton(isAutomatic: true, symbol: "circle.dotted.circle", name: qoText("Automatisch", "Automatic", language: language), detail: qoText("Kurz verweilen", "Pause briefly", language: language))
                selectionButton(isAutomatic: false, symbol: "cursorarrow.click.2", name: qoText("Per Klick", "By click", language: language), detail: qoText("Direkt anklicken", "Click directly", language: language))
            }
            Text(automatic
                 ? qoText("Auswahlkreis läuft bis zur Aktion.", "Selection ring runs until the action starts.", language: language)
                 : qoText("Anklicken führt aus; kein Auswahlkreis.", "Click to run; no selection ring.", language: language))
                .font(.caption)
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)
            if showPreview {
                HStack(spacing: 12) {
                    Button {
                        if !automatic { previewDone = true }
                    } label: {
                        Image(systemName: previewDone ? "checkmark" : "sparkle")
                            .font(.system(size: 18, weight: .semibold))
                            .foregroundStyle(previewDone ? Color.green : Color.accentColor)
                            .frame(width: 46, height: 46)
                            .background(Color.accentColor.opacity(0.10), in: RoundedRectangle(cornerRadius: 13, style: .continuous))
                            .overlay {
                                Circle()
                                    .trim(from: 0, to: automatic ? previewProgress : 0)
                                    .stroke(Color.accentColor, style: StrokeStyle(lineWidth: 2.5, lineCap: .round))
                                    .frame(width: 49, height: 49)
                                    .rotationEffect(.degrees(-90))
                                    .allowsHitTesting(false)
                            }
                            .contentShape(RoundedRectangle(cornerRadius: 13, style: .continuous))
                    }
                    .buttonStyle(.plain)
                    .onHover { inside in
                        previewTask?.cancel()
                        previewDone = false
                        previewProgress = 0
                        guard inside, automatic else { return }
                        previewTask = Task { @MainActor in
                            await Task.yield()
                            guard !Task.isCancelled else { return }
                            withAnimation(reduceMotion ? nil : .linear(duration: 0.8)) { previewProgress = 1 }
                            try? await Task.sleep(nanoseconds: 800_000_000)
                            if !Task.isCancelled { previewDone = true }
                        }
                    }
                    VStack(alignment: .leading, spacing: 2) {
                        Text(qoText("Ausprobieren", "Try it", language: language))
                            .font(.caption.weight(.semibold))
                        Text(previewDone
                             ? qoText("Ausgewählt ✓", "Selected ✓", language: language)
                             : automatic
                                ? qoText("Zeiger kurz über dem Feld halten", "Hold the pointer over the tile", language: language)
                                : qoText("Auf das Feld klicken", "Click the tile", language: language))
                            .font(.caption2)
                            .foregroundStyle(.secondary)
                    }
                    Spacer(minLength: 0)
                }
                .padding(10)
                .quickOrbitTutorialGlass(cornerRadius: 15)
                .onChange(of: automatic) { _, _ in
                    previewTask?.cancel()
                    previewProgress = 0
                    previewDone = false
                }
                .onDisappear { previewTask?.cancel() }
            }
        }
    }

    private func selectionButton(isAutomatic: Bool, symbol: String, name: String, detail: String) -> some View {
        Button { automatic = isAutomatic } label: {
            VStack(alignment: .leading, spacing: 5) {
                HStack(spacing: 6) {
                    Image(systemName: symbol)
                        .font(.system(size: 16, weight: .semibold))
                        .foregroundStyle(automatic == isAutomatic ? Color.accentColor : Color.secondary)
                    Spacer(minLength: 2)
                    if automatic == isAutomatic {
                        Image(systemName: "checkmark.circle.fill")
                            .foregroundStyle(Color.accentColor)
                    }
                }
                Text(name).font(.subheadline.weight(.semibold))
                Text(detail).font(.caption2).foregroundStyle(.secondary)
            }
            .frame(maxWidth: .infinity, minHeight: 76, alignment: .leading)
            .padding(.horizontal, 12)
            .background(automatic == isAutomatic ? Color.accentColor.opacity(0.12) : Color.primary.opacity(0.035), in: RoundedRectangle(cornerRadius: 14, style: .continuous))
            .overlay {
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .stroke(automatic == isAutomatic ? Color.accentColor.opacity(0.54) : Color.primary.opacity(0.12), lineWidth: 1)
                    .allowsHitTesting(false)
            }
            .contentShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(automatic == isAutomatic ? [.isSelected] : [])
    }
}

