    /// Consistent surfaces using the selected HUD appearance.
    func quickOrbitGlass(cornerRadius: CGFloat = 14, interactive: Bool = false) -> some View {
        let style = OrbitStore.shared.config.designStyle ?? .settings
        let base = self
            .background {
                if style == .home {
                    Color.black.opacity(interactive ? 0.050 : 0.035)
                } else {
                    ZStack {
                        HUDGlass(emphasized: true, blendingMode: .withinWindow)
                        Color.black.opacity(interactive ? 0.024 : 0.018)
                    }
                }
            }
            .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
            .overlay {
                RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
                    .stroke(
                        style == .home
                            ? Color.primary.opacity(interactive ? 0.24 : 0.18)
                            : Color.white.opacity(interactive ? 0.11 : 0.085),
                        lineWidth: style == .home ? 0.9 : 0.6
                    )
                    .allowsHitTesting(false)
            }
            .quickOrbitTileHover(enabled: interactive)
        return base
    }

    @ViewBuilder
    func quickOrbitTutorialGlass(cornerRadius: CGFloat) -> some View {
        if #available(macOS 26.0, *) {
            self.glassEffect(.regular, in: .rect(cornerRadius: cornerRadius))
        } else {
            self.quickOrbitGlass(cornerRadius: cornerRadius)
        }
    }

    func quickOrbitSurface(cornerRadius: CGFloat, emphasized: Bool = false) -> some View {
        let style = OrbitStore.shared.config.designStyle ?? .settings
        return self
            .background {
                if style == .home {
                    Color.black.opacity(emphasized ? 0.055 : 0.035)
                } else {
                    ZStack {
                        HUDGlass(emphasized: false, blendingMode: .withinWindow)
                        Color.black.opacity(emphasized ? 0.030 : 0.018)
                    }
                    .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
                }
            }
            .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
    }

    /// Kept for source compatibility. HUD Glass uses calm fades instead of matched glass morphs.
    func quickOrbitGlassIdentity<ID: Hashable & Sendable>(_ id: ID, in namespace: Namespace.ID, matched: Bool = true) -> some View {
        self
    }

    func quickOrbitGlassButton(prominent: Bool = false) -> some View {
        self.buttonStyle(HUDGlassButtonStyle(prominent: prominent))
    }

    func quickOrbitSolidButton(prominent: Bool = false) -> some View {
        self.buttonStyle(QuickOrbitSolidButtonStyle(prominent: prominent))
    }

    fileprivate func quickOrbitColorButton(_ color: QuickOrbitButtonColor) -> some View {
        self.buttonStyle(QuickOrbitColorButtonStyle(color: color))
    }

    func quickOrbitDiscordButton() -> some View {
        self.buttonStyle(QuickOrbitDiscordButtonStyle())
    }
}

