// MARK: - App icons and installed apps

@MainActor
enum IconHelper {
    static func image(for item: OrbitItem) -> NSImage? {
        guard item.type == .app, !item.target.isEmpty,
              FileManager.default.fileExists(atPath: item.target) else { return nil }
        return AppIconCache.shared.icon(for: item.target)
    }
}

@MainActor
final class AppIconCache {
    static let shared = AppIconCache()
    private let cache = NSCache<NSString, NSImage>()

    func icon(for path: String) -> NSImage {
        let key = path as NSString
        if let cached = cache.object(forKey: key) { return cached }
        let image = NSWorkspace.shared.icon(forFile: path)
        cache.setObject(image, forKey: key)
        return image
    }
}

struct InstalledAppChoice: Identifiable, Hashable {
    let id: String
    let name: String
    let url: URL

    @MainActor
    var icon: NSImage {
        AppIconCache.shared.icon(for: url.path)
    }

    static func == (lhs: InstalledAppChoice, rhs: InstalledAppChoice) -> Bool {
        lhs.id == rhs.id
    }

    func hash(into hasher: inout Hasher) {
        hasher.combine(id)
    }
}

enum InstalledApps {
    // The application list is stable during a normal QuickOrbit session.
    // Cache it once so opening Quick Edit / Action Editor feels immediate.
    private static let cachedList: [InstalledAppChoice] = scan()

    static func cached() -> [InstalledAppChoice] {
        cachedList
    }

    static func scan() -> [InstalledAppChoice] {
        let roots = [
            URL(fileURLWithPath: "/Applications"),
            URL(fileURLWithPath: "/System/Applications"),
            FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Applications", isDirectory: true)
        ]

        var seen = Set<String>()
        var result: [InstalledAppChoice] = []

        for root in roots {
            guard let urls = try? FileManager.default.contentsOfDirectory(
                at: root,
                includingPropertiesForKeys: nil,
                options: [.skipsHiddenFiles]
            ) else { continue }

            for url in urls where url.pathExtension.lowercased() == "app" {
                let path = url.path
                guard !seen.contains(path) else { continue }
                seen.insert(path)
                result.append(
                    InstalledAppChoice(
                        id: path,
                        name: url.deletingPathExtension().lastPathComponent,
                        url: url
                    )
                )
            }
        }

        let priority = [
            "Safari", "Mail", "Messages", "Nachrichten", "Notes", "Notizen",
            "Calendar", "Kalender", "Music", "Fotos", "Photos", "Preview", "Vorschau"
        ]

        return result.sorted { a, b in
            let ai = priority.firstIndex(of: a.name) ?? 999
            let bi = priority.firstIndex(of: b.name) ?? 999
            if ai != bi { return ai < bi }
            return a.name.localizedCaseInsensitiveCompare(b.name) == .orderedAscending
        }
    }
}

// MARK: - Small user-facing notices

enum QuickOrbitDiagnosticCode: String, Codable, CaseIterable {
    case invalidAction, destinationUnavailable, accessibilityRequired
    case commandRejected, commandFailed, captureFailed, recognitionFailed
    case translationFailed, calendarFailed, clipboardFailed, reportExportFailed

    func message(language: AppLanguage?) -> String {
        switch self {
        case .invalidAction: return qoText("Aktion unvollständig oder nicht verfügbar. Belegung prüfen.", "Action incomplete or unavailable. Check its configuration.", language: language)
        case .destinationUnavailable: return qoText("Ziel konnte nicht geöffnet werden. App oder Datei erneut auswählen.", "Destination could not be opened. Choose the app or file again.", language: language)
        case .accessibilityRequired: return qoText("Bedienungshilfe fehlt. Unter Info → Systemzugriff freigeben.", "Accessibility is required. Grant access under Info → System access.", language: language)
        case .commandRejected: return qoText("Terminal-Befehl wurde vor der Ausführung abgelehnt.", "Terminal command was rejected before execution.", language: language)
        case .commandFailed: return qoText("Terminal-Befehl konnte nicht erfolgreich abgeschlossen werden.", "Terminal command could not complete successfully.", language: language)
        case .captureFailed: return qoText("Bildschirmaufnahme konnte nicht gestartet werden. Systemzugriff prüfen.", "Screen capture could not start. Check system access.", language: language)
        case .recognitionFailed: return qoText("Texterkennung fehlgeschlagen. Einen besser lesbaren Bereich auswählen.", "Text recognition failed. Choose a more legible area.", language: language)
        case .translationFailed: return qoText("Übersetzung fehlgeschlagen. Sprache und Verfügbarkeit prüfen.", "Translation failed. Check language and availability.", language: language)
        case .calendarFailed: return qoText("Termin oder Erinnerung konnte nicht gespeichert werden. Kalenderzugriff prüfen.", "Event or reminder could not be saved. Check calendar access.", language: language)
        case .clipboardFailed: return qoText("Zwischenablage konnte nicht beschrieben werden. Erneut versuchen.", "Could not write to the clipboard. Try again.", language: language)
        case .reportExportFailed: return qoText("Report konnte nicht gespeichert werden. Einen anderen Speicherort wählen.", "Could not save the report. Choose another location.", language: language)
        }
    }
}

struct QuickOrbitDiagnosticEntry: Codable, Identifiable {
    let id: UUID
    let code: QuickOrbitDiagnosticCode
    var date: Date
    var count: Int
}

/// Only allowlisted codes enter this store. Never pass exception descriptions,
/// commands, targets, paths, clipboard contents, or user-entered text here.
@MainActor
final class QuickOrbitDiagnostics: ObservableObject {
    static let shared = QuickOrbitDiagnostics()
    static let maximumEntries = 100
    private let defaults: UserDefaults
    private let key = "QuickOrbit.Diagnostics.v1"
    @Published private(set) var entries: [QuickOrbitDiagnosticEntry]
    @Published var enabled: Bool {
        didSet { defaults.set(enabled, forKey: "QuickOrbit.Diagnostics.Enabled") }
    }

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        enabled = defaults.object(forKey: "QuickOrbit.Diagnostics.Enabled") as? Bool ?? true
        if let data = defaults.data(forKey: key), let saved = try? JSONDecoder().decode([QuickOrbitDiagnosticEntry].self, from: data) {
            entries = Array(saved.suffix(Self.maximumEntries))
        } else { entries = [] }
    }

    func record(_ code: QuickOrbitDiagnosticCode) {
        guard enabled else { return }
        let now = Date()
        if let last = entries.last, last.code == code, now.timeIntervalSince(last.date) < 5 {
            entries[entries.count - 1].count = min(last.count + 1, 9999)
            entries[entries.count - 1].date = now
        } else {
            entries.append(.init(id: UUID(), code: code, date: now, count: 1))
            entries = Array(entries.suffix(Self.maximumEntries))
        }
        if let data = try? JSONEncoder().encode(entries) { defaults.set(data, forKey: key) }
    }

    func clear() {
        entries = []
        defaults.removeObject(forKey: key)
    }

    func report() -> String {
        struct Event: Encodable { let code: QuickOrbitDiagnosticCode; let count: Int }
        struct Report: Encodable {
            let formatVersion: Int
            let appVersion: String
            let macOS: String
            let events: [Event]
        }
        let os = ProcessInfo.processInfo.operatingSystemVersion
        let version = (Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? "56")
            .filter { "0123456789.".contains($0) }
        let report = Report(formatVersion: 1, appVersion: String(version.prefix(20)),
                            macOS: "\(os.majorVersion).\(os.minorVersion)",
                            events: entries.map { Event(code: $0.code, count: $0.count) })
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        guard let data = try? encoder.encode(report), let text = String(data: data, encoding: .utf8) else { return "{}" }
        return text
    }
}

private struct QuickOrbitDiagnosticsView: View {
    @ObservedObject private var diagnostics = QuickOrbitDiagnostics.shared
    @ObservedObject private var store = OrbitStore.shared
    @State private var showReport = false
    @State private var showClear = false
    @State private var report = ""
    @State private var exportError: String?

    var body: some View {
        GlassCard(title: qoText("Diagnose & Fehlerreport", "Diagnostics & error report", language: store.config.language), symbol: "stethoscope") {
            VStack(alignment: .leading, spacing: 12) {
                Toggle(qoText("Fehler lokal protokollieren", "Log errors locally", language: store.config.language), isOn: $diagnostics.enabled)
                Text(qoText("Maximal 100 Einträge, nur auf diesem Mac. Der Report enthält Fehlercodes, Häufigkeiten sowie App- und macOS-Version. Keine Inhalte, Pfade, Namen, Kennungen oder genauen Zeitangaben. Es wird nichts automatisch gesendet.", "Up to 100 entries, only on this Mac. Reports include error codes, counts, and app/macOS versions. No contents, paths, names, identifiers, or exact timestamps. Nothing is sent automatically.", language: store.config.language))
                    .font(.caption).foregroundStyle(.secondary)
                if diagnostics.entries.isEmpty {
                    Label(qoText("Noch keine Fehler protokolliert", "No errors recorded yet", language: store.config.language), systemImage: "checkmark.circle")
                        .font(.callout).foregroundStyle(.secondary)
                } else {
                    ScrollView(.vertical, showsIndicators: false) {
                        LazyVStack(alignment: .leading, spacing: 10) {
                            ForEach(diagnostics.entries.reversed()) { entry in
                                HStack(alignment: .top, spacing: 10) {
                                    Image(systemName: "exclamationmark.circle.fill").foregroundStyle(.orange)
                                    VStack(alignment: .leading, spacing: 3) {
                                        Text(entry.code.message(language: store.config.language)).font(.callout)
                                        Text("\(entry.date.formatted(date: .abbreviated, time: .shortened)) · \(entry.count)×")
                                            .font(.caption).foregroundStyle(.secondary)
                                    }
                                }
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .padding(10).quickOrbitGlass(cornerRadius: 12)
                            }
                        }
                    }.frame(height: 180)
                }
                HStack {
                    Button(qoText("Report prüfen & exportieren", "Review & export report", language: store.config.language)) {
                        report = diagnostics.report()
                        exportError = nil
                        showReport = true
                    }.quickOrbitColorButton(.blue)
                    Spacer()
                    Button(qoText("Logbuch löschen", "Clear log", language: store.config.language)) { showClear = true }
                        .quickOrbitGlassButton().disabled(diagnostics.entries.isEmpty)
                }
            }
        }
        .confirmationDialog(qoText("Lokales Logbuch löschen?", "Clear the local log?", language: store.config.language), isPresented: $showClear) {
            Button(qoText("Löschen", "Clear", language: store.config.language), role: .destructive) { diagnostics.clear() }
        }
        .sheet(isPresented: $showReport) {
            VStack(alignment: .leading, spacing: 14) {
                Text(qoText("Anonymen Fehlerreport prüfen", "Review anonymous error report", language: store.config.language)).font(.title2.bold())
                Text(qoText("Genau dieser Inhalt wird gespeichert. Die Datei kannst du anschließend selbst an den Support senden.", "This exact content will be saved. You can then send the file to support yourself.", language: store.config.language)).font(.callout)
                ScrollView {
                    Text(report).font(.system(.caption, design: .monospaced)).textSelection(.enabled)
                        .frame(maxWidth: .infinity, alignment: .leading).padding(12)
                }.quickOrbitGlass(cornerRadius: 14)
                if let exportError { Text(exportError).foregroundStyle(.orange).font(.callout) }
                HStack {
                    Button(qoText("Schließen", "Close", language: store.config.language)) { showReport = false }.quickOrbitGlassButton()
                    Spacer()
                    Button(qoText("Als Datei speichern …", "Save to file…", language: store.config.language), action: exportReport).quickOrbitColorButton(.blue)
                }
            }.padding(22).frame(width: 620, height: 480).background(SystemBackdrop())
        }
    }

    private func exportReport() {
        let panel = NSSavePanel()
        panel.allowedContentTypes = [.json]
        panel.nameFieldStringValue = "QuickOrbit-Diagnose.json"
        guard panel.runModal() == .OK, let url = panel.url else { return }
        do {
            try report.write(to: url, atomically: true, encoding: .utf8)
            showReport = false
            QuickOrbitNoticeCenter.shared.show(qoText("Report gespeichert", "Report saved", language: store.config.language))
        } catch {
            diagnostics.record(.reportExportFailed)
            exportError = QuickOrbitDiagnosticCode.reportExportFailed.message(language: store.config.language)
        }
    }
}

@MainActor
final class QuickOrbitNoticeCenter: ObservableObject {
    static let shared = QuickOrbitNoticeCenter()
    @Published var message: String?
    private var clearWorkItem: DispatchWorkItem?

    func show(_ text: String, diagnostic: QuickOrbitDiagnosticCode? = nil) {
        if let diagnostic { QuickOrbitDiagnostics.shared.record(diagnostic) }
        clearWorkItem?.cancel()
        message = text
        let work = DispatchWorkItem { [weak self] in self?.message = nil }
        clearWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + (diagnostic == nil ? 2.6 : 6), execute: work)
    }
}

// MARK: - Private in-memory clipboard history

@MainActor
final class QuickOrbitClipboardHistoryCenter: ObservableObject {
    static let shared = QuickOrbitClipboardHistoryCenter()
    @Published private(set) var entries: [String] = []
    @Published private(set) var lastRestored: String?
    private var lastChangeCount = NSPasteboard.general.changeCount
    private var timer: Timer?

    func start() {
        guard timer == nil else { return }
        captureIfNeeded()
        let timer = Timer(timeInterval: 0.8, repeats: true) { _ in
            MainActor.assumeIsolated { QuickOrbitClipboardHistoryCenter.shared.captureIfNeeded() }
        }
        timer.tolerance = 0.16
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func clear() {
        entries = []
        lastRestored = nil
    }

    func restore(_ text: String) {
        guard entries.contains(text) else { return }
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        _ = pasteboard.setString(text, forType: .string)
        lastChangeCount = pasteboard.changeCount
        lastRestored = text
        QuickOrbitNoticeCenter.shared.show(qoText("Wieder in der Zwischenablage", "Restored to clipboard", language: OrbitStore.shared.config.language))
    }

    private func captureIfNeeded() {
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount
        let rawTypes = Set((pasteboard.types ?? []).map(\.rawValue))
        guard !rawTypes.contains(where: { $0.localizedCaseInsensitiveContains("concealed") || $0.localizedCaseInsensitiveContains("transient") }),
              let text = pasteboard.string(forType: .string),
              !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
              text.count <= 20_000 else { return }
        // Publish the completed snapshot once, not each intermediate mutation.
        guard entries.first != text else { return }
        entries = [text] + entries.filter { $0 != text }.prefix(4)
    }
}

private struct QuickOrbitClipboardHistoryRow: View {
    let text: String
    let number: Int
    let selectionEnabled: Bool
    let onRestore: (String) -> Void
    @State private var hoverWorkItem: DispatchWorkItem?
    @State private var didRestore = false
    @State private var hovering = false
    @State private var hoverProgress = 0.0

    var body: some View {
        HStack(spacing: 28) {
            Text("\(number)")
                .font(.caption2.monospacedDigit().weight(.bold))
                .foregroundStyle(.secondary)
                .frame(width: 26, height: 26)
                .background(Color.primary.opacity(0.055), in: Circle())
            VStack(alignment: .leading, spacing: 3) {
                Text(text.replacingOccurrences(of: "\n", with: " "))
                    .font(.subheadline.weight(.medium))
                    .lineLimit(2)
                    .truncationMode(.tail)
                Text(selectionEnabled
                     ? qoText("1,5 s darüber bleiben: übernehmen", "Hover for 1.5 sec to restore", language: OrbitStore.shared.config.language)
                     : qoText("Kurz ansehen · Auswahl gleich bereit", "Take a moment · selection will be ready", language: OrbitStore.shared.config.language))
                    .font(.caption2)
                    .foregroundStyle(hovering ? Color.accentColor : Color.secondary)
            }
            Spacer()
            Image(systemName: hovering ? "arrow.right.circle.fill" : "doc.on.clipboard")
                .foregroundStyle(hovering ? Color.accentColor : Color.secondary)
        }
        .padding(12)
        .frame(maxWidth: .infinity, minHeight: 62, alignment: .leading)
        .background(hovering ? Color.accentColor.opacity(0.08) : Color.primary.opacity(0.025), in: RoundedRectangle(cornerRadius: 14, style: .continuous))
        .overlay { RoundedRectangle(cornerRadius: 14, style: .continuous).stroke(Color.primary.opacity(0.08), lineWidth: 0.8) }
        .overlay {
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .trim(from: 0, to: hoverProgress)
                .stroke(Color.accentColor, style: StrokeStyle(lineWidth: 2, lineCap: .round, lineJoin: .round))
        }
        .contentShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        .onHover { hovering in
            hoverWorkItem?.cancel()
            self.hovering = hovering && selectionEnabled
            guard hovering, selectionEnabled, !didRestore else {
                withAnimation(.easeOut(duration: 0.08)) { hoverProgress = 0 }
                return
            }
            hoverProgress = 0
            withAnimation(.linear(duration: 1.50)) { hoverProgress = 1 }
            let work = DispatchWorkItem {
                guard !didRestore else { return }
                didRestore = true
                onRestore(text)
            }
            hoverWorkItem = work
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.50, execute: work)
        }
        .onDisappear { hoverWorkItem?.cancel() }
    }
}

struct QuickOrbitClipboardHistoryView: View {
    let onClose: () -> Void
    @ObservedObject private var history = QuickOrbitClipboardHistoryCenter.shared
    @State private var closeWorkItem: DispatchWorkItem?
    @State private var activationWorkItem: DispatchWorkItem?
    @State private var selectionEnabled = false

    private var preferredHeight: CGFloat {
        history.entries.isEmpty ? 245 : min(455, 126 + CGFloat(history.entries.count) * 70)
    }

    var body: some View {
        ZStack {
            SystemBackdrop()
            VStack(alignment: .leading, spacing: 13) {
                HStack(spacing: 12) {
                    Image(systemName: "list.clipboard.fill")
                        .font(.system(size: 21, weight: .semibold))
                        .foregroundStyle(Color.cyan)
                        .frame(width: 44, height: 44)
                        .quickOrbitGlass(cornerRadius: 13)
                    VStack(alignment: .leading, spacing: 2) {
                        Text(qoText("Zwischenablage", "Clipboard", language: OrbitStore.shared.config.language)).font(.title3.bold())
                        Text(selectionEnabled
                             ? qoText("Ruhig auswählen · der Rahmen zeigt die verbleibende Zeit", "Choose calmly · the outline shows the remaining time", language: OrbitStore.shared.config.language)
                             : qoText("Einen Moment ansehen – nichts wird sofort ausgewählt", "Take a moment — nothing is selected immediately", language: OrbitStore.shared.config.language))
                            .font(.caption).foregroundStyle(.secondary)
                    }
                    Spacer()
                    if !history.entries.isEmpty {
                        Button { history.clear() } label: { Image(systemName: "trash") }
                            .quickOrbitGlassButton()
                            .help(qoText("Verlauf leeren", "Clear history", language: OrbitStore.shared.config.language))
                    }
                }

                if history.entries.isEmpty {
                    ContentUnavailableView(
                        qoText("Noch nichts kopiert", "Nothing copied yet", language: OrbitStore.shared.config.language),
                        systemImage: "clipboard",
                        description: Text(qoText("Neue kopierte Texte erscheinen automatisch hier.", "Newly copied text appears here automatically.", language: OrbitStore.shared.config.language))
                    )
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .quickOrbitGlass(cornerRadius: 18)
                } else {
                    VStack(spacing: 8) {
                        ForEach(Array(history.entries.enumerated()), id: \.element) { index, text in
                            QuickOrbitClipboardHistoryRow(text: text, number: index + 1, selectionEnabled: selectionEnabled) { selectedText in
                                history.restore(selectedText)
                                onClose()
                            }
                        }
                    }
                    .padding(10)
                    .quickOrbitGlass(cornerRadius: 18)
                }
            }
            .padding(18)
        }
        .frame(width: 460, height: preferredHeight)
        .onHover { inside in
            closeWorkItem?.cancel()
            guard !inside else { return }
            let work = DispatchWorkItem { onClose() }
            closeWorkItem = work
            DispatchQueue.main.asyncAfter(deadline: .now() + 2.40, execute: work)
        }
        .onAppear {
            selectionEnabled = false
            let work = DispatchWorkItem {
                withAnimation(.easeOut(duration: 0.18)) {
                    selectionEnabled = true
                }
            }
            activationWorkItem = work
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.10, execute: work)
        }
        .onDisappear {
            closeWorkItem?.cancel()
            activationWorkItem?.cancel()
        }
    }
}

@MainActor
final class QuickOrbitClipboardHistoryWindowController {
    static let shared = QuickOrbitClipboardHistoryWindowController()
    private var panel: NSPanel?

    func show() {
        close()
        let view = QuickOrbitClipboardHistoryView { [weak self] in self?.close() }
        let count = QuickOrbitClipboardHistoryCenter.shared.entries.count
        let height: CGFloat = count == 0 ? 245 : min(455, 126 + CGFloat(count) * 70)
        let size = CGSize(width: 460, height: height)
        let panel = NSPanel(contentRect: NSRect(origin: .zero, size: size), styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
        panel.level = .popUpMenu
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = true
        panel.hidesOnDeactivate = false
        panel.becomesKeyOnlyIfNeeded = true
        panel.acceptsMouseMovedEvents = true
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .transient]
        panel.contentView = NSHostingView(rootView: view)
        let pointer = NSEvent.mouseLocation
        let screen = NSScreen.screens.first(where: { $0.frame.contains(pointer) }) ?? NSScreen.main
        let visible = screen?.visibleFrame ?? CGRect(x: 0, y: 0, width: 1_200, height: 800)
        let origin = CGPoint(
            x: min(max(pointer.x - size.width / 2, visible.minX + 10), visible.maxX - size.width - 10),
            y: min(max(pointer.y - size.height / 2, visible.minY + 10), visible.maxY - size.height - 10)
        )
        panel.setFrameOrigin(origin)
        panel.orderFrontRegardless()
        self.panel = panel
    }

    private func close() {
        panel?.orderOut(nil)
        panel?.close()
        panel = nil
    }
}

// MARK: - Compact emoji orbit

private enum QuickOrbitEmojiHUDCategory: String, CaseIterable, Identifiable {
    case favorites, faces, gestures, hearts, nature, celebration, work, flags

    var id: String { rawValue }

    func title(language: AppLanguage?) -> String {
        switch self {
        case .favorites: return qoText("Beliebt", "Popular", language: language)
        case .faces: return qoText("Gesichter", "Faces", language: language)
        case .gestures: return qoText("Gesten", "Gestures", language: language)
        case .hearts: return qoText("Herzen", "Hearts", language: language)
        case .nature: return qoText("Natur", "Nature", language: language)
        case .celebration: return qoText("Feiern", "Celebrate", language: language)
        case .work: return qoText("Arbeit", "Work", language: language)
        case .flags: return qoText("Flaggen", "Flags", language: language)
        }
    }

    var symbol: String {
        switch self {
        case .favorites: return "star.fill"
        case .faces: return "face.smiling"
        case .gestures: return "hand.wave.fill"
        case .hearts: return "heart.fill"
        case .nature: return "leaf.fill"
        case .celebration: return "party.popper.fill"
        case .work: return "briefcase.fill"
        case .flags: return "flag.fill"
        }
    }

    var emojis: [String] {
        switch self {
        case .favorites: return ["👍", "🎉", "🍀", "🐞", "❤️", "✨", "✅", "😂", "🙏"]
        case .faces: return ["😀", "😊", "😂", "🥹", "😍", "😎", "🤔", "🥳", "🫡"]
        case .gestures: return ["👋", "👍", "👏", "🙌", "🫶", "🙏", "💪", "🤝", "✌️"]
        case .hearts: return ["❤️", "🩷", "🧡", "💛", "💚", "🩵", "💙", "💜", "🤍"]
        case .nature: return ["☀️", "🌈", "🌙", "🌱", "🍀", "🌸", "🌻", "🍁", "🌊"]
        case .celebration: return ["🎉", "🎊", "🥳", "🎂", "🎁", "🏆", "🥇", "🎈", "✨"]
        case .work: return ["✅", "📅", "📝", "📌", "💡", "📊", "💻", "🔗", "⏰"]
        case .flags: return ["🇩🇪", "🇦🇹", "🇨🇭", "🇬🇧", "🇺🇸", "🇫🇷", "🇮🇹", "🇪🇸", "🇪🇺"]
        }
    }
}

private struct QuickOrbitEmojiArcGuide: Shape {
    func path(in rect: CGRect) -> Path {
        var path = Path()
        path.move(to: CGPoint(x: rect.minX + 24, y: rect.maxY - 36))
        path.addCurve(
            to: CGPoint(x: rect.maxX - 24, y: rect.maxY - 36),
            control1: CGPoint(x: rect.minX + 120, y: rect.minY + 6),
            control2: CGPoint(x: rect.maxX - 120, y: rect.minY + 6)
        )
        return path
    }
}

private struct QuickOrbitEmojiArcButton: View {
    let emoji: String
    let onChoose: () -> Void
    @State private var hovering = false
    @State private var hoverProgress = 0.0
    @State private var hoverWorkItem: DispatchWorkItem?
    @State private var didChoose = false

    var body: some View {
        Button { chooseOnce() } label: {
            Text(emoji)
                .font(.system(size: 31))
                .frame(width: 54, height: 54)
                .scaleEffect(hovering ? 1.07 : 1)
                .background(Color.primary.opacity(hovering ? 0.10 : 0.045), in: Circle())
                .overlay { Circle().stroke(Color.primary.opacity(hovering ? 0.18 : 0.08), lineWidth: 0.8) }
                .overlay {
                    Circle()
                        .trim(from: 0, to: hoverProgress)
                        .stroke(Color.accentColor, style: StrokeStyle(lineWidth: 2.2, lineCap: .round))
                        .rotationEffect(.degrees(-90))
                }
                .contentShape(Circle())
        }
        .buttonStyle(.plain)
        .shadow(color: Color.black.opacity(hovering ? 0.16 : 0.08), radius: hovering ? 10 : 5, y: 3)
        .onHover { inside in
            hoverWorkItem?.cancel()
            hovering = inside
            guard inside, !didChoose else {
                withAnimation(.easeOut(duration: 0.10)) { hoverProgress = 0 }
                return
            }
            hoverProgress = 0
            withAnimation(.linear(duration: 0.80)) { hoverProgress = 1 }
            let work = DispatchWorkItem { chooseOnce() }
            hoverWorkItem = work
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.80, execute: work)
        }
        .onDisappear { hoverWorkItem?.cancel() }
        .accessibilityLabel(emoji)
    }

    private func chooseOnce() {
        guard !didChoose else { return }
        didChoose = true
        hoverWorkItem?.cancel()
        onChoose()
    }
}

private struct QuickOrbitEmojiOrbitView: View {
    let onChoose: (String) -> Void
    let onClose: () -> Void
    @ObservedObject private var store = OrbitStore.shared
    @State private var categoryIndex = 0
    @State private var closeWorkItem: DispatchWorkItem?

    private var category: QuickOrbitEmojiHUDCategory {
        QuickOrbitEmojiHUDCategory.allCases[categoryIndex]
    }

    var body: some View {
        ZStack {
            SystemBackdrop()

            VStack(spacing: 0) {
                HStack(spacing: 9) {
                    Image(systemName: "face.smiling.inverse")
                        .foregroundStyle(Color.accentColor)
                    VStack(alignment: .leading, spacing: 1) {
                        Text(qoText("Emoji auswählen", "Choose an emoji", language: store.config.language))
                            .font(.headline)
                        Text(qoText("Kurz darüberfahren oder klicken", "Hover briefly or click", language: store.config.language))
                            .font(.caption2)
                            .foregroundStyle(.secondary)
                    }
                    Spacer()
                    Label(category.title(language: store.config.language), systemImage: category.symbol)
                        .font(.caption.weight(.semibold))
                        .padding(.horizontal, 10)
                        .frame(height: 28)
                        .quickOrbitGlass(cornerRadius: 999)
                }
                .padding(.horizontal, 18)
                .padding(.top, 15)

                Spacer()

                HStack(spacing: 10) {
                    categoryButton(symbol: "chevron.left", offset: -1)
                    Text(qoText("Kategorie wechseln", "Change category", language: store.config.language))
                        .font(.caption2.weight(.medium))
                        .foregroundStyle(.secondary)
                    categoryButton(symbol: "chevron.right", offset: 1)
                }
                .padding(.bottom, 15)
            }

            QuickOrbitEmojiArcGuide()
                .stroke(Color.primary.opacity(0.075), style: StrokeStyle(lineWidth: 58, lineCap: .round))
                .overlay {
                    QuickOrbitEmojiArcGuide()
                        .stroke(Color.white.opacity(0.10), style: StrokeStyle(lineWidth: 1, lineCap: .round))
                }
                .frame(width: 500, height: 185)
                .position(x: 280, y: 170)

            GeometryReader { geometry in
                ForEach(Array(category.emojis.enumerated()), id: \.element) { index, emoji in
                    let fraction = Double(index) / Double(max(category.emojis.count - 1, 1))
                    let angle = Double.pi + fraction * Double.pi
                    let x = geometry.size.width / 2 + CGFloat(cos(angle)) * 220
                    let y = CGFloat(252 + sin(angle) * 132)
                    QuickOrbitEmojiArcButton(emoji: emoji) { onChoose(emoji) }
                        .position(x: x, y: y)
                        .transition(.opacity.combined(with: .scale(scale: 0.92)))
                }
            }
            .padding(.horizontal, 0)
        }
        .frame(width: 560, height: 330)
        .clipShape(RoundedRectangle(cornerRadius: 28, style: .continuous))
        .overlay { RoundedRectangle(cornerRadius: 28, style: .continuous).stroke(Color.primary.opacity(0.10), lineWidth: 0.8) }
        .onHover { inside in
            closeWorkItem?.cancel()
            guard !inside else { return }
            let work = DispatchWorkItem { onClose() }
            closeWorkItem = work
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.60, execute: work)
        }
        .onDisappear { closeWorkItem?.cancel() }
    }

    private func categoryButton(symbol: String, offset: Int) -> some View {
        Button {
            let count = QuickOrbitEmojiHUDCategory.allCases.count
            withAnimation(.easeInOut(duration: 0.18)) {
                categoryIndex = (categoryIndex + offset + count) % count
            }
        } label: {
            Image(systemName: symbol)
                .font(.system(size: 11, weight: .bold))
                .frame(width: 30, height: 30)
                .contentShape(Circle())
        }
        .buttonStyle(.plain)
        .background(Color.primary.opacity(0.055), in: Circle())
        .quickOrbitPickerHover()
    }
}

@MainActor
private enum QuickOrbitEmojiOutput {
    static func focusedElementAcceptsText() -> Bool {
        guard AXIsProcessTrusted() else { return false }
        var focusedValue: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            AXUIElementCreateSystemWide(),
            kAXFocusedUIElementAttribute as CFString,
            &focusedValue
        ) == .success, let focusedValue else { return false }

        let element = focusedValue as! AXUIElement
        var roleValue: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, kAXRoleAttribute as CFString, &roleValue) == .success,
              let role = roleValue as? String else { return false }
        return [kAXTextFieldRole as String, kAXTextAreaRole as String, kAXComboBoxRole as String, "AXSearchField"].contains(role)
    }

    static func commit(_ emoji: String, pasteIntoFocusedText: Bool) {
        guard copyQuickOrbitText(emoji) else { return }
        guard pasteIntoFocusedText else {
            QuickOrbitNoticeCenter.shared.show(qoText("\(emoji) kopiert", "\(emoji) copied", language: OrbitStore.shared.config.language))
            return
        }

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.08) {
            let source = CGEventSource(stateID: .hidSystemState)
            let down = CGEvent(keyboardEventSource: source, virtualKey: 9, keyDown: true)
            let up = CGEvent(keyboardEventSource: source, virtualKey: 9, keyDown: false)
            down?.flags = .maskCommand
            up?.flags = .maskCommand
            down?.post(tap: .cghidEventTap)
            up?.post(tap: .cghidEventTap)
            QuickOrbitNoticeCenter.shared.show(qoText("\(emoji) eingefügt", "\(emoji) inserted", language: OrbitStore.shared.config.language))
        }
    }
}

@MainActor
final class QuickOrbitEmojiOrbitWindowController {
    static let shared = QuickOrbitEmojiOrbitWindowController()
    private var panel: NSPanel?

    func show() {
        close()
        let size = CGSize(width: 560, height: 330)
        let view = QuickOrbitEmojiOrbitView { [weak self] emoji in
            let pasteIntoText = QuickOrbitEmojiOutput.focusedElementAcceptsText()
            self?.close()
            QuickOrbitEmojiOutput.commit(emoji, pasteIntoFocusedText: pasteIntoText)
        } onClose: { [weak self] in
            self?.close()
        }
        let panel = NSPanel(contentRect: NSRect(origin: .zero, size: size), styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
        panel.level = .popUpMenu
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = true
        panel.hidesOnDeactivate = false
        panel.becomesKeyOnlyIfNeeded = true
        panel.acceptsMouseMovedEvents = true
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .transient]
        panel.contentView = NSHostingView(rootView: view)

        let pointer = NSEvent.mouseLocation
        let screen = NSScreen.screens.first(where: { $0.frame.contains(pointer) }) ?? NSScreen.main
        let visible = screen?.visibleFrame ?? CGRect(x: 0, y: 0, width: 1_200, height: 800)
        let origin = CGPoint(
            x: min(max(pointer.x - size.width / 2, visible.minX + 10), visible.maxX - size.width - 10),
            y: min(max(pointer.y - size.height + 72, visible.minY + 10), visible.maxY - size.height - 10)
        )
        panel.setFrameOrigin(origin)
        panel.orderFrontRegardless()
        self.panel = panel
    }

    private func close() {
        panel?.orderOut(nil)
        panel?.close()
        panel = nil
    }
}

// MARK: - Apple Calendar and Reminders

enum QuickOrbitEventKind {
    case reminder
    case calendarEvent
}

struct QuickOrbitAgendaEntry: Identifiable {
    let id = UUID()
    let kind: QuickOrbitEventKind
    let title: String
    let date: Date
    let source: String
}

@MainActor
final class QuickOrbitEventCenter {
    static let shared = QuickOrbitEventCenter()
    private let eventStore = EKEventStore()

    func loadUpcoming(completion: @escaping ([QuickOrbitAgendaEntry]) -> Void) {
        eventStore.requestFullAccessToEvents { [weak self] eventGranted, _ in
            Task { @MainActor in
                guard let self else { completion([]); return }
                var entries: [QuickOrbitAgendaEntry] = []
                if eventGranted {
                    let start = Calendar.current.startOfDay(for: Date())
                    let end = Calendar.current.date(byAdding: .day, value: 30, to: start) ?? start.addingTimeInterval(30 * 86_400)
                    let predicate = self.eventStore.predicateForEvents(withStart: start, end: end, calendars: nil)
                    entries = self.eventStore.events(matching: predicate).prefix(30).map {
                        QuickOrbitAgendaEntry(kind: .calendarEvent, title: $0.title ?? "", date: $0.startDate, source: $0.calendar.title)
                    }
                }
                self.loadUpcomingReminders(existing: entries, completion: completion)
            }
        }
    }

    private func loadUpcomingReminders(existing: [QuickOrbitAgendaEntry], completion: @escaping ([QuickOrbitAgendaEntry]) -> Void) {
        eventStore.requestFullAccessToReminders { [weak self] reminderGranted, _ in
            Task { @MainActor in
                guard let self else { completion(existing.sorted { $0.date < $1.date }); return }
                guard reminderGranted else { completion(existing.sorted { $0.date < $1.date }); return }
                let end = Calendar.current.date(byAdding: .day, value: 30, to: Date())
                let predicate = self.eventStore.predicateForIncompleteReminders(withDueDateStarting: Date(), ending: end, calendars: nil)
                self.eventStore.fetchReminders(matching: predicate) { reminders in
                    Task { @MainActor in
                        let reminderEntries = (reminders ?? []).compactMap { reminder -> QuickOrbitAgendaEntry? in
                            guard let components = reminder.dueDateComponents,
                                  let due = Calendar.current.date(from: components) else { return nil }
                            return QuickOrbitAgendaEntry(kind: .reminder, title: reminder.title, date: due, source: reminder.calendar.title)
                        }
                        completion((existing + reminderEntries).sorted { $0.date < $1.date })
                    }
                }
            }
        }
    }

    func create(kind: QuickOrbitEventKind, title: String, notes: String, date: Date, durationMinutes: Int, completion: @escaping (Bool, String?) -> Void) {
        let cleaned = title.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleaned.isEmpty else {
            completion(false, qoText("Bitte gib einen Titel ein.", "Please enter a title.", language: OrbitStore.shared.config.language))
            return
        }

        switch kind {
        case .reminder:
            eventStore.requestFullAccessToReminders { [weak self] granted, error in
                DispatchQueue.main.async {
                    guard let self, granted else {
                        completion(false, error?.localizedDescription ?? qoText("Zugriff auf Erinnerungen wurde nicht erlaubt.", "Reminders access was not allowed.", language: OrbitStore.shared.config.language))
                        return
                    }
                    let reminder = EKReminder(eventStore: self.eventStore)
                    reminder.title = cleaned
                    reminder.notes = notes.trimmingCharacters(in: .whitespacesAndNewlines)
                    reminder.calendar = self.eventStore.defaultCalendarForNewReminders()
                    reminder.dueDateComponents = Calendar.current.dateComponents([.year, .month, .day, .hour, .minute], from: date)
                    do {
                        try self.eventStore.save(reminder, commit: true)
                        completion(true, nil)
                    } catch { completion(false, error.localizedDescription) }
                }
            }

        case .calendarEvent:
            eventStore.requestFullAccessToEvents { [weak self] granted, error in
                DispatchQueue.main.async {
                    guard let self, granted else {
                        completion(false, error?.localizedDescription ?? qoText("Zugriff auf Kalender wurde nicht erlaubt.", "Calendar access was not allowed.", language: OrbitStore.shared.config.language))
                        return
                    }
                    guard let calendar = self.eventStore.defaultCalendarForNewEvents else {
                        completion(false, qoText("Kein beschreibbarer Kalender gefunden.", "No writable calendar was found.", language: OrbitStore.shared.config.language))
                        return
                    }
                    let event = EKEvent(eventStore: self.eventStore)
                    event.title = cleaned
                    event.notes = notes.trimmingCharacters(in: .whitespacesAndNewlines)
                    event.startDate = date
                    event.endDate = date.addingTimeInterval(TimeInterval(max(5, durationMinutes) * 60))
                    event.calendar = calendar
                    do {
                        try self.eventStore.save(event, span: .thisEvent, commit: true)
                        completion(true, nil)
                    } catch { completion(false, error.localizedDescription) }
                }
            }
        }
    }
}

struct QuickOrbitEventComposerView: View {
    let kind: QuickOrbitEventKind
    let onClose: () -> Void
    var initialText = ""
    @ObservedObject private var store = OrbitStore.shared
    @State private var title = ""
    @State private var notes = ""
    @State private var date = Date().addingTimeInterval(3600)
    @State private var durationMinutes = 60
    @State private var isSaving = false
    @State private var errorText: String?
    @State private var showCalendarPicker = false

    private var isReminder: Bool {
        if case .reminder = kind { return true }
        return false
    }

    private func applyRecognizedText() {
        guard !initialText.isEmpty else { return }
        title = String((initialText.split(separator: "\n").first.map(String.init) ?? initialText).prefix(160))
        notes = initialText
        if let detector = try? NSDataDetector(types: NSTextCheckingResult.CheckingType.date.rawValue),
           let match = detector.firstMatch(in: initialText, range: NSRange(initialText.startIndex..., in: initialText)),
           let detected = match.date { date = detected }
    }

    var body: some View {
        ZStack {
            SystemBackdrop()
            VStack(alignment: .leading, spacing: 18) {
                HStack(spacing: 12) {
                    Image(systemName: isReminder ? "checklist" : "calendar.badge.plus")
                        .font(.system(size: 22, weight: .semibold))
                        .foregroundStyle(isReminder ? Color.orange : Color.blue)
                        .frame(width: 44, height: 44)
                        .quickOrbitGlass(cornerRadius: 13)
                    VStack(alignment: .leading, spacing: 2) {
                        Text(isReminder ? qoText("Neue Erinnerung", "New reminder", language: store.config.language) : qoText("Neuer Kalendereintrag", "New calendar event", language: store.config.language))
                            .font(.title3.bold())
                        Text(qoText("Du bestätigst jeden Eintrag, bevor er gespeichert wird.", "You confirm every item before it is saved.", language: store.config.language))
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                }

                VStack(alignment: .leading, spacing: 12) {
                    Label(qoText("Details", "Details", language: store.config.language), systemImage: "text.alignleft")
                        .font(.caption.weight(.bold))
                        .foregroundStyle(.secondary)
                    TextField(qoText("Titel", "Title", language: store.config.language), text: $title)
                        .quickOrbitInputField()
                        .font(.headline)
                    TextField(qoText("Notiz (optional)", "Note (optional)", language: store.config.language), text: $notes)
                        .quickOrbitInputField()

                    HStack(spacing: 8) {
                        quickDateButton(qoText("Heute · 18:00", "Today · 6 PM", language: store.config.language), dayOffset: 0, hour: 18)
                        quickDateButton(qoText("Morgen · 09:00", "Tomorrow · 9 AM", language: store.config.language), dayOffset: 1, hour: 9)
                        quickDateButton(qoText("Morgen · 18:00", "Tomorrow · 6 PM", language: store.config.language), dayOffset: 1, hour: 18)
                    }

                    HStack(spacing: 8) {
                        Button {
                            showCalendarPicker = true
                        } label: {
                            hudChoiceLabel(symbol: "calendar", text: date.formatted(.dateTime.weekday(.abbreviated).day().month(.abbreviated)), width: 190)
                        }
                        .buttonStyle(.plain)
                        .popover(isPresented: $showCalendarPicker, arrowEdge: .bottom) {
                            ZStack {
                                SystemBackdrop()
                                VStack(alignment: .leading, spacing: 12) {
                                    Label(qoText("Datum auswählen", "Choose date", language: store.config.language), systemImage: "calendar")
                                        .font(.headline)
                                    DatePicker("", selection: $date, displayedComponents: .date)
                                        .datePickerStyle(.graphical)
                                        .labelsHidden()
                                        .controlSize(.large)
                                        .scaleEffect(1.10)
                                        .frame(width: 340, height: 270)
                                    HStack {
                                        Spacer()
                                        Button(qoText("Übernehmen", "Done", language: store.config.language)) {
                                            showCalendarPicker = false
                                        }
                                        .quickOrbitColorButton(.blue)
                                        .keyboardShortcut(.defaultAction)
                                    }
                                }
                                .padding(16)
                            }
                            .frame(width: 400, height: 370)
                        }

                        Menu {
                            ForEach(0..<24, id: \.self) { hour in
                                Button(String(format: "%02d", hour)) { setTime(hour: hour, minute: Calendar.current.component(.minute, from: date)) }
                            }
                        } label: {
                            hudChoiceLabel(symbol: "clock", text: String(format: "%02d Std", Calendar.current.component(.hour, from: date)), width: 112)
                        }
                        .menuStyle(.borderlessButton)

                        Menu {
                            ForEach([0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55], id: \.self) { minute in
                                Button(String(format: "%02d", minute)) { setTime(hour: Calendar.current.component(.hour, from: date), minute: minute) }
                            }
                        } label: {
                            hudChoiceLabel(symbol: "timer", text: String(format: "%02d Min", Calendar.current.component(.minute, from: date)), width: 112)
                        }
                        .menuStyle(.borderlessButton)
                    }
                    if !isReminder {
                        Picker(qoText("Dauer", "Duration", language: store.config.language), selection: $durationMinutes) {
                            Text("30 Min").tag(30)
                            Text("1 Std").tag(60)
                            Text("2 Std").tag(120)
                        }
                        .pickerStyle(.segmented)
                    }
                    if let errorText {
                        Label(errorText, systemImage: "exclamationmark.triangle.fill")
                            .font(.caption)
                            .foregroundStyle(Color.orange)
                    }
                }
                .padding(16)
                .quickOrbitGlass(cornerRadius: 18)

                HStack {
                    Button(qoText("Abbrechen", "Cancel", language: store.config.language)) { onClose() }
                        .quickOrbitSolidButton()
                    Spacer()
                    Button {
                        isSaving = true
                        errorText = nil
                        QuickOrbitEventCenter.shared.create(kind: kind, title: title, notes: notes, date: date, durationMinutes: durationMinutes) { success, error in
                            isSaving = false
                            if success {
                                QuickOrbitNoticeCenter.shared.show(isReminder ? qoText("Erinnerung hinzugefügt", "Reminder added", language: store.config.language) : qoText("Kalendereintrag hinzugefügt", "Calendar event added", language: store.config.language))
                                onClose()
                            } else {
                                errorText = error
                                QuickOrbitDiagnostics.shared.record(.calendarFailed)
                            }
                        }
                    } label: {
                        Label(isSaving ? qoText("Speichern …", "Saving …", language: store.config.language) : qoText("Hinzufügen", "Add", language: store.config.language), systemImage: "plus")
                    }
                    .quickOrbitColorButton(.green)
                    .keyboardShortcut(.defaultAction)
                    .disabled(title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || isSaving)
                }
            }
            .padding(24)
        }
        .frame(width: 560, height: isReminder ? 410 : 450)
        .onAppear { applyRecognizedText() }
    }

    private func quickDateButton(_ label: String, dayOffset: Int, hour: Int) -> some View {
        let target = quickDate(dayOffset: dayOffset, hour: hour)
        let selected = abs(date.timeIntervalSince(target)) < 60
        return Button {
            date = target
        } label: {
            HStack(spacing: 5) {
                Image(systemName: selected ? "checkmark.circle.fill" : "clock")
                Text(label).lineLimit(1)
            }
            .font(.caption2.weight(.semibold))
            .foregroundStyle(selected ? Color.white : Color.primary)
            .padding(.horizontal, 9)
            .frame(maxWidth: .infinity, minHeight: 30)
            .background(selected ? Color.blue : Color.primary.opacity(0.055), in: RoundedRectangle(cornerRadius: 9, style: .continuous))
            .overlay { RoundedRectangle(cornerRadius: 9, style: .continuous).stroke(selected ? Color.blue : Color.primary.opacity(0.09), lineWidth: 0.8) }
        }
        .buttonStyle(.plain)
    }

    private func quickDate(dayOffset: Int, hour: Int) -> Date {
        let calendar = Calendar.current
        let base = calendar.date(byAdding: .day, value: dayOffset, to: Date()) ?? Date()
        return calendar.date(bySettingHour: hour, minute: 0, second: 0, of: base) ?? base
    }

    private func setTime(hour: Int, minute: Int) {
        date = Calendar.current.date(bySettingHour: hour, minute: minute, second: 0, of: date) ?? date
    }

    private func hudChoiceLabel(symbol: String, text: String, width: CGFloat) -> some View {
        HStack(spacing: 7) {
            Image(systemName: symbol)
                .foregroundStyle(Color.accentColor)
            Text(text)
                .lineLimit(1)
                .minimumScaleFactor(0.75)
            Spacer(minLength: 3)
            Image(systemName: "chevron.up.chevron.down")
                .font(.system(size: 8, weight: .bold))
                .foregroundStyle(.secondary)
        }
        .font(.caption.weight(.semibold))
        .padding(.horizontal, 10)
        .frame(width: width, height: 36)
        .background(Color.primary.opacity(0.035), in: RoundedRectangle(cornerRadius: 10, style: .continuous))
        .overlay { RoundedRectangle(cornerRadius: 10, style: .continuous).stroke(Color.primary.opacity(0.11), lineWidth: 0.8) }
    }
}

private struct QuickOrbitAgendaPopover: View {
    @ObservedObject private var store = OrbitStore.shared
    @State private var entries: [QuickOrbitAgendaEntry] = []
    @State private var loading = true
    @State private var filter = 0

    private var filteredEntries: [QuickOrbitAgendaEntry] {
        entries.filter { filter == 0 || (filter == 1 ? $0.kind == .calendarEvent : $0.kind == .reminder) }
    }

    private var groupedEntries: [(date: Date, entries: [QuickOrbitAgendaEntry])] {
        let grouped = Dictionary(grouping: filteredEntries) { Calendar.current.startOfDay(for: $0.date) }
        return grouped.keys.sorted().map { ($0, grouped[$0] ?? []) }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack {
                Label(qoText("Anstehend", "Upcoming", language: store.config.language), systemImage: "calendar")
                    .font(.headline.weight(.bold))
                Spacer()
                Button { create(.reminder) } label: { Image(systemName: "checklist") }
                    .help(qoText("Neue Erinnerung", "New reminder", language: store.config.language))
                Button { create(.calendarEvent) } label: { Image(systemName: "calendar.badge.plus") }
                    .help(qoText("Neuer Kalendereintrag", "New calendar event", language: store.config.language))
            }
            .buttonStyle(.plain)

            Picker(qoText("Anzeigen", "Show", language: store.config.language), selection: $filter) {
                Text(qoText("Beides", "Both", language: store.config.language)).tag(0)
                Text(qoText("Termine", "Events", language: store.config.language)).tag(1)
                Text(qoText("Erinnerungen", "Reminders", language: store.config.language)).tag(2)
            }
            .pickerStyle(.segmented)

            if loading {
                HStack { Spacer(); ProgressView(); Spacer() }
                    .frame(height: 180)
            } else if filteredEntries.isEmpty {
                ContentUnavailableView(
                    qoText("Nichts geplant", "Nothing scheduled", language: store.config.language),
                    systemImage: "calendar.badge.checkmark",
                    description: Text(qoText("Lege oben eine Erinnerung oder einen Termin an.", "Create a reminder or event above.", language: store.config.language))
                )
                .frame(height: 190)
            } else {
                ScrollView(.vertical, showsIndicators: false) {
                    LazyVStack(alignment: .leading, spacing: 15) {
                        ForEach(groupedEntries, id: \.date) { group in
                            VStack(alignment: .leading, spacing: 7) {
                                Text(dayTitle(group.date))
                                    .font(.caption.weight(.bold))
                                    .foregroundStyle(.secondary)
                                ForEach(group.entries) { entry in
                                    agendaRow(entry)
                                }
                            }
                        }
                    }
                    .padding(.vertical, 2)
                }
                .frame(maxHeight: 330)
            }
        }
        .padding(17)
        .frame(width: 430)
        .frame(minHeight: 260)
        .background(SystemBackdrop())
        .onAppear(perform: reload)
    }

    private func agendaRow(_ entry: QuickOrbitAgendaEntry) -> some View {
        HStack(spacing: 11) {
            Capsule()
                .fill(entry.kind == .reminder ? Color.red : Color.blue)
                .frame(width: 4, height: 52)
            VStack(alignment: .leading, spacing: 3) {
                Label(entry.kind == .reminder ? qoText("Erinnerung", "Reminder", language: store.config.language) : entry.source,
                      systemImage: entry.kind == .reminder ? "checklist" : "calendar")
                    .font(.caption2.weight(.semibold))
                    .foregroundStyle(.secondary)
                Text(entry.title)
                    .font(.headline)
                    .lineLimit(1)
                Text(entry.date.formatted(date: .omitted, time: .shortened))
                    .font(.caption.weight(.medium))
                    .foregroundStyle(.secondary)
            }
            Spacer()
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 8)
        .quickOrbitGlass(cornerRadius: 13, interactive: true)
    }

    private func dayTitle(_ date: Date) -> String {
        if Calendar.current.isDateInToday(date) { return qoText("Heute", "Today", language: store.config.language) }
        if Calendar.current.isDateInTomorrow(date) { return qoText("Morgen", "Tomorrow", language: store.config.language) }
        return date.formatted(.dateTime.weekday(.wide).day().month(.wide))
    }

    private func create(_ kind: QuickOrbitEventKind) {
        QuickOrbitEventComposerWindowController.shared.show(kind: kind)
    }

    private func reload() {
        loading = true
        QuickOrbitEventCenter.shared.loadUpcoming { loaded in
            entries = Array(loaded.prefix(30))
            loading = false
        }
    }
}

@MainActor
final class QuickOrbitAgendaWindowController {
    static let shared = QuickOrbitAgendaWindowController()
    private var panel: NSPanel?

    func show() {
        panel?.close()
        let panel = NSPanel(
            contentRect: NSRect(x: 0, y: 0, width: 430, height: 470),
            styleMask: [.titled, .closable, .fullSizeContentView],
            backing: .buffered,
            defer: false
        )
        panel.titleVisibility = .hidden
        panel.titlebarAppearsTransparent = true
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.level = .floating
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]
        panel.contentView = NSHostingView(rootView: QuickOrbitAgendaPopover())
        panel.center()
        self.panel = panel
        NSApp.activate(ignoringOtherApps: true)
        panel.makeKeyAndOrderFront(nil)
    }
}

@MainActor
final class QuickOrbitEventComposerWindowController {
    static let shared = QuickOrbitEventComposerWindowController()
    private var panel: NSPanel?

    func show(kind: QuickOrbitEventKind, initialText: String = "") {
        panel?.close()
        let view = QuickOrbitEventComposerView(kind: kind, onClose: { [weak self] in self?.panel?.close() }, initialText: initialText)
        let panel = NSPanel(
            contentRect: NSRect(x: 0, y: 0, width: 560, height: kindHeight(kind)),
            styleMask: [.titled, .closable, .fullSizeContentView],
            backing: .buffered,
            defer: false
        )
        panel.titlebarAppearsTransparent = true
        panel.titleVisibility = .hidden
        panel.isMovableByWindowBackground = true
        panel.contentView = NSHostingView(rootView: view)
        panel.center()
        panel.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        self.panel = panel
    }

    private func kindHeight(_ kind: QuickOrbitEventKind) -> CGFloat {
        if case .reminder = kind { return 410 }
        return 450
    }
}

#if canImport(Translation)
@available(macOS 15.0, *)
struct QuickOrbitTranslationView: View {
    let onClose: () -> Void
    @State private var sourceText = NSPasteboard.general.string(forType: .string) ?? ""
    @State private var translatedText = ""
    @State private var targetLanguage = "en"
    @State private var configuration: TranslationSession.Configuration?
    @State private var isWorking = false
    @State private var errorText: String?
    @State private var liveTranslationTask: Task<Void, Never>?

    private let languages = [
        ("de", "Deutsch", "German"), ("en", "Englisch", "English"),
        ("fr", "Französisch", "French"), ("es", "Spanisch", "Spanish"),
        ("it", "Italienisch", "Italian"), ("nl", "Niederländisch", "Dutch"),
        ("pl", "Polnisch", "Polish"), ("pt", "Portugiesisch", "Portuguese")
    ]

    var body: some View {
        ZStack {
            SystemBackdrop()
            VStack(alignment: .leading, spacing: 16) {
                HStack(spacing: 12) {
                    Image(systemName: "translate")
                        .font(.system(size: 24, weight: .semibold))
                        .foregroundStyle(Color.blue)
                        .frame(width: 46, height: 46)
                        .background(Color.blue.opacity(0.11), in: RoundedRectangle(cornerRadius: 13, style: .continuous))
                    VStack(alignment: .leading, spacing: 3) {
                        Text(qoText("Text übersetzen", "Translate text", language: OrbitStore.shared.config.language))
                            .font(.title3.weight(.semibold))
                        Text(qoText("Quellsprache automatisch erkennen · Verarbeitung auf dem Mac", "Detect source language automatically · Processed on this Mac", language: OrbitStore.shared.config.language))
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                    Spacer()
                    Picker(qoText("Zielsprache", "Target language", language: OrbitStore.shared.config.language), selection: $targetLanguage) {
                        ForEach(languages, id: \.0) { language in
                            Text(qoText(language.1, language.2, language: OrbitStore.shared.config.language)).tag(language.0)
                        }
                    }
                    .frame(width: 190)
                }

                HStack(spacing: 12) {
                    translationEditor(title: qoText("Original", "Original", language: OrbitStore.shared.config.language), text: $sourceText, placeholder: qoText("Text eingeben oder aus der Zwischenablage übernehmen …", "Enter text or use the clipboard…", language: OrbitStore.shared.config.language))
                    translationEditor(title: qoText("Übersetzung", "Translation", language: OrbitStore.shared.config.language), text: $translatedText, placeholder: qoText("Die Übersetzung erscheint hier.", "The translation appears here.", language: OrbitStore.shared.config.language))
                }

                if let errorText {
                    Label(errorText, systemImage: "exclamationmark.triangle.fill")
                        .font(.caption)
                        .foregroundStyle(Color.orange)
                }

                HStack {
                    Button(qoText("Schließen", "Close", language: OrbitStore.shared.config.language)) { onClose() }
                        .quickOrbitGlassButton()
                    Button(qoText("Zwischenablage einsetzen", "Paste clipboard", language: OrbitStore.shared.config.language)) {
                        sourceText = NSPasteboard.general.string(forType: .string) ?? ""
                    }
                    .quickOrbitGlassButton()
                    Spacer()
                    if !translatedText.isEmpty {
                        Button(qoText("Übersetzung kopieren", "Copy translation", language: OrbitStore.shared.config.language)) {
                            if copyQuickOrbitText(translatedText) {
                                QuickOrbitNoticeCenter.shared.show(qoText("Übersetzung kopiert", "Translation copied", language: OrbitStore.shared.config.language))
                            }
                        }
                        .quickOrbitColorButton(.green)
                    }
                    Label(
                        isWorking ? qoText("Übersetzt automatisch …", "Translating automatically…", language: OrbitStore.shared.config.language) : qoText("Live-Übersetzung aktiv", "Live translation active", language: OrbitStore.shared.config.language),
                        systemImage: isWorking ? "ellipsis.circle" : "bolt.fill"
                    )
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(isWorking ? Color.secondary : Color.blue)
                    .padding(.horizontal, 11)
                    .frame(height: 32)
                    .background(Color.blue.opacity(0.08), in: Capsule())
                }
            }
            .padding(22)
        }
        .frame(width: 720, height: 470)
        .onAppear {
            if (OrbitStore.shared.config.language ?? .german) == .english, targetLanguage == "en" {
                targetLanguage = "de"
            }
            scheduleLiveTranslation()
        }
        .onChange(of: sourceText) { _, _ in scheduleLiveTranslation() }
        .onChange(of: targetLanguage) { _, _ in scheduleLiveTranslation() }
        .onDisappear { liveTranslationTask?.cancel() }
        .translationTask(configuration) { session in
            guard isWorking else { return }
            let requestedText = sourceText
            do {
                let response = try await session.translate(requestedText)
                if requestedText == sourceText {
                    translatedText = response.targetText
                    errorText = nil
                }
            } catch {
                if requestedText == sourceText {
                    if !(error is CancellationError), !Task.isCancelled {
                        QuickOrbitDiagnostics.shared.record(.translationFailed)
                    }
                    errorText = qoText("Übersetzung wurde abgebrochen oder ist für dieses Sprachpaar nicht verfügbar.", "Translation was cancelled or isn't available for this language pair.", language: OrbitStore.shared.config.language)
                }
            }
            isWorking = false
        }
    }

    private func translationEditor(title: String, text: Binding<String>, placeholder: String) -> some View {
        VStack(alignment: .leading, spacing: 7) {
            Text(title).font(.caption.weight(.bold)).foregroundStyle(.secondary)
            ZStack(alignment: .topLeading) {
                if text.wrappedValue.isEmpty {
                    Text(placeholder)
                        .font(.callout)
                        .foregroundStyle(.tertiary)
                        .padding(.horizontal, 13)
                        .padding(.vertical, 15)
                        .allowsHitTesting(false)
                }
                TextEditor(text: text)
                    .scrollContentBackground(.hidden)
                    .font(.body)
                    .padding(8)
            }
            .frame(maxWidth: .infinity, minHeight: 280)
            .quickOrbitGlass(cornerRadius: 16, interactive: true)
            .overlay { RoundedRectangle(cornerRadius: 16, style: .continuous).stroke(Color.primary.opacity(0.09), lineWidth: 0.8) }
        }
    }

    private func beginTranslation() {
        isWorking = true
        errorText = nil
        configuration = nil
        Task { @MainActor in
            await Task.yield()
            configuration = .init(source: nil, target: Locale.Language(identifier: targetLanguage))
        }
    }

    private func scheduleLiveTranslation() {
        liveTranslationTask?.cancel()
        let trimmed = sourceText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            translatedText = ""
            errorText = nil
            isWorking = false
            configuration = nil
            return
        }
        liveTranslationTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 120_000_000)
            guard !Task.isCancelled else { return }
            beginTranslation()
        }
    }
}
