@MainActor
final class QuickOrbitBatteryWarningCenter {
    static let shared = QuickOrbitBatteryWarningCenter()
    private var timer: Timer?
    private var warnedDuringCurrentDischarge = false
    private var enabledEnergySavingAutomatically = false

    func start() {
        guard timer == nil else { return }
        timer = Timer.scheduledTimer(withTimeInterval: 45, repeats: true) { _ in
            MainActor.assumeIsolated { QuickOrbitBatteryWarningCenter.shared.checkNow() }
        }
        timer?.tolerance = 5
        if OrbitStore.shared.config.lowBatteryWarningEnabled ?? false {
            requestNotificationAccess()
        }
        checkNow()
    }

    func setEnabled(_ enabled: Bool) {
        if enabled {
            requestNotificationAccess()
            checkNow()
        } else {
            warnedDuringCurrentDischarge = false
        }
    }

    private func checkNow() {
        let status = QuickOrbitSystemInfo.battery()
        let threshold = 20
        guard let percent = status.percent else { return }
        if status.isCharging || status.onExternalPower || percent > threshold + 5 {
            warnedDuringCurrentDischarge = false
            if enabledEnergySavingAutomatically, OrbitStore.shared.config.energySavingMode ?? false {
                OrbitStore.shared.config.energySavingMode = false
            }
            enabledEnergySavingAutomatically = false
            return
        }
        guard percent <= threshold else { return }

        if !(OrbitStore.shared.config.energySavingMode ?? false), !enabledEnergySavingAutomatically {
            OrbitStore.shared.config.energySavingMode = true
            enabledEnergySavingAutomatically = true
            QuickOrbitNoticeCenter.shared.show(qoText("Akku niedrig · QuickOrbit spart jetzt Energie", "Low battery · QuickOrbit is now saving energy", language: OrbitStore.shared.config.language))
        }

        guard OrbitStore.shared.config.lowBatteryWarningEnabled ?? false,
              !warnedDuringCurrentDischarge else { return }
        warnedDuringCurrentDischarge = true

        let content = UNMutableNotificationContent()
        content.title = qoText("Batterie niedrig", "Low battery", language: OrbitStore.shared.config.language)
        content.body = qoText("Noch \(percent) % – verbinde deinen Mac mit Strom.", "\(percent)% remaining—connect your Mac to power.", language: OrbitStore.shared.config.language)
        content.sound = .default
        let request = UNNotificationRequest(identifier: "quickorbit.low-battery", content: content, trigger: nil)
        UNUserNotificationCenter.current().add(request)
        if NSApp.isActive { QuickOrbitNoticeCenter.shared.show(content.body) }
    }

    private func requestNotificationAccess() {
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound]) { granted, _ in
            if !granted {
                Task { @MainActor in
                    QuickOrbitNoticeCenter.shared.show(qoText("Mitteilungen sind nicht erlaubt.", "Notifications are not allowed.", language: OrbitStore.shared.config.language))
                }
            }
        }
    }
}

// MARK: - Local usage statistics

struct QuickOrbitUsageEntry: Codable, Identifiable, Equatable {
    var key: String
    var title: String
    var symbol: String
    var count: Int
    var id: String { key }
}

private struct QuickOrbitUsageSnapshot: Codable {
    var totalRuns: Int
    var entries: [QuickOrbitUsageEntry]
    var hourlyRuns: [String: [String: Int]]?
    var weekdayRuns: [String: [String: Int]]?
    var transitions: [String: [String: Int]]?
    var recentKeys: [String]?
    var appContextRuns: [String: [String: Int]]?
}

@MainActor
final class QuickOrbitUsageStatsCenter: ObservableObject {
    static let shared = QuickOrbitUsageStatsCenter()

    @Published private(set) var totalRuns: Int = 0
    @Published private(set) var entries: [QuickOrbitUsageEntry] = []
    private var hourlyRuns: [String: [String: Int]] = [:]
    private var weekdayRuns: [String: [String: Int]] = [:]
    private var transitions: [String: [String: Int]] = [:]
    private var recentKeys: [String] = []
    private var appContextRuns: [String: [String: Int]] = [:]

    private let storageKey = "QuickOrbit.UsageStats.v1"
    private var saveWorkItem: DispatchWorkItem?

    private init() {
        guard let data = UserDefaults.standard.data(forKey: storageKey),
              let snapshot = try? JSONDecoder().decode(QuickOrbitUsageSnapshot.self, from: data) else { return }
        totalRuns = snapshot.totalRuns
        hourlyRuns = snapshot.hourlyRuns ?? [:]
        weekdayRuns = snapshot.weekdayRuns ?? [:]
        transitions = snapshot.transitions ?? [:]
        recentKeys = Array((snapshot.recentKeys ?? []).suffix(30))
        appContextRuns = snapshot.appContextRuns ?? [:]

        // Older builds used the visible title as part of the statistics key.
        // Renaming the same action could therefore create duplicate entries.
        // Merge old entries by the real action identity: type + target.
        var merged: [String: QuickOrbitUsageEntry] = [:]
        for entry in snapshot.entries {
            let parts = entry.key.split(separator: "|", omittingEmptySubsequences: false)
            let target = parts.count >= 2 ? String(parts[1]) : ""
            let stableKey = target.hasPrefix("timer")
                ? "\(OrbitActionType.timer.rawValue)|\(target)"
                : (parts.count >= 2 ? "\(parts[0])|\(parts[1])" : entry.key)
            if var existing = merged[stableKey] {
                existing.count += entry.count
                existing.title = entry.title
                existing.symbol = entry.symbol
                existing.key = stableKey
                merged[stableKey] = existing
            } else {
                var normalized = entry
                normalized.key = stableKey
                merged[stableKey] = normalized
            }
        }
        entries = Array(merged.values)
        scheduleSave()
    }

    var topThree: [QuickOrbitUsageEntry] {
        Array(entries.sorted {
            if $0.count != $1.count { return $0.count > $1.count }
            return $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending
        }.prefix(3))
    }

    func record(_ item: OrbitItem) {
        guard item.enabled, item.target != "smartSuggestion" else { return }
        let key = "\(item.type.rawValue)|\(item.target)"
        totalRuns += 1
        if let index = entries.firstIndex(where: { $0.key == key }) {
            entries[index].count += 1
            entries[index].title = item.title
            entries[index].symbol = item.symbol
        } else {
            entries.append(.init(key: key, title: item.title, symbol: item.symbol, count: 1))
        }
        let now = Date()
        let hour = String(Calendar.current.component(.hour, from: now))
        var values = hourlyRuns[key] ?? [:]
        values[hour, default: 0] += 1
        hourlyRuns[key] = values
        let weekday = String(Calendar.current.component(.weekday, from: now))
        var weekdayValues = weekdayRuns[key] ?? [:]
        weekdayValues[weekday, default: 0] += 1
        weekdayRuns[key] = weekdayValues
        if let previous = recentKeys.last, previous != key {
            var nextValues = transitions[previous] ?? [:]
            nextValues[key, default: 0] += 1
            transitions[previous] = nextValues
        }
        if let bundleID = foregroundContextBundleID() {
            var appValues = appContextRuns[key] ?? [:]
            appValues[bundleID, default: 0] += 1
            appContextRuns[key] = appValues
        }
        recentKeys.append(key)
        if recentKeys.count > 30 { recentKeys.removeFirst(recentKeys.count - 30) }
        scheduleSave()
    }

    func suggestion(from items: [OrbitItem], at date: Date = Date()) -> OrbitItem? {
        let hour = Calendar.current.component(.hour, from: date)
        let nearby = [hour, (hour + 23) % 24, (hour + 1) % 24]
        let weekday = String(Calendar.current.component(.weekday, from: date))
        let previousKey = recentKeys.last
        let foregroundBundleID = foregroundContextBundleID()
        return items
            .filter { $0.enabled && $0.target != "smartSuggestion" && $0.type != .url && $0.type != .shellCommand }
            .map { item -> (OrbitItem, Int) in
                let key = "\(item.type.rawValue)|\(item.target)"
                let values = hourlyRuns[key] ?? [:]
                let timeScore = (values[String(nearby[0])] ?? 0) * 4
                    + (values[String(nearby[1])] ?? 0)
                    + (values[String(nearby[2])] ?? 0)
                let weekdayScore = weekdayRuns[key]?[weekday] ?? 0
                let sequenceScore = previousKey.flatMap { transitions[$0]?[key] } ?? 0
                let contextScore = foregroundBundleID.flatMap { appContextRuns[key]?[$0] } ?? 0
                let recencyScore = recentKeys.suffix(8).enumerated().reduce(0) { partial, value in
                    partial + (value.element == key ? value.offset + 1 : 0)
                }
                let total = entries.first(where: { $0.key == key })?.count ?? 0
                return (item, timeScore * 40 + weekdayScore * 8 + sequenceScore * 65 + contextScore * 55 + recencyScore * 3 + total)
            }
            .filter { $0.1 > 0 }
            .max { $0.1 < $1.1 }?.0
    }

    func reset() {
        saveWorkItem?.cancel()
        saveWorkItem = nil
        totalRuns = 0
        entries = []
        hourlyRuns = [:]
        weekdayRuns = [:]
        transitions = [:]
        recentKeys = []
        appContextRuns = [:]
        UserDefaults.standard.removeObject(forKey: storageKey)
    }

    private func scheduleSave() {
        saveWorkItem?.cancel()
        let work = DispatchWorkItem { [weak self] in
            self?.save()
            self?.saveWorkItem = nil
        }
        saveWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.25, execute: work)
    }

    func flushPendingSave() {
        guard saveWorkItem != nil else { return }
        saveWorkItem?.cancel()
        saveWorkItem = nil
        save()
    }

    private func save() {
        let snapshot = QuickOrbitUsageSnapshot(
            totalRuns: totalRuns,
            entries: entries,
            hourlyRuns: hourlyRuns,
            weekdayRuns: weekdayRuns,
            transitions: transitions,
            recentKeys: recentKeys,
            appContextRuns: appContextRuns
        )
        guard let data = try? JSONEncoder().encode(snapshot) else { return }
        UserDefaults.standard.set(data, forKey: storageKey)
    }

    private func foregroundContextBundleID() -> String? {
        guard let app = NSWorkspace.shared.frontmostApplication,
              app.bundleIdentifier != Bundle.main.bundleIdentifier else { return nil }
        return app.bundleIdentifier
    }
}

// MARK: - Action validation

struct QuickOrbitPreparedBetaCommand {
    let executableURL: URL
    let arguments: [String]
}

enum QuickOrbitBetaCommandPolicy {
    private static let blockedCommands: Set<String> = [
        // Administrator, accounts and credentials
        "sudo", "su", "doas", "login", "dscl", "sysadminctl", "security",
        // Destructive files, disks and permissions
        "rm", "rmdir", "unlink", "shred", "truncate", "dd", "diskutil", "fdisk", "gpt",
        "chmod", "chown", "chgrp", "setfacl", "xattr", "mv",
        // Processes, services and power
        "kill", "killall", "pkill", "launchctl", "systemctl", "shutdown", "reboot", "halt", "nvram",
        // Indirect shells and general-purpose interpreters
        "sh", "bash", "zsh", "fish", "dash", "python", "python3", "perl", "ruby", "node", "php", "swift",
        "eval", "exec", "command", "env",
        // Remote/network clients are deliberately unavailable in the local beta
        "curl", "wget", "nc", "netcat", "ssh", "scp", "sftp", "ftp", "telnet"
    ]

    private static let searchDirectories = [
        "/usr/bin", "/bin", "/usr/sbin", "/sbin", "/opt/homebrew/bin", "/usr/local/bin"
    ]

    static func prepare(_ rawCommand: String, language: AppLanguage?) -> Result<QuickOrbitPreparedBetaCommand, QuickOrbitBetaCommandError> {
        let trimmed = rawCommand.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            return .failure(.init(message: qoText("Bitte einen Befehl eingeben.", "Enter a command first.", language: language)))
        }
        guard trimmed.count <= 2_000 else {
            return .failure(.init(message: qoText("Der Befehl ist zu lang.", "The command is too long.", language: language)))
        }

        let tokens: [String]
        do {
            tokens = try parseArguments(trimmed, language: language)
        } catch let error as QuickOrbitBetaCommandError {
            return .failure(error)
        } catch {
            return .failure(.init(message: qoText("Der Befehl konnte nicht gelesen werden.", "The command could not be parsed.", language: language)))
        }
        guard let command = tokens.first, !command.isEmpty else {
            return .failure(.init(message: qoText("Bitte einen Befehl eingeben.", "Enter a command first.", language: language)))
        }
        guard !command.contains("/") else {
            return .failure(.init(message: qoText("Direkte Programmpfade sind in der Beta nicht erlaubt.", "Direct executable paths aren't allowed in the beta.", language: language)))
        }

        let commandName = command.lowercased()
        guard !blockedCommands.contains(commandName) else {
            return .failure(.init(message: qoText("Dieser Befehl ist aus Sicherheitsgründen nicht erlaubt.", "This command isn't allowed for security reasons.", language: language)))
        }

        if commandName == "osascript" {
            let script = tokens.dropFirst().joined(separator: " ").lowercased()
            let blockedAppleScript = [
                "do shell script", "administrator privileges", "tell application system events",
                "tell application finder", "delete ", "empty trash", "erase ", "keystroke "
            ]
            guard !blockedAppleScript.contains(where: script.contains) else {
                return .failure(.init(message: qoText("Diese AppleScript-Aktion ist in der Beta nicht erlaubt.", "This AppleScript action isn't allowed in the beta.", language: language)))
            }
        }

        if commandName == "find" {
            let dangerousOptions = Set(["-delete", "-exec", "-execdir", "-ok", "-okdir"])
            guard Set(tokens.dropFirst().map { $0.lowercased() }).isDisjoint(with: dangerousOptions) else {
                return .failure(.init(message: qoText("Löschende oder indirekt ausführende find-Optionen sind nicht erlaubt.", "Destructive or indirectly executing find options aren't allowed.", language: language)))
            }
        }

        if commandName == "git" {
            let arguments = tokens.dropFirst().map { $0.lowercased() }
            let destructiveReset = arguments.first == "reset" && arguments.contains("--hard")
            guard arguments.first != "clean", !destructiveReset else {
                return .failure(.init(message: qoText("Dieser Git-Befehl kann Dateien unwiderruflich entfernen und ist nicht erlaubt.", "This Git command can remove files irreversibly and isn't allowed.", language: language)))
            }
        }

        guard let executableURL = resolveExecutable(named: command) else {
            return .failure(.init(message: qoText("Der Befehl wurde auf diesem Mac nicht gefunden.", "The command wasn't found on this Mac.", language: language)))
        }
        return .success(.init(executableURL: executableURL, arguments: Array(tokens.dropFirst())))
    }

    static func status(_ rawCommand: String, language: AppLanguage?) -> (valid: Bool, message: String) {
        switch prepare(rawCommand, language: language) {
        case .success:
            return (true, qoText("Bereit für die lokale Ausführung", "Ready for local execution", language: language))
        case .failure(let error):
            return (false, error.message)
        }
    }

    private static func resolveExecutable(named name: String) -> URL? {
        for directory in searchDirectories {
            let candidate = URL(fileURLWithPath: directory, isDirectory: true).appendingPathComponent(name)
            if FileManager.default.isExecutableFile(atPath: candidate.path) {
                return candidate.resolvingSymlinksInPath()
            }
        }
        return nil
    }

    private static func parseArguments(_ command: String, language: AppLanguage?) throws -> [String] {
        var result: [String] = []
        var current = ""
        var quote: Character?
        var escaping = false
        let characters = Array(command)

        for (index, character) in characters.enumerated() {
            if escaping {
                current.append(character)
                escaping = false
                continue
            }
            if character == "\\" {
                escaping = true
                continue
            }
            if let activeQuote = quote {
                if character == activeQuote {
                    quote = nil
                } else {
                    current.append(character)
                }
                continue
            }
            if character == "\"" || character == "'" {
                quote = character
                continue
            }
            if character.isWhitespace {
                if !current.isEmpty {
                    result.append(current)
                    current = ""
                }
                continue
            }
            if ";|&><`".contains(character)
                || (character == "$" && index + 1 < characters.count && ["(", "{"].contains(characters[index + 1])) {
                throw QuickOrbitBetaCommandError(message: qoText("Verkettungen und Umleitungen sind nicht erlaubt. Lege dafür getrennte Kacheln an.", "Chaining and redirection aren't allowed. Create separate tiles instead.", language: language))
            }
            current.append(character)
        }

        guard quote == nil, !escaping else {
            throw QuickOrbitBetaCommandError(message: qoText("Anführungszeichen oder Escape-Zeichen sind nicht vollständig.", "A quote or escape character is incomplete.", language: language))
        }
        if !current.isEmpty { result.append(current) }
        return result
    }
}

struct QuickOrbitBetaCommandError: Error {
    let message: String
}

@MainActor
enum QuickOrbitBetaCommandRunner {
    static func run(_ rawCommand: String) {
        let language = OrbitStore.shared.config.language
        switch QuickOrbitBetaCommandPolicy.prepare(rawCommand, language: language) {
        case .failure(let error):
            QuickOrbitNoticeCenter.shared.show(error.message, diagnostic: .commandRejected)
        case .success(let prepared):
            DispatchQueue.global(qos: .userInitiated).async {
                let process = Process()
                let outputPipe = Pipe()
                let outputLock = NSLock()
                var capturedOutput = Data()
                process.executableURL = prepared.executableURL
                process.arguments = prepared.arguments
                process.standardInput = FileHandle.nullDevice
                process.standardOutput = outputPipe
                process.standardError = outputPipe
                outputPipe.fileHandleForReading.readabilityHandler = { handle in
                    let data = handle.availableData
                    guard !data.isEmpty else { return }
                    outputLock.lock()
                    let remaining = max(0, 8_192 - capturedOutput.count)
                    if remaining > 0 { capturedOutput.append(data.prefix(remaining)) }
                    outputLock.unlock()
                }

                do {
                    try process.run()
                } catch {
                    Task { @MainActor in
                        QuickOrbitNoticeCenter.shared.show(qoText("Der Beta-Befehl konnte nicht gestartet werden.", "The beta command couldn't be started.", language: language), diagnostic: .commandFailed)
                    }
                    return
                }

                let timeout = DispatchWorkItem {
                    if process.isRunning { process.terminate() }
                }
                DispatchQueue.global(qos: .utility).asyncAfter(deadline: .now() + 60, execute: timeout)
                process.waitUntilExit()
                timeout.cancel()
                outputPipe.fileHandleForReading.readabilityHandler = nil
                let tail = outputPipe.fileHandleForReading.readDataToEndOfFile()
                outputLock.lock()
                let remaining = max(0, 8_192 - capturedOutput.count)
                if remaining > 0 { capturedOutput.append(tail.prefix(remaining)) }
                let output = String(data: capturedOutput, encoding: .utf8)?
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                outputLock.unlock()
                let succeeded = process.terminationStatus == 0
                Task { @MainActor in
                    if succeeded, let output, !output.isEmpty {
                        let compact = output.replacingOccurrences(of: "\n", with: " · ")
                        QuickOrbitNoticeCenter.shared.show(String(compact.prefix(220)))
                    } else {
                        QuickOrbitNoticeCenter.shared.show(succeeded
                            ? qoText("Beta-Befehl ausgeführt", "Beta command completed", language: language)
                            : qoText("Befehl beendet (Code \(process.terminationStatus))", "Command exited (code \(process.terminationStatus))", language: language), diagnostic: succeeded ? nil : .commandFailed)
                    }
                }
            }
        }
    }
}

struct OrbitActionHealth {
    let valid: Bool
    let message: String
}

enum OrbitValidator {
    static func health(for item: OrbitItem, language: AppLanguage? = nil) -> OrbitActionHealth {
        guard item.enabled else { return OrbitActionHealth(valid: true, message: qoText("Leer", "Empty", language: language)) }

        switch item.type {
        case .app, .file:
            let resource = quickOrbitResolvedResource(for: item)
            let ok = resource.map { FileManager.default.fileExists(atPath: $0.url.path) } ?? false
            resource?.stopAccessing()
            return OrbitActionHealth(valid: ok, message: ok ? qoText("Bereit", "Ready", language: language) : qoText("Ziel wurde nicht gefunden", "Target not found", language: language))
        case .url:
            var text = item.target.trimmingCharacters(in: .whitespacesAndNewlines)
            if !text.contains("://") { text = "https://" + text }
            let parsed = URLComponents(string: text)
            let ok = ["http", "https"].contains(parsed?.scheme?.lowercased() ?? "")
                && parsed?.host?.isEmpty == false
            return OrbitActionHealth(valid: ok, message: ok ? qoText("Bereit", "Ready", language: language) : qoText("Webadresse prüfen", "Check web address", language: language))
        case .systemAction, .windowManagement:
            if item.requiresAccessibility && !AXIsProcessTrusted() {
                return OrbitActionHealth(valid: true, message: qoText("Bedienungshilfe nötig", "Accessibility required", language: language))
            }
            return OrbitActionHealth(valid: true, message: qoText("Bereit", "Ready", language: language))
        case .shellCommand:
            let status = QuickOrbitBetaCommandPolicy.status(item.target, language: language)
            return OrbitActionHealth(valid: status.valid, message: status.message)
        case .edit:
            return OrbitActionHealth(valid: true, message: qoText("Bereit", "Ready", language: language))
        case .screenshot, .timer, .emoji, .windowLeft, .windowRight:
            return OrbitActionHealth(valid: true, message: qoText("Bereit", "Ready", language: language))
        case .clipboard, .pasteText:
            let ok = !item.target.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            return OrbitActionHealth(valid: ok, message: ok ? qoText("Bereit", "Ready", language: language) : qoText("Inhalt fehlt", "Content is missing", language: language))
        case .shortcut:
            return OrbitActionHealth(
                valid: false,
                message: qoText("Kurzbefehle wurden aus dieser Version entfernt.", "Shortcuts were removed from this version.", language: language)
            )
        }
    }
}

// MARK: - Live Mac information + reliable system audio

struct QuickOrbitBatterySnapshot {
    let percent: Int?
    let isCharging: Bool
    let onExternalPower: Bool
}

enum QuickOrbitSystemInfo {
    private static var storageSample: (time: TimeInterval, text: String)?
    private static var previousCPUTicks: (user: UInt64, nice: UInt64, system: UInt64, idle: UInt64)?
    private static var previousNetworkSample: (received: UInt64, sent: UInt64, date: Date)?
    private static var cpuSampleTime = Date.distantPast
    private static var cachedCPU: Int?
    private static var cachedNetwork: (received: Double, sent: Double)?

    static func cpuUsage() -> Int? {
        let now = Date()
        let elapsed = now.timeIntervalSince(cpuSampleTime)
        if elapsed < 0.45 { return cachedCPU }
        if elapsed > 5 { previousCPUTicks = nil; cachedCPU = nil }
        cpuSampleTime = now
        var load = host_cpu_load_info_data_t()
        var count = mach_msg_type_number_t(MemoryLayout<host_cpu_load_info_data_t>.stride / MemoryLayout<integer_t>.stride)
        let result = withUnsafeMutablePointer(to: &load) { pointer in
            pointer.withMemoryRebound(to: integer_t.self, capacity: Int(count)) {
                host_statistics(mach_host_self(), HOST_CPU_LOAD_INFO, $0, &count)
            }
        }
        guard result == KERN_SUCCESS else { return nil }
        let ticks = (
            UInt64(load.cpu_ticks.0), UInt64(load.cpu_ticks.1),
            UInt64(load.cpu_ticks.2), UInt64(load.cpu_ticks.3)
        )
        defer { previousCPUTicks = (ticks.0, ticks.1, ticks.2, ticks.3) }
        guard let previous = previousCPUTicks else { return nil }
        let active = (ticks.0 - previous.user) + (ticks.1 - previous.nice) + (ticks.2 - previous.system)
        let idle = ticks.3 - previous.idle
        let total = active + idle
        guard total > 0 else { return cachedCPU }
        cachedCPU = min(100, max(0, Int((Double(active) / Double(total) * 100).rounded())))
        return cachedCPU
    }

    static func freeStorageText() -> String {
        let now = ProcessInfo.processInfo.systemUptime
        if let sample = storageSample, now - sample.time < 5 { return sample.text }
        guard let values = try? FileManager.default.attributesOfFileSystem(forPath: FileManager.default.homeDirectoryForCurrentUser.path),
              let bytes = values[.systemFreeSize] as? NSNumber else { return "–" }
        let formatter = ByteCountFormatter()
        formatter.allowedUnits = bytes.int64Value >= 1_000_000_000 ? [.useGB, .useTB] : [.useMB]
        formatter.countStyle = .file
        formatter.includesUnit = true
        formatter.isAdaptive = true
        let text = formatter.string(fromByteCount: bytes.int64Value)
        storageSample = (now, text)
        return text
    }

    static func memoryUsage() -> Int? {
        var statistics = vm_statistics64_data_t()
        var count = mach_msg_type_number_t(MemoryLayout<vm_statistics64_data_t>.stride / MemoryLayout<integer_t>.stride)
        let result = withUnsafeMutablePointer(to: &statistics) { pointer in
            pointer.withMemoryRebound(to: integer_t.self, capacity: Int(count)) {
                host_statistics64(mach_host_self(), HOST_VM_INFO64, $0, &count)
            }
        }
        guard result == KERN_SUCCESS else { return nil }
        let pageSize = UInt64(vm_kernel_page_size)
        let availablePages = UInt64(statistics.free_count + statistics.inactive_count + statistics.speculative_count)
        let physical = ProcessInfo.processInfo.physicalMemory
        guard physical > 0 else { return nil }
        let available = min(physical, availablePages * pageSize)
        return min(100, max(0, Int((Double(physical - available) / Double(physical) * 100).rounded())))
    }

    static func networkSpeed() -> (received: Double, sent: Double)? {
        let now = Date()
        if let previous = previousNetworkSample {
            let elapsed = now.timeIntervalSince(previous.date)
            if elapsed < 0.45 { return cachedNetwork }
            if elapsed > 5 { previousNetworkSample = nil; cachedNetwork = nil }
        }
        var firstAddress: UnsafeMutablePointer<ifaddrs>?
        guard getifaddrs(&firstAddress) == 0, let firstAddress else { return nil }
        defer { freeifaddrs(firstAddress) }

        var received: UInt64 = 0
        var sent: UInt64 = 0
        var cursor: UnsafeMutablePointer<ifaddrs>? = firstAddress
        while let interface = cursor {
            let value = interface.pointee
            if let address = value.ifa_addr,
               address.pointee.sa_family == UInt8(AF_LINK),
               (Int32(value.ifa_flags) & IFF_LOOPBACK) == 0,
               (Int32(value.ifa_flags) & IFF_UP) != 0,
               let rawData = value.ifa_data {
                let data = rawData.assumingMemoryBound(to: if_data.self).pointee
                received += UInt64(data.ifi_ibytes)
                sent += UInt64(data.ifi_obytes)
            }
            cursor = value.ifa_next
        }

        defer { previousNetworkSample = (received, sent, now) }
        guard let previous = previousNetworkSample else { return nil }
        let elapsed = max(0.1, now.timeIntervalSince(previous.date))
        guard received >= previous.received, sent >= previous.sent else { cachedNetwork = nil; return nil }
        cachedNetwork = (Double(received - previous.received) / elapsed, Double(sent - previous.sent) / elapsed)
        return cachedNetwork
    }

    static func speedText(_ bytesPerSecond: Double) -> String {
        if bytesPerSecond >= 1_000_000 { return String(format: "%.1f MB/s", bytesPerSecond / 1_000_000) }
        if bytesPerSecond >= 1_000 { return String(format: "%.0f KB/s", bytesPerSecond / 1_000) }
        return "\(Int(max(0, bytesPerSecond))) B/s"
    }

    static func uptimeText() -> String {
        let seconds = Int(ProcessInfo.processInfo.systemUptime)
        let days = seconds / 86_400
        let hours = (seconds % 86_400) / 3_600
        if days > 0 { return "\(days)T \(hours)Std" }
        let minutes = (seconds % 3_600) / 60
        return hours > 0 ? "\(hours)Std \(minutes)Min" : "\(minutes)Min"
    }

    static func battery() -> QuickOrbitBatterySnapshot {
        guard let blob = IOPSCopyPowerSourcesInfo()?.takeRetainedValue(),
              let list = IOPSCopyPowerSourcesList(blob)?.takeRetainedValue() as? [CFTypeRef] else {
            return QuickOrbitBatterySnapshot(percent: nil, isCharging: false, onExternalPower: true)
        }

        for source in list {
            guard let raw = IOPSGetPowerSourceDescription(blob, source)?.takeUnretainedValue(),
                  let description = raw as? [String: Any] else { continue }

            let current = description[kIOPSCurrentCapacityKey as String] as? Int
            let maximum = description[kIOPSMaxCapacityKey as String] as? Int
            let charging = description[kIOPSIsChargingKey as String] as? Bool ?? false
            let state = description[kIOPSPowerSourceStateKey as String] as? String
            let external = state == (kIOPSACPowerValue as String)

            let percent: Int?
            if let current, let maximum, maximum > 0 {
                percent = max(0, min(100, Int((Double(current) / Double(maximum) * 100).rounded())))
            } else {
                percent = current.map { max(0, min(100, $0)) }
            }
            return QuickOrbitBatterySnapshot(percent: percent, isCharging: charging, onExternalPower: external)
        }

        return QuickOrbitBatterySnapshot(percent: nil, isCharging: false, onExternalPower: true)
    }

    static func wifi() -> (powered: Bool, connected: Bool, name: String?, rssi: Int) {
        guard let interface = CWWiFiClient.shared().interface() else {
            return (false, false, nil, -100)
        }
        let powered = interface.powerOn()
        let active = interface.serviceActive()
        let name = interface.ssid()
        return (powered, powered && active, name, interface.rssiValue())
    }

    static func wifiSymbol(rssi: Int, connected: Bool, powered: Bool) -> String {
        guard powered else { return "wifi.slash" }
        guard connected else { return "wifi.exclamationmark" }
        if rssi >= -55 { return "wifi" }
        if rssi >= -70 { return "wifi" }
        return "wifi"
    }

    static func batterySymbol(percent: Int?, charging: Bool) -> String {
        if charging { return "battery.100.bolt" }
        guard let percent else { return "battery.0" }
        switch percent {
        case 76...100: return "battery.100"
        case 51...75: return "battery.75"
        case 26...50: return "battery.50"
        case 1...25: return "battery.25"
        default: return "battery.0"
        }
    }
}

@MainActor
struct QuickOrbitTimerState {
    let durationSeconds: Int
    let endDate: Date
    let profileName: String
}

@MainActor
struct QuickOrbitStopwatchState {
    let startedAt: Date?
    let elapsed: TimeInterval

    var isRunning: Bool { startedAt != nil }
    func total(at date: Date) -> TimeInterval { elapsed + (startedAt.map { date.timeIntervalSince($0) } ?? 0) }
}

@MainActor
final class QuickOrbitTimerCenter: ObservableObject {
    static let shared = QuickOrbitTimerCenter()
    @Published private(set) var states: [UUID: QuickOrbitTimerState] = [:]
    @Published private(set) var stopwatchStates: [UUID: QuickOrbitStopwatchState] = [:]
    private var completionTimers: [UUID: Timer] = [:]

    func toggle(minutes: Int, profileID: UUID, profileName: String) {
        toggle(seconds: minutes * 60, profileID: profileID, profileName: profileName)
    }

    func toggle(seconds: Int, profileID: UUID, profileName: String) {
        let safeSeconds = min(max(seconds, 5), 10_800)
        if let state = states[profileID], state.endDate > Date(), state.durationSeconds == safeSeconds {
            cancel(profileID: profileID, showNotice: true)
            return
        }
        start(seconds: safeSeconds, profileID: profileID, profileName: profileName)
    }

    func start(seconds: Int, profileID: UUID, profileName: String) {
        completionTimers[profileID]?.invalidate()
        let safeSeconds = min(max(seconds, 5), 10_800)
        let date = Date().addingTimeInterval(TimeInterval(safeSeconds))
        states[profileID] = QuickOrbitTimerState(durationSeconds: safeSeconds, endDate: date, profileName: profileName)
        completionTimers[profileID] = Timer.scheduledTimer(withTimeInterval: TimeInterval(safeSeconds), repeats: false) { _ in
            Task { @MainActor in
                self.states[profileID] = nil
                self.completionTimers[profileID] = nil
                QuickOrbitNoticeCenter.shared.show(qoText("Timer fertig", "Timer finished", language: OrbitStore.shared.config.language))
                QuickOrbitTimerCompletionPresenter.shared.show(seconds: safeSeconds, profileName: profileName)
            }
        }
        QuickOrbitNoticeCenter.shared.show(qoText(
            "\(profileName): Timer läuft \(quickOrbitDurationLabel(seconds: safeSeconds, language: .german))",
            "\(profileName): timer running for \(quickOrbitDurationLabel(seconds: safeSeconds, language: .english))",
            language: OrbitStore.shared.config.language
        ))
    }

    func toggleStopwatch(profileID: UUID) {
        let now = Date()
        if let state = stopwatchStates[profileID], let startedAt = state.startedAt {
            stopwatchStates[profileID] = QuickOrbitStopwatchState(startedAt: nil, elapsed: state.elapsed + now.timeIntervalSince(startedAt))
            QuickOrbitNoticeCenter.shared.show(qoText("Stoppuhr gestoppt", "Stopwatch stopped", language: OrbitStore.shared.config.language))
        } else {
            stopwatchStates[profileID] = QuickOrbitStopwatchState(startedAt: now, elapsed: stopwatchStates[profileID]?.elapsed ?? 0)
            QuickOrbitNoticeCenter.shared.show(qoText("Stoppuhr gestartet", "Stopwatch started", language: OrbitStore.shared.config.language))
        }
    }

    func resetStopwatch(profileID: UUID) {
        stopwatchStates[profileID] = nil
        QuickOrbitNoticeCenter.shared.show(qoText("Stoppuhr zurückgesetzt", "Stopwatch reset", language: OrbitStore.shared.config.language))
    }

    func cancel(profileID: UUID, showNotice: Bool = false) {
        completionTimers[profileID]?.invalidate()
        completionTimers[profileID] = nil
        states[profileID] = nil
        if showNotice {
            QuickOrbitNoticeCenter.shared.show(qoText("Timer gestoppt", "Timer stopped", language: OrbitStore.shared.config.language))
        }
    }

    func cancelAll() {
        completionTimers.values.forEach { $0.invalidate() }
        completionTimers.removeAll()
        states.removeAll()
        stopwatchStates.removeAll()
    }

    func remaining(for profileID: UUID, at date: Date) -> Int? {
        guard let state = states[profileID] else { return nil }
        return max(0, Int(ceil(state.endDate.timeIntervalSince(date))))
    }
}

@MainActor
private final class QuickOrbitTimerCompletionPresenter {
    static let shared = QuickOrbitTimerCompletionPresenter()

    private var panel: NSPanel?

    func show(seconds: Int, profileName: String) {
        for index in 0..<3 {
            DispatchQueue.main.asyncAfter(deadline: .now() + Double(index)) {
                if let sound = NSSound(named: NSSound.Name("Glass")) {
                    sound.stop()
                    sound.play()
                } else {
                    NSSound.beep()
                }
            }
        }
        NSApp.requestUserAttention(.informationalRequest)

        let size = CGSize(width: 344, height: 104)
        let panel = self.panel ?? NSPanel(
            contentRect: CGRect(origin: .zero, size: size),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = true
        panel.level = .statusBar
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .transient]
        panel.contentView = NSHostingView(rootView: QuickOrbitTimerCompletionBanner(seconds: seconds, profileName: profileName))

        let screen = NSScreen.screens.first(where: { $0.frame.contains(NSEvent.mouseLocation) }) ?? NSScreen.main
        if let visibleFrame = screen?.visibleFrame {
            panel.setFrameOrigin(CGPoint(
                x: visibleFrame.midX - size.width / 2,
                y: visibleFrame.maxY - size.height - 22
            ))
        }
        self.panel = panel
        panel.orderFrontRegardless()

    }

    func dismiss() {
        panel?.orderOut(nil)
    }
}

private struct QuickOrbitTimerCompletionBanner: View {
    let seconds: Int
    let profileName: String

    var body: some View {
        HStack(spacing: 15) {
            ZStack {
                Circle().fill(Color.green.opacity(0.16))
                Image(systemName: "timer.circle.fill")
                    .font(.system(size: 27, weight: .semibold))
                    .foregroundStyle(Color.green)
            }
            .frame(width: 52, height: 52)

            VStack(alignment: .leading, spacing: 4) {
                Text(qoText("Timer fertig", "Timer finished", language: OrbitStore.shared.config.language))
                    .font(.system(size: 17, weight: .bold, design: .rounded))
                Text(qoText(
                    "\(profileName) · \(quickOrbitDurationLabel(seconds: seconds, language: .german)) sind vorbei.",
                    "\(profileName) · Your \(quickOrbitDurationLabel(seconds: seconds, language: .english)) timer has ended.",
                    language: OrbitStore.shared.config.language
                ))
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
            }
            Spacer(minLength: 0)
            Button {
                QuickOrbitTimerCompletionPresenter.shared.dismiss()
            } label: {
                Image(systemName: "xmark")
                    .font(.system(size: 11, weight: .bold))
                    .frame(width: 28, height: 28)
                    .background(Color.primary.opacity(0.08), in: Circle())
            }
            .buttonStyle(.plain)
            .help(qoText("Schließen", "Close", language: OrbitStore.shared.config.language))
        }
        .padding(.horizontal, 18)
        .frame(width: 344, height: 104)
        .quickOrbitGlass(cornerRadius: 24)
    }
}

enum SystemAudioController {
    static func outputSnapshot() -> (percent: Int?, muted: Bool) {
        guard let device = defaultOutputDevice() else { return (nil, false) }
        let master = readVolume(device: device, element: kAudioObjectPropertyElementMain)
        let channels = [AudioObjectPropertyElement(1), 2].compactMap { readVolume(device: device, element: $0) }
        let level = master ?? (channels.isEmpty ? nil : channels.reduce(0, +) / Float(channels.count))
        var address = muteAddress()
        var muted: UInt32 = 0
        var size = UInt32(MemoryLayout<UInt32>.size)
        if AudioObjectHasProperty(device, &address) {
            _ = AudioObjectGetPropertyData(device, &address, 0, nil, &size, &muted)
        }
        return (level.map { Int((min(1, max(0, $0)) * 100).rounded()) }, muted != 0)
    }

    private static func defaultOutputDevice() -> AudioDeviceID? {
        var device = AudioDeviceID(0)
        var size = UInt32(MemoryLayout<AudioDeviceID>.size)
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDefaultOutputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        let status = AudioObjectGetPropertyData(
            AudioObjectID(kAudioObjectSystemObject),
            &address,
            0,
            nil,
            &size,
            &device
        )
        return status == noErr && device != 0 ? device : nil
    }

    private static func volumeAddress(element: AudioObjectPropertyElement) -> AudioObjectPropertyAddress {
        AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyVolumeScalar,
            mScope: kAudioDevicePropertyScopeOutput,
            mElement: element
        )
    }

    private static func muteAddress() -> AudioObjectPropertyAddress {
        AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyMute,
            mScope: kAudioDevicePropertyScopeOutput,
            mElement: kAudioObjectPropertyElementMain
        )
    }

    private static func readVolume(device: AudioDeviceID, element: AudioObjectPropertyElement) -> Float32? {
        var address = volumeAddress(element: element)
        guard AudioObjectHasProperty(device, &address) else { return nil }
        var value: Float32 = 0
        var size = UInt32(MemoryLayout<Float32>.size)
        guard AudioObjectGetPropertyData(device, &address, 0, nil, &size, &value) == noErr else { return nil }
        return value
    }

    private static func writeVolume(_ value: Float32, device: AudioDeviceID, element: AudioObjectPropertyElement) -> Bool {
        var address = volumeAddress(element: element)
        guard AudioObjectHasProperty(device, &address) else { return false }
        var settable = DarwinBoolean(false)
        guard AudioObjectIsPropertySettable(device, &address, &settable) == noErr, settable.boolValue else { return false }
        var value = max(0, min(1, value))
        return AudioObjectSetPropertyData(device, &address, 0, nil, UInt32(MemoryLayout<Float32>.size), &value) == noErr
    }

    static func changeVolume(by delta: Float32) -> Bool {
        guard let device = defaultOutputDevice() else { return false }

        if let master = readVolume(device: device, element: kAudioObjectPropertyElementMain),
           writeVolume(master + delta, device: device, element: kAudioObjectPropertyElementMain) {
            if delta > 0 { _ = setMuted(false, device: device) }
            return true
        }

        let channels: [AudioObjectPropertyElement] = [1, 2]
        let current = channels.compactMap { element in
            readVolume(device: device, element: element).map { (element, $0) }
        }
        guard !current.isEmpty else { return false }

        var changed = false
        for (element, value) in current {
            changed = writeVolume(value + delta, device: device, element: element) || changed
        }
        if changed && delta > 0 { _ = setMuted(false, device: device) }
        return changed
    }

    private static func setMuted(_ muted: Bool, device: AudioDeviceID) -> Bool {
        var address = muteAddress()
        guard AudioObjectHasProperty(device, &address) else { return false }
        var settable = DarwinBoolean(false)
        guard AudioObjectIsPropertySettable(device, &address, &settable) == noErr, settable.boolValue else { return false }
        var value: UInt32 = muted ? 1 : 0
        return AudioObjectSetPropertyData(device, &address, 0, nil, UInt32(MemoryLayout<UInt32>.size), &value) == noErr
    }

    static func toggleMute() -> Bool {
        guard let device = defaultOutputDevice() else { return false }
        var address = muteAddress()
        guard AudioObjectHasProperty(device, &address) else { return false }
        var value: UInt32 = 0
        var size = UInt32(MemoryLayout<UInt32>.size)
        guard AudioObjectGetPropertyData(device, &address, 0, nil, &size, &value) == noErr else { return false }
        return setMuted(value == 0, device: device)
    }
}

@MainActor
enum QuickOrbitColorSampler {
    static func pickAndCopy() {
        let sampler = NSColorSampler()
        sampler.show { color in
            MainActor.assumeIsolated {
                guard let color, let rgb = color.usingColorSpace(.deviceRGB) else {
                    QuickOrbitNoticeCenter.shared.show(qoText("Farbe konnte nicht gelesen werden.", "The color couldn't be read.", language: OrbitStore.shared.config.language))
                    return
                }
                let red = Int((rgb.redComponent * 255).rounded())
                let green = Int((rgb.greenComponent * 255).rounded())
                let blue = Int((rgb.blueComponent * 255).rounded())
                let hex = String(format: "#%02X%02X%02X", red, green, blue)
                if copyQuickOrbitText(hex) {
                    QuickOrbitNoticeCenter.shared.show(qoText("\(hex) kopiert", "\(hex) copied", language: OrbitStore.shared.config.language))
                }
            }
        }
    }
}

private enum QuickOrbitNativeDragPayload {
    static func canExport(_ item: OrbitItem) -> Bool {
        item.insertedEmoji != nil
            || item.target == "copyTimestamp"
            || item.target == "liveClock"
            || item.target == "liveDate"
            || ["batteryStatus", "cpuStatus", "memoryStatus", "storageStatus", "uptimeStatus"].contains(item.target)
            || (item.type == .pasteText && !item.target.isEmpty)
            || (item.type == .url && !item.target.isEmpty)
    }

    static func payload(for item: OrbitItem) -> String? {
        if let emoji = item.insertedEmoji { return emoji }
        if item.target == "copyTimestamp" { return ISO8601DateFormatter().string(from: Date()) }
        if item.target == "liveClock" {
            return DateFormatter.localizedString(from: Date(), dateStyle: .none, timeStyle: .medium)
        }
        if item.target == "liveDate" {
            return DateFormatter.localizedString(from: Date(), dateStyle: .full, timeStyle: .none)
        }
        if item.target == "batteryStatus" {
            let battery = QuickOrbitSystemInfo.battery()
            return battery.percent.map { "\($0)%" } ?? (battery.onExternalPower ? "AC" : nil)
        }
        if item.target == "cpuStatus" { return QuickOrbitSystemInfo.cpuUsage().map { "CPU \($0)%" } }
        if item.target == "memoryStatus" { return QuickOrbitSystemInfo.memoryUsage().map { "RAM \($0)%" } }
        if item.target == "storageStatus" { return QuickOrbitSystemInfo.freeStorageText() }
        if item.target == "uptimeStatus" { return QuickOrbitSystemInfo.uptimeText() }
        if item.type == .pasteText, !item.target.isEmpty { return item.target }
        if item.type == .url, !item.target.isEmpty { return item.target }
        return nil
    }

    static func preview(for item: OrbitItem) -> String {
        if let emoji = item.insertedEmoji { return emoji }
        if item.target == "copyTimestamp" { return "ISO 8601" }
        if item.target == "liveClock" {
            return DateFormatter.localizedString(from: Date(), dateStyle: .none, timeStyle: .short)
        }
        if item.target == "liveDate" {
            return DateFormatter.localizedString(from: Date(), dateStyle: .medium, timeStyle: .none)
        }
        if ["batteryStatus", "cpuStatus", "memoryStatus", "storageStatus", "uptimeStatus"].contains(item.target) {
            return payload(for: item) ?? item.title
        }
        return String(item.target.prefix(32))
    }
}

private struct QuickOrbitPayloadDragModifier: ViewModifier {
    let item: OrbitItem
    let enabled: Bool

    @ViewBuilder
    func body(content: Content) -> some View {
        if enabled && QuickOrbitNativeDragPayload.canExport(item) {
            content.overlay { QuickOrbitNativeDragSource(item: item) }
        } else {
            content
        }
    }
}

private struct QuickOrbitCustomTextEditor: View {
    let item: OrbitItem
    let language: AppLanguage?
    let onChange: (OrbitItem) -> Void
    @State private var title = ""
    @State private var text = ""

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            Text(qoText("Eigener Text", "Custom text", language: language)).font(.title3.bold())
            Text(qoText("Herausziehen fügt den Text im Ziel ein. Automatisches Auswählen kopiert ihn.", "Drag into a destination to insert your text. Hover selection copies it.", language: language))
                .font(.callout).foregroundStyle(.secondary)
            TextField(qoText("Name der Kachel", "Tile name", language: language), text: $title).quickOrbitInputField()
            if text.isEmpty {
                HStack(spacing: 8) {
                    Button(qoText("Signatur", "Signature", language: language)) {
                        title = qoText("Signatur", "Signature", language: language)
                        text = qoText("Viele Grüße\nDein Name", "Best regards\nYour name", language: language)
                    }
                    Button(qoText("Kurze Antwort", "Quick reply", language: language)) {
                        title = qoText("Danke", "Thanks", language: language)
                        text = qoText("Vielen Dank! Ich melde mich bei dir.", "Thank you! I'll get back to you.", language: language)
                    }
                }
                .quickOrbitGlassButton()
            }
            TextEditor(text: $text)
                .font(.body)
                .scrollContentBackground(.hidden)
                .padding(10)
                .frame(minHeight: 180)
                .quickOrbitGlass(cornerRadius: 14)
                .accessibilityLabel(qoText("Textinhalt", "Text content", language: language))
            HStack {
                Text(qoText("\(text.count) Zeichen", "\(text.count) characters", language: language))
                    .font(.caption.monospacedDigit()).foregroundStyle(.secondary)
                Spacer()
                Button(qoText("Text kopieren", "Copy text", language: language)) {
                    if copyQuickOrbitText(text) {
                        QuickOrbitNoticeCenter.shared.show(qoText("Text kopiert", "Text copied", language: language))
                    }
                }
                .quickOrbitGlassButton()
                .disabled(text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            Text(qoText("Zum Beispiel: E-Mail-Adresse, Signatur oder eine häufige Antwort.", "For example: email address, signature, or a frequent reply.", language: language))
                .font(.caption).foregroundStyle(.secondary)
        }
        .onAppear {
            title = item.type == .pasteText ? item.title : ""
            text = item.type == .pasteText ? item.target : ""
        }
        .onChange(of: title) { _, _ in update() }
        .onChange(of: text) { _, _ in update() }
    }

    private func update() {
        var next = item
        next.type = .pasteText
        next.target = text
        next.title = title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? qoText("Eigener Text", "Custom text", language: language) : title
        next.symbol = "text.alignleft"
        next.securityScopedBookmark = nil
        next.enabled = !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        onChange(next)
    }
}

private enum QuickOrbitNativeDragContext {
    case orbit
    case menuDock
}

private struct QuickOrbitNativeDragSource: NSViewRepresentable {
    let item: OrbitItem
    var dragContext: QuickOrbitNativeDragContext = .orbit

    func makeNSView(context: Context) -> QuickOrbitNativeDragSourceView {
        QuickOrbitNativeDragSourceView(item: item, dragContext: dragContext)
    }

    func updateNSView(_ nsView: QuickOrbitNativeDragSourceView, context: Context) {
        nsView.item = item
        nsView.dragContext = dragContext
    }
}

@MainActor
private final class QuickOrbitNativeDragSourceView: NSView, NSDraggingSource {
    var item: OrbitItem
    var dragContext: QuickOrbitNativeDragContext
    private var mouseDownPoint: CGPoint?
    private var startedDrag = false

    init(item: OrbitItem, dragContext: QuickOrbitNativeDragContext) {
        self.item = item
        self.dragContext = dragContext
        super.init(frame: .zero)
        wantsLayer = true
        layer?.backgroundColor = NSColor.clear.cgColor
    }

    required init?(coder: NSCoder) { nil }

    override var acceptsFirstResponder: Bool { false }
    override func acceptsFirstMouse(for event: NSEvent?) -> Bool { true }

    override func mouseDown(with event: NSEvent) {
        mouseDownPoint = convert(event.locationInWindow, from: nil)
        startedDrag = false
        if dragContext == .orbit { OrbitController.shared.payloadPressDidBegin() }
    }

    override func mouseDragged(with event: NSEvent) {
        guard !startedDrag,
              let origin = mouseDownPoint,
              hypot(convert(event.locationInWindow, from: nil).x - origin.x,
                    convert(event.locationInWindow, from: nil).y - origin.y) >= 4,
              let payload = QuickOrbitNativeDragPayload.payload(for: item) else { return }

        startedDrag = true
        let pasteboardItem = NSPasteboardItem()
        pasteboardItem.setString(payload, forType: .string)
        let draggingItem = NSDraggingItem(pasteboardWriter: pasteboardItem)
        let image = dragImage()
        let location = convert(event.locationInWindow, from: nil)
        draggingItem.setDraggingFrame(
            CGRect(x: location.x - image.size.width / 2, y: location.y - image.size.height / 2, width: image.size.width, height: image.size.height),
            contents: image
        )
        let session = beginDraggingSession(with: [draggingItem], event: event, source: self)
        session.draggingFormation = .none
        switch dragContext {
        case .orbit:
            OrbitController.shared.payloadDragDidBegin()
        case .menuDock:
            QuickOrbitMenuDockStore.shared.beginPayloadExport()
        }
    }

    override func mouseUp(with event: NSEvent) {
        if dragContext == .orbit, !startedDrag { OrbitController.shared.payloadPressDidEnd() }
        mouseDownPoint = nil
        startedDrag = false
    }

    func draggingSession(_ session: NSDraggingSession, sourceOperationMaskFor context: NSDraggingContext) -> NSDragOperation {
        .copy
    }

    func ignoreModifierKeys(for session: NSDraggingSession) -> Bool { true }

    func draggingSession(_ session: NSDraggingSession, endedAt screenPoint: NSPoint, operation: NSDragOperation) {
        mouseDownPoint = nil
        startedDrag = false
        switch dragContext {
        case .orbit:
            OrbitController.shared.payloadDragDidEnd()
        case .menuDock:
            QuickOrbitMenuDockStore.shared.endPayloadExport()
            StatusBarController.shared.closeQuickDockAfterPayloadDrag()
        }
    }

    private func dragImage() -> NSImage {
        let label = QuickOrbitNativeDragPayload.preview(for: item)
        let font = NSFont.systemFont(ofSize: item.insertedEmoji == nil ? 13 : 22, weight: .semibold)
        let shadow = NSShadow()
        shadow.shadowColor = NSColor.black.withAlphaComponent(0.55)
        shadow.shadowBlurRadius = 4
        shadow.shadowOffset = NSSize(width: 0, height: -1)
        let attributes: [NSAttributedString.Key: Any] = [
            .font: font,
            .foregroundColor: NSColor.white,
            .shadow: shadow
        ]
        let measured = (label as NSString).size(withAttributes: attributes)
        let size = NSSize(width: min(max(measured.width + 12, 30), 244), height: max(measured.height + 8, 30))
        return NSImage(size: size, flipped: false) { rect in
            let textRect = NSRect(x: 6, y: (rect.height - measured.height) / 2, width: rect.width - 12, height: measured.height)
            (label as NSString).draw(in: textRect, withAttributes: attributes)
            return true
        }
    }
}

enum QuickOrbitWindowLayout: String {
    case leftHalf, rightHalf, topLeft, topRight, bottomLeft, bottomRight, maximize, center, restore
}

@MainActor
enum QuickOrbitWindowManager {
    private static var restoreFrames: [String: CGRect] = [:]

    static func arrange(_ layout: QuickOrbitWindowLayout) {
        guard AXIsProcessTrusted() else {
            _ = AXIsProcessTrustedWithOptions(["AXTrustedCheckOptionPrompt": true] as CFDictionary)
            QuickOrbitAccessibilityGuide.openSystemAccess()
            return
        }
        guard let application = OrbitController.shared.externalApplicationForMacControl() else {
            QuickOrbitNoticeCenter.shared.show(qoText("Kein anderes vorderes Fenster gefunden.", "No other front window was found.", language: OrbitStore.shared.config.language))
            return
        }

        let appElement = AXUIElementCreateApplication(application.processIdentifier)
        var windowValue: CFTypeRef?
        guard AXUIElementCopyAttributeValue(appElement, kAXFocusedWindowAttribute as CFString, &windowValue) == .success,
              let windowValue else {
            QuickOrbitNoticeCenter.shared.show(qoText("Diese App stellt kein anordenbares Fenster bereit.", "This app doesn't provide a window that can be arranged.", language: OrbitStore.shared.config.language))
            return
        }
        let window = windowValue as! AXUIElement
        guard let currentFrame = frame(of: window) else {
            QuickOrbitNoticeCenter.shared.show(qoText("Fensterposition konnte nicht gelesen werden.", "The window position couldn't be read.", language: OrbitStore.shared.config.language))
            return
        }

        let pid = application.processIdentifier
        let restoreKey = windowKey(window, pid: pid)
        let targetFrame: CGRect
        if layout == .restore {
            guard let saved = restoreFrames[restoreKey] else {
                QuickOrbitNoticeCenter.shared.show(qoText("Für dieses Fenster ist noch keine frühere Anordnung gespeichert.", "No previous arrangement is stored for this window yet.", language: OrbitStore.shared.config.language))
                return
            }
            targetFrame = saved
        } else {
            restoreFrames[restoreKey] = currentFrame
            let visible = screen(containing: currentFrame)?.visibleFrame
                ?? NSScreen.main?.visibleFrame
                ?? CGRect(x: 0, y: 0, width: 1280, height: 720)
            let halfWidth = visible.width / 2
            let halfHeight = visible.height / 2
            switch layout {
            case .leftHalf:
                targetFrame = CGRect(x: visible.minX, y: visible.minY, width: halfWidth, height: visible.height)
            case .rightHalf:
                targetFrame = CGRect(x: visible.midX, y: visible.minY, width: halfWidth, height: visible.height)
            case .topLeft:
                targetFrame = CGRect(x: visible.minX, y: visible.midY, width: halfWidth, height: halfHeight)
            case .topRight:
                targetFrame = CGRect(x: visible.midX, y: visible.midY, width: halfWidth, height: halfHeight)
            case .bottomLeft:
                targetFrame = CGRect(x: visible.minX, y: visible.minY, width: halfWidth, height: halfHeight)
            case .bottomRight:
                targetFrame = CGRect(x: visible.midX, y: visible.minY, width: halfWidth, height: halfHeight)
            case .maximize:
                targetFrame = visible
            case .center:
                let width = min(currentFrame.width, visible.width)
                let height = min(currentFrame.height, visible.height)
                targetFrame = CGRect(x: visible.midX - width / 2, y: visible.midY - height / 2, width: width, height: height)
            case .restore:
                targetFrame = currentFrame
            }
        }

        guard set(frame: targetFrame.integral, for: window) else {
            QuickOrbitNoticeCenter.shared.show(qoText("Diese App erlaubt das Anordnen ihres Fensters nicht.", "This app doesn't allow its window to be arranged.", language: OrbitStore.shared.config.language))
            return
        }
        if layout == .restore { restoreFrames.removeValue(forKey: restoreKey) }
        QuickOrbitNoticeCenter.shared.show(qoText("Fenster angeordnet", "Window arranged", language: OrbitStore.shared.config.language))
    }

    private static func frame(of window: AXUIElement) -> CGRect? {
        var positionValue: CFTypeRef?
        var sizeValue: CFTypeRef?
        guard AXUIElementCopyAttributeValue(window, kAXPositionAttribute as CFString, &positionValue) == .success,
              AXUIElementCopyAttributeValue(window, kAXSizeAttribute as CFString, &sizeValue) == .success,
              let positionValue, let sizeValue,
              CFGetTypeID(positionValue) == AXValueGetTypeID(),
              CFGetTypeID(sizeValue) == AXValueGetTypeID() else { return nil }
        var position = CGPoint.zero
        var size = CGSize.zero
        guard AXValueGetValue(positionValue as! AXValue, .cgPoint, &position),
              AXValueGetValue(sizeValue as! AXValue, .cgSize, &size) else { return nil }
        let primaryTop = NSScreen.screens.first?.frame.maxY ?? 0
        return CGRect(x: position.x, y: primaryTop - position.y - size.height, width: size.width, height: size.height)
    }

    private static func set(frame: CGRect, for window: AXUIElement) -> Bool {
        let primaryTop = NSScreen.screens.first?.frame.maxY ?? 0
        var position = CGPoint(x: frame.minX, y: primaryTop - frame.maxY)
        var size = frame.size
        guard let positionValue = AXValueCreate(.cgPoint, &position),
              let sizeValue = AXValueCreate(.cgSize, &size) else { return false }
        let sizeResult = AXUIElementSetAttributeValue(window, kAXSizeAttribute as CFString, sizeValue)
        let positionResult = AXUIElementSetAttributeValue(window, kAXPositionAttribute as CFString, positionValue)
        return positionResult == .success && sizeResult == .success
    }

    private static func screen(containing frame: CGRect) -> NSScreen? {
        NSScreen.screens.first { $0.frame.contains(CGPoint(x: frame.midX, y: frame.midY)) }
            ?? NSScreen.screens.max { lhs, rhs in
                lhs.frame.intersection(frame).width * lhs.frame.intersection(frame).height
                    < rhs.frame.intersection(frame).width * rhs.frame.intersection(frame).height
            }
    }

    private static func windowKey(_ window: AXUIElement, pid: pid_t) -> String {
        for attribute in [kAXIdentifierAttribute as CFString, kAXTitleAttribute as CFString] {
            var value: CFTypeRef?
            if AXUIElementCopyAttributeValue(window, attribute, &value) == .success,
               let string = value as? String, !string.isEmpty {
                return "\(pid):\(string)"
            }
        }
        return "\(pid):\(CFHash(window))"
    }
}

// MARK: - Actions


@MainActor
enum OrbitRunner {
    static func run(_ item: OrbitItem) {
        guard item.enabled else { return }
        let health = OrbitValidator.health(for: item, language: OrbitStore.shared.config.language)
        guard health.valid else {
            QuickOrbitNoticeCenter.shared.show(health.message, diagnostic: .invalidAction)
            NSSound.beep()
            return
        }

        if item.type == .systemAction, item.target == "smartSuggestion" {
            if let suggestion = QuickOrbitUsageStatsCenter.shared.suggestion(from: OrbitStore.shared.visibleItems) {
                QuickOrbitNoticeCenter.shared.show(qoText("Vorschlag: \(suggestion.title)", "Suggestion: \(suggestion.title)", language: OrbitStore.shared.config.language))
                run(suggestion)
            } else {
                QuickOrbitNoticeCenter.shared.show(qoText("QuickOrbit lernt noch aus deinen lokalen Aktionen.", "QuickOrbit is still learning from your local actions.", language: OrbitStore.shared.config.language))
            }
            return
        }

        let activationProfileID = OrbitStore.shared.config.activeProfileID
        QuickOrbitUsageStatsCenter.shared.record(item)
        OrbitStore.shared.noteSuccessfulActivation(from: activationProfileID)

        switch item.type {
        case .app:
            guard let resource = quickOrbitResolvedResource(for: item) else { return }
            guard FileManager.default.fileExists(atPath: resource.url.path) else {
                resource.stopAccessing()
                return
            }
            NSWorkspace.shared.openApplication(
                at: resource.url,
                configuration: NSWorkspace.OpenConfiguration(),
                completionHandler: { _, _ in resource.stopAccessing() }
            )

        case .file:
            guard let resource = quickOrbitResolvedResource(for: item) else { return }
            NSWorkspace.shared.open(resource.url)
            resource.stopAccessing()

        case .url:
            var text = item.target.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !text.isEmpty else { return }
            if !text.contains("://") { text = "https://" + text }
            guard let components = URLComponents(string: text),
                  ["http", "https"].contains(components.scheme?.lowercased() ?? ""),
                  components.host?.isEmpty == false,
                  let url = components.url else { return }
            NSWorkspace.shared.open(url)

        case .shortcut:
            QuickOrbitNoticeCenter.shared.show(
                qoText("Diese alte Kurzbefehl-Aktion wurde entfernt.", "This legacy Shortcut action has been removed.", language: OrbitStore.shared.config.language)
            )

        case .pasteText:
            if copyQuickOrbitText(item.target) {
                QuickOrbitNoticeCenter.shared.show(qoText("Text kopiert", "Text copied", language: OrbitStore.shared.config.language))
            }

        case .clipboard, .windowLeft, .windowRight:
            // Only reachable for a manually crafted legacy item. Normal loading
            // removes these retired actions before they reach the interface.
            QuickOrbitNoticeCenter.shared.show(
                qoText("Diese alte Aktion wurde entfernt.", "This legacy action has been removed.", language: OrbitStore.shared.config.language)
            )

        case .screenshot:
            Task { @MainActor in
                ScreenshotManager.shared.captureArea()
            }

        case .systemAction, .windowManagement, .timer, .emoji:
            runSystemAction(item.target)

        case .edit:
            Task { @MainActor in
                OrbitController.shared.showQuickEditMenu()
            }

        case .shellCommand:
            Task { @MainActor in
                QuickOrbitBetaCommandRunner.run(item.target)
            }
        }
    }

    private static func runSystemAction(_ id: String) {
        if id.hasPrefix("emojiInsert:") {
            let emoji = String(id.dropFirst("emojiInsert:".count))
            guard !emoji.isEmpty else { return }
            if copyQuickOrbitText(emoji) {
                QuickOrbitNoticeCenter.shared.show(qoText("\(emoji) in die Zwischenablage kopiert", "\(emoji) copied to the clipboard", language: OrbitStore.shared.config.language))
            }
            return
        }

        if id == "stopwatch", let profileID = OrbitStore.shared.config.activeProfileID {
            QuickOrbitTimerCenter.shared.toggleStopwatch(profileID: profileID)
            return
        }

        if id.hasPrefix("timer") {
            let seconds: Int?
            if id == "timerCustom" {
                seconds = OrbitStore.shared.config.customTimerSeconds ?? 300
            } else if id.hasPrefix("timerSeconds") {
                seconds = Int(id.dropFirst("timerSeconds".count))
            } else {
                seconds = Int(id.dropFirst("timer".count)).map { $0 * 60 }
            }
            if let seconds,
               let profileID = OrbitStore.shared.config.activeProfileID {
                let profileName = OrbitStore.shared.activeProfile?.name ?? qoText("Profil", "Profile", language: OrbitStore.shared.config.language)
                QuickOrbitTimerCenter.shared.toggle(seconds: seconds, profileID: profileID, profileName: profileName)
                return
            }
        }

        switch id {
        case "copyTimestamp":
            if copyQuickOrbitText(ISO8601DateFormatter().string(from: Date())) {
                QuickOrbitNoticeCenter.shared.show(qoText("Zeitstempel kopiert", "Timestamp copied", language: OrbitStore.shared.config.language))
            }

        case "emojiPalette":
            NSApp.orderFrontCharacterPalette(nil)

        case "focus":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.Focus-Settings.extension",
                fallbackNotice: qoText("Systemeinstellungen → Fokus", "System Settings → Focus", language: OrbitStore.shared.config.language)
            )

        case "mediaPrevious":
            postMediaKey(18)

        case "mediaPlayPause":
            postMediaKey(16)

        case "mediaNext":
            postMediaKey(17)

        case "volumeUp":
            if !SystemAudioController.changeVolume(by: 0.0625) {
                QuickOrbitNoticeCenter.shared.show(qoText("Lautstärke konnte für dieses Ausgabegerät nicht geändert werden.", "Volume could not be changed for this output device.", language: OrbitStore.shared.config.language))
            }

        case "volumeDown":
            if !SystemAudioController.changeVolume(by: -0.0625) {
                QuickOrbitNoticeCenter.shared.show(qoText("Lautstärke konnte für dieses Ausgabegerät nicht geändert werden.", "Volume could not be changed for this output device.", language: OrbitStore.shared.config.language))
            }

        case "volumeMute":
            if !SystemAudioController.toggleMute() {
                QuickOrbitNoticeCenter.shared.show(qoText("Stumm konnte für dieses Ausgabegerät nicht geändert werden.", "Mute could not be changed for this output device.", language: OrbitStore.shared.config.language))
            }

        case "volumeStatus":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.Sound-Settings.extension",
                fallbackNotice: qoText("Systemeinstellungen → Ton", "System Settings → Sound", language: OrbitStore.shared.config.language)
            )

        case "liveClock":
            copyLiveValue(dateStyle: .none, timeStyle: .medium)

        case "liveDate":
            copyLiveValue(dateStyle: .full, timeStyle: .none)

        case "batteryStatus":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.Battery-Settings.extension",
                fallbackNotice: qoText("Systemeinstellungen → Batterie", "System Settings → Battery", language: OrbitStore.shared.config.language)
            )

        case "chargingStatus":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.Battery-Settings.extension",
                fallbackNotice: qoText("Systemeinstellungen → Batterie", "System Settings → Battery", language: OrbitStore.shared.config.language)
            )

        case "cpuStatus":
            openKnownPath(URL(fileURLWithPath: "/System/Applications/Utilities/Activity Monitor.app"))

        case "memoryStatus", "networkStatus", "thermalStatus":
            openKnownPath(URL(fileURLWithPath: "/System/Applications/Utilities/Activity Monitor.app"))

        case "storageStatus":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.settings.Storage",
                fallbackNotice: qoText("Systemeinstellungen → Allgemein → Speicher", "System Settings → General → Storage", language: OrbitStore.shared.config.language)
            )

        case "uptimeStatus":
            openKnownPath(URL(fileURLWithPath: "/System/Applications/Utilities/System Information.app"))

        case "batteryWarning":
            let enabled = !(OrbitStore.shared.config.lowBatteryWarningEnabled ?? false)
            OrbitStore.shared.config.lowBatteryWarningEnabled = enabled
            OrbitStore.shared.config.lowBatteryWarningThreshold = 20
            QuickOrbitBatteryWarningCenter.shared.setEnabled(enabled)
            QuickOrbitNoticeCenter.shared.show(enabled
                ? qoText("Akkualarm bei 20 % eingeschaltet", "20% battery alert enabled", language: OrbitStore.shared.config.language)
                : qoText("Akkualarm ausgeschaltet", "Battery alert disabled", language: OrbitStore.shared.config.language))

        case "newReminder":
            QuickOrbitEventComposerWindowController.shared.show(kind: .reminder)

        case "newCalendarEvent":
            QuickOrbitEventComposerWindowController.shared.show(kind: .calendarEvent)

        case "showAgenda":
            QuickOrbitAgendaWindowController.shared.show()

        case "clipboardHistory":
            QuickOrbitClipboardHistoryWindowController.shared.show()

        case "orbitDropBox":
            QuickOrbitDropBoxController.shared.show()

        case "ocrCapture":
            QuickOrbitOCRCenter.shared.captureText()

        case "translateText":
            QuickOrbitTranslationWindowController.shared.show()

        case "colorSampler":
            QuickOrbitColorSampler.pickAndCopy()

        case "windowLeftHalf":
            QuickOrbitWindowManager.arrange(.leftHalf)
        case "windowRightHalf":
            QuickOrbitWindowManager.arrange(.rightHalf)
        case "windowTopLeft":
            QuickOrbitWindowManager.arrange(.topLeft)
        case "windowTopRight":
            QuickOrbitWindowManager.arrange(.topRight)
        case "windowBottomLeft":
            QuickOrbitWindowManager.arrange(.bottomLeft)
        case "windowBottomRight":
            QuickOrbitWindowManager.arrange(.bottomRight)
        case "windowMaximize":
            QuickOrbitWindowManager.arrange(.maximize)
        case "windowCenter":
            QuickOrbitWindowManager.arrange(.center)
        case "windowRestore":
            QuickOrbitWindowManager.arrange(.restore)

        case "wifiStatus", "wifiSettings":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.wifi-settings-extension",
                fallbackNotice: qoText("Systemeinstellungen → WLAN", "System Settings → Wi-Fi", language: OrbitStore.shared.config.language)
            )

        case "bluetoothSettings":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.BluetoothSettings",
                fallbackNotice: qoText("Systemeinstellungen → Bluetooth", "System Settings → Bluetooth", language: OrbitStore.shared.config.language)
            )

        case "notificationsSettings":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.Notifications-Settings.extension",
                fallbackNotice: qoText("Systemeinstellungen → Mitteilungen", "System Settings → Notifications", language: OrbitStore.shared.config.language)
            )

        case "soundSettings":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.Sound-Settings.extension",
                fallbackNotice: qoText("Systemeinstellungen → Ton", "System Settings → Sound", language: OrbitStore.shared.config.language)
            )

        case "displaySettings":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.Displays-Settings.extension",
                fallbackNotice: qoText("Systemeinstellungen → Displays", "System Settings → Displays", language: OrbitStore.shared.config.language)
            )

        case "privacySettings":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.settings.PrivacySecurity.extension",
                fallbackNotice: qoText("Systemeinstellungen → Datenschutz & Sicherheit", "System Settings → Privacy & Security", language: OrbitStore.shared.config.language)
            )

        case "downloads":
            openKnownPath(FileManager.default.urls(for: .downloadsDirectory, in: .userDomainMask).first)

        case "desktopFolder":
            openKnownPath(FileManager.default.urls(for: .desktopDirectory, in: .userDomainMask).first)

        case "homeFolder":
            openKnownPath(FileManager.default.homeDirectoryForCurrentUser)

        case "trashFolder":
            openKnownPath(FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent(".Trash", isDirectory: true))

        case "activityMonitor":
            openKnownPath(URL(fileURLWithPath: "/System/Applications/Utilities/Activity Monitor.app"))

        case "calculator":
            openKnownPath(URL(fileURLWithPath: "/System/Applications/Calculator.app"))

        case "forceQuit":
            guard ensureAccessibilityAccess() else { return }
            postKeyboardShortcut(keyCode: 53, flags: [.maskCommand, .maskAlternate])

        case "displaySleep":
            let process = Process()
            process.executableURL = URL(fileURLWithPath: "/usr/bin/pmset")
            process.arguments = ["displaysleepnow"]
            do {
                try process.run()
            } catch {
                QuickOrbitNoticeCenter.shared.show(qoText("Display konnte nicht ausgeschaltet werden.", "The display could not be turned off.", language: OrbitStore.shared.config.language))
            }

        case "spotlight":
            guard ensureAccessibilityAccess() else { return }
            postKeyboardShortcut(keyCode: 49, flags: .maskCommand)

        case "lowPowerMode":
            openSystemSettings(
                urlString: "x-apple.systempreferences:com.apple.Battery-Settings.extension",
                fallbackNotice: qoText("Systemeinstellungen → Batterie/Energie → Stromsparmodus", "System Settings → Battery/Energy → Low Power Mode", language: OrbitStore.shared.config.language)
            )

        case "screenSaver":
            let candidates = [
                "/System/Library/CoreServices/ScreenSaverEngine.app",
                "/System/Library/CoreServices/ScreenSaverEngine.app/Contents/MacOS/ScreenSaverEngine"
            ]
            if let path = candidates.first(where: { FileManager.default.fileExists(atPath: $0) }) {
                if path.hasSuffix(".app") {
                    NSWorkspace.shared.openApplication(
                        at: URL(fileURLWithPath: path),
                        configuration: NSWorkspace.OpenConfiguration(),
                        completionHandler: nil
                    )
                } else {
                    let process = Process()
                    process.executableURL = URL(fileURLWithPath: path)
                    try? process.run()
                }
            } else {
                // Apple documents Lock Screen as another way to start the screen saver.
                postKeyboardShortcut(keyCode: 12, flags: [.maskControl, .maskCommand])
            }

        case "logout":
            guard ensureAccessibilityAccess() else { return }
            confirmLogout()

        case "brightnessUp":
            guard ensureAccessibilityAccess() else { return }
            postSystemDefinedKey(2)

        case "brightnessDown":
            guard ensureAccessibilityAccess() else { return }
            postSystemDefinedKey(3)

        case "lockScreen":
            guard ensureAccessibilityAccess() else { return }
            postKeyboardShortcut(keyCode: 12, flags: [.maskControl, .maskCommand])

        default:
            QuickOrbitNoticeCenter.shared.show(qoText("Unbekannte Mac-Aktion", "Unknown Mac action", language: OrbitStore.shared.config.language))
        }
    }

    private static func copyLiveValue(dateStyle: DateFormatter.Style, timeStyle: DateFormatter.Style) {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: (OrbitStore.shared.config.language ?? .german) == .german ? "de_DE" : "en_US")
        formatter.dateStyle = dateStyle
        formatter.timeStyle = timeStyle
        let value = formatter.string(from: Date())
        if copyQuickOrbitText(value) {
            QuickOrbitNoticeCenter.shared.show(qoText("\(value) in die Zwischenablage kopiert", "\(value) copied to the clipboard", language: OrbitStore.shared.config.language))
        }
    }

    private static func openSystemSettings(urlString: String, fallbackNotice: String) {
        if let url = URL(string: urlString), NSWorkspace.shared.open(url) {
            return
        }

        let settingsURL = URL(fileURLWithPath: "/System/Applications/System Settings.app")
        if FileManager.default.fileExists(atPath: settingsURL.path) {
            NSWorkspace.shared.openApplication(
                at: settingsURL,
                configuration: NSWorkspace.OpenConfiguration(),
                completionHandler: nil
            )
        }
        QuickOrbitNoticeCenter.shared.show(fallbackNotice)
    }

    private static func openKnownPath(_ url: URL?) {
        guard let url, FileManager.default.fileExists(atPath: url.path) else {
            QuickOrbitNoticeCenter.shared.show(
                qoText("Dieses Ziel ist auf diesem Mac nicht verfügbar.", "This destination is not available on this Mac.", language: OrbitStore.shared.config.language), diagnostic: .destinationUnavailable
            )
            return
        }
        if !NSWorkspace.shared.open(url) {
            QuickOrbitNoticeCenter.shared.show(QuickOrbitDiagnosticCode.destinationUnavailable.message(language: OrbitStore.shared.config.language), diagnostic: .destinationUnavailable)
        }
    }

    private static func ensureAccessibilityAccess() -> Bool {
        if AXIsProcessTrusted() { return true }
        let options = ["AXTrustedCheckOptionPrompt": true] as CFDictionary
        _ = AXIsProcessTrustedWithOptions(options)
        QuickOrbitNoticeCenter.shared.show(
            qoText(
                "Für diese Mac-Steuerung bitte QuickOrbit unter Datenschutz & Sicherheit → Bedienungshilfen erlauben.",
                "Allow QuickOrbit in Privacy & Security → Accessibility for this Mac control.",
                language: OrbitStore.shared.config.language
            ), diagnostic: .accessibilityRequired
        )
        return false
    }

    private static func postKeyboardShortcut(keyCode: CGKeyCode, flags: CGEventFlags) {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.08) {
            guard let down = CGEvent(keyboardEventSource: nil, virtualKey: keyCode, keyDown: true),
                  let up = CGEvent(keyboardEventSource: nil, virtualKey: keyCode, keyDown: false) else { return }
            down.flags = flags
            up.flags = flags
            down.post(tap: .cghidEventTap)
            up.post(tap: .cghidEventTap)
        }
    }

    // Media controls use the system-defined consumer keys. Try the event first;
    // if Accessibility is not granted, also request it so the next press works.
    private static func postMediaKey(_ key: Int32) {
        postSystemDefinedKey(key)
        if !AXIsProcessTrusted() {
            let options = ["AXTrustedCheckOptionPrompt": true] as CFDictionary
            _ = AXIsProcessTrustedWithOptions(options)
            QuickOrbitNoticeCenter.shared.show(
                qoText(
                    "Für Mediensteuerung QuickOrbit einmal unter Bedienungshilfen erlauben.",
                    "Allow QuickOrbit once in Accessibility for media controls.",
                    language: OrbitStore.shared.config.language
                )
            )
        }
    }

    // System-defined media key values from macOS' HID event map:
    // 0 volume up, 1 volume down, 2 brightness up, 3 brightness down,
    // 16 play/pause, 17 next track, 18 previous track.
    private static func postSystemDefinedKey(_ key: Int32) {
        func post(state: Int32, flagsRaw: UInt) {
            let data1 = Int((key << 16) | (state << 8))
            guard let event = NSEvent.otherEvent(
                with: .systemDefined,
                location: .zero,
                modifierFlags: NSEvent.ModifierFlags(rawValue: flagsRaw),
                timestamp: ProcessInfo.processInfo.systemUptime,
                windowNumber: 0,
                context: nil,
                subtype: 8,
                data1: data1,
                data2: -1
            ) else { return }
            event.cgEvent?.post(tap: .cghidEventTap)
        }

        post(state: 0xA, flagsRaw: 0xA00)
        post(state: 0xB, flagsRaw: 0xB00)
    }

    private static func confirmLogout() {
        let alert = NSAlert()
        alert.messageText = qoText("Vom Mac abmelden?", "Log out of this Mac?", language: OrbitStore.shared.config.language)
        alert.informativeText = qoText("Nicht gespeicherte Änderungen in anderen Apps könnten verloren gehen.", "Unsaved changes in other apps could be lost.", language: OrbitStore.shared.config.language)
        alert.alertStyle = .warning
        alert.addButton(withTitle: qoText("Abmelden", "Log Out", language: OrbitStore.shared.config.language))
        alert.addButton(withTitle: qoText("Abbrechen", "Cancel", language: OrbitStore.shared.config.language))
        guard alert.runModal() == .alertFirstButtonReturn else { return }

        // Option-Shift-Command-Q is Apple's documented immediate log-out shortcut.
        postKeyboardShortcut(keyCode: 12, flags: [.maskAlternate, .maskShift, .maskCommand])
    }

}

// MARK: - Screenshot

@MainActor
final class ScreenshotManager: ObservableObject {
    static let shared = ScreenshotManager()

    @Published var lastURL: URL?
    @Published var status = "Bereit"
    @Published var isWorking = false

    private var folderURL: URL {
        let pictures = FileManager.default.urls(for: .picturesDirectory, in: .userDomainMask).first
            ?? FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Pictures", isDirectory: true)
        let folder = pictures.appendingPathComponent("QuickOrbit Screenshots", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        return folder
    }

    func captureArea() {
        let url = nextURL()
        run(arguments: ["-i", url.path], expectedURL: url)
    }

    func captureAreaToClipboard() {
        run(arguments: ["-i", "-c"], expectedURL: nil)
    }

    func captureScreen() {
        let url = nextURL()
        run(arguments: ["-x", url.path], expectedURL: url)
    }

    func revealLast() {
        guard let lastURL else { return }
        NSWorkspace.shared.activateFileViewerSelecting([lastURL])
    }

    private func nextURL() -> URL {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd_HH-mm-ss"
        return folderURL.appendingPathComponent("QuickOrbit_\(formatter.string(from: Date())).png")
    }

    private func run(arguments: [String], expectedURL: URL?) {
        guard !isWorking else { return }
        isWorking = true
        status = "Screenshot läuft …"

        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/sbin/screencapture")
        process.arguments = arguments
        process.terminationHandler = { [weak self] process in
            guard let controller = self else { return }
            DispatchQueue.main.async { [controller] in
                controller.isWorking = false

                if process.terminationStatus == 0 {
                    if let expectedURL, FileManager.default.fileExists(atPath: expectedURL.path) {
                        controller.lastURL = expectedURL
                        controller.status = "Gespeichert"
                    } else if expectedURL == nil {
                        controller.status = "In Zwischenablage"
                    } else {
                        controller.status = "Abgebrochen"
                    }
                } else {
                    controller.status = "Abgebrochen oder nicht erlaubt"
                }
            }
        }

        do {
            try process.run()
        } catch {
            isWorking = false
            status = "Konnte nicht gestartet werden"
        }
    }
}

// MARK: - Local screen text recognition

@MainActor
final class QuickOrbitOCRCenter {
    static let shared = QuickOrbitOCRCenter()
    private var isWorking = false
    private(set) var isSelecting = false
    private var activeCaptureProcess: Process?
    private var resultPanel: NSPanel?

    func captureText() {
        guard !isWorking else {
            QuickOrbitNoticeCenter.shared.show(qoText("Texterkennung läuft bereits", "Text recognition is already running", language: OrbitStore.shared.config.language))
            return
        }

        guard CGPreflightScreenCaptureAccess() || CGRequestScreenCaptureAccess() else {
            QuickOrbitNoticeCenter.shared.show(
                qoText(
                    "Bildschirmaufnahme erlauben und QuickOrbit danach erneut öffnen.",
                    "Allow Screen Recording, then reopen QuickOrbit.",
                    language: OrbitStore.shared.config.language
                )
            )
            if let url = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture") {
                NSWorkspace.shared.open(url)
            }
            return
        }

        isWorking = true
        isSelecting = true
        OrbitController.shared.hideOverlay()
        StatusBarController.shared.closeQuickDockAfterPayloadDrag()
        // Let the originating mouse gesture and overlay dismissal finish before
        // handing pointer ownership to macOS's native screenshot selector.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.25) { [weak self] in
            self?.beginAreaSelection()
        }
    }

    private func beginAreaSelection() {
        let imageURL = FileManager.default.temporaryDirectory
            .appendingPathComponent("QuickOrbit-OCR-\(UUID().uuidString).png")
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/sbin/screencapture")
        process.arguments = ["-i", "-s", "-x", imageURL.path]
        process.terminationHandler = { [weak self] process in
            DispatchQueue.main.async {
                guard let self else { return }
                self.activeCaptureProcess = nil
                self.isSelecting = false
                guard process.terminationStatus == 0,
                      FileManager.default.fileExists(atPath: imageURL.path) else {
                    self.isWorking = false
                    try? FileManager.default.removeItem(at: imageURL)
                    return
                }
                self.recognizeText(in: imageURL)
            }
        }

        do {
            activeCaptureProcess = process
            try process.run()
        } catch {
            activeCaptureProcess = nil
            isSelecting = false
            isWorking = false
            try? FileManager.default.removeItem(at: imageURL)
            QuickOrbitNoticeCenter.shared.show(qoText("Bereichsauswahl konnte nicht gestartet werden.", "The area selector could not be started.", language: OrbitStore.shared.config.language), diagnostic: .captureFailed)
        }
    }

    private func recognizeText(in imageURL: URL) {
        guard let image = NSImage(contentsOf: imageURL),
              let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            finish(imageURL: imageURL, text: nil, errorMessage: qoText("Die Auswahl konnte nicht gelesen werden.", "The selection could not be read.", language: OrbitStore.shared.config.language))
            return
        }

        QuickOrbitNoticeCenter.shared.show(qoText("Text wird lokal erkannt …", "Recognizing text locally…", language: OrbitStore.shared.config.language))
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            let request = VNRecognizeTextRequest()
            request.recognitionLevel = .accurate
            request.usesLanguageCorrection = true
            request.automaticallyDetectsLanguage = true
            let codes = VNDetectBarcodesRequest()
            codes.symbologies = [.qr]

            do {
                try VNImageRequestHandler(cgImage: cgImage, options: [:]).perform([request, codes])
                let observations = (request.results ?? []).sorted { lhs, rhs in
                    let verticalDistance = abs(lhs.boundingBox.midY - rhs.boundingBox.midY)
                    return verticalDistance > 0.025
                        ? lhs.boundingBox.midY > rhs.boundingBox.midY
                        : lhs.boundingBox.minX < rhs.boundingBox.minX
                }
                let recognizedText = observations
                    .compactMap { $0.topCandidates(1).first?.string }
                    .joined(separator: "\n")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                var parts = recognizedText.isEmpty ? [] : [recognizedText]
                for code in codes.results ?? [] {
                    if let value = code.payloadStringValue, !parts.contains(value) { parts.append(value) }
                }
                let text = parts.joined(separator: "\n")
                DispatchQueue.main.async {
                    self?.finish(imageURL: imageURL, text: text, errorMessage: nil)
                }
            } catch {
                DispatchQueue.main.async {
                    self?.finish(
                        imageURL: imageURL,
                        text: nil,
                        errorMessage: qoText("Text konnte nicht erkannt werden.", "Text could not be recognized.", language: OrbitStore.shared.config.language)
                    )
                }
            }
        }
    }

    private func finish(imageURL: URL, text: String?, errorMessage: String?) {
        isWorking = false
        try? FileManager.default.removeItem(at: imageURL)

        if let errorMessage {
            QuickOrbitNoticeCenter.shared.show(errorMessage, diagnostic: .recognitionFailed)
            return
        }
        guard let text, !text.isEmpty else {
            QuickOrbitNoticeCenter.shared.show(qoText("In diesem Bereich wurde kein Text erkannt.", "No text was found in this area.", language: OrbitStore.shared.config.language))
            return
        }
        if copyQuickOrbitText(text) {
            QuickOrbitNoticeCenter.shared.show(qoText("Text erkannt und kopiert", "Text recognized and copied", language: OrbitStore.shared.config.language))
        }
        showResult(text)
    }

    private func showResult(_ text: String) {
        resultPanel?.close()
        let panel = NSPanel(contentRect: NSRect(x: 0, y: 0, width: 480, height: 300), styleMask: [.titled, .closable, .fullSizeContentView], backing: .buffered, defer: false)
        panel.titleVisibility = .hidden
        panel.titlebarAppearsTransparent = true
        let language = OrbitStore.shared.config.language
        panel.contentView = NSHostingView(rootView:
            VStack(alignment: .leading, spacing: 14) {
                Label(qoText("Erkannter Text & QR-Codes", "Recognized text & QR codes", language: language), systemImage: "text.viewfinder").font(.headline)
                ScrollView { Text(text).textSelection(.enabled).frame(maxWidth: .infinity, alignment: .leading).padding(12) }
                    .quickOrbitGlass(cornerRadius: 14)
                Text(qoText("Kalenderdaten vor dem Speichern prüfen. QR-Inhalte werden nicht automatisch geöffnet.", "Review calendar details before saving. QR contents are never opened automatically.", language: language)).font(.caption).foregroundStyle(.secondary)
                HStack {
                    Button(qoText("Schließen", "Close", language: language)) { [weak panel] in panel?.close() }.quickOrbitGlassButton()
                    Spacer()
                    Button(qoText("Kalendereintrag", "Calendar event", language: language)) { [weak panel] in
                        panel?.close()
                        QuickOrbitEventComposerWindowController.shared.show(kind: .calendarEvent, initialText: text)
                    }.quickOrbitColorButton(.blue)
                }
            }.padding(20).frame(width: 480, height: 300).background(SystemBackdrop())
        )
        let point = NSEvent.mouseLocation
        let frame = (NSScreen.screens.first { $0.frame.contains(point) } ?? NSScreen.main)?.visibleFrame ?? .zero
        panel.setFrameOrigin(NSPoint(x: min(max(point.x - 240, frame.minX), max(frame.minX, frame.maxX - 480)), y: min(max(point.y - 320, frame.minY), max(frame.minY, frame.maxY - 300))))
        resultPanel = panel
        panel.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
    }
}

// MARK: - Orbit geometry

/// One bounded entry: pointer movement does not change the tile layout.
struct OrbitSelectionGeometryCache {
    private struct Key: Equatable {
        let count: Int
        let layout: OrbitLayout
        let radius: CGFloat
        let spacing: CGFloat
        let tileSize: CGFloat
        let labels: Bool
        let screenFrame: CGRect?
        let visibleFrame: CGRect?
    }
    private var key: Key?
    private var value: [CGPoint] = []

    mutating func offsets(config: QuickOrbitConfig, screenFrame: CGRect?, visibleFrame: CGRect?) -> [CGPoint] {
        let next = Key(count: config.itemCount, layout: config.layout,
                       radius: OrbitGeometry.radius(config: config), spacing: CGFloat(config.itemSpacing),
                       tileSize: OrbitGeometry.tileSize(config: config), labels: config.showLabels,
                       screenFrame: screenFrame, visibleFrame: visibleFrame)
        if key == next { return value }
        var result = OrbitGeometry.offsets(count: next.count, layout: next.layout, radius: next.radius, spacingScale: next.spacing)
        if let screenFrame, let visibleFrame {
            let safeArea = CGRect(x: visibleFrame.minX - screenFrame.minX,
                                  y: screenFrame.maxY - visibleFrame.maxY,
                                  width: visibleFrame.width, height: visibleFrame.height)
            result = OrbitGeometry.fittedOffsets(result, tileSize: next.tileSize,
                                                  availableSize: screenFrame.size, showLabels: next.labels,
                                                  safeArea: safeArea)
        }
        key = next
        value = result
        return result
    }
}

enum OrbitGeometry {
    /// AppKit coordinates: below the anchor has negative y. Keep the center
    /// neutral and never treat occupied portions of circular/grid layouts as exits.
    static func isDismissRegion(mouse: CGPoint, anchor: CGPoint, layout: OrbitLayout, count: Int, deadZone: CGFloat) -> Bool {
        let threshold = max(36, deadZone + 14)
        switch resolvedLayout(layout, count: count) {
        case .fan, .compactArc, .horizontal: return mouse.y < anchor.y - threshold
        case .lowerFan: return mouse.y > anchor.y + threshold
        case .vertical: return mouse.x < anchor.x - threshold
        default: return false
        }
    }
    static func resolvedLayout(_ layout: OrbitLayout, count: Int) -> OrbitLayout {
        guard layout == .automatic else { return layout }
        if count <= 5 { return .fan }
        if count <= 8 { return .circle }
        return .grid
    }

    static func radius(config: QuickOrbitConfig) -> CGFloat {
        let base: CGFloat
        switch config.sizePreset {
        case .compact: base = 126
        case .comfortable: base = 158
        case .large: base = 192
        }
        let extra = CGFloat(max(config.itemCount - 8, 0)) * 4
        return max(CGFloat(config.radius), base + extra)
    }

    static func tileSize(config: QuickOrbitConfig) -> CGFloat {
        let base: CGFloat
        switch config.sizePreset {
        case .compact: base = config.itemCount > 10 ? 54 : 62
        case .comfortable: base = config.itemCount > 10 ? 62 : 72
        case .large: base = config.itemCount > 10 ? 70 : 82
        }
        return base * CGFloat(config.tileScale)
    }

    static func adjustedVisualCenter(
        from requested: CGPoint,
        offsets: [CGPoint],
        tileSize: CGFloat,
        availableSize: CGSize,
        showLabels: Bool,
        safeArea: CGRect? = nil
    ) -> CGPoint {
        guard let minOffsetX = offsets.map(\.x).min(), let maxOffsetX = offsets.map(\.x).max(),
              let minOffsetY = offsets.map(\.y).min(), let maxOffsetY = offsets.map(\.y).max() else { return requested }

        let labelRoom: CGFloat = showLabels ? 30 : 14
        let margin = tileSize / 2 + labelRoom
        let bounds = safeArea ?? CGRect(origin: .zero, size: availableSize)
        var result = requested

        let left = result.x + minOffsetX - margin
        let right = result.x + maxOffsetX + margin
        if left < bounds.minX + 10 { result.x += bounds.minX + 10 - left }
        if right > bounds.maxX - 10 { result.x -= right - (bounds.maxX - 10) }

        let top = result.y + minOffsetY - margin
        let bottom = result.y + maxOffsetY + margin
        if top < bounds.minY + 10 { result.y += bounds.minY + 10 - top }
        if bottom > bounds.maxY - 10 { result.y -= bottom - (bounds.maxY - 10) }

        return result
    }

    static func fittedOffsets(
        _ offsets: [CGPoint],
        tileSize: CGFloat,
        availableSize: CGSize,
        showLabels: Bool,
        safeArea: CGRect? = nil
    ) -> [CGPoint] {
        guard let minX = offsets.map(\.x).min(), let maxX = offsets.map(\.x).max(),
              let minY = offsets.map(\.y).min(), let maxY = offsets.map(\.y).max() else { return offsets }
        let bounds = safeArea ?? CGRect(origin: .zero, size: availableSize)
        let labelRoom: CGFloat = showLabels ? 30 : 14
        let sideRoom = tileSize + labelRoom * 2 + 20
        let usableWidth = max(bounds.width - sideRoom, tileSize)
        let usableHeight = max(bounds.height - sideRoom, tileSize)
        let widthScale = (maxX - minX) > 0 ? usableWidth / (maxX - minX) : 1
        let heightScale = (maxY - minY) > 0 ? usableHeight / (maxY - minY) : 1
        let scale = min(1, widthScale, heightScale)
        guard scale < 0.999 else { return offsets }
        return offsets.map { CGPoint(x: $0.x * scale, y: $0.y * scale) }
    }

    static func offsets(count: Int, layout: OrbitLayout, radius: CGFloat, spacingScale: CGFloat = 1.0) -> [CGPoint] {
        guard count > 0 else { return [] }

        switch resolvedLayout(layout, count: count) {
        case .automatic:
            return []
        case .circle:
            return (0..<count).map { index in
                let angle = -CGFloat.pi / 2 + CGFloat(index) * (.pi * 2 / CGFloat(count))
                return CGPoint(x: cos(angle) * radius, y: sin(angle) * radius)
            }
        case .fan:
            return fanOffsets(count: count, radius: radius, totalDegrees: 138 * min(max(spacingScale, 0.72), 1.35), centerAngle: -.pi / 2)
        case .lowerFan:
            return fanOffsets(count: count, radius: radius, totalDegrees: 138 * min(max(spacingScale, 0.72), 1.35), centerAngle: .pi / 2)
        case .compactArc:
            return fanOffsets(count: count, radius: radius * 0.74, totalDegrees: 76 * min(max(spacingScale, 0.72), 1.35), centerAngle: -.pi / 2)
        case .horizontal:
            let spacing = max(58, min(152, radius * 0.70 * spacingScale))
            let total = CGFloat(count - 1) * spacing
            let y = -max(86, radius * 0.62)
            return (0..<count).map { index in
                CGPoint(x: -total / 2 + CGFloat(index) * spacing, y: y)
            }
        case .vertical:
            let spacing = max(56, min(146, radius * 0.66 * spacingScale))
            let total = CGFloat(count - 1) * spacing
            let x = max(86, radius * 0.62)
            return (0..<count).map { index in
                CGPoint(x: x, y: -total / 2 + CGFloat(index) * spacing)
            }
        case .grid:
            let columns = Int(ceil(sqrt(Double(count))))
            let rows = Int(ceil(Double(count) / Double(columns)))
            let spacing = max(58, min(142, radius * 0.62 * spacingScale))
            let width = CGFloat(columns - 1) * spacing
            let height = CGFloat(rows - 1) * spacing
            // Keep every grid row clearly outside the mouse dead zone. In the
            // previous layout the last row of a 3x3 grid could slip below the
            // pointer center while hit testing still expected an upward gesture.
            let lift = height / 2 + max(68, spacing * 0.56)
            return (0..<count).map { index in
                let row = index / columns
                let column = index % columns
                return CGPoint(
                    x: -width / 2 + CGFloat(column) * spacing,
                    y: -height / 2 + CGFloat(row) * spacing - lift
                )
            }
        }
    }

    private static func fanOffsets(
        count: Int,
        radius: CGFloat,
        totalDegrees: CGFloat,
        centerAngle: CGFloat
    ) -> [CGPoint] {
        if count == 1 {
            return [CGPoint(x: cos(centerAngle) * radius, y: sin(centerAngle) * radius)]
        }
        let total = totalDegrees * .pi / 180
        let start = centerAngle - total / 2
        let step = total / CGFloat(count - 1)
        return (0..<count).map { index in
            let angle = start + CGFloat(index) * step
            return CGPoint(x: cos(angle) * radius, y: sin(angle) * radius)
        }
    }

    // Small helper for selection hysteresis. It estimates the local spacing
    // without depending on the current visual tile style.
    static func tileSizeForSelection(offsets: [CGPoint]) -> CGFloat {
        guard offsets.count > 1 else { return 72 }
        var nearest = CGFloat.greatestFiniteMagnitude
        for i in offsets.indices {
            for j in offsets.indices where i != j {
                nearest = min(nearest, hypot(offsets[i].x - offsets[j].x, offsets[i].y - offsets[j].y))
            }
        }
        return nearest.isFinite ? min(max(nearest * 0.72, 48), 96) : 72
    }

    static func selectedIndex(
        mouse: CGPoint,
        anchor: CGPoint,
        offsets: [CGPoint],
        layout: OrbitLayout,
        deadZone: CGFloat,
        previous: Int?
    ) -> Int? {
        let dx = mouse.x - anchor.x
        let dy = -(mouse.y - anchor.y)
        let distance = hypot(dx, dy)
        guard !offsets.isEmpty else { return nil }

        if distance < deadZone {
            if let previous, distance >= deadZone * 0.86 { return previous }
            return nil
        }

        let resolved = resolvedLayout(layout, count: offsets.count)

        // Reihe: use the real visual slot directions and put the hit boundaries
        // exactly between them. This gives inner and outer fields comparable areas.
        if resolved == .horizontal {
            guard -dy >= deadZone * 0.30 else { return nil }
            let forward = max(-dy, deadZone * 0.65)
            let pointerSlope = dx / max(forward, 1)
            let centers = offsets.map { offset in
                offset.x / max(-offset.y, deadZone * 0.65)
            }
            guard let first = centers.first, let last = centers.last else { return nil }
            let edgePadding = centers.count > 1 ? abs(centers[1] - centers[0]) * 0.58 : 0.8
            guard pointerSlope >= first - edgePadding, pointerSlope <= last + edgePadding else { return nil }

            var candidate = 0
            var best = CGFloat.greatestFiniteMagnitude
            for (index, center) in centers.enumerated() {
                let delta = abs(pointerSlope - center)
                if delta < best { best = delta; candidate = index }
            }

            if let previous, previous != candidate, centers.indices.contains(previous) {
                let localGap = max(abs(centers[candidate] - centers[previous]), 0.08)
                if abs(pointerSlope - centers[previous]) <= best + localGap * 0.12 { return previous }
            }
            return candidate
        }

        // Spalte: same visual midpoint logic, rotated by 90 degrees.
        if resolved == .vertical {
            guard dx >= deadZone * 0.30 else { return nil }
            let forward = max(dx, deadZone * 0.65)
            let pointerSlope = dy / max(forward, 1)
            let centers = offsets.map { offset in
                offset.y / max(offset.x, deadZone * 0.65)
            }
            guard let minCenter = centers.min(), let maxCenter = centers.max() else { return nil }
            let sorted = centers.sorted()
            let edgePadding = sorted.count > 1 ? abs(sorted[1] - sorted[0]) * 0.58 : 0.8
            guard pointerSlope >= minCenter - edgePadding, pointerSlope <= maxCenter + edgePadding else { return nil }

            var candidate = 0
            var best = CGFloat.greatestFiniteMagnitude
            for (index, center) in centers.enumerated() {
                let delta = abs(pointerSlope - center)
                if delta < best { best = delta; candidate = index }
            }
            if let previous, previous != candidate, centers.indices.contains(previous) {
                let localGap = max(abs(centers[candidate] - centers[previous]), 0.08)
                if abs(pointerSlope - centers[previous]) <= best + localGap * 0.12 { return previous }
            }
            return candidate
        }

        // Raster: columns are selected by direction, rows by the real visual
        // distance of each row from the pointer center. The previous version mapped
        // distance in the opposite row order for a 3x3 layout; that made the middle
        // and near rows unnecessarily hard to reach.
        if resolved == .grid {
            let count = offsets.count
            let columns = Int(ceil(sqrt(Double(count))))
            let forward = -dy
            guard forward >= deadZone * 0.28 else { return nil }

            // Pick the visually nearest row using the actual y position of that row.
            var rowCandidates: [(row: Int, forward: CGFloat)] = []
            let rowCount = Int(ceil(Double(count) / Double(columns)))
            for row in 0..<rowCount {
                let indices = (0..<columns).map { row * columns + $0 }.filter { $0 < count }
                guard !indices.isEmpty else { continue }
                let average = indices.map { -offsets[$0].y }.reduce(0, +) / CGFloat(indices.count)
                rowCandidates.append((row, max(average, deadZone)))
            }

            var chosenRow = rowCandidates.first?.row ?? 0
            var rowDistance = CGFloat.greatestFiniteMagnitude
            for row in rowCandidates {
                let delta = abs(forward - row.forward)
                if delta < rowDistance { rowDistance = delta; chosenRow = row.row }
            }

            // Once the row is known, choose the field whose visible x-position is
            // closest to the pointer. This scales correctly for 2x2, 3x3 and 4x4
            // grids and keeps every visible tile reachable from its own center.
            let rowIndices = (0..<columns).map { chosenRow * columns + $0 }.filter { $0 < count }
            guard var candidate = rowIndices.first else { return nil }
            var xDistance = CGFloat.greatestFiniteMagnitude
            for index in rowIndices {
                let delta = abs(dx - offsets[index].x)
                if delta < xDistance { xDistance = delta; candidate = index }
            }

            if rowIndices.count > 1 {
                let xs = rowIndices.map { offsets[$0].x }.sorted()
                let gap = abs(xs[1] - xs[0])
                guard dx >= (xs.first ?? dx) - gap * 0.62,
                      dx <= (xs.last ?? dx) + gap * 0.62 else { return nil }
            }

            if let previous, previous != candidate, offsets.indices.contains(previous) {
                let previousTarget = offsets[previous]
                let candidateTarget = offsets[candidate]
                let previousScore = hypot(dx - previousTarget.x, dy - previousTarget.y)
                let candidateScore = hypot(dx - candidateTarget.x, dy - candidateTarget.y)
                let hysteresis = max(8, OrbitGeometry.tileSizeForSelection(offsets: offsets) * 0.10)
                if previousScore <= candidateScore + hysteresis { return previous }
            }
            return candidate
        }

        let pointerAngle = atan2(dy, dx)
        func angleDifference(_ a: CGFloat, _ b: CGFloat) -> CGFloat {
            var diff = abs(a - b)
            while diff > .pi { diff = abs(diff - 2 * .pi) }
            return diff
        }

        var bestIndex = 0
        var bestDifference = CGFloat.greatestFiniteMagnitude
        for (index, offset) in offsets.enumerated() {
            let itemAngle = atan2(offset.y, offset.x)
            let difference = angleDifference(pointerAngle, itemAngle)
            if difference < bestDifference {
                bestDifference = difference
                bestIndex = index
            }
        }

        if let previous, offsets.indices.contains(previous), previous != bestIndex {
            let previousAngle = atan2(offsets[previous].y, offsets[previous].x)
            let previousDifference = angleDifference(pointerAngle, previousAngle)
            let adaptiveHysteresis = min(0.17, max(0.08, (.pi / CGFloat(max(offsets.count, 2))) * 0.28))
            if previousDifference <= bestDifference + adaptiveHysteresis { return previous }
        }
        return bestIndex
    }
}

// MARK: - Overlay state

enum OverlayMode: Equatable {
    case run
    case edit
}

@MainActor
final class OverlayState: ObservableObject {
    @Published var visible = false
    @Published var mode: OverlayMode = .run
    @Published var anchor = CGPoint.zero
    @Published var selectionAnchor = CGPoint.zero
    @Published var pointer = CGPoint.zero
    @Published var selected: Int?
    @Published private var storedProgress = 0.0
    var progress: Double {
        get { storedProgress }
        set {
            // Idle/reset ticks must not invalidate the entire Orbit at 60 Hz.
            let value = newValue.isFinite ? min(max(newValue, 0), 1) : 0
            guard value != storedProgress else { return }
            storedProgress = value
        }
    }
    @Published var profileCount = 1
    @Published var profileIndex = 0
    @Published var profileColors: [OrbitProfileColor] = []
    @Published var animationToken = 0
    @Published var awaitingCenter = false
    @Published var payloadDragging = false
}

// MARK: - Global controller

@MainActor
final class OrbitController: ObservableObject {
    static let shared = OrbitController()

    let overlay = OverlayState()

    private let store = OrbitStore.shared
    private var overlayPanel: NSPanel?
    private var eventTap: CFMachPort?
    private var runLoopSource: CFRunLoopSource?
    private var timer: Timer?
    private var selectionStartedAt: Date?
    private var openingSelectionReadyAt = Date.distantPast
    private var validatedSelection: OrbitItem?
    private var selectionValid = false
    private var selectionValidatedAt: TimeInterval = 0
    private var selectionGeometryCache = OrbitSelectionGeometryCache()
    private var payloadPressActive = false
    private var clickSelection: (itemID: UUID, point: CGPoint)?
    private var lastPointerSample = CGPoint.zero
    private var lastPointerSampleAt = Date.distantPast
    private var pointerVelocity: CGFloat = 0
    private var fastActivationUntil = Date.distantPast
    private var selectionReady = true
    private var shouldScheduleMainProfileReturnAfterCurrentOrbit = false

    private var quickEditArmed = false
    private var quickEditAnchor = CGPoint.zero
    private var quickEditModifierWasPressed = false
    private var directEditSelection = false

    private var trackpadHoldWorkItem: DispatchWorkItem?
    private var trackpadHoldAnchor = CGPoint.zero
    private var trackpadOpenedOrbit = false

    private var controlTapPressedAt: Date?
    private var controlTapCancelled = false

    private var eligibleProfileIDs: [UUID] = []
    private var scrollAccumulator: CGFloat = 0
    private var lastProfileScrollAt = Date.distantPast

    private var fallbackGlobalMonitor: Any?
    private var fallbackLocalMonitor: Any?
    private var workspaceObserver: NSObjectProtocol?
    private var lastExternalBundleIdentifier: String?

    private init() {}

    func start() {
        stop()
        installWorkspaceObserver()
        installEventTap()
        if eventTap == nil { installFallbackMonitors() }
        refreshActiveApplicationContext()
    }

    func stop() {
        timer?.invalidate()
        timer = nil
        cancelTrackpadHold()

        if let eventTap { CGEvent.tapEnable(tap: eventTap, enable: false) }
        if let runLoopSource {
            CFRunLoopRemoveSource(CFRunLoopGetMain(), runLoopSource, .commonModes)
        }
        eventTap = nil
        runLoopSource = nil

        if let fallbackGlobalMonitor { NSEvent.removeMonitor(fallbackGlobalMonitor) }
        if let fallbackLocalMonitor { NSEvent.removeMonitor(fallbackLocalMonitor) }
        fallbackGlobalMonitor = nil
        fallbackLocalMonitor = nil

        if let workspaceObserver {
            NSWorkspace.shared.notificationCenter.removeObserver(workspaceObserver)
        }
        workspaceObserver = nil
    }

    func reconnect() {
        start()
    }

    func testMenu() {
        showOrbit(at: NSEvent.mouseLocation, mode: .run)
    }

    // Same edit orbit that normally appears after the Control gesture.
    // Used by the assignable "Edit" action so both paths behave identically.
    func showQuickEditMenu() {
        directEditSelection = true
        showOrbit(at: NSEvent.mouseLocation, mode: .edit)
    }

    func requestAccessibility() {
        _ = AXIsProcessTrustedWithOptions(["AXTrustedCheckOptionPrompt": true] as CFDictionary)
    }

    func openAccessibilitySettings() {
        guard let url = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility") else { return }
        NSWorkspace.shared.open(url)
    }

    private func installWorkspaceObserver() {
        workspaceObserver = NSWorkspace.shared.notificationCenter.addObserver(
            forName: NSWorkspace.didActivateApplicationNotification,
            object: nil,
            queue: .main
        ) { [weak self] notification in
            guard let app = notification.userInfo?[NSWorkspace.applicationUserInfoKey] as? NSRunningApplication else { return }
            MainActor.assumeIsolated {
                self?.handleActivatedApplication(app)
            }
        }
    }

    private func refreshActiveApplicationContext() {
        guard let app = NSWorkspace.shared.frontmostApplication else { return }
        handleActivatedApplication(app)
    }

    private func handleActivatedApplication(_ app: NSRunningApplication) {
        guard let bundleIdentifier = app.bundleIdentifier else { return }
        if bundleIdentifier == Bundle.main.bundleIdentifier {
            // Settings and profile editing must never inherit an older return
            // countdown from an Orbit that was closed in another app.
            store.cancelMainProfileReturnCountdown()
            return
        }
        lastExternalBundleIdentifier = bundleIdentifier
        store.applyPendingMainProfileReturnForOrbitIfNeeded()
        store.autoSelectProfile(for: bundleIdentifier)
    }

    private func currentContextBundleIdentifier() -> String? {
        let frontmost = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        if let frontmost, frontmost != Bundle.main.bundleIdentifier {
            lastExternalBundleIdentifier = frontmost
            return frontmost
        }
        return lastExternalBundleIdentifier ?? frontmost
    }

    func externalApplicationForMacControl() -> NSRunningApplication? {
        if let frontmost = NSWorkspace.shared.frontmostApplication,
           frontmost.bundleIdentifier != Bundle.main.bundleIdentifier {
            lastExternalBundleIdentifier = frontmost.bundleIdentifier
            return frontmost
        }
        guard let lastExternalBundleIdentifier else { return nil }
        return NSRunningApplication.runningApplications(withBundleIdentifier: lastExternalBundleIdentifier)
            .first(where: { !$0.isTerminated })
    }

    private func installEventTap() {
        let mask =
            (CGEventMask(1) << CGEventType.otherMouseDown.rawValue) |
            (CGEventMask(1) << CGEventType.leftMouseDown.rawValue) |
            (CGEventMask(1) << CGEventType.leftMouseUp.rawValue) |
            (CGEventMask(1) << CGEventType.leftMouseDragged.rawValue) |
            (CGEventMask(1) << CGEventType.mouseMoved.rawValue) |
            (CGEventMask(1) << CGEventType.otherMouseDragged.rawValue) |
            (CGEventMask(1) << CGEventType.scrollWheel.rawValue) |
            (CGEventMask(1) << CGEventType.flagsChanged.rawValue) |
            (CGEventMask(1) << CGEventType.keyDown.rawValue)

        let userInfo = UnsafeMutableRawPointer(Unmanaged.passUnretained(self).toOpaque())

        guard let tap = CGEvent.tapCreate(
            tap: .cgSessionEventTap,
            place: .headInsertEventTap,
            options: .defaultTap,
            eventsOfInterest: mask,
            callback: { _, type, event, userInfo in
                guard let userInfo else { return Unmanaged.passUnretained(event) }
                let controller = Unmanaged<OrbitController>.fromOpaque(userInfo).takeUnretainedValue()

                if type == .tapDisabledByTimeout || type == .tapDisabledByUserInput {
                    Task { @MainActor in
                        if let tap = controller.eventTap { CGEvent.tapEnable(tap: tap, enable: true) }
                    }
                    return Unmanaged.passUnretained(event)
                }

                let swallow = MainActor.assumeIsolated {
                    controller.handle(type: type, event: event)
                }
                return swallow ? nil : Unmanaged.passUnretained(event)
            },
            userInfo: userInfo
        ) else { return }

        eventTap = tap
        let source = CFMachPortCreateRunLoopSource(kCFAllocatorDefault, tap, 0)
        runLoopSource = source
        CFRunLoopAddSource(CFRunLoopGetMain(), source, .commonModes)
        CGEvent.tapEnable(tap: tap, enable: true)
    }

    private func installFallbackMonitors() {
        fallbackGlobalMonitor = NSEvent.addGlobalMonitorForEvents(
            matching: [.otherMouseDown, .leftMouseDown, .leftMouseUp, .leftMouseDragged, .mouseMoved, .otherMouseDragged, .scrollWheel, .flagsChanged, .keyDown]
        ) { [weak self] event in
            MainActor.assumeIsolated {
                self?.handleFallback(event)
            }
        }

        fallbackLocalMonitor = NSEvent.addLocalMonitorForEvents(
            matching: [.otherMouseDown, .leftMouseDown, .leftMouseUp, .leftMouseDragged, .mouseMoved, .otherMouseDragged, .scrollWheel, .flagsChanged, .keyDown]
        ) { [weak self] event in
            MainActor.assumeIsolated {
                self?.handleFallback(event)
            }
            return event
        }
    }

    private func handleFallback(_ event: NSEvent) {
        if QuickOrbitOCRCenter.shared.isSelecting {
            cancelTrackpadHold()
            return
        }
        switch event.type {
        case .otherMouseDown:
            guard event.buttonNumber == 2, store.config.middleClickEnabled else { return }
            cancelTrackpadHold()
            trackpadOpenedOrbit = false
            if overlay.visible { hideOverlay() } else { showOrbit(at: NSEvent.mouseLocation, mode: .run) }

        case .leftMouseDown:
            if overlay.visible, overlay.mode == .run,
               hypot(NSEvent.mouseLocation.x - overlay.selectionAnchor.x, NSEvent.mouseLocation.y - overlay.selectionAnchor.y) <= max(CGFloat(store.config.deadZone), 54) {
                hideOverlay()
                return
            }
            if overlay.visible, overlay.mode == .run, store.config.orbitAutoSelect == false {
                _ = beginClickSelection(at: NSEvent.mouseLocation)
                return
            }
            beginTrackpadHold(at: NSEvent.mouseLocation)

        case .leftMouseUp:
            if clickSelection != nil { _ = finishClickSelection(at: NSEvent.mouseLocation) }
            cancelTrackpadHold()

        case .leftMouseDragged:
            cancelTrackpadHoldIfMoved(to: NSEvent.mouseLocation)
            StatusBarController.shared.handlePointerProximity(at: NSEvent.mouseLocation)
            handlePointerMove(point: NSEvent.mouseLocation, flags: cgFlags(from: event.modifierFlags))

        case .mouseMoved, .otherMouseDragged:
            StatusBarController.shared.handlePointerProximity(at: NSEvent.mouseLocation)
            handlePointerMove(point: NSEvent.mouseLocation, flags: cgFlags(from: event.modifierFlags))

        case .scrollWheel:
            handleProfileScroll(deltaY: event.scrollingDeltaY, isTrackpad: event.hasPreciseScrollingDeltas)

        case .flagsChanged:
            handleModifierFlags(cgFlags(from: event.modifierFlags))

        case .keyDown:
            handleKeyDown(keyCode: Int64(event.keyCode))

        default:
            break
        }
    }

    /// A click commits the highlighted tile on release. A real drag remains a
    /// native text/file drag and never triggers the action a second time.
    private func beginClickSelection(at point: CGPoint) -> Bool {
        clickSelection = nil
        updateSelection(at: point)
        guard overlay.visible, selectionReady,
              let index = overlay.selected, store.visibleItems.indices.contains(index) else { return false }
        let item = store.visibleItems[index]
        guard item.enabled, OrbitValidator.health(for: item).valid else { return false }
        clickSelection = (item.id, point)
        return !QuickOrbitNativeDragPayload.canExport(item)
    }

    private func finishClickSelection(at point: CGPoint) -> Bool {
        guard let clickSelection else { return false }
        self.clickSelection = nil
        let consumesEvent = store.visibleItems.first(where: { $0.id == clickSelection.itemID })
            .map { !QuickOrbitNativeDragPayload.canExport($0) } ?? true
        guard overlay.visible, !overlay.payloadDragging,
              hypot(point.x - clickSelection.point.x, point.y - clickSelection.point.y) <= 12 else { return consumesEvent }
        updateSelection(at: point)
        guard overlay.visible, let index = overlay.selected,
              store.visibleItems.indices.contains(index),
              store.visibleItems[index].id == clickSelection.itemID else { return consumesEvent }
        let item = store.visibleItems[index]
        hideOverlay()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.04) {
            guard OrbitStore.shared.editorSlot == nil else { return }
            OrbitRunner.run(item)
        }
        return consumesEvent
    }

    private func cgFlags(from flags: NSEvent.ModifierFlags) -> CGEventFlags {
        var result: CGEventFlags = []
        if flags.contains(.control) { result.insert(.maskControl) }
        if flags.contains(.option) { result.insert(.maskAlternate) }
        if flags.contains(.command) { result.insert(.maskCommand) }
        if flags.contains(.shift) { result.insert(.maskShift) }
        return result
    }

    private func handle(type: CGEventType, event: CGEvent) -> Bool {
        if QuickOrbitOCRCenter.shared.isSelecting {
            cancelTrackpadHold()
            return false
        }
        switch type {
        case .leftMouseDown:
            let point = NSEvent.mouseLocation

            // If QuickOrbit was opened from the trackpad, pressing once more in the
            // center/dead-zone is an explicit cancel gesture. This is intentionally
            // independent from releasing the first press, so the orbit does not close
            // unexpectedly while the user is still deciding.
            if overlay.visible, overlay.mode == .run {
                let centerCancelRadius = max(CGFloat(store.config.deadZone), 54)
                let distanceToCenter = hypot(point.x - overlay.selectionAnchor.x, point.y - overlay.selectionAnchor.y)
                if distanceToCenter <= centerCancelRadius {
                    trackpadOpenedOrbit = false
                    cancelTrackpadHold()
                    hideOverlay()
                    return false
                }
                if store.config.orbitAutoSelect == false {
                    return beginClickSelection(at: point)
                }
            }

            beginTrackpadHold(at: point)
            return false

        case .leftMouseUp:
            if clickSelection != nil { return finishClickSelection(at: NSEvent.mouseLocation) }
            cancelTrackpadHold()
            return false

        case .leftMouseDragged:
            cancelTrackpadHoldIfMoved(to: NSEvent.mouseLocation)
            StatusBarController.shared.handlePointerProximity(at: NSEvent.mouseLocation)
            handlePointerMove(point: NSEvent.mouseLocation, flags: event.flags)
            return false

        case .otherMouseDown:
            let button = event.getIntegerValueField(.mouseEventButtonNumber)
            guard button == 2, store.config.middleClickEnabled else { return false }

            // The physical middle mouse button is its own activation path. Never let a
            // pending trackpad hold affect it.
            cancelTrackpadHold()
            trackpadOpenedOrbit = false

            if overlay.visible {
                hideOverlay()
                return store.config.suppressMiddleClick
            }

            cancelQuickEditArm()
            QuickReplaceController.shared.close()
            showOrbit(at: NSEvent.mouseLocation, mode: .run)
            return store.config.suppressMiddleClick

        case .mouseMoved, .otherMouseDragged:
            StatusBarController.shared.handlePointerProximity(at: NSEvent.mouseLocation)
            handlePointerMove(point: NSEvent.mouseLocation, flags: event.flags)
            return false

        case .scrollWheel:
            let delta = CGFloat(event.getDoubleValueField(.scrollWheelEventPointDeltaAxis1))
            let isTrackpad = event.getIntegerValueField(.scrollWheelEventIsContinuous) != 0
            let consume = overlay.visible && overlay.mode == .run
            handleProfileScroll(deltaY: delta, isTrackpad: isTrackpad)
            return consume

        case .flagsChanged:
            handleModifierFlags(event.flags)
            return false

        case .keyDown:
            let keyCode = event.getIntegerValueField(.keyboardEventKeycode)
            handleKeyDown(keyCode: keyCode)
            return false

        default:
            return false
        }
    }

    private func beginTrackpadHold(at point: CGPoint) {
        let trackpadEnabled = store.config.trackpadHoldEnabled ?? false
        let mouseEnabled = store.config.mouseHoldEnabled ?? false
        guard trackpadEnabled || mouseEnabled else { return }
        guard !NSApp.isActive else { return }
        cancelTrackpadHold()
        trackpadHoldAnchor = point

        // macOS reports a primary click from a mouse and a click from a trackpad
        // through the same leftMouseDown event. Use the shorter enabled hold as the
        // activation deadline, while movement still cancels it immediately.
        let trackpadDuration = min(max(store.config.trackpadHoldDuration ?? 3.0, 1.0), 6.0)
        let mouseDuration = min(max(store.config.mouseHoldDuration ?? 2.0, 0.8), 5.0)
        let duration: Double
        if trackpadEnabled && mouseEnabled { duration = min(trackpadDuration, mouseDuration) }
        else if mouseEnabled { duration = mouseDuration }
        else { duration = trackpadDuration }
        let work = DispatchWorkItem { [weak self] in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.trackpadHoldWorkItem = nil
                guard !self.overlay.visible else { return }
                QuickReplaceController.shared.close()
                self.trackpadOpenedOrbit = true
                self.showOrbit(at: NSEvent.mouseLocation, mode: .run)
                if self.store.config.haptics && !(self.store.config.energySavingMode ?? false) {
                    NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
                }
            }
        }
        trackpadHoldWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + duration, execute: work)
    }

    private func cancelTrackpadHoldIfMoved(to point: CGPoint) {
        let distance = hypot(point.x - trackpadHoldAnchor.x, point.y - trackpadHoldAnchor.y)
        if distance > 12 { cancelTrackpadHold() }
    }

    private func cancelTrackpadHold() {
        trackpadHoldWorkItem?.cancel()
        trackpadHoldWorkItem = nil
    }

    private func handleProfileScroll(deltaY: CGFloat, isTrackpad: Bool) {
        guard overlay.visible, eligibleProfileIDs.count > 1 else { return }

        scrollAccumulator += deltaY

        // Mouse wheel and trackpad deliberately use different tuning. A normal mouse
        // wheel should feel immediate; precise/continuous trackpad scrolling is slowed
        // down so one swipe cannot race through several profiles.
        let threshold: CGFloat = isTrackpad ? 18 : 1
        let cooldown: TimeInterval = isTrackpad ? 0.34 : 0.08

        guard abs(scrollAccumulator) >= threshold else { return }
        guard Date().timeIntervalSince(lastProfileScrollAt) >= cooldown else { return }
        let direction = scrollAccumulator > 0 ? -1 : 1
        scrollAccumulator = 0
        lastProfileScrollAt = Date()

        guard let currentID = store.config.activeProfileID,
              let current = eligibleProfileIDs.firstIndex(of: currentID) else { return }

        let nextIndex = (current + direction + eligibleProfileIDs.count) % eligibleProfileIDs.count
        store.switchProfile(to: eligibleProfileIDs[nextIndex])
        overlay.selected = nil
        overlay.progress = 0
        overlay.payloadDragging = false
        selectionStartedAt = nil
        overlay.profileCount = eligibleProfileIDs.count
        overlay.profileIndex = nextIndex
        overlay.animationToken &+= 1
        prepareOpeningSelection()
        fastActivationUntil = .distantPast
        pointerVelocity = 0

        if store.config.haptics && !(store.config.energySavingMode ?? false) {
            NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
        }
    }

    private func handleKeyDown(keyCode: Int64) {
        controlTapCancelled = true
        if keyCode == 53 {
            cancelQuickEditArm()
            QuickReplaceController.shared.close()
            hideOverlay()
            return
        }

        if quickEditArmed || (overlay.visible && overlay.mode == .edit) {
            // A real keyboard shortcut is being used. Do not hijack Control/Option.
            cancelQuickEditArm()
            if overlay.mode == .edit { hideOverlay() }
        }
    }

    private func handleModifierFlags(_ flags: CGEventFlags) {
        let tapModifier = store.config.tapOpenModifier ?? .control
        let activationKeyOnly = tapModifier.matchesExactly(flags)
        let activationKeyIsDown = flags.contains(tapModifier.requiredFlag)

        // Optional single modifier tap. A short tap toggles QuickOrbit open/closed.
        // If the selected modifier is also used by Quick Edit, moving while it is
        // held continues to enter the editing gesture exactly as before.
        if store.config.controlTapOpenEnabled ?? false {
            if controlTapPressedAt != nil && activationKeyIsDown && !activationKeyOnly {
                controlTapCancelled = true
            }
            if activationKeyOnly && controlTapPressedAt == nil {
                controlTapPressedAt = Date()
                controlTapCancelled = false
                quickEditAnchor = NSEvent.mouseLocation
            } else if !activationKeyIsDown, let pressedAt = controlTapPressedAt {
                let duration = Date().timeIntervalSince(pressedAt)
                controlTapPressedAt = nil
                let isShortTap = duration <= 0.34 && !controlTapCancelled
                controlTapCancelled = false

                if isShortTap {
                    cancelQuickEditArm(resetPressed: false)
                    QuickReplaceController.shared.close()

                    if overlay.visible && overlay.mode == .run {
                        trackpadOpenedOrbit = false
                        hideOverlay()
                    } else if !overlay.visible {
                        showOrbit(at: NSEvent.mouseLocation, mode: .run)
                    }

                    quickEditModifierWasPressed = false
                    return
                }
            }
        } else {
            controlTapPressedAt = nil
            controlTapCancelled = false
        }

        guard store.config.quickEditEnabled else {
            cancelQuickEditArm()
            return
        }

        let pressed = store.config.quickEditModifier.matchesExactly(flags)

        if pressed && !quickEditModifierWasPressed {
            if !overlay.visible {
                QuickReplaceController.shared.close()
                quickEditArmed = true
                quickEditAnchor = NSEvent.mouseLocation
            }
        } else if !pressed && quickEditModifierWasPressed {
            let requiredStillHeld = flags.intersection(store.config.quickEditModifier.requiredFlags)
                == store.config.quickEditModifier.requiredFlags

            if requiredStillHeld {
                // Another modifier was added. Treat this as a normal keyboard shortcut.
                cancelQuickEditArm(resetPressed: false)
                if overlay.visible && overlay.mode == .edit { hideOverlay() }
            } else {
                finishQuickEditGesture()
            }
        }

        quickEditModifierWasPressed = pressed
    }

    private func handlePointerMove(point: CGPoint, flags: CGEventFlags) {
        if controlTapPressedAt != nil && hypot(point.x - quickEditAnchor.x, point.y - quickEditAnchor.y) > 8 {
            controlTapCancelled = true
        }

        if quickEditArmed {
            guard store.config.quickEditModifier.matchesExactly(flags) else {
                cancelQuickEditArm()
                return
            }

            let travel = hypot(point.x - quickEditAnchor.x, point.y - quickEditAnchor.y)
            if travel >= store.config.quickEditTravel {
                quickEditArmed = false
                directEditSelection = false
                showOrbit(at: quickEditAnchor, mode: .edit)
            }
        }

        guard overlay.visible else { return }
        updateSelection(at: point)
    }

    private func finishQuickEditGesture() {
        defer { cancelQuickEditArm(resetPressed: false) }

        guard overlay.visible, overlay.mode == .edit else { return }
        let selected = overlay.selected
        let point = overlay.pointer
        hideOverlay()

        guard let selected, store.visibleItems.indices.contains(selected) else { return }
        store.selectedSlot = selected
        QuickReplaceController.shared.show(slot: selected, near: point)
    }

    private func cancelQuickEditArm(resetPressed: Bool = true) {
        quickEditArmed = false
        if resetPressed { quickEditModifierWasPressed = false }
    }

    private func showOrbit(at point: CGPoint, mode: OverlayMode) {
        guard !QuickOrbitOCRCenter.shared.isSelecting else { return }
        guard mode == .edit || store.editorSlot == nil else { return }
        if mode == .run, NSEvent.pressedMouseButtons & 1 != 0,
           NSPasteboard(name: .drag).types?.contains(.fileURL) == true {
            QuickOrbitDropBoxController.shared.show()
            return
        }
        shouldScheduleMainProfileReturnAfterCurrentOrbit = !NSApp.isActive
        store.cancelMainProfileReturnCountdown()
        let bundleID = currentContextBundleIdentifier()
        var eligible = store.eligibleProfiles(for: bundleID)
        if eligible.isEmpty {
            if let mainID = store.mainProfileID,
               let main = store.profiles.first(where: { $0.id == mainID }) {
                eligible = [main]
            } else if let first = store.profiles.first {
                eligible = [first]
            }
        }

        guard !eligible.isEmpty else { return }
        eligibleProfileIDs = eligible.map(\.id)
        if let activeID = store.config.activeProfileID, !eligibleProfileIDs.contains(activeID),
           let first = eligibleProfileIDs.first {
            store.switchProfile(to: first)
        }

        store.ensureActiveProfileIsUsable()
        guard !store.visibleItems.isEmpty else { return }

        overlay.profileCount = eligibleProfileIDs.count
        overlay.profileIndex = store.config.activeProfileID.flatMap { eligibleProfileIDs.firstIndex(of: $0) } ?? 0
        overlay.profileColors = eligible.map { $0.color ?? .blue }
        scrollAccumulator = 0
        overlay.mode = mode

        // Keep the pointer untouched. Near an edge, move only the Orbit's visual
        // and interaction center inward and require one deliberate trip to it.
        let anchor = point
        let selectionAnchor = adjustedSelectionAnchor(for: point)
        let centerShift = hypot(selectionAnchor.x - point.x, selectionAnchor.y - point.y)
        selectionReady = centerShift < 2

        overlay.anchor = anchor
        overlay.selectionAnchor = selectionAnchor
        overlay.pointer = point
        overlay.selected = nil
        overlay.awaitingCenter = !selectionReady
        lastPointerSample = anchor
        lastPointerSampleAt = Date()
        pointerVelocity = 0
        fastActivationUntil = .distantPast
        overlay.progress = 0
        overlay.payloadDragging = false
        overlay.animationToken &+= 1
        prepareOpeningSelection()
        withAnimation(.easeOut(duration: 0.18)) {
            overlay.visible = true
        }
        store.setOrbitSessionActive(true)
        selectionStartedAt = nil

        prepareOverlayPanel(near: anchor)
        overlayPanel?.orderFrontRegardless()

        timer?.invalidate()
        let samplingInterval = (store.config.energySavingMode ?? false) ? (1.0 / 30.0) : (1.0 / 60.0)
        timer = Timer.scheduledTimer(withTimeInterval: samplingInterval, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated {
                self?.tick()
            }
        }
        timer?.tolerance = samplingInterval * 0.1
        if let timer { RunLoop.main.add(timer, forMode: .common) }
    }

    private func prepareOpeningSelection() {
        let level = store.config.orbitAnimationLevel ?? .subtle
        let rotates = OrbitGeometry.resolvedLayout(store.config.layout, count: store.config.itemCount) == .circle && (store.config.circleOpeningRotation ?? true)
        let active = (level == .full || (rotates && level != .none)) && !(store.config.energySavingMode ?? false) && !NSWorkspace.shared.accessibilityDisplayShouldReduceMotion
        let duration = min(max(store.config.orbitAnimationDuration ?? 0.38, 0.16), 1.2)
        openingSelectionReadyAt = active ? Date().addingTimeInterval(duration + Double(store.config.itemCount) * 0.014 * min(max(duration / 0.38, 0.55), 2)) : .distantPast
    }

    private func updateSelection(at point: CGPoint) {
        guard overlay.visible, !payloadPressActive, !overlay.payloadDragging else { return }

        let now = Date()
        let dt = now.timeIntervalSince(lastPointerSampleAt)
        if dt > 0.003 && dt < 0.20 {
            let distance = hypot(point.x - lastPointerSample.x, point.y - lastPointerSample.y)
            let instantVelocity = CGFloat(distance / dt)
            pointerVelocity = pointerVelocity * 0.58 + instantVelocity * 0.42
        } else if dt >= 0.20 {
            pointerVelocity = 0
        }
        lastPointerSample = point
        lastPointerSampleAt = now
        if overlay.pointer != point { overlay.pointer = point }

        let config = store.config
        if overlay.mode == .run, selectionReady,
           OrbitGeometry.isDismissRegion(mouse: point, anchor: overlay.selectionAnchor, layout: config.layout, count: config.itemCount, deadZone: CGFloat(config.deadZone)) {
            overlay.selected = nil
            overlay.progress = 0
            selectionStartedAt = nil
            hideOverlay()
            return
        }
        let screen = NSScreen.screens.first(where: { $0.frame.contains(overlay.selectionAnchor) }) ?? NSScreen.main
        let selectionOffsets = selectionGeometryCache.offsets(
            config: config, screenFrame: screen?.frame, visibleFrame: screen?.visibleFrame
        )

        let deadZone = overlay.mode == .edit
            ? max(CGFloat(config.deadZone), 42)
            : CGFloat(config.deadZone)

        if !selectionReady {
            let distanceToCenter = hypot(point.x - overlay.selectionAnchor.x, point.y - overlay.selectionAnchor.y)
            guard distanceToCenter <= max(30, deadZone * 0.72) else {
                overlay.selected = nil
                overlay.progress = 0
                selectionStartedAt = nil
                return
            }
            selectionReady = true
            overlay.awaitingCenter = false
            pointerVelocity = 0
            lastPointerSample = point
            lastPointerSampleAt = now
            if config.haptics && !(config.energySavingMode ?? false) {
                NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
            }
        }

        let newSelection = OrbitGeometry.selectedIndex(
            mouse: point,
            anchor: overlay.selectionAnchor,
            offsets: selectionOffsets,
            layout: config.layout,
            deadZone: deadZone,
            previous: overlay.selected
        )

        if newSelection != overlay.selected {
            overlay.selected = newSelection
            overlay.progress = 0
            selectionStartedAt = newSelection == nil ? nil : now

            if newSelection != nil, store.smartFlickEnabled,
               pointerVelocity >= CGFloat(config.smartFlickVelocity ?? 980) {
                fastActivationUntil = now.addingTimeInterval(0.24)
            } else if newSelection == nil {
                fastActivationUntil = .distantPast
            }

            if newSelection != nil, config.haptics, !(config.energySavingMode ?? false) {
                NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
            }
        }

        if overlay.mode == .run, store.config.orbitAutoSelect == false, eventTap == nil {
            // Fallback monitors cannot swallow a global click. Keep the panel
            // interactive so a click does not reach the app beneath it.
            overlayPanel?.ignoresMouseEvents = false
        } else if overlay.mode == .run,
           let selected = overlay.selected,
           store.visibleItems.indices.contains(selected),
           QuickOrbitNativeDragPayload.canExport(store.visibleItems[selected]) {
            overlayPanel?.ignoresMouseEvents = false
        } else {
            overlayPanel?.ignoresMouseEvents = true
        }

    }

    private func adjustedSelectionAnchor(for point: CGPoint) -> CGPoint {
        guard let screen = NSScreen.screens.first(where: { $0.frame.contains(point) }) ?? NSScreen.main else { return point }
        let config = store.config
        let localCenter = CGPoint(x: point.x - screen.frame.minX, y: screen.frame.maxY - point.y)
        let safeArea = CGRect(
            x: screen.visibleFrame.minX - screen.frame.minX,
            y: screen.frame.maxY - screen.visibleFrame.maxY,
            width: screen.visibleFrame.width,
            height: screen.visibleFrame.height
        )
        let fitted = OrbitGeometry.fittedOffsets(
            OrbitGeometry.offsets(count: config.itemCount, layout: config.layout, radius: OrbitGeometry.radius(config: config), spacingScale: CGFloat(config.itemSpacing)),
            tileSize: OrbitGeometry.tileSize(config: config),
            availableSize: screen.frame.size,
            showLabels: config.showLabels,
            safeArea: safeArea
        )
        let adjusted = OrbitGeometry.adjustedVisualCenter(
            from: localCenter,
            offsets: fitted,
            tileSize: OrbitGeometry.tileSize(config: config),
            availableSize: screen.frame.size,
            showLabels: config.showLabels,
            safeArea: safeArea
        )
        return CGPoint(x: screen.frame.minX + adjusted.x, y: screen.frame.maxY - adjusted.y)
    }

    private func tick() {
        if overlay.mode == .run, store.editorSlot != nil {
            hideOverlay()
            return
        }
        guard overlay.visible else {
            timer?.invalidate()
            timer = nil
            return
        }

        guard !payloadPressActive, !overlay.payloadDragging else { return }
        let pointer = NSEvent.mouseLocation
        if pointer != overlay.pointer || !selectionReady { updateSelection(at: pointer) }

        // Control-based Quick Edit confirms on modifier release. The assignable
        // Edit action has no modifier to release, so it confirms after a short dwell.
        if overlay.mode == .edit {
            guard directEditSelection else {
                overlay.progress = overlay.selected == nil ? 0 : 1
                return
            }

            guard let selected = overlay.selected,
                  store.visibleItems.indices.contains(selected),
                  let selectionStartedAt else {
                overlay.progress = 0
                return
            }

            let duration = max(0.38, min(store.config.dwellTime, 0.70))
            let elapsed = Date().timeIntervalSince(selectionStartedAt)
            overlay.progress = min(max(elapsed / duration, 0), 1)

            if overlay.progress >= 1 {
                let point = overlay.pointer
                directEditSelection = false
                if store.config.haptics && !(store.config.energySavingMode ?? false) {
                    NSHapticFeedbackManager.defaultPerformer.perform(.levelChange, performanceTime: .now)
                }
                store.selectedSlot = selected
                hideOverlay()
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.06) {
                    QuickReplaceController.shared.show(slot: selected, near: point)
                }
            }
            return
        }

        if overlay.mode == .run, store.config.orbitAutoSelect == false {
            overlay.progress = 0
            return
        }

        guard let selected = overlay.selected,
              store.visibleItems.indices.contains(selected),
              let selectionStartedAt else {
            overlay.progress = 0
            return
        }

        let item = store.visibleItems[selected]
        if Date() < openingSelectionReadyAt {
            overlay.progress = 0
            self.selectionStartedAt = Date()
            return
        }
        let validationTime = ProcessInfo.processInfo.systemUptime
        if validatedSelection != item || validationTime - selectionValidatedAt >= 0.4 {
            validatedSelection = item
            selectionValid = OrbitValidator.health(for: item).valid
            selectionValidatedAt = validationTime
        }
        guard item.enabled, selectionValid else {
            if overlay.progress != 0 { overlay.progress = 0 }
            return
        }

        let now = Date()
        let normalDuration = max(store.config.dwellTime, 0.18)
        let duration = store.smartFlickEnabled && now <= fastActivationUntil
            ? min(normalDuration, max(store.config.smartFlickDwell ?? 0.16, 0.10))
            : normalDuration
        let elapsed = now.timeIntervalSince(selectionStartedAt)
        overlay.progress = min(max(elapsed / duration, 0), 1)

        if overlay.progress >= 1 {
            if store.config.haptics && !(store.config.energySavingMode ?? false) {
                NSHapticFeedbackManager.defaultPerformer.perform(.levelChange, performanceTime: .now)
            }
            hideOverlay()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.04) {
                guard OrbitStore.shared.editorSlot == nil else { return }
                OrbitRunner.run(item)
            }
        }
    }

    func hideOverlay() {
        cancelTrackpadHold()
        clickSelection = nil
        validatedSelection = nil
        payloadPressActive = false
        let wasVisible = overlay.visible
        let shouldScheduleReturn = shouldScheduleMainProfileReturnAfterCurrentOrbit
        shouldScheduleMainProfileReturnAfterCurrentOrbit = false
        withAnimation(.easeIn(duration: 0.13)) {
            overlay.visible = false
        }
        store.setOrbitSessionActive(false)
        overlay.selected = nil
        overlay.progress = 0
        selectionStartedAt = nil
        selectionReady = true
        overlay.awaitingCenter = false
        overlay.payloadDragging = false
        scrollAccumulator = 0
        pointerVelocity = 0
        fastActivationUntil = .distantPast
        timer?.invalidate()
        timer = nil
        overlayPanel?.ignoresMouseEvents = true

        if wasVisible && shouldScheduleReturn {
            store.scheduleMainProfileReturnAfterOrbitClosed()
        }

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.16) { [weak self] in
            guard let self, !self.overlay.visible else { return }
            self.overlayPanel?.orderOut(nil)
        }
    }

    func payloadPressDidBegin() {
        guard overlay.visible, overlay.mode == .run else { return }
        payloadPressActive = true
        overlay.progress = 0
        selectionStartedAt = nil
        fastActivationUntil = .distantPast
    }

    func payloadPressDidEnd() {
        payloadPressActive = false
        selectionStartedAt = overlay.selected == nil ? nil : Date()
    }

    func payloadDragDidBegin() {
        payloadPressActive = false
        timer?.invalidate()
        timer = nil
        overlay.progress = 0
        overlay.payloadDragging = true
        selectionStartedAt = nil
        DispatchQueue.main.async { [weak self] in
            self?.overlayPanel?.ignoresMouseEvents = true
        }
    }

    func payloadDragDidEnd() {
        overlay.payloadDragging = false
        hideOverlay()
    }

    private func prepareOverlayPanel(near point: CGPoint) {
        guard let screen = NSScreen.screens.first(where: { $0.frame.contains(point) }) ?? NSScreen.main else { return }

        if overlayPanel == nil {
            let panel = NSPanel(
                contentRect: screen.frame,
                styleMask: [.borderless, .nonactivatingPanel],
                backing: .buffered,
                defer: false
            )
            panel.level = .statusBar
            panel.isOpaque = false
            panel.backgroundColor = .clear
            panel.hasShadow = false
            panel.ignoresMouseEvents = true
            panel.hidesOnDeactivate = false
            panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .stationary]
            panel.contentView = NSHostingView(rootView: OrbitOverlayView(state: overlay, store: store).environment(\.quickOrbitLiveSurface, true))
            overlayPanel = panel
        }

        overlayPanel?.setFrame(screen.frame, display: true)
    }
}

// MARK: - Floating Quick Edit panel

@MainActor
final class QuickReplaceController {
    static let shared = QuickReplaceController()
    private var panel: NSPanel?

    func show(slot: Int, near point: CGPoint) {
        if OrbitStore.shared.config.items.indices.contains(slot), !OrbitStore.shared.config.items[slot].enabled {
            FloatingActionEditorController.shared.show(slot: slot)
            return
        }
        close()

        let size = CGSize(width: 500, height: 390)
        guard let screen = NSScreen.screens.first(where: { $0.frame.contains(point) }) ?? NSScreen.main else { return }
        let visible = screen.visibleFrame
        let origin = CGPoint(
            x: min(max(point.x - size.width / 2, visible.minX + 14), visible.maxX - size.width - 14),
            y: min(max(point.y - size.height / 2, visible.minY + 14), visible.maxY - size.height - 14)
        )

        let panel = NSPanel(
            contentRect: CGRect(origin: origin, size: size),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        panel.level = .popUpMenu
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = true
        panel.hidesOnDeactivate = false
        panel.isMovableByWindowBackground = true
        panel.becomesKeyOnlyIfNeeded = true
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]
        panel.contentView = NSHostingView(rootView: QuickReplaceView(slot: slot) { [weak self] in self?.close() })

        self.panel = panel
        panel.orderFrontRegardless()
    }

    func close() {
        panel?.orderOut(nil)
        panel = nil
    }
}

private enum QuickEditPanelMode: Equatable {
    case menu
    case change
    case move
}

struct QuickReplaceView: View {
    @ObservedObject private var store = OrbitStore.shared
    let slot: Int
    let onDone: () -> Void

    @State private var mode: QuickEditPanelMode = .menu
    @State private var apps: [InstalledAppChoice] = Array(InstalledApps.cached().prefix(8))
    @State private var showDeleteConfirmation = false

    private var current: OrbitItem {
        guard store.config.items.indices.contains(slot) else { return .empty(slot) }
        return store.config.items[slot]
    }

    var body: some View {
        VStack(spacing: 0) {
            header
            if store.profiles.count > 1 {
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 7) {
                        ForEach(store.profiles) { profile in
                            Button { store.switchProfile(to: profile.id) } label: {
                                HStack(spacing: 5) {
                                    Circle()
                                        .fill((profile.color ?? .gray).color)
                                        .frame(width: 7, height: 7)
                                    Text(profile.name)
                                        .font(.caption2.weight(.semibold))
                                }
                                .padding(.horizontal, 9)
                                .padding(.vertical, 6)
                                .background(
                                    store.config.activeProfileID == profile.id ? Color.primary.opacity(0.10) : Color.clear,
                                    in: Capsule()
                                )
                            }
                            .buttonStyle(.plain)
                        }
                    }
                    .padding(.horizontal, 16)
                    .padding(.bottom, 10)
                }
            }
            Divider().opacity(0.45)

            Group {
                switch mode {
                case .menu: actionMenu
                case .change: changeMenu
                case .move: moveMenu
                }
            }
            .padding(18)
        }
        .background {
            RoundedRectangle(cornerRadius: 24, style: .continuous)
                .fill(Color(nsColor: .windowBackgroundColor).opacity(0.42))
                .quickOrbitGlass(cornerRadius: 24)
                .shadow(color: .black.opacity(0.14), radius: 22, y: 10)
        }
        .clipShape(RoundedRectangle(cornerRadius: 24, style: .continuous))
        .padding(1)
        .confirmationDialog(
            qoText("Feld wirklich komplett löschen?", "Delete this field completely?", language: store.config.language),
            isPresented: $showDeleteConfirmation,
            titleVisibility: .visible
        ) {
            Button(qoText("Feld komplett löschen", "Delete field completely", language: store.config.language), role: .destructive) {
                store.removeSlot(slot)
                onDone()
            }
            Button(qoText("Abbrechen", "Cancel", language: store.config.language), role: .cancel) { }
        }
    }

    private var header: some View {
        HStack(spacing: 12) {
            FieldIcon(item: current, size: 42)
            VStack(alignment: .leading, spacing: 2) {
                Text(qoText("Feld \(slot + 1)", "Field \(slot + 1)", language: store.config.language))
                    .font(.headline)
                Text(current.enabled ? current.title : qoText("Noch leer", "Still empty", language: store.config.language))
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
            Spacer()
            if mode != .menu {
                Button { mode = .menu } label: { Image(systemName: "chevron.left") }
                    .buttonStyle(.plain)
                    .quickOrbitGlass(cornerRadius: QuickOrbitUI.smallRadius, interactive: true)
            }
            Button { onDone() } label: { Image(systemName: "xmark") }
                .buttonStyle(.plain)
                .quickOrbitGlass(cornerRadius: QuickOrbitUI.smallRadius, interactive: true)
        }
        .padding(16)
    }

    private var actionMenu: some View {
        VStack(spacing: 12) {
            Text(qoText("Was möchtest du machen?", "What do you want to do?", language: store.config.language))
                .font(.caption.weight(.semibold))
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, alignment: .leading)

            LazyVGrid(columns: [GridItem(.flexible()), GridItem(.flexible())], spacing: 12) {
                panelAction(qoText("Ändern", "Change", language: store.config.language), "slider.horizontal.3", .accentColor) { mode = .change }
                panelAction(qoText("Verschieben", "Move", language: store.config.language), "arrow.left.arrow.right", .primary) { mode = .move }
                panelAction(qoText("Löschen", "Delete", language: store.config.language), "trash", .red) {
                    showDeleteConfirmation = true
                }
            }
        }
    }

    private func panelAction(_ title: String, _ symbol: String, _ color: Color, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            HStack(spacing: 10) {
                Image(systemName: symbol)
                    .font(.system(size: 17, weight: .semibold))
                    .foregroundStyle(color)
                Text(title)
                    .font(.subheadline.weight(.semibold))
                Spacer()
            }
            .padding(.horizontal, 14)
            .frame(height: 64)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .quickOrbitGlass(cornerRadius: 16, interactive: true)
    }

    private var changeMenu: some View {
        VStack(alignment: .leading, spacing: 13) {
            Text(qoText("Neue Aktion auswählen", "Choose a new action", language: store.config.language))
                .font(.caption.weight(.semibold))
                .foregroundStyle(.secondary)

            QuickOrbitGlassGroup(spacing: 8) {
                LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 8), count: 4), spacing: 10) {
                    ForEach(apps) { app in
                        Button {
                            apply(app)
                        } label: {
                            VStack(spacing: 5) {
                                Image(nsImage: app.icon)
                                    .resizable()
                                    .scaledToFit()
                                    .frame(width: 38, height: 38)
                                Text(app.name)
                                    .font(.caption2)
                                    .lineLimit(1)
                                    .minimumScaleFactor(0.7)
                            }
                            .frame(maxWidth: .infinity)
                            .frame(height: 64)
                        }
                        .buttonStyle(.plain)
                        .quickOrbitGlass(cornerRadius: QuickOrbitUI.smallRadius, interactive: true)
                        .quickOrbitPickerHover()
                    }
                }
            }

            HStack(spacing: 9) {
                Button { chooseOtherApp() } label: { Label(qoText("Andere App", "Other app", language: store.config.language), systemImage: "app.fill") }
                    .quickOrbitGlassButton()
                Button { chooseFile() } label: { Label(qoText("Datei", "File", language: store.config.language), systemImage: "folder.badge.plus") }
                    .quickOrbitGlassButton()
                Button {
                    var item = current
                    item.type = .screenshot
                    item.target = "area"
                    item.title = "Screenshot"
                    item.symbol = "camera.viewfinder"
                    item.enabled = true
                    store.setItem(item, at: slot)
                    onDone()
                } label: { Label(qoText("Screenshot", "Screenshot", language: store.config.language), systemImage: "camera.viewfinder") }
                    .quickOrbitGlassButton()

                Spacer()

                Button(qoText("Alle Aktionen …", "All actions …", language: store.config.language)) {
                    onDone()
                    FloatingActionEditorController.shared.show(slot: slot)
                }
                .quickOrbitGlassButton(prominent: true)
            }
        }
    }

    private var moveMenu: some View {
        VStack(spacing: 18) {
            Text(qoText("Feld \(slot + 1) verschieben", "Move field \(slot + 1)", language: store.config.language))
                .font(.title3.weight(.semibold))
            Text(qoText("Die Nachbarfelder tauschen dabei ihren Platz mit diesem Feld.", "Neighboring fields swap positions with this field.", language: store.config.language))
                .font(.caption)
                .foregroundStyle(.secondary)

            HStack(spacing: 16) {
                Button {
                    store.moveSlot(slot, by: -1)
                    onDone()
                } label: {
                    Label(qoText("Nach links", "Move left", language: store.config.language), systemImage: "arrow.left")
                        .frame(maxWidth: .infinity)
                }
                .quickOrbitGlassButton(prominent: true)
                .disabled(slot == 0)

                Button {
                    store.moveSlot(slot, by: 1)
                    onDone()
                } label: {
                    Label(qoText("Nach rechts", "Move right", language: store.config.language), systemImage: "arrow.right")
                        .frame(maxWidth: .infinity)
                }
                .quickOrbitGlassButton(prominent: true)
                .disabled(slot >= store.config.itemCount - 1)
            }
        }
        .frame(maxHeight: .infinity)
    }

    private func apply(_ app: InstalledAppChoice) {
        var item = current
        item.type = .app
        item.target = app.url.path
        item.securityScopedBookmark = quickOrbitBookmark(for: app.url)
        item.title = app.name
        item.symbol = "app.fill"
        item.enabled = true
        store.setItem(item, at: slot)
        onDone()
    }

    private func chooseOtherApp() {
        let panel = NSOpenPanel()
        panel.title = "App für Feld \(slot + 1) auswählen"
        panel.canChooseDirectories = false
        panel.canChooseFiles = true
        panel.allowsMultipleSelection = false
        panel.allowedContentTypes = [.application]
        if panel.runModal() == .OK, let url = panel.url {
            apply(InstalledAppChoice(id: url.path, name: url.deletingPathExtension().lastPathComponent, url: url))
        }
    }

    private func chooseFile() {
        let panel = NSOpenPanel()
        panel.title = "Datei oder Ordner für Feld \(slot + 1) auswählen"
        panel.canChooseDirectories = true
        panel.canChooseFiles = true
        panel.allowsMultipleSelection = false
        if panel.runModal() == .OK, let url = panel.url {
            var item = current
            item.type = .file
            item.target = url.path
            item.securityScopedBookmark = quickOrbitBookmark(for: url)
            item.title = url.lastPathComponent
            item.symbol = url.hasDirectoryPath ? "folder.fill" : "doc.fill"
            item.enabled = true
            store.setItem(item, at: slot)
            onDone()
        }
    }
}

// MARK: - Overlay UI

struct OrbitOverlayView: View {
    @ObservedObject var state: OverlayState
    @ObservedObject var store: OrbitStore

    var body: some View {
        GeometryReader { proxy in
            let screenFrame = activeScreenFrame()
            let visibleFrame = activeScreenVisibleFrame()
            let safeArea = CGRect(
                x: visibleFrame.minX - screenFrame.minX,
                y: screenFrame.maxY - visibleFrame.maxY,
                width: visibleFrame.width,
                height: visibleFrame.height
            )
            let center = CGPoint(
                x: state.anchor.x - screenFrame.minX,
                y: screenFrame.maxY - state.anchor.y
            )
            let interactionCenter = CGPoint(
                x: state.selectionAnchor.x - screenFrame.minX,
                y: screenFrame.maxY - state.selectionAnchor.y
            )
            let pointer = CGPoint(
                x: state.pointer.x - screenFrame.minX,
                y: screenFrame.maxY - state.pointer.y
            )

            ZStack {
                if state.visible {
                    OrbitMenuVisual(
                        items: store.visibleItems,
                        selectedIndex: state.selected,
                        progress: state.progress,
                        config: store.config,
                        mode: state.mode,
                        center: center,
                        interactionCenter: interactionCenter,
                        pointer: pointer,
                        availableSize: proxy.size,
                        profileCount: state.profileCount,
                        profileIndex: state.profileIndex,
                        profileColors: state.profileColors,
                        animationToken: state.animationToken,
                        awaitingCenter: state.awaitingCenter,
                        safeArea: safeArea
                    )
                    .opacity(state.payloadDragging ? 0.001 : 1)
                    .transition(.opacity.combined(with: .scale(scale: 0.9)))

                }
            }

        }
        .allowsHitTesting(true)
    }

    private func activeScreenFrame() -> CGRect {
        NSScreen.screens.first(where: { $0.frame.contains(state.anchor) })?.frame
            ?? NSScreen.main?.frame
            ?? .zero
    }

    private func activeScreenVisibleFrame() -> CGRect {
        NSScreen.screens.first(where: { $0.frame.contains(state.anchor) })?.visibleFrame
            ?? NSScreen.main?.visibleFrame
            ?? activeScreenFrame()
    }
}

struct OrbitMenuVisual: View {
    let items: [OrbitItem]
    let selectedIndex: Int?
    let progress: Double
    let config: QuickOrbitConfig
    let mode: OverlayMode
    let center: CGPoint
    var interactionCenter: CGPoint? = nil
    let pointer: CGPoint
    let availableSize: CGSize
    var profileCount: Int = 1
    var profileIndex: Int = 0
    var profileColors: [OrbitProfileColor] = []
    var animationToken: Int = 0
    var awaitingCenter: Bool = false
    var visualScale: CGFloat = 1
    var safeArea: CGRect? = nil

    var body: some View {
        let radius = OrbitGeometry.radius(config: config) * visualScale
        let tileSize = OrbitGeometry.tileSize(config: config) * visualScale
        let rawOffsets = OrbitGeometry.offsets(count: items.count, layout: config.layout, radius: radius, spacingScale: CGFloat(config.itemSpacing))
        let offsets = OrbitGeometry.fittedOffsets(
            rawOffsets,
            tileSize: tileSize,
            availableSize: availableSize,
            showLabels: config.showLabels,
            safeArea: safeArea
        )
        let guideRadius = min(radius, offsets.map { hypot($0.x, $0.y) }.max() ?? radius)
        let origin = interactionCenter ?? center
        let visualCenter = OrbitGeometry.adjustedVisualCenter(
            from: center,
            offsets: offsets,
            tileSize: tileSize,
            availableSize: availableSize,
            showLabels: config.showLabels,
            safeArea: safeArea
        )

        ZStack {
            if config.showGuide && !(config.showOuterGuide ?? false) {
                Circle()
                    .stroke(
                        Color.primary.opacity(mode == .edit ? 0.13 : 0.08),
                        style: StrokeStyle(lineWidth: 1, dash: [5, 7])
                    )
                    .frame(width: guideRadius * 2, height: guideRadius * 2)
                    .position(origin)
            }

            if config.showOuterGuide ?? false {
                Circle()
                    .stroke(
                        config.profileColor.color.opacity(mode == .edit ? 0.34 : 0.26),
                        style: StrokeStyle(lineWidth: 1.35, dash: [3, 7])
                    )
                    .frame(width: guideRadius * 2.34, height: guideRadius * 2.34)
                    .position(origin)
                    .allowsHitTesting(false)
            }

            if config.showDeadZone ?? true {
                ZStack {
                    Circle()
                        .fill(Color.primary.opacity(0.025))
                    Circle()
                        .stroke(Color.primary.opacity(0.16), style: StrokeStyle(lineWidth: 1.2, dash: [4, 4]))
                }
                .frame(width: CGFloat(config.deadZone) * 2 * visualScale, height: CGFloat(config.deadZone) * 2 * visualScale)
                .position(origin)
                .allowsHitTesting(false)
            }

            if let selectedIndex, offsets.indices.contains(selectedIndex) {
                let target = CGPoint(
                    x: visualCenter.x + offsets[selectedIndex].x,
                    y: visualCenter.y + offsets[selectedIndex].y
                )
                SelectionBeam(from: origin, to: target, editMode: mode == .edit, accent: config.profileColor.color)
            }

            if config.showCenterDot {
                ZStack {
                    Circle()
                        .fill(config.profileColor.color.opacity(0.13))
                        .frame(width: 36, height: 36)
                    Circle()
                        .fill(config.profileColor.color)
                        .frame(width: 9, height: 9)
                }
                .position(origin)
            }

            if awaitingCenter {
                ZStack {
                    Circle()
                        .stroke(config.profileColor.color.opacity(0.72), lineWidth: 2)
                        .frame(width: 48, height: 48)
                        .overlay {
                            Image(systemName: "scope")
                                .font(.system(size: 14, weight: .bold))
                                .foregroundStyle(config.profileColor.color)
                        }
                    Text(qoText("Zur Mitte", "Move to center", language: config.language))
                        .font(.system(size: 9.5, weight: .bold, design: .rounded))
                        .padding(.horizontal, 8)
                        .padding(.vertical, 4)
                        .background { HUDGlass(emphasized: false, blendingMode: .withinWindow) }
                        .clipShape(Capsule())
                        .offset(y: 38)
                }
                .position(origin)
                .allowsHitTesting(false)
                .zIndex(40)
            }

            ForEach(Array(items.enumerated()), id: \.element.id) { index, item in
                let point = CGPoint(x: visualCenter.x + offsets[index].x, y: visualCenter.y + offsets[index].y)
                let compact = OrbitGeometry.resolvedLayout(config.layout, count: items.count) == .compactArc

                OrbitAnimatedTile(
                    target: point,
                    origin: origin,
                    index: index,
                    token: animationToken,
                    level: (config.energySavingMode ?? false) ? .none : (config.orbitAnimationLevel ?? .subtle),
                    duration: config.orbitAnimationDuration ?? 0.38,
                    rotates: OrbitGeometry.resolvedLayout(config.layout, count: items.count) == .circle && (config.circleOpeningRotation ?? true)
                ) {
                    OrbitTile(
                        item: item,
                        number: index + 1,
                        size: tileSize,
                        selected: selectedIndex == index,
                        progress: selectedIndex == index ? progress : 0,
                        showSelectionRing: mode == .edit || (config.orbitAutoSelect ?? true),
                        showLabel: config.showLabels,
                        editMode: mode == .edit,
                        compactMode: compact,
                        selectedScale: CGFloat(config.highlightScale),
                        showGlass: (config.orbitTileGlassEnabled ?? true) && (item.type != .app || selectedIndex == index)
                    )
                }
                .zIndex(selectedIndex == index ? 20 : 1)
            }

            if mode == .run && profileCount > 1 && (config.showProfileDots ?? true) {
                let dotsScale: CGFloat = 1.0
                VStack(spacing: 7) { profileDots(scale: dotsScale) }
                    .padding(.horizontal, 8)
                    .padding(.vertical, 9)
                    .background { HUDGlass(emphasized: false, blendingMode: .withinWindow) }
                    .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                    .overlay {
                        RoundedRectangle(cornerRadius: 14, style: .continuous)
                            .stroke(Color.white.opacity(0.10), lineWidth: 0.65)
                    }
                    .position(
                        x: min(max(visualCenter.x + CGFloat(config.profileDotsHorizontalOffset ?? 0) * visualScale, 26), max(26, availableSize.width - 26)),
                        y: min(max(visualCenter.y, 44), max(44, availableSize.height - 44))
                    )
            }

            if mode == .edit {
                editHint(selectedIndex: selectedIndex)
                    .position(
                        x: min(max(visualCenter.x, 150), max(150, availableSize.width - 150)),
                        y: min(max(visualCenter.y + radius + 88, 48), max(48, availableSize.height - 48))
                    )
            }
        }
    }

    @ViewBuilder
    private func profileDots(scale: CGFloat) -> some View {
        ForEach(0..<profileCount, id: \.self) { index in
            let dotColor = profileColors.indices.contains(index) ? profileColors[index].color : config.profileColor.color
            Circle()
                .fill(index == profileIndex ? dotColor : dotColor.opacity(0.34))
                .frame(
                    width: (index == profileIndex ? 8 : 6) * scale,
                    height: (index == profileIndex ? 8 : 6) * scale
                )
        }
    }

    private func profileDotsPoint(position: OrbitProfileDotsPosition, center: CGPoint, radius: CGFloat) -> CGPoint {
        let edge: CGFloat = 54
        switch position {
        case .right:
            return CGPoint(
                x: min(max(center.x + radius + edge, 26), max(26, availableSize.width - 26)),
                y: min(max(center.y, 44), max(44, availableSize.height - 44))
            )
        case .left:
            return CGPoint(
                x: min(max(center.x - radius - edge, 26), max(26, availableSize.width - 26)),
                y: min(max(center.y, 44), max(44, availableSize.height - 44))
            )
        case .top:
            return CGPoint(
                x: min(max(center.x, 44), max(44, availableSize.width - 44)),
                y: min(max(center.y - radius - edge, 26), max(26, availableSize.height - 26))
            )
        case .bottom:
            return CGPoint(
                x: min(max(center.x, 44), max(44, availableSize.width - 44)),
                y: min(max(center.y + radius + edge, 26), max(26, availableSize.height - 26))
            )
        }
    }

    @ViewBuilder
    private func editHint(selectedIndex: Int?) -> some View {
        HStack(spacing: 8) {
            Image(systemName: selectedIndex == nil ? "cursorarrow.motionlines" : "pencil.circle.fill")
                .foregroundStyle(config.profileColor.color)

            if let selectedIndex {
                Text(qoText("Control loslassen · Feld \(selectedIndex + 1) ändern", "Release Control · Edit field \(selectedIndex + 1)", language: config.language))
                    .font(.system(size: 12, weight: .semibold))
            } else {
                Text(qoText("Zum gewünschten Feld bewegen", "Move to the field you want", language: config.language))
                    .font(.system(size: 12, weight: .semibold))
            }
        }
        .padding(.horizontal, 14)
        .padding(.vertical, 9)
        .quickOrbitGlass(cornerRadius: 18)
    }
}

/// Moves every HUD tile out from the pointer with a tiny stagger. The state is
/// local to each tile, so live selection updates do not restart the animation.
enum OrbitOpeningMotion {
    static func point(progress: CGFloat, start: CGPoint, target: CGPoint, origin: CGPoint, angle: CGFloat, flourish: CGFloat) -> CGPoint {
        let p = min(max(progress, 0), 1)
        let dx = target.x - origin.x
        let dy = target.y - origin.y
        let distance = max(hypot(dx, dy), 1)
        // A smooth bow peaks midway, then decays to exactly zero at rest.
        let wave = sin(.pi * p) * (1 - p)
        let bow = min(34, distance * 0.19) * flourish * wave
        let radial = 1 + abs(flourish) * 0.055 * sin(.pi * p) * sin(.pi * p)
        let x = (start.x + (target.x - start.x) * p - origin.x) * radial - dy / distance * bow
        let y = (start.y + (target.y - start.y) * p - origin.y) * radial + dx / distance * bow
        let turn = angle * (1 - p)
        return CGPoint(x: origin.x + x * cos(turn) - y * sin(turn), y: origin.y + x * sin(turn) + y * cos(turn))
    }
}

private struct OrbitRevealPosition: AnimatableModifier {
    var progress: CGFloat
    let start: CGPoint
    let target: CGPoint
    let origin: CGPoint
    let angle: CGFloat
    let flourish: CGFloat
    var animatableData: CGFloat { get { progress } set { progress = newValue } }
    func body(content: Content) -> some View {
        let p = min(max(progress, 0), 1)
        let position = OrbitOpeningMotion.point(progress: p, start: start, target: target, origin: origin, angle: angle, flourish: flourish)
        content
            .scaleEffect(1 + abs(flourish) * 0.035 * pow(sin(.pi * p), 2))
            .position(position)
    }
}

struct OrbitAnimatedTile<Content: View>: View {
    let target: CGPoint
    let origin: CGPoint
    let index: Int
    let token: Int
    let level: OrbitAnimationLevel
    let duration: Double
    var rotates = false
    @ViewBuilder let content: () -> Content
    @State private var revealed = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        let start = startPoint
        content()
            .modifier(OrbitRevealPosition(progress: revealed ? 1 : 0, start: start, target: target, origin: origin,
                                          angle: rotates && !reduceMotion && level != .none ? (level == .full ? -.pi / 2 : -.pi / 18) : 0,
                                          flourish: level == .full && !reduceMotion ? (index.isMultiple(of: 2) ? 1 : -1) : 0))
            .scaleEffect(revealed ? 1 : startScale)
            .opacity(revealed ? 1 : 0)
            .animation(
                .spring(response: response, dampingFraction: damping, blendDuration: 0.04)
                    .delay(Double(index) * stagger),
                value: revealed
            )
            .onAppear { play(animated: token > 0 && level != .none && !reduceMotion) }
            .onChange(of: token) { _, _ in play(animated: level != .none && !reduceMotion) }
    }

    private var startPoint: CGPoint {
        if level == .subtle {
            return CGPoint(
                x: origin.x + (target.x - origin.x) * 0.88,
                y: origin.y + (target.y - origin.y) * 0.88
            )
        }
        guard level == .full else { return target }

        // Full mode gives every field a small individual, curved arrival path.
        // The path remains restrained and never adds the old colored trail.
        let dx = target.x - origin.x
        let dy = target.y - origin.y
        let distance = max(hypot(dx, dy), 1)
        let tangent = min(20, max(8, distance * 0.09)) * (index.isMultiple(of: 2) ? 1 : -1)
        let progress = 0.34 + CGFloat(index % 3) * 0.025
        return CGPoint(
            x: origin.x + dx * progress - (dy / distance) * tangent,
            y: origin.y + dy * progress + (dx / distance) * tangent
        )
    }

    private var startScale: CGFloat {
        level == .full ? 0.76 + CGFloat(index % 3) * 0.025 : (level == .subtle ? 0.97 : 1)
    }
    private var response: Double {
        let clamped = min(max(duration, 0.16), 1.20)
        return level == .full ? clamped * (0.94 + Double(index % 4) * 0.015) : max(0.12, clamped * 0.62)
    }
    private var damping: Double { level == .full ? 0.94 : 1.0 }
    private var stagger: Double {
        let factor = min(max(duration / 0.38, 0.55), 2.0)
        return (level == .full ? 0.014 : 0.006) * factor
    }

    private func play(animated: Bool) {
        var reset = Transaction(animation: nil)
        reset.disablesAnimations = true
        withTransaction(reset) { revealed = !animated }
        guard animated else { return }
        DispatchQueue.main.async { revealed = true }
    }
}

struct OrbitTile: View {
    let item: OrbitItem
    let number: Int
    let size: CGFloat
    let selected: Bool
    let progress: Double
    let showSelectionRing: Bool
    let showLabel: Bool
    let editMode: Bool
    let compactMode: Bool
    let selectedScale: CGFloat
    let showGlass: Bool
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        VStack(spacing: showLabel ? 7 : 0) {
            ZStack {
                if item.target == "orbitDropBox" { QuickOrbitDropBoxBadge(size: size * 0.85).zIndex(10) }

                if let emoji = item.insertedEmoji {
                    if showGlass { orbitGlassCircle(scale: 0.78) }
                    Text(emoji)
                        .font(.system(size: size * 0.50))
                        .lineLimit(1)
                        .minimumScaleFactor(0.55)
                        .frame(width: size * 0.78, height: size * 0.78)

                } else if item.isLiveSystemTile {
                    if showGlass { orbitGlassCircle(scale: 0.78) }
                    LiveSystemTileValue(item: item, size: size, compact: false)
                        .frame(width: size * 0.82, height: size * 0.82)

                } else if let icon = IconHelper.image(for: item) {
                    // Like the older activation view: apps stay clean normally,
                    // but the selected app gets the glass circle when the option is enabled.
                    if selected && showGlass { orbitGlassCircle(scale: 0.98) }
                    Image(nsImage: icon)
                        .resizable()
                        .interpolation(.high)
                        .scaledToFit()
                        .frame(width: size * 0.78, height: size * 0.78)
                        .shadow(color: .black.opacity(selected ? 0.20 : 0.10), radius: selected ? 9 : 4, y: selected ? 4 : 2)

                } else {
                    if showGlass { orbitGlassCircle(scale: 0.78) }
                    Image(systemName: item.enabled ? item.symbol : "plus")
                        .font(.system(size: size * 0.36, weight: .semibold))
                        .foregroundStyle(item.enabled ? Color.white.opacity(0.94) : Color.white.opacity(0.48))
                }

                if selected && showSelectionRing {
                    Circle()
                        .trim(from: 0, to: max(0.001, progress))
                        .stroke(
                            editMode ? Color.orange : Color.primary,
                            style: StrokeStyle(lineWidth: 3, lineCap: .round)
                        )
                        .frame(width: size, height: size)
                        .rotationEffect(.degrees(-90))
                }

                if editMode && selected {
                    Image(systemName: "pencil")
                        .font(.system(size: 10, weight: .bold))
                        .foregroundStyle(.white)
                        .frame(width: 22, height: 22)
                        .background(Color.orange, in: Circle())
                        .offset(x: size * 0.34, y: -size * 0.34)
                }

                if item.requiresAccessibility && !AXIsProcessTrusted() {
                    Image(systemName: "hand.raised.fill")
                        .font(.system(size: max(8, size * 0.12), weight: .bold))
                        .foregroundStyle(Color.orange)
                        .frame(width: 22, height: 22)
                        .background(Color.orange.opacity(0.16), in: Circle())
                        .offset(x: -size * 0.34, y: -size * 0.34)
                        .help(QuickOrbitAccessibilityGuide.helpText(language: OrbitStore.shared.config.language))
                        .onTapGesture {
                            QuickOrbitAccessibilityGuide.openSystemAccess()
                        }
                }

                if item.type == .shellCommand {
                    Text("BETA")
                        .font(.system(size: max(7, size * 0.085), weight: .black, design: .rounded))
                        .foregroundStyle(Color.black.opacity(0.82))
                        .padding(.horizontal, 6)
                        .padding(.vertical, 3)
                        .background(Color.yellow, in: Capsule())
                        .offset(x: size * 0.31, y: -size * 0.34)
                        .allowsHitTesting(false)
                }

            }
            .frame(width: size, height: size)

            if showLabel {
                Text(item.enabled ? item.title : qoText("Leer", "Empty", language: OrbitStore.shared.config.language))
                    .font(.system(size: min(11, max(7.8, size * 0.155)), weight: selected ? .semibold : .medium))
                    .lineLimit(1)
                    .minimumScaleFactor(0.58)
                    .padding(.horizontal, min(9, max(6, size * 0.12)))
                    .padding(.vertical, min(4, max(2.5, size * 0.052)))
                    .background {
                        HUDGlass(emphasized: selected, blendingMode: .withinWindow)
                    }
                    .clipShape(Capsule())
                    .overlay {
                        if selected { Capsule().stroke(Color.primary.opacity(0.12), lineWidth: 0.8) }
                    }
                    .allowsHitTesting(false)
            }
        }
        .scaleEffect(selected ? selectedScale : 1)
        .opacity(!item.enabled && !editMode ? 0.45 : (selected ? 1 : 0.90))
        .animation(reduceMotion ? nil : .easeOut(duration: 0.12), value: selected)
        .modifier(QuickOrbitPayloadDragModifier(item: item, enabled: !editMode))
    }

    @ViewBuilder
    private func orbitGlassCircle(scale: CGFloat) -> some View {
        Circle()
            .fill(Color.primary.opacity(0.035))
            .frame(width: size * scale, height: size * scale)
            .background {
                HUDGlass(emphasized: selected, blendingMode: .withinWindow)
                    .clipShape(Circle())
                    .frame(width: size * scale, height: size * scale)
            }
            .overlay {
                Circle().stroke(Color.white.opacity(selected ? 0.14 : 0.075), lineWidth: 0.6)
            }
    }
}

struct SelectionBeam: View {
    let from: CGPoint
    let to: CGPoint
    let editMode: Bool
    let accent: Color

    var body: some View {
        Canvas { context, _ in
            var path = Path()
            path.move(to: from)
            path.addLine(to: to)

            context.stroke(
                path,
                with: .color((editMode ? Color.orange : accent).opacity(0.08)),
                style: StrokeStyle(lineWidth: 4, lineCap: .round)
            )
            context.stroke(
                path,
                with: .color((editMode ? Color.orange : accent).opacity(0.46)),
                style: StrokeStyle(lineWidth: 1.2, lineCap: .round)
            )
        }
        .allowsHitTesting(false)
    }
}

private struct QuickOrbitLiveSurfaceKey: EnvironmentKey {
    static let defaultValue = false
}

private extension EnvironmentValues {
    var quickOrbitLiveSurface: Bool {
        get { self[QuickOrbitLiveSurfaceKey.self] }
        set { self[QuickOrbitLiveSurfaceKey.self] = newValue }
    }
}

struct LiveSystemTileValue: View {
    let item: OrbitItem
    let size: CGFloat
    let compact: Bool
    @ObservedObject private var store = OrbitStore.shared
    @ObservedObject private var timerCenter = QuickOrbitTimerCenter.shared
    @Environment(\.quickOrbitLiveSurface) private var quickOrbitLiveSurface

    @ViewBuilder
    var body: some View {
        if quickOrbitLiveSurface {
            // Live values are deliberately created only for an active Orbit.
            // Editors and previews render a static symbol and do no polling.
            TimelineView(.periodic(from: .now, by: refreshInterval)) { context in
                Group {
                    switch item.target {
                case "liveClock":
                    VStack(spacing: 1) {
                        Text(context.date, format: .dateTime.hour().minute())
                            .font(.system(size: size * (compact ? 0.20 : 0.18), weight: .bold, design: .rounded))
                            .monospacedDigit()
                        if !compact {
                            Text(context.date, format: .dateTime.second())
                                .font(.system(size: size * 0.16, weight: .bold, design: .rounded))
                                .foregroundStyle(Color.primary.opacity(0.72))
                                .monospacedDigit()
                        }
                    }

                case "liveDate":
                    VStack(spacing: 0) {
                        Text(context.date, format: .dateTime.weekday(.abbreviated))
                            .font(.system(size: size * 0.12, weight: .semibold, design: .rounded))
                            .foregroundStyle(.secondary)
                        Text(context.date, format: .dateTime.day())
                            .font(.system(size: size * 0.24, weight: .bold, design: .rounded))
                            .monospacedDigit()
                    }

                case "stopwatch":
                    stopwatchContent(at: context.date)

                case let target where target.hasPrefix("timer"):
                    timerContent(at: context.date, defaultSeconds: timerSeconds(for: target))

                case "batteryStatus":
                    let status = QuickOrbitSystemInfo.battery()
                    let low = (status.percent ?? 100) <= 20 && !status.isCharging && !status.onExternalPower
                    VStack(spacing: 0) {
                        Image(systemName: QuickOrbitSystemInfo.batterySymbol(percent: status.percent, charging: status.isCharging))
                            .font(.system(size: size * 0.23, weight: .semibold))
                            .foregroundStyle(status.isCharging ? Color.green : (low ? Color.orange : Color.primary))
                        Text(status.percent.map { "\($0)%" } ?? (status.onExternalPower ? "AC" : "–"))
                            .font(.system(size: size * 0.15, weight: .bold, design: .rounded))
                            .monospacedDigit()
                        Text(status.isCharging
                             ? qoText("Lädt", "Charging", language: OrbitStore.shared.config.language)
                             : (low
                                ? qoText("Bald laden · Sparen", "Charge soon · Saving", language: OrbitStore.shared.config.language)
                                : (status.onExternalPower ? qoText("Netzbetrieb", "Power", language: OrbitStore.shared.config.language) : qoText("Akkubetrieb", "Battery", language: OrbitStore.shared.config.language))))
                            .font(.system(size: size * 0.088, weight: .bold, design: .rounded))
                            .foregroundStyle(low ? Color.orange : Color.secondary)
                            .lineLimit(1)
                            .minimumScaleFactor(0.42)
                    }

                case "chargingStatus":
                    let status = QuickOrbitSystemInfo.battery()
                    VStack(spacing: 2) {
                        Image(systemName: status.isCharging ? "bolt.fill" : (status.onExternalPower ? "powerplug.fill" : "battery.75"))
                            .font(.system(size: size * 0.25, weight: .semibold))
                            .foregroundStyle(status.isCharging ? Color.green : Color.primary)
                        Text(status.isCharging
                             ? qoText("Lädt", "Charging", language: OrbitStore.shared.config.language)
                             : (status.onExternalPower ? qoText("Netzbetrieb", "Power", language: OrbitStore.shared.config.language) : qoText("Akku", "Battery", language: OrbitStore.shared.config.language)))
                            .font(.system(size: size * 0.105, weight: .bold, design: .rounded))
                            .lineLimit(1)
                            .minimumScaleFactor(0.55)
                    }

                case "volumeStatus":
                    let audio = SystemAudioController.outputSnapshot()
                    VStack(spacing: 2) {
                        Image(systemName: audio.muted ? "speaker.slash.fill" : "speaker.wave.2.fill")
                            .font(.system(size: size * 0.23, weight: .semibold))
                        Text(audio.muted ? qoText("Stumm", "Muted", language: store.config.language) : (audio.percent.map { "\($0)%" } ?? "–"))
                            .font(.system(size: size * 0.16, weight: .bold, design: .rounded))
                            .monospacedDigit()
                    }

                case "cpuStatus":
                    VStack(spacing: 2) {
                        Image(systemName: "cpu.fill")
                            .font(.system(size: size * 0.24, weight: .semibold))
                        Text(QuickOrbitSystemInfo.cpuUsage().map { "\($0)%" } ?? "…")
                            .font(.system(size: size * 0.16, weight: .bold, design: .rounded))
                            .monospacedDigit()
                    }

                case "memoryStatus":
                    VStack(spacing: 2) {
                        Image(systemName: "memorychip.fill")
                            .font(.system(size: size * 0.24, weight: .semibold))
                        Text(QuickOrbitSystemInfo.memoryUsage().map { "\($0)%" } ?? "–")
                            .font(.system(size: size * 0.16, weight: .bold, design: .rounded))
                            .monospacedDigit()
                    }

                case "networkStatus":
                    let speed = QuickOrbitSystemInfo.networkSpeed()
                    VStack(spacing: 1) {
                        Label(speed.map { QuickOrbitSystemInfo.speedText($0.received) } ?? "…", systemImage: "arrow.down")
                        Label(speed.map { QuickOrbitSystemInfo.speedText($0.sent) } ?? "…", systemImage: "arrow.up")
                    }
                    .font(.system(size: size * 0.105, weight: .bold, design: .rounded))
                    .lineLimit(1)
                    .minimumScaleFactor(0.48)

                case "storageStatus":
                    VStack(spacing: 2) {
                        Image(systemName: "internaldrive.fill")
                            .font(.system(size: size * 0.23, weight: .semibold))
                        Text(QuickOrbitSystemInfo.freeStorageText())
                            .font(.system(size: size * 0.125, weight: .bold, design: .rounded))
                            .lineLimit(1)
                            .minimumScaleFactor(0.52)
                    }

                case "uptimeStatus":
                    VStack(spacing: 2) {
                        Image(systemName: "clock.arrow.circlepath")
                            .font(.system(size: size * 0.23, weight: .semibold))
                        Text(QuickOrbitSystemInfo.uptimeText())
                            .font(.system(size: size * 0.12, weight: .bold, design: .rounded))
                            .lineLimit(1)
                            .minimumScaleFactor(0.50)
                    }

                case "thermalStatus":
                    VStack(spacing: 2) {
                        Image(systemName: thermalSymbol)
                            .font(.system(size: size * 0.23, weight: .semibold))
                            .foregroundStyle(thermalColor)
                        Text(thermalText)
                            .font(.system(size: size * 0.12, weight: .bold, design: .rounded))
                            .lineLimit(1)
                    }

                case "batteryWarning":
                    let enabled = OrbitStore.shared.config.lowBatteryWarningEnabled ?? false
                    VStack(spacing: 2) {
                        Image(systemName: enabled ? "bell.fill" : "bell.slash.fill")
                            .font(.system(size: size * 0.24, weight: .semibold))
                            .foregroundStyle(enabled ? Color.orange : Color.secondary)
                        Text(enabled ? qoText("AN · 20%", "ON · 20%", language: OrbitStore.shared.config.language) : qoText("AUS", "OFF", language: OrbitStore.shared.config.language))
                            .font(.system(size: size * 0.105, weight: .bold, design: .rounded))
                    }

                case "smartSuggestion":
                    let suggestion = QuickOrbitUsageStatsCenter.shared.suggestion(from: OrbitStore.shared.visibleItems)
                    VStack(spacing: 2) {
                        ZStack(alignment: .bottomTrailing) {
                            Group {
                                if let emoji = suggestion?.insertedEmoji {
                                    Text(emoji).font(.system(size: size * 0.27))
                                } else if let suggestion, let icon = IconHelper.image(for: suggestion) {
                                    Image(nsImage: icon).resizable().scaledToFit()
                                } else {
                                    Image(systemName: suggestion?.symbol ?? "sparkles")
                                        .resizable().scaledToFit()
                                        .foregroundStyle(Color.primary)
                                }
                            }
                            .frame(width: size * 0.30, height: size * 0.30)
                            Image(systemName: "sparkles")
                                .font(.system(size: size * 0.075, weight: .black))
                                .foregroundStyle(.white)
                                .frame(width: size * 0.16, height: size * 0.16)
                                .background(Color.purple, in: Circle())
                                .offset(x: size * 0.055, y: size * 0.035)
                        }
                        Text(suggestion?.title
                             ?? qoText("Lernt", "Learning", language: OrbitStore.shared.config.language))
                            .font(.system(size: size * 0.10, weight: .bold, design: .rounded))
                            .lineLimit(1)
                            .minimumScaleFactor(0.48)
                    }

                case "wifiStatus":
                    let wifi = QuickOrbitSystemInfo.wifi()
                    VStack(spacing: 1) {
                        Image(systemName: QuickOrbitSystemInfo.wifiSymbol(rssi: wifi.rssi, connected: wifi.connected, powered: wifi.powered))
                            .font(.system(size: size * 0.26, weight: .semibold))
                        Text(wifiLabel(wifi))
                            .font(.system(size: size * 0.13, weight: .semibold, design: .rounded))
                            .lineLimit(1)
                            .minimumScaleFactor(0.55)
                    }

                default:
                    Image(systemName: item.symbol)
                        .font(.system(size: size * 0.34, weight: .semibold))
                    }
                }
            }
        } else {
            Image(systemName: item.symbol)
                .font(.system(size: size * 0.30, weight: .semibold))
                .foregroundStyle(Color.primary.opacity(0.82))
                .accessibilityLabel(qoText("Live beim Öffnen des Orbits", "Live when the Orbit opens", language: store.config.language))
        }
    }

    private var refreshInterval: TimeInterval {
        let savingEnergy = store.config.energySavingMode ?? false
        switch item.target {
        case "liveClock", "stopwatch": return 1
        case let target where target.hasPrefix("timer"): return 1
        case "cpuStatus", "networkStatus": return savingEnergy ? 1.5 : 0.5
        case "memoryStatus", "volumeStatus": return savingEnergy ? 2 : 1
        case "liveDate": return 30
        case "storageStatus", "uptimeStatus": return 10
        case "batteryStatus", "chargingStatus", "batteryWarning", "thermalStatus": return 3
        case "wifiStatus", "smartSuggestion": return 3
        default: return 5
        }
    }

    private var thermalText: String {
        switch ProcessInfo.processInfo.thermalState {
        case .nominal: return qoText("Normal", "Normal", language: OrbitStore.shared.config.language)
        case .fair: return qoText("Erhöht", "Elevated", language: OrbitStore.shared.config.language)
        case .serious: return qoText("Hoch", "High", language: OrbitStore.shared.config.language)
        case .critical: return qoText("Kritisch", "Critical", language: OrbitStore.shared.config.language)
        @unknown default: return "–"
        }
    }

    private var thermalSymbol: String {
        switch ProcessInfo.processInfo.thermalState {
        case .nominal: return "thermometer.low"
        case .fair: return "thermometer.medium"
        case .serious, .critical: return "thermometer.high"
        @unknown default: return "thermometer.medium"
        }
    }

    private var thermalColor: Color {
        switch ProcessInfo.processInfo.thermalState {
        case .nominal: return .green
        case .fair: return .orange
        case .serious, .critical: return .red
        @unknown default: return .secondary
        }
    }

    private func timerSeconds(for target: String) -> Int {
        if target == "timerCustom" {
            return min(max(OrbitStore.shared.config.customTimerSeconds ?? 300, 5), 10_800)
        }
        if target.hasPrefix("timerSeconds") {
            return min(max(Int(target.dropFirst("timerSeconds".count)) ?? 60, 5), 10_800)
        }
        return min(max((Int(target.dropFirst("timer".count)) ?? 10) * 60, 5), 10_800)
    }

    @ViewBuilder
    private func timerContent(at date: Date, defaultSeconds: Int) -> some View {
        let profileID = OrbitStore.shared.config.activeProfileID
        if let profileID,
           timerCenter.states[profileID]?.durationSeconds == defaultSeconds,
           let seconds = timerCenter.remaining(for: profileID, at: date), seconds > 0 {
            VStack(spacing: 0) {
                Image(systemName: "timer")
                    .font(.system(size: size * 0.18, weight: .semibold))
                Text(clockDuration(seconds))
                    .font(.system(size: size * 0.16, weight: .bold, design: .rounded))
                    .monospacedDigit()
            }
            .frame(width: size * 0.62, height: size * 0.62)
            .background {
                Circle().stroke(Color.primary.opacity(0.09), lineWidth: 2)
                Circle()
                    .trim(from: 0, to: min(1, max(0, Double(seconds) / Double(max(defaultSeconds, 1)))))
                    .stroke(Color.accentColor.opacity(0.70), style: StrokeStyle(lineWidth: 2, lineCap: .round))
                    .rotationEffect(.degrees(-90))
            }
            .accessibilityElement(children: .ignore)
            .accessibilityLabel(qoText("Timer · Verbleibend", "Timer · Remaining", language: store.config.language))
            .accessibilityValue(clockDuration(seconds))
        } else {
            VStack(spacing: 1) {
                Image(systemName: "timer")
                    .font(.system(size: size * 0.24, weight: .semibold))
                Text(quickOrbitCompactDurationLabel(seconds: defaultSeconds))
                    .font(.system(size: size * 0.15, weight: .bold, design: .rounded))
                    .minimumScaleFactor(0.68)
            }
        }
    }

    @ViewBuilder
    private func stopwatchContent(at date: Date) -> some View {
        let profileID = OrbitStore.shared.config.activeProfileID
        let state = profileID.flatMap { timerCenter.stopwatchStates[$0] }
        let elapsed = Int(state?.total(at: date) ?? 0)
        VStack(spacing: 0) {
            Image(systemName: state?.isRunning == true ? "stopwatch.fill" : "stopwatch")
                .font(.system(size: size * 0.18, weight: .semibold))
            Text(clockDuration(elapsed))
                .font(.system(size: size * 0.16, weight: .bold, design: .rounded))
                .monospacedDigit()
        }
    }

    private func clockDuration(_ seconds: Int) -> String {
        if seconds >= 3600 {
            return String(format: "%d:%02d:%02d", seconds / 3600, (seconds % 3600) / 60, seconds % 60)
        }
        return String(format: "%d:%02d", seconds / 60, seconds % 60)
    }

    private func wifiLabel(_ wifi: (powered: Bool, connected: Bool, name: String?, rssi: Int)) -> String {
        if !wifi.powered { return qoText("Aus", "Off", language: OrbitStore.shared.config.language) }
        if let name = wifi.name, !name.isEmpty { return name }
        return wifi.connected
            ? qoText("Verbunden", "Connected", language: OrbitStore.shared.config.language)
            : qoText("An", "On", language: OrbitStore.shared.config.language)
    }
}

struct FieldIcon: View {
    let item: OrbitItem
    let size: CGFloat

    var body: some View {
        ZStack {
            if item.target == "orbitDropBox" {
                QuickOrbitDropBoxBadge(size: size).zIndex(5)
            }
            if let emoji = item.insertedEmoji {
                RoundedRectangle(cornerRadius: size * 0.24, style: .continuous)
                    .fill(Color.primary.opacity(0.045))
                    .frame(width: size, height: size)
                Text(emoji)
                    .font(.system(size: size * 0.56))
                    .lineLimit(1)
                    .minimumScaleFactor(0.55)
                    .frame(width: size * 0.88, height: size * 0.88)
            } else if item.isLiveSystemTile {
                RoundedRectangle(cornerRadius: size * 0.24, style: .continuous)
                    .fill(Color.primary.opacity(0.045))
                    .frame(width: size, height: size)
                LiveSystemTileValue(item: item, size: size, compact: true)
                    .frame(width: size * 0.90, height: size * 0.90)
            } else if let icon = IconHelper.image(for: item) {
                Image(nsImage: icon)
                    .resizable()
                    .scaledToFit()
                    .frame(width: size, height: size)
            } else {
                RoundedRectangle(cornerRadius: size * 0.24, style: .continuous)
                    .fill(Color.primary.opacity(0.045))
                    .frame(width: size, height: size)
                    .overlay {
                        Image(systemName: item.enabled ? item.symbol : "plus")
                            .font(.system(size: size * 0.42, weight: .semibold))
                            .foregroundStyle(item.enabled ? Color.primary : Color.secondary)
                    }
            }

            if item.enabled && !OrbitValidator.health(for: item).valid {
                Image(systemName: "exclamationmark.circle.fill")
                    .font(.system(size: max(12, size * 0.28), weight: .bold))
                    .foregroundStyle(Color.orange)
                    .background(Color(nsColor: .windowBackgroundColor), in: Circle())
                    .offset(x: size * 0.38, y: -size * 0.38)
            }

        }
    }
}

