// MARK: - Main window

enum MainSection: String, CaseIterable, Identifiable {
    case orbit = "QuickOrbit"
    case profiles = "Profile"
    case menuBar = "Menüleiste"
    case behavior = "Verhalten"
    case news = "Neuigkeiten"
    case info = "Info"

    var id: String { rawValue }

    var symbol: String {
        switch self {
        case .orbit: return "circle.grid.cross.fill"
        case .profiles: return "square.stack.3d.up.fill"
        case .menuBar: return "menubar.rectangle"
        case .behavior: return "cursorarrow.motionlines"
        case .news: return "sparkles"
        case .info: return "info.circle.fill"
        }
    }
}

@MainActor
final class AppNavigation: ObservableObject {
    static let shared = AppNavigation()
    @Published var requestedSection: MainSection?
    @Published var requestedMenuBarEditorIndex: Int?
    @Published var requestedInfoAnchor: String?

    func open(_ section: MainSection, menuBarEditorIndex: Int? = nil) {
        requestedSection = section
        requestedMenuBarEditorIndex = menuBarEditorIndex
    }

    func openSystemAccess() {
        requestedInfoAnchor = "system-access"
        requestedSection = .info
    }
}

@MainActor
enum QuickOrbitAccessibilityGuide {
    static func openSystemAccess() {
        OrbitStore.shared.editorSlot = nil
        OrbitStore.shared.newlyCreatedEditorSlot = nil
        FloatingActionEditorController.shared.close()
        AppWindow.show()
        AppNavigation.shared.openSystemAccess()
    }

    static func helpText(language: AppLanguage?) -> String {
        qoText(
            "Diese Aktion benötigt die macOS-Bedienungshilfe. Klicken, um sie unter Info → Systemzugriff zu erlauben.",
            "This action requires macOS Accessibility access. Click to allow it under Info → System access.",
            language: language
        )
    }
}

struct MainView: View {
    @ObservedObject private var store = OrbitStore.shared
    @ObservedObject private var controller = OrbitController.shared
    @ObservedObject private var navigation = AppNavigation.shared
    @ObservedObject private var notices = QuickOrbitNoticeCenter.shared
    @State private var section: MainSection? = .orbit
    @State private var draggedProfileID: UUID?
    @State private var dropTargetProfileID: UUID?
    @State private var profileFrames: [UUID: CGRect] = [:]
    @State private var dragStartProfileFrames: [UUID: CGRect] = [:]
    @State private var profileDragTranslation: CGSize = .zero
    @State private var profileGrabOffset: CGSize = .zero
    @State private var suppressProfileTap = false
    @State private var lastProfileFeedbackTargetID: UUID?
    @State private var showNewsOverlay = false
    @State private var railHoverLabel: String?
    @State private var railHoverFrames: [String: CGRect] = [:]
    @State private var profileDragGlobalCenter: CGPoint?


    var body: some View {
        ZStack(alignment: .leading) {
            SystemBackdrop()

            Group {
                switch section ?? .orbit {
                case .orbit:
                    OrbitSetupView()
                case .profiles:
                    ProfilesView(section: $section)
                case .menuBar:
                    MenuBarQuickActionsView()
                case .behavior:
                    BehaviorSettingsView()
                case .news:
                    NewsPageView()
                case .info:
                    InfoView()
                }
            }
            .padding(.leading, 96)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .blur(radius: draggedProfileID == nil ? 0 : 3.5)
            .animation(.easeOut(duration: 0.20), value: draggedProfileID)

            if draggedProfileID != nil {
                Color.black.opacity(0.08)
                    .ignoresSafeArea()
                    .allowsHitTesting(false)
                    .transition(.opacity)
                    .zIndex(29000)
            }

            floatingNavigationRail
                .padding(.leading, 18)
                .padding(.top, 70)
                .padding(.bottom, 22)
                .zIndex(30000)

            if let draggedProfileID {
                profileReorderPalette(sourceID: draggedProfileID)
                    .zIndex(36000)
            }

            if let draggedID = draggedProfileID,
               let dragged = store.profiles.first(where: { $0.id == draggedID }),
               let globalCenter = profileDragGlobalCenter {
                GeometryReader { proxy in
                    draggedProfileOverlay(dragged)
                        .position(
                            x: globalCenter.x - proxy.frame(in: .global).minX,
                            y: globalCenter.y - proxy.frame(in: .global).minY
                        )
                }
                .allowsHitTesting(false)
                .zIndex(39000)
            }

            if let hoverName = railHoverLabel, let hoverFrame = railHoverFrames[hoverName], railLabelIsVisible(hoverName, frame: hoverFrame) {
                GeometryReader { proxy in
                    railHoverBubble(hoverName)
                        .offset(
                            x: hoverFrame.maxX - proxy.frame(in: .global).minX + 9,
                            y: hoverFrame.midY - proxy.frame(in: .global).minY - 14
                        )
                        .allowsHitTesting(false)
                }
                .zIndex(40000)
            }

            if let message = notices.message {
                VStack {
                    Spacer()
                    Label(message, systemImage: "exclamationmark.triangle.fill")
                        .font(.caption.weight(.semibold))
                        .padding(.horizontal, 14)
                        .padding(.vertical, 10)
                        .quickOrbitGlass(cornerRadius: 999)
                        .padding(.bottom, 18)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .allowsHitTesting(false)
                .transition(.opacity)
                .zIndex(35000)
            }

            if showNewsOverlay {
                ZStack {
                    Color.black.opacity(0.42)
                        .ignoresSafeArea()
                        .onTapGesture { showNewsOverlay = false }

                    QuickOrbitNewsModal(onClose: { showNewsOverlay = false })
                        .transition(.opacity.combined(with: .scale(scale: 0.985)))
                }
                .zIndex(50000)
            }

            if store.config.onboardingCompleted != true {
                Color.black.opacity(0.62)
                    .ignoresSafeArea()
                    .allowsHitTesting(false)
                    .transition(.opacity)
                    .zIndex(45000)
            }
        }
        .frame(minWidth: 1120, minHeight: 760)
        .background(QuickOrbitWindowConfigurator().frame(width: 0, height: 0))
        .preferredColorScheme((store.config.appearance ?? .system).colorScheme)
        .animation(.easeOut(duration: 0.18), value: showNewsOverlay)
        .animation(.easeOut(duration: 0.22), value: notices.message)
        .onPreferenceChange(QuickOrbitProfileFramePreferenceKey.self) { profileFrames = $0 }
        .onPreferenceChange(QuickOrbitRailHoverFramePreferenceKey.self) { railHoverFrames = $0 }
        .onDisappear {
            resetProfileDragState()
        }
        .onChange(of: navigation.requestedSection) { _, requested in
            guard let requested else { return }
            selectMainSection(requested)
            DispatchQueue.main.async {
                AppNavigation.shared.requestedSection = nil
            }
        }
        .onChange(of: section) { _, _ in
            railHoverLabel = nil
            if draggedProfileID != nil {
                resetProfileDragState()
            }
        }
        .sheet(isPresented: Binding(
            get: { store.config.onboardingCompleted != true },
            set: { _ in }
        )) {
            QuickOrbitOnboardingView()
                .interactiveDismissDisabled()
        }
        .sheet(
            isPresented: Binding(
                get: { store.editorSlot != nil },
                set: { isPresented in
                    guard !isPresented else { return }
                    DispatchQueue.main.async {
                        OrbitStore.shared.editorSlot = nil
                        OrbitStore.shared.applyPendingAutomaticProfileIfNeeded()
                    }
                }
            )
        ) {
            if let slot = store.editorSlot,
               store.config.items.indices.contains(slot) {
                ActionEditorSheet(slot: slot)
            }
        }
    }

