    private func floatingSectionButton(_ item: MainSection) -> some View {
        let selected = section == item
        return Button {
            selectMainSection(item)
        } label: {
            Image(systemName: item.symbol)
                .font(.system(size: 18, weight: .semibold))
                .foregroundStyle(selected ? Color.accentColor : Color.primary.opacity(0.88))
                .frame(width: 52, height: 52)
                .background {
                    HUDGlass(emphasized: selected, blendingMode: .withinWindow)
                        .clipShape(Circle())
                }
                .overlay {
                    Circle()
                        .stroke(selected ? Color.accentColor.opacity(0.55) : Color.white.opacity(0.11), lineWidth: selected ? 1.3 : 0.75)
                }
                .shadow(color: .black.opacity(selected ? 0.10 : 0.035), radius: selected ? 7 : 3, y: 2)
        }
        .buttonStyle(.plain)
        // Update on mouse-down, not only after mouse-up. The guard in
        // `selectMainSection` prevents repeated drag samples from doing work.
        .simultaneousGesture(
            DragGesture(minimumDistance: 0)
                .onChanged { _ in selectMainSection(item) }
        )
        .quickOrbitNavigationHover()
        .accessibilityLabel(sectionTitle(item))
        .accessibilityValue(selected ? qoText("Ausgewählt", "Selected", language: store.config.language) : "")
        .accessibilityAddTraits(selected ? [.isSelected] : [])
        .frame(maxWidth: .infinity, alignment: .center)
        .background {
            GeometryReader { proxy in
                Color.clear.preference(
                    key: QuickOrbitRailHoverFramePreferenceKey.self,
                    value: [sectionTitle(item): proxy.frame(in: .global)]
                )
            }
        }
        .onHover { hovering in
            withAnimation(.easeOut(duration: 0.10)) {
                railHoverLabel = hovering ? sectionTitle(item) : (railHoverLabel == sectionTitle(item) ? nil : railHoverLabel)
            }
        }
        .help(sectionTitle(item))
    }

    private func selectMainSection(_ item: MainSection) {
        guard section != item else { return }
        var transaction = Transaction(animation: nil)
        transaction.disablesAnimations = true
        withTransaction(transaction) {
            railHoverLabel = nil
            section = item
        }
    }

    private func railLabelIsVisible(_ name: String, frame: CGRect) -> Bool {
        guard store.profiles.contains(where: { $0.name == name }) || name == qoText("Profil hinzufügen", "Add profile", language: store.config.language) else { return true }
        return railHoverFrames["__profileViewport"]?.contains(CGPoint(x: frame.midX, y: frame.midY)) ?? false
    }

    private func floatingProfileButton(_ profile: OrbitProfile) -> some View {
        let selectedProfile = store.config.activeProfileID == profile.id
        let isDragging = draggedProfileID == profile.id
        let visible = profileFrames[profile.id].map { frame in
            railHoverFrames["__profileViewport"]?.contains(CGPoint(x: frame.midX, y: frame.midY)) ?? false
        } ?? false

        return Button {
            guard !suppressProfileTap else { return }
            store.switchProfile(to: profile.id)
            section = .profiles
        } label: {
            ZStack {
                Circle()
                    .fill((profile.color ?? .gray).color.opacity(selectedProfile ? 0.30 : 0.14))
                if selectedProfile {
                    Circle()
                        .fill((profile.color ?? .gray).color)
                        .frame(width: 10, height: 10)
                } else {
                    Circle()
                        .stroke((profile.color ?? .gray).color.opacity(0.98), lineWidth: 2)
                        .frame(width: 14, height: 14)
                }
                if store.mainProfileID == profile.id {
                    Image(systemName: "star.fill")
                        .font(.system(size: 7, weight: .bold))
                        .foregroundStyle(Color.yellow)
                        .offset(x: 11, y: -11)
                }
            }
            .frame(width: 34, height: 34)
            .background {
                HUDGlass(emphasized: selectedProfile || isDragging, blendingMode: .withinWindow)
                    .clipShape(Circle())
            }
            .overlay {
                Circle()
                    .stroke(Color.white.opacity(selectedProfile ? 0.16 : 0.10), lineWidth: 0.8)
            }
            .background {
                GeometryReader { proxy in
                    Color.clear.preference(
                        key: QuickOrbitProfileFramePreferenceKey.self,
                        value: [profile.id: proxy.frame(in: .global)]
                    )
                }
            }
        }
        .buttonStyle(.plain)
        .quickOrbitHoverScale(1.09, enabled: !isDragging)
        .accessibilityLabel(profile.name)
        .accessibilityValue(selectedProfile ? qoText("Aktives Profil", "Active profile", language: store.config.language) : "")
        .accessibilityHint(store.mainProfileID == profile.id
            ? qoText("Hauptprofil", "Main profile", language: store.config.language)
            : qoText("Klicken zum Aktivieren, ziehen zum Sortieren", "Click to activate, drag to reorder", language: store.config.language))
        .frame(maxWidth: .infinity, alignment: .center)
        .offset(isDragging ? CGSize(width: 0, height: profileDragTranslation.height) : profilePreviewOffset(for: profile.id))
        .scaleEffect(isDragging ? 1.01 : 1)
        .opacity(isDragging ? 0.01 : 1)
        .shadow(color: .black.opacity(isDragging ? 0.15 : 0.03), radius: isDragging ? 9 : 3, y: isDragging ? 3 : 1)
        .zIndex(isDragging ? 10000 : 0)
        .animation(.interactiveSpring(response: 0.20, dampingFraction: 0.92, blendDuration: 0.04), value: dropTargetProfileID)
        .background {
            GeometryReader { proxy in
                Color.clear.preference(
                    key: QuickOrbitRailHoverFramePreferenceKey.self,
                    value: [profile.name: proxy.frame(in: .global)]
                )
            }
        }
        .onHover { hovering in
            guard !isDragging, visible else { return }
            withAnimation(.easeOut(duration: 0.10)) {
                railHoverLabel = hovering ? profile.name : (railHoverLabel == profile.name ? nil : railHoverLabel)
            }
        }
        .allowsHitTesting(visible || isDragging)
        .simultaneousGesture(
            DragGesture(minimumDistance: 8, coordinateSpace: .global)
                .onChanged { value in
                    guard store.mainProfileID != profile.id else { return }
                    updateProfileDrag(value, profile: profile)
                }
                .onEnded { value in
                    guard store.mainProfileID != profile.id else {
                        resetProfileDragState()
                        return
                    }
                    finishProfileDrag(value, profile: profile)
                }
        )
    }

    private func updateProfileDrag(
        _ value: DragGesture.Value,
        profile: OrbitProfile
    ) {
        if draggedProfileID == nil {
            dragStartProfileFrames = profileFrames
            draggedProfileID = profile.id
            suppressProfileTap = true
            if let sourceFrame = dragStartProfileFrames[profile.id] {
                profileGrabOffset = CGSize(
                    width: value.startLocation.x - sourceFrame.midX,
                    height: value.startLocation.y - sourceFrame.midY
                )
            } else {
                profileGrabOffset = .zero
            }
            NSHapticFeedbackManager.defaultPerformer.perform(.generic, performanceTime: .now)
        }
        guard draggedProfileID == profile.id else { return }

        let sourceFrame = dragStartProfileFrames[profile.id] ?? profileFrames[profile.id]
        let railX = sourceFrame?.midX ?? (value.location.x - profileGrabOffset.width)
        let sourceY = sourceFrame?.midY ?? (value.location.y - profileGrabOffset.height)
        let rawY = value.location.y - profileGrabOffset.height
        let clampedY = clampedProfileDragCenterY(rawY, sourceID: profile.id, sourceY: sourceY)
        let draggedCenter = CGPoint(x: railX, y: clampedY)
        profileDragGlobalCenter = draggedCenter
        profileDragTranslation = CGSize(width: 0, height: clampedY - sourceY)

        let previousTarget = dropTargetProfileID
        updateProfileTarget(
            stableProfileTarget(at: draggedCenter, sourceID: profile.id, current: previousTarget),
            sourceID: profile.id
        )
        if let target = dropTargetProfileID,
           target != profile.id,
           target != previousTarget,
           target != lastProfileFeedbackTargetID {
            lastProfileFeedbackTargetID = target
            NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
        }
    }

    private func finishProfileDrag(_ value: DragGesture.Value, profile: OrbitProfile) {
        let sourceFrame = dragStartProfileFrames[profile.id] ?? profileFrames[profile.id]
        let railX = sourceFrame?.midX ?? (value.location.x - profileGrabOffset.width)
        let draggedCenter = CGPoint(x: railX, y: value.location.y - profileGrabOffset.height)
        let target = dropTargetProfileID ?? finalProfileTarget(at: draggedCenter, sourceID: profile.id)
        if let target, target != profile.id {
            store.moveProfile(profile.id, before: target)
            NSHapticFeedbackManager.defaultPerformer.perform(.levelChange, performanceTime: .now)
        }
        resetProfileDragState()
    }


