    @ViewBuilder
    private func profileReorderPalette(sourceID: UUID) -> some View {
        GeometryReader { proxy in
            if let sourceFrame = dragStartProfileFrames[sourceID] ?? profileFrames[sourceID],
               let sourceIndex = store.profiles.firstIndex(where: { $0.id == sourceID }),
               let sourceProfile = store.profiles.first(where: { $0.id == sourceID }) {
                let globalFrame = proxy.frame(in: .global)
                let rowHeight: CGFloat = 44
                let firstCenterY = sourceFrame.midY - CGFloat(sourceIndex) * rowHeight
                let paletteHeight = CGFloat(store.profiles.count) * rowHeight + 20
                let paletteCenterX = sourceFrame.midX + 94
                let paletteCenterY = firstCenterY + CGFloat(store.profiles.count - 1) * rowHeight / 2
                RoundedRectangle(cornerRadius: 20, style: .continuous)
                    .fill(Color.white.opacity(0.035))
                    .background {
                        HUDGlass(emphasized: false, blendingMode: .withinWindow)
                            .clipShape(RoundedRectangle(cornerRadius: 20, style: .continuous))
                    }
                    .overlay {
                        RoundedRectangle(cornerRadius: 20, style: .continuous)
                            .stroke(Color.white.opacity(0.25), lineWidth: 0.8)
                    }
                    .frame(width: 230, height: paletteHeight)
                    .position(
                        x: paletteCenterX - globalFrame.minX,
                        y: paletteCenterY - globalFrame.minY
                    )
                    .shadow(color: .black.opacity(0.14), radius: 18, y: 8)

                ForEach(Array(store.profiles.enumerated()), id: \.element.id) { index, profile in
                    let isSource = profile.id == sourceID
                    HStack(spacing: 11) {
                        ZStack {
                            Circle()
                                .fill((profile.color ?? .gray).color.opacity(0.22))
                            Circle()
                                .fill((profile.color ?? .gray).color)
                                .frame(width: 9, height: 9)
                        }
                        .frame(width: 30, height: 30)

                        Text(profile.name)
                            .font(.system(size: 12.5, weight: .semibold))
                            .lineLimit(1)
                        Spacer(minLength: 6)
                        Text("\(index + 1)")
                            .font(.system(size: 9, weight: .bold, design: .rounded))
                            .foregroundStyle(.secondary)
                        if store.mainProfileID == profile.id {
                            Image(systemName: "star.fill")
                                .font(.system(size: 9, weight: .bold))
                                .foregroundStyle(Color.yellow)
                        }
                        if !isSource && store.mainProfileID != profile.id {
                            Image(systemName: "line.3.horizontal")
                                .font(.system(size: 9, weight: .semibold))
                                .foregroundStyle(.tertiary)
                        }
                    }
                    .padding(.horizontal, 10)
                    .frame(width: 208, height: 38)
                    .background(
                        Color.white.opacity(isSource ? 0.035 : 0.075),
                        in: RoundedRectangle(cornerRadius: 13, style: .continuous)
                    )
                    .opacity(isSource ? 0.28 : 1)
                    .offset(y: profilePreviewOffset(for: profile.id).height)
                    .position(
                        x: paletteCenterX - globalFrame.minX,
                        y: firstCenterY + CGFloat(index) * rowHeight - globalFrame.minY
                    )
                }

                if let targetID = dropTargetProfileID,
                   let targetIndex = store.profiles.firstIndex(where: { $0.id == targetID }) {
                    let sourceColor = (sourceProfile.color ?? .gray).color
                    HStack(spacing: 10) {
                        ZStack {
                            Circle().fill(Color.black.opacity(0.22))
                            Circle().fill(sourceColor.opacity(0.52)).padding(4)
                            Circle().fill(sourceColor).frame(width: 8, height: 8)
                        }
                        .frame(width: 28, height: 28)

                        Text(sourceProfile.name)
                            .font(.system(size: 12.5, weight: .semibold))
                            .lineLimit(1)
                        Spacer(minLength: 5)
                        Text(qoText("Vorschau", "Preview", language: store.config.language))
                            .font(.system(size: 8.5, weight: .bold))
                            .foregroundStyle(.secondary)
                    }
                    .padding(.horizontal, 10)
                    .frame(width: 208, height: 38)
                    .background(Color.primary.opacity(0.10), in: RoundedRectangle(cornerRadius: 13, style: .continuous))
                    .overlay {
                        RoundedRectangle(cornerRadius: 13, style: .continuous)
                            .stroke(sourceColor.opacity(0.58), style: StrokeStyle(lineWidth: 1, dash: [4, 3]))
                    }
                    .opacity(0.68)
                    .position(
                        x: paletteCenterX - globalFrame.minX,
                        y: firstCenterY + CGFloat(targetIndex) * rowHeight - globalFrame.minY
                    )
                }
            }
        }
        .allowsHitTesting(false)
        .transition(.opacity)
    }

    private func clampedProfileDragCenterY(_ proposedY: CGFloat, sourceID: UUID, sourceY: CGFloat) -> CGFloat {
        let ids = store.profiles.map(\.id)
        guard let sourceIndex = ids.firstIndex(of: sourceID), !ids.isEmpty else { return proposedY }
        let step: CGFloat = 44
        let minimumIndex = store.mainProfileID == nil ? 0 : 1
        let minimumY = sourceY - CGFloat(sourceIndex - minimumIndex) * step
        let maximumY = sourceY + CGFloat(ids.count - 1 - sourceIndex) * step
        return min(max(proposedY, minimumY), maximumY)
    }

    private func profilePreviewOffset(for profileID: UUID) -> CGSize {
        guard let sourceID = draggedProfileID,
              let targetID = dropTargetProfileID,
              sourceID != targetID else { return .zero }

        let ids = store.profiles.map(\.id)
        guard let sourceIndex = ids.firstIndex(of: sourceID),
              let targetIndex = ids.firstIndex(of: targetID),
              let itemIndex = ids.firstIndex(of: profileID),
              profileID != sourceID else { return .zero }

        let step: CGFloat = 44
        if sourceIndex < targetIndex, itemIndex > sourceIndex, itemIndex <= targetIndex {
            return CGSize(width: 0, height: -step)
        }
        if sourceIndex > targetIndex, itemIndex >= targetIndex, itemIndex < sourceIndex {
            return CGSize(width: 0, height: step)
        }
        return .zero
    }

    private func stableProfileTarget(at point: CGPoint, sourceID: UUID, current: UUID?) -> UUID? {
        let ids = store.profiles.map(\.id)
        guard let sourceIndex = ids.firstIndex(of: sourceID), !ids.isEmpty else { return current }

        let minimumSlot = store.mainProfileID == nil ? 0 : 1
        let frames = dragStartProfileFrames.isEmpty ? profileFrames : dragStartProfileFrames
        let step: CGFloat = 44
        let sourceY = frames[sourceID]?.midY ?? point.y

        // Fixed insertion slots. The moving/scrolling profile views never become
        // the calculation base, so the target cannot jump when the list animates.
        let relative = (point.y - sourceY) / step
        var targetIndex = sourceIndex
        if relative > 0.56 {
            targetIndex = sourceIndex + Int(floor(relative + 0.44))
        } else if relative < -0.56 {
            targetIndex = sourceIndex + Int(ceil(relative - 0.44))
        }
        targetIndex = max(minimumSlot, min(ids.count - 1, targetIndex))

        if targetIndex == sourceIndex { return nil }
        return ids[targetIndex]
    }

    private func updateProfileTarget(_ candidate: UUID?, sourceID: UUID) {
        let resolved = (candidate == sourceID) ? nil : candidate
        guard dropTargetProfileID != resolved else { return }
        dropTargetProfileID = resolved
    }

    private func finalProfileTarget(at point: CGPoint, sourceID: UUID) -> UUID? {
        // The visibly marked row is exactly where we drop. Do not recalculate on
        // mouse-up, because the final event can differ by a few pixels.
        if let dropTargetProfileID, dropTargetProfileID != sourceID {
            return dropTargetProfileID
        }
        return stableProfileTarget(at: point, sourceID: sourceID, current: nil)
    }


    private func resetProfileDragState() {
        draggedProfileID = nil
        dropTargetProfileID = nil
        lastProfileFeedbackTargetID = nil
        profileGrabOffset = .zero
        profileDragGlobalCenter = nil
        dragStartProfileFrames = [:]
        withAnimation(.easeOut(duration: 0.12)) {
            profileDragTranslation = .zero
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.12) {
            suppressProfileTap = false
        }
    }

    @ViewBuilder
    private func railHoverBubble(_ name: String) -> some View {
        Text(name)
                .font(.system(size: 11, weight: .semibold))
                .foregroundStyle(Color.primary.opacity(0.92))
                .padding(.horizontal, 10)
                .padding(.vertical, 6)
                .background {
                    HUDGlass(emphasized: true, blendingMode: .withinWindow)
                }
                .clipShape(Capsule())
                .overlay {
                    Capsule().stroke(Color.white.opacity(0.12), lineWidth: 0.7)
                }
                .shadow(color: .black.opacity(0.10), radius: 7, y: 2)
                .fixedSize()
                .allowsHitTesting(false)
                .transition(.opacity.combined(with: .move(edge: .leading)))
                .zIndex(50000)
    }

    private func sectionTitle(_ item: MainSection) -> String {
        switch item {
        case .orbit: return "QuickOrbit"
        case .profiles: return qoText("Profile", "Profiles", language: store.config.language)
        case .menuBar: return qoText("Menüleiste", "Menu Bar", language: store.config.language)
        case .behavior: return qoText("Verhalten", "Behavior", language: store.config.language)
        case .news: return qoText("Neuigkeiten", "News", language: store.config.language)
        case .info: return qoText("Info", "About", language: store.config.language)
        }
    }
}

