@MainActor
final class QuickOrbitNewsWindowController {
    static let shared = QuickOrbitNewsWindowController()
    private var panel: NSPanel?

    func show() {
        if let panel {
            panel.orderFrontRegardless()
            return
        }
        let size = CGSize(width: 800, height: 680)
        let screen = NSScreen.main?.visibleFrame ?? CGRect(x: 0, y: 0, width: 1200, height: 800)
        let origin = CGPoint(x: screen.midX - size.width / 2, y: screen.midY - size.height / 2)
        let panel = NSPanel(
            contentRect: CGRect(origin: origin, size: size),
            styleMask: [.titled, .closable, .resizable],
            backing: .buffered,
            defer: false
        )
        panel.title = qoText("Neuigkeiten", "News", language: OrbitStore.shared.config.language)
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.titlebarAppearsTransparent = true
        panel.isReleasedWhenClosed = false
        panel.contentView = NSHostingView(rootView: NewsPageView())
        panel.center()
        panel.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        self.panel = panel
    }
}

