struct QuickOrbitOverviewCard: View {
    @ObservedObject private var store = OrbitStore.shared
    @ObservedObject private var usage = QuickOrbitUsageStatsCenter.shared
    @State private var greetingPresented = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    private var totalOccupiedFields: Int {
        store.profiles.reduce(0) { total, profile in
            if profile.id == store.config.activeProfileID {
                return total + Array(store.config.items.prefix(min(store.config.itemCount, 16))).filter(\.enabled).count
            }
            return total + Array(profile.items.prefix(min(profile.itemCount, 16))).filter(\.enabled).count
        }
    }

    private var greetingText: String {
        let name = (store.config.userDisplayName ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let hour = Calendar.current.component(.hour, from: Date())
        let greeting: String
        let emoji: String
        switch hour {
        case 5..<12:
            greeting = qoText("Guten Morgen", "Good morning", language: store.config.language)
            emoji = "☀️👋"
        case 12..<18:
            greeting = qoText("Guten Tag", "Good afternoon", language: store.config.language)
            emoji = "👋"
        default:
            greeting = qoText("Guten Abend", "Good evening", language: store.config.language)
            emoji = "🌙👋"
        }
        return name.isEmpty ? "\(greeting) \(emoji)" : "\(greeting), \(name) \(emoji)"
    }

    private var dateText: String {
        Date.now.formatted(
            Date.FormatStyle()
                .weekday(.wide)
                .day()
                .month(.wide)
                .locale(Locale(identifier: (store.config.language ?? .german) == .german ? "de_DE" : "en_US"))
        )
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 28) {
            HStack(spacing: 26) {
                VStack(alignment: .leading, spacing: 10) {
                    Text(dateText.uppercased())
                        .font(.system(size: 10.5, weight: .bold, design: .rounded))
                        .tracking(1.25)
                        .foregroundStyle(.secondary)

                    Text(greetingText)
                        .font(.system(size: 46, weight: .bold, design: .rounded))
                        .foregroundStyle(Color.primary.opacity(0.98))
                        .lineLimit(2)
                        .minimumScaleFactor(0.74)
                        .opacity(greetingPresented ? 1 : 0)
                        .offset(y: greetingPresented ? 0 : 7)
                        .animation(reduceMotion ? nil : .easeOut(duration: 0.34), value: greetingPresented)

                    Text(qoText("Alles Wichtige auf einen Blick – ruhig, klar und bereit für deine nächste Aktion.", "Everything important at a glance—calm, clear, and ready for your next action.", language: store.config.language))
                        .font(.system(size: 13, weight: .medium))
                        .foregroundStyle(.secondary)
                }

                Spacer(minLength: 18)

                VStack(spacing: 7) {
                    QuickOrbitLogoView(size: 78, cornerRadius: 19)
                        .frame(width: 92, height: 92)
                        .shadow(color: .black.opacity(0.12), radius: 16, y: 7)

                    Text(quickOrbitVersionLabel)
                        .font(.system(size: 9.5, weight: .bold, design: .rounded))
                        .foregroundStyle(.secondary)
                        .padding(.horizontal, 9)
                        .padding(.vertical, 4)
                        .background(Color.primary.opacity(0.055), in: Capsule())
                }
            }
            .padding(.horizontal, 26)
            .padding(.vertical, 28)
            .quickOrbitSurface(cornerRadius: 20)
            .overlay {
                RoundedRectangle(cornerRadius: 20, style: .continuous)
                    .stroke(Color.primary.opacity(0.10), lineWidth: 0.8)
            }
            .quickOrbitTileHover(home: true)

            LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 14), count: 4), spacing: 14) {
                metricTile(value: "\(usage.totalRuns)", title: qoText("Ausführungen", "Runs", language: store.config.language), subtitle: qoText("Alle bisherigen Starts", "All previous runs", language: store.config.language), symbol: "bolt.fill")
                metricTile(value: "\(totalOccupiedFields)/144", title: qoText("Felder", "Fields", language: store.config.language), subtitle: qoText("Über alle Profile", "Across all profiles", language: store.config.language), symbol: "square.grid.3x3.fill")
                metricTile(value: "\(store.profiles.count)/9", title: qoText("Profile", "Profiles", language: store.config.language), subtitle: qoText("Eingerichtet", "Configured", language: store.config.language), symbol: "square.stack.3d.up.fill")
                metricTile(value: usage.topThree.first.map { "\($0.count)×" } ?? "–", title: qoText("Top-Aktion", "Top action", language: store.config.language), subtitle: usage.topThree.first?.title ?? qoText("Noch keine Nutzung", "No usage yet", language: store.config.language), symbol: "star.fill")
            }

            VStack(alignment: .leading, spacing: 14) {
                HStack(alignment: .firstTextBaseline) {
                    VStack(alignment: .leading, spacing: 3) {
                        Label(qoText("Top 3 Aktivitäten", "Top 3 activities", language: store.config.language), systemImage: "square.grid.3x3.fill")
                            .font(.system(size: 17, weight: .bold))
                        Text(qoText("Deine am häufigsten verwendeten QuickOrbit-Aktionen.", "Your most frequently used QuickOrbit actions.", language: store.config.language))
                            .font(.system(size: 10.5, weight: .medium))
                            .foregroundStyle(.secondary)
                    }
                    Spacer()
                }

                HStack(spacing: 14) {
                    if usage.topThree.isEmpty {
                        emptyTopTile
                        placeholderTopTile(index: 2)
                        placeholderTopTile(index: 3)
                    } else {
                        ForEach(Array(usage.topThree.enumerated()), id: \.element.id) { index, entry in
                            topTile(index: index + 1, entry: entry)
                        }
                        ForEach(usage.topThree.count..<3, id: \.self) { index in
                            placeholderTopTile(index: index + 1)
                        }
                    }
                }
            }
            .padding(18)
            .quickOrbitSurface(cornerRadius: 16)
            .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
            .overlay {
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .stroke(Color.primary.opacity(0.08), lineWidth: 0.6)
            }
        }
        .padding(32)
        .frame(maxWidth: .infinity, minHeight: 540, alignment: .topLeading)
        .onAppear {
            guard !greetingPresented else { return }
            if reduceMotion {
                greetingPresented = true
            } else {
                DispatchQueue.main.async { greetingPresented = true }
            }
        }
    }

