            Spacer(minLength: 3)
            Text(qoText("Noch keine Aktivitäten", "No activities yet", language: store.config.language))
                .font(.system(size: 13, weight: .bold))
            Text("0× " + qoText("ausgeführt", "run", language: store.config.language))
