struct OrbitPreview: View {
    @ObservedObject private var store = OrbitStore.shared
    var compact = false

    var body: some View {
        GeometryReader { proxy in
            let scale = fitScale(in: proxy.size)
            let center = previewCenter(in: proxy.size, scale: scale)

            OrbitMenuVisual(
                items: store.visibleItems,
                selectedIndex: nil,
                progress: 0,
                config: store.config,
                mode: .run,
                center: center,
                interactionCenter: center,
                pointer: center,
                availableSize: proxy.size,
                profileCount: store.profiles.count,
                profileIndex: store.activeProfileIndex,
                profileColors: store.profiles.map { $0.color ?? .gray },
                visualScale: scale
            )
        }
        .background {
            RoundedRectangle(cornerRadius: 20, style: .continuous)
                .fill(Color.black.opacity(0.018))
        }
        .quickOrbitGlass(cornerRadius: 20)
        .overlay(alignment: .bottomLeading) {
            HStack(spacing: 6) {
                Image(systemName: "eye")
                if !compact { Text(qoText("Live-Vorschau", "Live preview", language: store.config.language)) }
            }
            .font(.caption)
            .foregroundStyle(.secondary)
            .padding(10)
        }
    }

    private func fitScale(in size: CGSize) -> CGFloat {
        let radius = OrbitGeometry.radius(config: store.config)
        let tile = OrbitGeometry.tileSize(config: store.config)
        let offsets = OrbitGeometry.offsets(count: store.visibleItems.count, layout: store.config.layout, radius: radius, spacingScale: CGFloat(store.config.itemSpacing))
        guard !offsets.isEmpty else { return 1 }

        let xs = offsets.map(\.x)
        let ys = offsets.map(\.y)
        let minX = xs.min() ?? 0
        let maxX = xs.max() ?? 0
        let minY = ys.min() ?? 0
        let maxY = ys.max() ?? 0
        // Reserve enough room for real labels, not only the circular tile. This
        // keeps longer German and English titles inside the live preview.
        let horizontalRoom = tile * 0.72 + (store.config.showLabels ? estimatedLabelHalfWidth : 16)
        let topRoom = tile * 0.72 + 20
        let bottomRoom = tile * 0.74 + (store.config.showLabels ? 54 : 20)
        let neededWidth = maxX - minX + horizontalRoom * 2
        let neededHeight = maxY - minY + topRoom + bottomRoom
        let availableWidth = max(80, size.width - (compact ? 18 : 30))
        let availableHeight = max(80, size.height - (compact ? 18 : 30))
        let fit = min(availableWidth / max(neededWidth, 1), availableHeight / max(neededHeight, 1))
        let count = store.visibleItems.count
        let maximumScale: CGFloat = compact ? 0.68 : (count <= 4 ? 0.90 : (count <= 8 ? 0.82 : 0.72))
        return min(maximumScale, max(0.14, fit * 0.94))
    }

    private func previewCenter(in size: CGSize, scale: CGFloat) -> CGPoint {
        let radius = OrbitGeometry.radius(config: store.config) * scale
        let offsets = OrbitGeometry.offsets(
            count: store.visibleItems.count,
            layout: store.config.layout,
            radius: radius,
            spacingScale: CGFloat(store.config.itemSpacing)
        )
        guard let minX = offsets.map(\.x).min(), let maxX = offsets.map(\.x).max(),
              let minY = offsets.map(\.y).min(), let maxY = offsets.map(\.y).max() else {
            return CGPoint(x: size.width / 2, y: size.height / 2)
        }

        let tile = OrbitGeometry.tileSize(config: store.config) * scale
        let horizontalRoom = tile * 0.72 + (store.config.showLabels ? estimatedLabelHalfWidth * scale : 16 * scale)
        let topRoom = tile * 0.72 + 20 * scale
        let bottomRoom = tile * 0.74 + (store.config.showLabels ? 54 * scale : 20 * scale)
        let contentMidX = ((minX - horizontalRoom) + (maxX + horizontalRoom)) / 2
        let contentMidY = ((minY - topRoom) + (maxY + bottomRoom)) / 2
        return CGPoint(
            x: size.width / 2 - contentMidX,
            y: size.height / 2 - contentMidY
        )
    }

    private var estimatedLabelHalfWidth: CGFloat {
        let longest = store.visibleItems
            .filter(\.enabled)
            .map { $0.title.count }
            .max() ?? 0
        return min(96, max(42, CGFloat(longest) * 3.35))
    }
}

private struct QuickOrbitFieldFramePreferenceKey: PreferenceKey {
    static let defaultValue: [UUID: CGRect] = [:]

    static func reduce(value: inout [UUID: CGRect], nextValue: () -> [UUID: CGRect]) {
        value.merge(nextValue(), uniquingKeysWith: { _, new in new })
    }
}


private struct QuickOrbitRailHoverFramePreferenceKey: PreferenceKey {
    static let defaultValue: [String: CGRect] = [:]
    static func reduce(value: inout [String: CGRect], nextValue: () -> [String: CGRect]) {
        value.merge(nextValue(), uniquingKeysWith: { _, new in new })
    }
}

private struct QuickOrbitProfileFramePreferenceKey: PreferenceKey {
    static let defaultValue: [UUID: CGRect] = [:]

    static func reduce(value: inout [UUID: CGRect], nextValue: () -> [UUID: CGRect]) {
        value.merge(nextValue(), uniquingKeysWith: { _, new in new })
    }
}

struct FieldGrid: View {
    @ObservedObject private var store = OrbitStore.shared
    @State private var draggedFieldID: UUID?
    @State private var dropTargetFieldID: UUID?
    @State private var fieldFrames: [UUID: CGRect] = [:]
    @State private var dragStartFieldFrames: [UUID: CGRect] = [:]
    @State private var dragTranslation: CGSize = .zero
    @State private var fieldGrabOffset: CGSize = .zero
    @State private var pendingFieldTargetID: UUID?
    @State private var pendingFieldTargetSince: TimeInterval = 0
    @State private var suppressFieldTap = false
    @State private var hoveredFieldID: UUID?
    @State private var lastFeedbackTargetID: UUID?

    private struct Entry: Identifiable {
        let index: Int
        let item: OrbitItem
        var id: UUID { item.id }
    }

    private var entries: [Entry] {
        Array(store.config.items.prefix(store.config.itemCount).enumerated()).compactMap {
            $0.element.enabled ? Entry(index: $0.offset, item: $0.element) : nil
        }
    }

    var body: some View {
        VStack(spacing: 14) {
            ZStack(alignment: .top) {
                GeometryReader { proxy in
                    if let placeholder = fieldPlaceholderFrame() {
                        RoundedRectangle(cornerRadius: QuickOrbitUI.smallRadius, style: .continuous)
                            .stroke(Color.primary.opacity(0.34), lineWidth: 1.6)
                            .background(Color.primary.opacity(0.055), in: RoundedRectangle(cornerRadius: QuickOrbitUI.smallRadius, style: .continuous))
                            .frame(width: placeholder.width, height: placeholder.height)
                            .position(x: placeholder.midX - proxy.frame(in: .global).minX, y: placeholder.midY - proxy.frame(in: .global).minY)
                            .allowsHitTesting(false)
                    }
                }
                .zIndex(0)

                LazyVGrid(
                    columns: Array(repeating: GridItem(.flexible(), spacing: 10), count: 4),
                    spacing: 10
                ) {
                    ForEach(entries) { entry in
                        fieldButton(entry)
                    }

                    if store.config.itemCount < 16 {
                        Button {
                            if store.config.haptics && !(store.config.energySavingMode ?? false) {
                                NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
                            }
                            store.addSlot()
                        } label: {
                            VStack(spacing: 7) {
                                Image(systemName: "plus")
                                    .font(.system(size: 20, weight: .semibold))
                                    .frame(height: 40)
                                Text(qoText("Neu", "New", language: store.config.language))
                                    .font(.caption)
                            }
                            .frame(maxWidth: .infinity)
                            .frame(height: 76)
                            .contentShape(RoundedRectangle(cornerRadius: QuickOrbitUI.smallRadius, style: .continuous))
                        }
                        .buttonStyle(.plain)
                        .quickOrbitGlass(cornerRadius: QuickOrbitUI.smallRadius, interactive: true)
                        .quickOrbitPickerHover()
                        .accessibilityLabel(qoText("Neues Feld hinzufügen", "Add new field", language: store.config.language))
                        .help(qoText("Überall in dieser Kachel klicken", "Click anywhere in this tile", language: store.config.language))
                    }
                }
                .onPreferenceChange(QuickOrbitFieldFramePreferenceKey.self) { fieldFrames = $0 }
                .zIndex(draggedFieldID != nil ? 1000 : 0)

                if draggedFieldID != nil {
                    Label(
                        qoText("Zum Ziel ziehen · loslassen zum Platzieren", "Drag to a target · release to place", language: store.config.language),
                        systemImage: "hand.draw.fill"
                    )
                    .font(.caption2.weight(.semibold))
                    .padding(.horizontal, 11)
                    .padding(.vertical, 7)
                    .quickOrbitGlass(cornerRadius: 999)
                    .offset(y: -36)
                    .zIndex(0)
                    .allowsHitTesting(false)
                }
            }

            Label(qoText("Kachel greifen und auf die gewünschte Position ziehen.", "Grab a tile and drag it to the position you want.", language: store.config.language), systemImage: "arrow.up.and.down.and.arrow.left.and.right")
                .font(.caption2)
                .foregroundStyle(.secondary)

            HStack {
                Text(qoText("\(store.occupiedCount) belegt", "\(store.occupiedCount) occupied", language: store.config.language))
                    .font(.caption)
                    .foregroundStyle(.secondary)

                Spacer()

                Text("\(store.config.itemCount)/16")
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(.secondary)

                if store.config.itemCount > 0 {
                    Button(qoText("Letztes entfernen", "Remove last", language: store.config.language)) {
                        store.removeLastSlot()
                    }
                    .font(.caption)
                    .quickOrbitGlassButton()
                    .controlSize(.small)
                }
            }
        }
        .onDisappear {
            resetFieldDragState()
        }
    }

    private func fieldButton(_ entry: Entry) -> some View {
        let index = entry.index
        let item = entry.item
        let selected = store.selectedSlot == index
        let isDragging = draggedFieldID == item.id
        let isHovered = hoveredFieldID == item.id && draggedFieldID == nil

        return VStack(spacing: 6) {
            FieldIcon(item: item, size: 38)

            Text(item.enabled ? item.title : qoText("Leer", "Empty", language: OrbitStore.shared.config.language))
                .font(.caption2.weight(selected ? .semibold : .regular))
                .lineLimit(1)
                .minimumScaleFactor(0.7)
        }
        .frame(maxWidth: .infinity)
        .frame(height: 76)
        .overlay(alignment: .topLeading) {
            Text("\(index + 1)")
                .font(.system(size: 9, weight: .bold))
                .foregroundStyle(.secondary)
                .padding(6)
        }
        .overlay(alignment: .topTrailing) {
            if isDragging {
                Image(systemName: "hand.draw.fill")
                    .font(.system(size: 10, weight: .bold))
                    .foregroundStyle(Color.accentColor)
                    .padding(7)
            } else if isHovered {
                Image(systemName: "arrow.up.and.down.and.arrow.left.and.right")
                    .font(.system(size: 9, weight: .bold))
                    .foregroundStyle(.secondary)
                    .padding(7)
            }
        }
        .background {
            if selected && draggedFieldID == nil {
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .fill(Color.accentColor.opacity(0.11))
            }
        }
        .contentShape(RoundedRectangle(cornerRadius: QuickOrbitUI.smallRadius, style: .continuous))
        .quickOrbitGlass(cornerRadius: QuickOrbitUI.smallRadius, interactive: false)
        .background {
            GeometryReader { proxy in
                Color.clear.preference(
                    key: QuickOrbitFieldFramePreferenceKey.self,
                    value: [item.id: proxy.frame(in: .global)]
                )
            }
        }
        .overlay {
            if isHovered {
                RoundedRectangle(cornerRadius: QuickOrbitUI.smallRadius, style: .continuous)
                    .stroke(Color.primary.opacity(0.11), lineWidth: 1)
                    .allowsHitTesting(false)
            }
        }
        .offset(isDragging ? dragTranslation : previewOffset(for: item.id))
        .scaleEffect(isDragging ? 1.018 : 1)
        .opacity(draggedFieldID != nil && !isDragging ? 0.96 : 1)
        .shadow(color: .black.opacity(isDragging ? 0.16 : 0), radius: 12, y: 5)
        .zIndex(isDragging ? 10000 : (index == 0 ? 2 : 0))
        .animation(.interactiveSpring(response: 0.16, dampingFraction: 0.96, blendDuration: 0.03), value: dropTargetFieldID)
        .onHover { hovering in
            if draggedFieldID == nil {
                hoveredFieldID = hovering ? item.id : nil
            }
        }
        .onTapGesture {
            guard !suppressFieldTap else { return }
            store.selectedSlot = index
            if item.enabled {
                QuickReplaceController.shared.show(slot: index, near: NSEvent.mouseLocation)
            } else {
                // Empty slots now go straight to the full editor. No compact popup first.
                store.editorSlot = index
            }
        }
        .contextMenu {
            Button(role: .destructive) {
                store.removeSlot(index)
            } label: {
                Label(qoText("Feld komplett löschen", "Delete field completely", language: store.config.language), systemImage: "trash")
            }
        }
        .simultaneousGesture(
            DragGesture(minimumDistance: QuickOrbitUI.reorderMinimumDistance, coordinateSpace: .global)
                .onChanged { value in
                    if draggedFieldID == nil {
                        dragStartFieldFrames = fieldFrames
                        draggedFieldID = item.id
                        suppressFieldTap = true
                        hoveredFieldID = nil
                        if let sourceFrame = dragStartFieldFrames[item.id] {
                            fieldGrabOffset = CGSize(
                                width: value.startLocation.x - sourceFrame.midX,
                                height: value.startLocation.y - sourceFrame.midY
                            )
                        } else {
                            fieldGrabOffset = .zero
                        }
                        NSHapticFeedbackManager.defaultPerformer.perform(.generic, performanceTime: .now)
                    }
                    guard draggedFieldID == item.id else { return }

                    dragTranslation = value.translation
                    let rawCenter = CGPoint(
                        x: value.location.x - fieldGrabOffset.width,
                        y: value.location.y - fieldGrabOffset.height
                    )
                    let draggedCenter = clampedFieldDragCenter(rawCenter)
                    dragTranslation = CGSize(
                        width: draggedCenter.x - (dragStartFieldFrames[item.id]?.midX ?? draggedCenter.x),
                        height: draggedCenter.y - (dragStartFieldFrames[item.id]?.midY ?? draggedCenter.y)
                    )
                    let candidate = stableFieldTarget(
                        at: draggedCenter,
                        sourceID: item.id,
                        current: dropTargetFieldID
                    )
                    let previousTarget = dropTargetFieldID
                    updateFieldTarget(candidate, sourceID: item.id)
                    if let target = dropTargetFieldID,
                       target != item.id,
                       target != previousTarget,
                       target != lastFeedbackTargetID {
                        lastFeedbackTargetID = target
                        NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
                    }
                }
                .onEnded { value in
                    let draggedCenter = clampedFieldDragCenter(CGPoint(
                        x: value.location.x - fieldGrabOffset.width,
                        y: value.location.y - fieldGrabOffset.height
                    ))
                    let targetID = dropTargetFieldID ?? finalFieldTarget(at: draggedCenter, sourceID: item.id)
                    if let targetID,
                       let source = store.visibleItems.firstIndex(where: { $0.id == item.id }),
                       let target = store.visibleItems.firstIndex(where: { $0.id == targetID }),
                       source != target {
                        store.reorderSlot(from: source, to: target)
                        NSHapticFeedbackManager.defaultPerformer.perform(.levelChange, performanceTime: .now)
                    }
                    resetFieldDragState()
                }
        )
    }

    private func clampedFieldDragCenter(_ point: CGPoint) -> CGPoint {
        let frames = dragStartFieldFrames.isEmpty ? fieldFrames : dragStartFieldFrames
        guard !frames.isEmpty else { return point }
        let union = frames.values.reduce(CGRect.null) { $0.union($1) }
        guard !union.isNull else { return point }
        // Only real field slots are inside this rectangle. The separate `Neu` (+) tile
        // is not part of fieldFrames and therefore cannot be entered visually.
        return CGPoint(
            x: min(max(point.x, union.minX + 2), union.maxX - 2),
            y: min(max(point.y, union.minY + 2), union.maxY - 2)
        )
    }

    private func previewOffset(for itemID: UUID) -> CGSize {
        guard let sourceID = draggedFieldID,
              let targetID = dropTargetFieldID,
              sourceID != targetID else { return .zero }

        let originalIDs = entries.map(\.id)
        guard let sourceIndex = originalIDs.firstIndex(of: sourceID),
              let targetIndex = originalIDs.firstIndex(of: targetID),
              let itemOriginalIndex = originalIDs.firstIndex(of: itemID) else { return .zero }

        var previewIDs = originalIDs
        let moved = previewIDs.remove(at: sourceIndex)
        previewIDs.insert(moved, at: targetIndex)

        guard let previewIndex = previewIDs.firstIndex(of: itemID),
              previewIndex != itemOriginalIndex else { return .zero }

        let frames = dragStartFieldFrames.isEmpty ? fieldFrames : dragStartFieldFrames
        guard originalIDs.indices.contains(previewIndex),
              let from = frames[itemID],
              let destination = frames[originalIDs[previewIndex]] else { return .zero }

        return CGSize(width: destination.midX - from.midX, height: destination.midY - from.midY)
    }

    private func stableFieldTarget(at point: CGPoint, sourceID: UUID, current: UUID?) -> UUID? {
        let frames = dragStartFieldFrames.isEmpty ? fieldFrames : dragStartFieldFrames
        guard !frames.isEmpty else { return current }

        let bounds = frames.values.reduce(CGRect.null) { $0.union($1) }
            .insetBy(dx: -(QuickOrbitUI.reorderOuterTolerance * 1.25), dy: -(QuickOrbitUI.reorderOuterTolerance * 1.25))
        guard bounds.contains(point) else { return current }

        // Compare the CENTER of the dragged tile with frozen target frames. Normalizing
        // by tile size makes the four-column grid feel consistent even if the window is
        // resized and the cells get wider or narrower.
        func score(_ frame: CGRect) -> CGFloat {
            let dx = (frame.midX - point.x) / max(frame.width, 1)
            let dy = (frame.midY - point.y) / max(frame.height, 1)
            return hypot(dx, dy)
        }

        let nearest = frames.min { score($0.value) < score($1.value) }
        guard let nearest else { return current }

        if nearest.key == sourceID {
            if let current, current != sourceID, let currentFrame = frames[current] {
                let sticky = currentFrame.insetBy(
                    dx: -(QuickOrbitUI.reorderHitExpansion * 1.25),
                    dy: -(QuickOrbitUI.reorderHitExpansion * 1.25)
                )
                if sticky.contains(point) { return current }
            }
            return nil
        }

        if let current,
           current != sourceID,
           current != nearest.key,
           let currentFrame = frames[current] {
            let currentScore = score(currentFrame)
            let nearestScore = score(nearest.value)
            let normalizedMargin = max(0.13, QuickOrbitUI.reorderHysteresis / max(max(currentFrame.width, currentFrame.height), 1))
            if nearestScore + normalizedMargin >= currentScore { return current }
        }

        return nearest.key
    }

    private func updateFieldTarget(_ candidate: UUID?, sourceID: UUID) {
        guard let candidate, candidate != sourceID else {
            dropTargetFieldID = nil
            pendingFieldTargetID = nil
            pendingFieldTargetSince = 0
            return
        }

        // Fields follow the dragged tile immediately. The frozen start frames and
        // hysteresis in stableFieldTarget keep the target from flickering while the
        // direct update makes the live rearrangement feel continuous.
        if dropTargetFieldID != candidate {
            dropTargetFieldID = candidate
        }
        pendingFieldTargetID = nil
        pendingFieldTargetSince = 0
    }

    private func finalFieldTarget(at point: CGPoint, sourceID: UUID) -> UUID? {
        let frames = dragStartFieldFrames.isEmpty ? fieldFrames : dragStartFieldFrames
        guard !frames.isEmpty else { return nil }
        let bounds = frames.values.reduce(CGRect.null) { $0.union($1) }
            .insetBy(dx: -(QuickOrbitUI.reorderOuterTolerance * 1.25), dy: -(QuickOrbitUI.reorderOuterTolerance * 1.25))
        guard bounds.contains(point) else { return nil }

        func score(_ frame: CGRect) -> CGFloat {
            let dx = (frame.midX - point.x) / max(frame.width, 1)
            let dy = (frame.midY - point.y) / max(frame.height, 1)
            return hypot(dx, dy)
        }
        guard let nearest = frames.min(by: { score($0.value) < score($1.value) }) else { return nil }

        if nearest.key == sourceID {
            if let current = dropTargetFieldID,
               current != sourceID,
               let currentFrame = frames[current] {
                let sticky = currentFrame.insetBy(
                    dx: -(QuickOrbitUI.reorderHitExpansion * 1.25),
                    dy: -(QuickOrbitUI.reorderHitExpansion * 1.25)
                )
                if sticky.contains(point) { return current }
            }
            return nil
        }
        return nearest.key
    }


    private func fieldPlaceholderFrame() -> CGRect? {
        guard let sourceID = draggedFieldID,
              let targetID = dropTargetFieldID,
              sourceID != targetID else { return nil }
        let ids = entries.map(\.id)
        guard let targetIndex = ids.firstIndex(of: targetID) else { return nil }
        let frames = dragStartFieldFrames.isEmpty ? fieldFrames : dragStartFieldFrames
        guard ids.indices.contains(targetIndex), let frame = frames[ids[targetIndex]] else { return nil }
        return frame
    }

    private func resetFieldDragState() {
        draggedFieldID = nil
        dropTargetFieldID = nil
        pendingFieldTargetID = nil
        pendingFieldTargetSince = 0
        lastFeedbackTargetID = nil
        hoveredFieldID = nil
        fieldGrabOffset = .zero
        dragStartFieldFrames = [:]
        withAnimation(.spring(response: 0.17, dampingFraction: 0.97)) {
            dragTranslation = .zero
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.12) {
            suppressFieldTap = false
        }
    }
}

struct SelectedFieldCard: View {
    @ObservedObject private var store = OrbitStore.shared

    private var index: Int {
        min(max(store.selectedSlot, 0), max(store.config.itemCount - 1, 0))
    }

    private var item: OrbitItem {
        store.config.items[index]
    }

    var body: some View {
        GlassCard(title: qoText("Feld \(index + 1)", "Field \(index + 1)", language: store.config.language), symbol: "square.and.pencil") {
            VStack(alignment: .leading, spacing: 14) {
                HStack(spacing: 12) {
                    FieldIcon(item: item, size: 48)

                    VStack(alignment: .leading, spacing: 2) {
                        Text(item.enabled ? item.title : qoText("Noch nicht belegt", "Not assigned yet", language: store.config.language))
                            .font(.headline)
                        Text(item.enabled ? item.type.title(language: store.config.language) : qoText("Aktion auswählen", "Choose action", language: store.config.language))
                            .font(.caption)
                            .foregroundStyle(.secondary)

                        if item.enabled && !OrbitValidator.health(for: item).valid {
                            Label(OrbitValidator.health(for: item, language: store.config.language).message, systemImage: "exclamationmark.triangle.fill")
                                .font(.caption2.weight(.semibold))
                                .foregroundStyle(Color.orange)
                        }
                    }

                    Spacer()
                }

                HStack(spacing: 9) {
                    Button {
                        store.editorSlot = index
                    } label: {
                        Label(item.enabled ? qoText("Ändern", "Change", language: store.config.language) : qoText("Belegen", "Set up", language: store.config.language), systemImage: "slider.horizontal.3")
                            .frame(maxWidth: .infinity)
                    }
                    .quickOrbitGlassButton(prominent: true)

                    if item.enabled {
                        let health = OrbitValidator.health(for: item, language: store.config.language)
                        Button {
                            OrbitRunner.run(item)
                        } label: {
                            Image(systemName: "play.fill")
                        }
                        .quickOrbitGlassButton()
                        .disabled(!health.valid)
                        .help(health.valid ? qoText("Aktion testen", "Test action", language: store.config.language) : health.message)
                    }
                }

                if item.enabled {
                    HStack(spacing: 8) {
                        Button {
                            store.moveSlot(index, by: -1)
                        } label: { Image(systemName: "arrow.left") }
                        .quickOrbitGlassButton()
                        .disabled(index == 0)

                        Button {
                            store.moveSlot(index, by: 1)
                        } label: { Image(systemName: "arrow.right") }
                        .quickOrbitGlassButton()
                        .disabled(index == store.config.itemCount - 1)

                        Spacer()

                        Button(role: .destructive) {
                            store.removeSlot(index)
                        } label: {
                            Image(systemName: "trash")
                        }
                        .quickOrbitColorButton(.red)
                    }
                }
            }
        }
    }
}


struct ProfilesView: View {
    @ObservedObject private var store = OrbitStore.shared
    @Binding var section: MainSection?
    @FocusState private var renameFocused: Bool
    @State private var showDeleteProfileConfirmation = false
    @State private var profileNameLimitWarning = false
    @State private var profileNameWarningToken = UUID()

    private var activeProfile: OrbitProfile? { store.activeProfile }

    var body: some View {
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: 18) {
                if activeProfile != nil {
                    HStack(spacing: 12) {
                        VStack(alignment: .leading, spacing: 4) {
                            TextField(qoText("Profilname", "Profile name", language: store.config.language), text: Binding(
                                get: { store.activeProfile?.name ?? "" },
                                set: { newValue in
                                    if newValue.count <= 28 {
                                        store.renameActiveProfile(newValue)
                                        if newValue.count >= 28 {
                                            profileNameLimitWarning = true
                                            profileNameWarningToken = UUID()
                                        } else {
                                            profileNameLimitWarning = false
                                        }
                                    } else {
                                        profileNameLimitWarning = true
                                        profileNameWarningToken = UUID()
                                    }
                                }
                            ))
                            .textFieldStyle(.plain)
                            .font(.title2.weight(.semibold))
                            .focused($renameFocused)

                            if profileNameLimitWarning {
                                Text(qoText("Maximal 28 Zeichen.", "Maximum 28 characters.", language: store.config.language))
                                    .font(.caption2.weight(.semibold))
                                    .foregroundStyle(Color.red)
                                    .transition(.opacity)
                            }
                        }
                        .task(id: profileNameWarningToken) {
                            guard profileNameLimitWarning else { return }
                            try? await Task.sleep(nanoseconds: 5_000_000_000)
                            guard !Task.isCancelled else { return }
                            withAnimation(.easeOut(duration: 0.18)) {
                                profileNameLimitWarning = false
                            }
                        }

                        Spacer()

                        Button {
                            renameFocused = true
                        } label: {
                            Label(qoText("Umbenennen", "Rename", language: store.config.language), systemImage: "pencil")
                        }
                        .quickOrbitSolidButton()

                        Button {
                            guard let profileID = store.activeProfile?.id else { return }
                            store.setMainProfile(store.mainProfileID == profileID ? nil : profileID)
                        } label: {
                            let isMain = store.mainProfileID == store.activeProfile?.id
                            Label(
                                isMain
                                    ? qoText("Hauptprofil", "Main profile", language: store.config.language)
                                    : qoText("Als Hauptprofil", "Make main", language: store.config.language),
                                systemImage: isMain ? "star.fill" : "star"
                            )
                        }
                        .quickOrbitColorButton(store.mainProfileID == store.activeProfile?.id ? .yellow : .neutral)
                        .help(qoText("Das Hauptprofil bleibt oben und ist das automatische Rückkehrziel.", "The main profile stays at the top and is the automatic return target.", language: store.config.language))

                        Button(role: .destructive) { showDeleteProfileConfirmation = true } label: {
                            Image(systemName: "trash")
                        }
                        .quickOrbitColorButton(.red)
                        .disabled(store.profiles.count <= 1)

                        Text("\(store.profiles.count)/9")
                            .font(.caption.weight(.semibold))
                            .foregroundStyle(.secondary)
                            .padding(.horizontal, 9)
                            .padding(.vertical, 5)
                            .quickOrbitGlass(cornerRadius: 10)
                    }

                    GlassCard(title: qoText("Profil-Automatik", "Profile automation", language: store.config.language), symbol: "app.badge.checkmark") {
                        VStack(alignment: .leading, spacing: 12) {
                            Picker(qoText("Aktiv wenn", "Active when", language: store.config.language), selection: Binding(
                                get: { store.activeProfile?.scope ?? .allApps },
                                set: { store.setActiveProfileScope($0) }
                            )) {
                                ForEach(OrbitProfileScope.allCases) { scope in
                                    Label(scope.title(language: store.config.language), systemImage: scope.symbol).tag(scope)
                                }
                            }
                            .pickerStyle(.segmented)

                            Text(profileAutomationSummary)
                                .font(.caption)
                                .foregroundStyle(.secondary)

                            if store.autoProfileSwitchEnabled {
                                Label(
                                    qoText("Reihenfolge: „Nur bei“ → „Außer bei“ → Hauptprofil. Bei gleichen Regeln gewinnt das obere Profil.", "Priority: Selected apps only → Except selected apps → Main profile. For equal rules, the upper profile wins.", language: store.config.language),
                                    systemImage: "arrow.up.arrow.down"
                                )
                                .font(.caption2)
                                .foregroundStyle(.secondary)
                            }

                            if store.activeProfile?.scope != .allApps {
                                VStack(alignment: .leading, spacing: 8) {
                                    ScrollView(.horizontal, showsIndicators: false) {
                                        HStack(spacing: 8) {
                                            ForEach(store.activeProfile?.appsForCurrentScope ?? []) { app in
                                                ProfileAppChip(app: app) { store.removeAppFromActiveProfile(app) }
                                            }
                                        }
                                    }

                                    HStack {
                                        Button { chooseProfileApp() } label: {
                                            Label(
                                                store.activeProfile?.scope == .selectedApps
                                                    ? qoText("Apps hinzufügen", "Add apps", language: store.config.language)
                                                    : qoText("Ausnahmen hinzufügen", "Add exceptions", language: store.config.language),
                                                systemImage: "plus"
                                            )
                                        }
                                        .quickOrbitSolidButton()

                                        Spacer()

                                        Text("\(store.activeProfile?.appsForCurrentScope.count ?? 0)")
                                            .font(.caption.monospacedDigit().weight(.semibold))
                                            .foregroundStyle(.secondary)
                                            .padding(.horizontal, 8)
                                            .padding(.vertical, 5)
                                            .background(Color.primary.opacity(0.055), in: Capsule())
                                    }

                                    Label(
                                        qoText("Die Listen für „Nur bei“ und „Außer bei“ sind getrennt.", "The “Selected apps only” and “Except selected apps” lists are separate.", language: store.config.language),
                                        systemImage: "rectangle.2.swap"
                                    )
                                    .font(.caption2)
                                    .foregroundStyle(.secondary)
                                }
                            }
                        }
                    }

                    GlassCard(title: qoText("Live", "Live", language: store.config.language), symbol: "eye.fill") {
                        OrbitPreview(compact: true)
                            .frame(height: 310)
                    }

                    GlassCard(title: qoText("Felder", "Fields", language: store.config.language), symbol: "square.grid.3x3") {
                        FieldGrid()
                    }

                    HStack(alignment: .top, spacing: 14) {
                        GlassCard(title: qoText("Form", "Shape", language: store.config.language), symbol: "circle.grid.cross") {
                            VStack(alignment: .leading, spacing: 12) {
                                Picker(qoText("Layout", "Layout", language: store.config.language), selection: store.binding(\.layout)) {
                                    ForEach(OrbitLayout.allCases) { layout in
                                        Label(layout.title(language: store.config.language), systemImage: layout.symbol).tag(layout)
                                    }
                                }
                                .labelsHidden()
                                .pickerStyle(.menu)

                                Picker(qoText("Größe", "Size", language: store.config.language), selection: Binding(
                                    get: { store.config.sizePreset },
                                    set: { preset in
                                        withAnimation(.easeInOut(duration: 0.34)) {
                                            store.applySizePreset(preset)
                                        }
                                    }
                                )) {
                                    ForEach(OrbitSizePreset.allCases) { size in
                                        Text(size.title(language: store.config.language)).tag(size)
                                    }
                                }
                                .pickerStyle(.segmented)
                                .labelsHidden()

                                VStack(alignment: .leading, spacing: 5) {
                                    HStack {
                                        Text(qoText("Abstand zur Maus", "Distance from pointer", language: store.config.language))
                                        Spacer()
                                        Text("\(Int(store.config.radius)) pt")
                                    }
                                    .font(.caption.weight(.semibold))
                                    Slider(value: store.binding(\.radius), in: 95...260, step: 2)
                                }

                                VStack(alignment: .leading, spacing: 5) {
                                    HStack {
                                        Text(qoText("Feldgröße", "Field size", language: store.config.language))
                                        Spacer()
                                        Text("\(Int(store.config.tileScale * 100)) %")
                                    }
                                    .font(.caption.weight(.semibold))
                                    Slider(value: store.binding(\.tileScale), in: 0.72...1.42, step: 0.02)
                                }

                                VStack(alignment: .leading, spacing: 5) {
                                    HStack {
                                        Text(qoText("Abstand der Felder", "Space between fields", language: store.config.language))
                                        Spacer()
                                        Text("\(Int(store.config.itemSpacing * 100)) %")
                                    }
                                    .font(.caption.weight(.semibold))
                                    Slider(value: store.binding(\.itemSpacing), in: 0.68...1.45, step: 0.02)
                                }

                                VStack(alignment: .leading, spacing: 5) {
                                    HStack { Text(qoText("Hervorheben", "Highlight", language: store.config.language)); Spacer(); Text("\(Int((store.config.highlightScale - 1) * 100)) %") }
                                        .font(.caption.weight(.semibold))
                                    Slider(value: store.binding(\.highlightScale), in: 1.0...1.40, step: 0.02)
                                }
                            }
                        }

                        GlassCard(title: qoText("Aussehen", "Appearance", language: store.config.language), symbol: "paintpalette.fill") {
                            VStack(alignment: .leading, spacing: 12) {
                                HStack(spacing: 9) {
                                    ForEach(OrbitProfileColor.allCases) { choice in
                                        Button { store.config.profileColor = choice } label: {
                                            Circle()
                                                .fill(choice.color)
                                                .frame(width: 22, height: 22)
                                                .overlay {
                                                    if store.config.profileColor == choice {
                                                        Image(systemName: "checkmark")
                                                            .font(.system(size: 9, weight: .bold))
                                                            .foregroundStyle(.white)
                                                    }
                                                }
                                        }
                                        .buttonStyle(.plain)
                                    }
                                }

                                Toggle(qoText("Text anzeigen", "Show text", language: store.config.language), isOn: Binding(get: { store.config.showLabels }, set: { store.setShowLabels($0) }))
                                Toggle(qoText("Tote Zone anzeigen", "Show dead zone", language: store.config.language), isOn: Binding(
                                    get: { store.config.showDeadZone ?? true },
                                    set: { store.config.showDeadZone = $0 }
                                ))
                                Toggle(qoText("Äußeren Kreis anzeigen", "Show outer circle", language: store.config.language), isOn: Binding(
                                    get: { store.config.showOuterGuide ?? false },
                                    set: { store.setShowOuterGuide($0) }
                                ))
                                Toggle(qoText("Orbit-Glasflächen anzeigen", "Show Orbit glass circles", language: store.config.language), isOn: Binding(
                                    get: { store.config.orbitTileGlassEnabled ?? true },
                                    set: { store.config.orbitTileGlassEnabled = $0 }
                                ))

                                Divider().opacity(0.35)
                                Toggle(qoText("Profilpunkte anzeigen", "Show profile dots", language: store.config.language), isOn: Binding(
                                    get: { store.config.showProfileDots ?? true },
                                    set: { store.setShowProfileDots($0) }
                                ))
                                LabeledContent(qoText("Profilpunkte · 0 = Mitte", "Profile dots · 0 = center", language: store.config.language)) {
                                    Text("\(Int(store.config.profileDotsHorizontalOffset ?? 0)) pt")
                                        .monospacedDigit()
                                        .foregroundStyle(.secondary)
                                }
                                Slider(value: Binding(
                                    get: { store.config.profileDotsHorizontalOffset ?? 0.0 },
                                    set: { store.setProfileDotsHorizontalOffset($0) }
                                ), in: -240...240, step: 2)
                                .disabled(!(store.config.showProfileDots ?? true))

                                VStack(alignment: .leading, spacing: 5) {
                                    HStack {
                                        Text(qoText("Auswahlzeit", "Selection time", language: store.config.language))
                                            .font(.caption.weight(.semibold))
                                        Spacer()
                                        Text(String(format: "%.2f s", store.config.dwellTime))
                                            .font(.caption.monospacedDigit().weight(.semibold))
                                            .foregroundStyle(.secondary)
                                    }
                                    Slider(value: store.binding(\.dwellTime), in: 0.24...3.00, step: 0.02)
                                    Text(qoText("Gilt nur für dieses Orbit-Profil.", "Applies only to this Orbit profile.", language: store.config.language))
                                        .font(.caption).foregroundStyle(.secondary)
                                    Button(qoText("Für alle Profile übernehmen", "Apply to all profiles", language: store.config.language)) {
