        }
        .confirmationDialog(
            qoText("Profil wirklich löschen?", "Delete this profile?", language: store.config.language),
            isPresented: $showDeleteProfileConfirmation,
            titleVisibility: .visible
        ) {
            Button(qoText("Profil löschen", "Delete profile", language: store.config.language), role: .destructive) {
                store.deleteActiveProfile()
            }
            Button(qoText("Abbrechen", "Cancel", language: store.config.language), role: .cancel) { }
        } message: {
            Text(qoText("Die Belegung dieses Profils wird entfernt.", "This profile and its assignments will be removed.", language: store.config.language))
        }
    }

    private var profileAutomationSummary: String {
        guard let profile = store.activeProfile else { return "" }
        let names = profile.appsForCurrentScope.map(\.name).joined(separator: ", ")
        switch profile.scope {
        case .allApps:
            return qoText("\(profile.name) ist immer verfügbar.", "\(profile.name) is always available.", language: store.config.language)
        case .selectedApps:
            return names.isEmpty
                ? qoText("Wähle mindestens eine App aus.", "Choose at least one app.", language: store.config.language)
                : qoText("\(profile.name) ist nur aktiv bei: \(names).", "\(profile.name) is only active with: \(names).", language: store.config.language)
        case .excludedApps:
            return names.isEmpty
                ? qoText("Wähle mindestens eine Ausnahme. Bis dahin ist diese Regel inaktiv.", "Choose at least one exception. Until then, this rule is inactive.", language: store.config.language)
                : qoText("\(profile.name) ist überall aktiv, außer bei: \(names).", "\(profile.name) is active everywhere except with: \(names).", language: store.config.language)
        }
    }

    private func chooseProfileApp() {
        let panel = NSOpenPanel()
        panel.canChooseDirectories = false
        panel.canChooseFiles = true
        panel.allowsMultipleSelection = true
        panel.allowedContentTypes = [.application]
        panel.title = qoText("Apps für Profil auswählen", "Choose apps for profile", language: store.config.language)
        if panel.runModal() == .OK { store.addAppsToActiveProfile(urls: panel.urls) }
    }

}

