                                Button {
                                    withAnimation(.easeInOut(duration: 0.18)) { store.config.menuBarMainSymbol = symbol }
                                } label: {
                                    VStack(spacing: 7) {
                                        Image(systemName: symbol)
                                            .font(.system(size: 27, weight: .medium))
                                            .frame(height: 35)
                                        Text(symbol == "circle.grid.cross" ? qoText("Orbit", "Orbit", language: store.config.language)
                                             : symbol == "sparkles" ? qoText("Funkeln", "Sparkle", language: store.config.language)
                                             : qoText("Geste", "Gesture", language: store.config.language))
                                            .font(.caption2.weight(.semibold))
