                                    .foregroundStyle(selected ? Color.accentColor : Color.primary)
                                    .background(selected ? Color.accentColor.opacity(0.17) : Color.primary.opacity(0.045), in: RoundedRectangle(cornerRadius: 13, style: .continuous))
                                    .overlay {
                                        RoundedRectangle(cornerRadius: 13, style: .continuous)
                                            .stroke(selected ? Color.accentColor.opacity(0.55) : Color.primary.opacity(0.07), lineWidth: 1)
                                    }
                                    .contentShape(RoundedRectangle(cornerRadius: 13, style: .continuous))
