                GlassCard(title: qoText("Schnellleiste", "Quick bar", language: store.config.language), symbol: "rectangle.3.group", fillsGridRow: true) {
                    VStack(alignment: .leading, spacing: 12) {
                        HStack(spacing: 16) {
                            Label(qoText("Größe", "Size", language: store.config.language), systemImage: "arrow.up.left.and.arrow.down.right")
                                .frame(width: 116, alignment: .leading)
                            Picker(qoText("Größe der Schnellleiste", "Quick bar size", language: store.config.language), selection: $dockStore.dockSize) {
                                ForEach(QuickOrbitMenuDockSize.allCases) { size in
