                            .labelsHidden()
                            .pickerStyle(.segmented)
                            .frame(maxWidth: .infinity)
                        }
                        Divider().opacity(0.45)
                        HStack(spacing: 16) {
                            Label(qoText("Anzeige", "Visibility", language: store.config.language), systemImage: "eye")
                                .frame(width: 116, alignment: .leading)
                            Picker(qoText("Schnellleiste anzeigen", "Show quick bar", language: store.config.language), selection: $dockStore.visibility) {
                                ForEach(QuickOrbitMenuDockVisibility.allCases) { visibility in
                                    Text(visibility.title(language: store.config.language)).tag(visibility)
                                }
                            }
                            .labelsHidden()
                            .pickerStyle(.segmented)
                            .frame(maxWidth: .infinity)
                        }
                        Divider().opacity(0.45)
                        HStack(spacing: 16) {
                            Label(qoText("Bildschirme", "Displays", language: store.config.language), systemImage: "display.2")
                                .frame(width: 116, alignment: .leading)
                            Picker(qoText("Schnellleiste auf Bildschirmen", "Quick bar on displays", language: store.config.language), selection: $dockStore.displayMode) {
                                ForEach(QuickOrbitMenuDockDisplayMode.allCases) { mode in
                                    Text(mode.title(language: store.config.language)).tag(mode)
                                }
                            }
                            .labelsHidden()
                            .pickerStyle(.segmented)
                            .frame(maxWidth: .infinity)
                        }
                        Text(qoText("Aktivem folgen: Bildschirm unter der Maus. Auf allen: dieselbe Leiste auf jedem verbundenen Bildschirm.", "Follow active: display under the pointer. On all displays: the same bar on every connected display.", language: store.config.language))
                            .font(.caption)
                            .foregroundStyle(.secondary)
                        Divider().opacity(0.45)
                        HStack(spacing: 16) {
                            Label(qoText("Vergrößerung", "Magnification", language: store.config.language), systemImage: "arrow.up.left.and.arrow.down.right")
                                .frame(width: 116, alignment: .leading)
                            Slider(value: $dockStore.hoverMagnification, in: 1.0...1.40, step: 0.01)
                                .frame(maxWidth: .infinity)
                            Text("\(Int((dockStore.hoverMagnification - 1) * 100)) %")
                                .font(.caption.monospacedDigit().weight(.semibold))
                                .frame(width: 54, alignment: .trailing)
                        }
                        Text(qoText("Wie stark Apps beim Darüberfahren wachsen.", "How much icons grow on hover.", language: store.config.language))
                            .font(.caption)
                            .foregroundStyle(.secondary)
                        Divider().opacity(0.45)
                        HStack(spacing: 18) {
                            Toggle(qoText("Im Vollbild ausblenden", "Hide in full screen", language: store.config.language), isOn: $dockStore.hideDockInFullscreen)
                            Toggle(qoText("Auch bei fast maximierten Fenstern", "Also for near-maximized windows", language: store.config.language), isOn: $dockStore.hideDockInNearFullscreen)
                        }
                        .font(.caption.weight(.medium))
                        if dockStore.autoOpen {
                            Divider().opacity(0.45)
                            HStack(spacing: 16) {
                                Label(qoText("Auswahlzeit", "Selection time", language: store.config.language), systemImage: "timer")
                                    .frame(width: 116, alignment: .leading)
                                Slider(value: $dockStore.hoverDelay, in: 0.24...2.0, step: 0.02)
                                    .frame(maxWidth: .infinity)
                                Text(String(format: "%.2f s", dockStore.hoverDelay))
                                    .font(.caption.monospacedDigit().weight(.semibold))
                                    .frame(width: 54, alignment: .trailing)
                            }
                        }
                    }
                    .font(.subheadline)
                }
                }

                GlassCard(title: qoText("Schnellleiste · Belegung", "Quick bar · Assignments", language: store.config.language), symbol: "square.grid.3x3.fill") {
                    VStack(alignment: .leading, spacing: QuickOrbitUI.sectionSpacing) {
                        Label(qoText("Bis zu zehn Plätze pro Profil · Punkt anklicken zum Wechseln, doppelklicken zum Bearbeiten.", "Up to ten slots per profile · click a dot to switch, double-click to edit.", language: store.config.language), systemImage: "hand.tap")
                            .font(.caption)
                            .foregroundStyle(.secondary)
                        Text(qoText("In der Vorschau ziehen zum Sortieren, auf einem Feld kurz halten für einen Ordner. Rechtsklick entfernt; Plus fügt hinzu.", "Drag in the preview to reorder, pause over a tile to make a folder. Right-click removes; Plus adds.", language: store.config.language))
                            .font(.caption)
                            .foregroundStyle(.secondary)

                        MenuBarArcPopoverView(embeddedEditing: true, onAdd: openActionOverview)
                            .frame(
                                maxWidth: dockStore.orientation.isVertical ? dockStore.dockSize.panelHeight : .infinity,
                                minHeight: dockStore.orientation.isVertical ? 360 : dockStore.dockSize.panelHeight,
                                maxHeight: dockStore.orientation.isVertical ? 560 : dockStore.dockSize.panelHeight,
                                alignment: .leading
                            )
                            .clipShape(RoundedRectangle(cornerRadius: 32, style: .continuous))

                        Text("\(dockStore.items.count)/\(QuickOrbitMenuDockStore.maximumItemCount)")
                            .font(.caption.monospacedDigit().weight(.semibold))
                            .foregroundStyle(dockStore.isFull ? Color.secondary : Color.accentColor)

                        HStack(spacing: 10) {
                            Label(
                                dockStore.autoOpen ? qoText("Darüberfahren öffnet", "Hover to open", language: store.config.language) : qoText("Klick öffnet", "Click to open", language: store.config.language),
                                systemImage: "cursorarrow.motionlines"
                            )
                            Label(
                                qoText("Rechtsklick entfernt", "Right-click removes", language: store.config.language),
                                systemImage: "trash"
                            )
                            Label(
                                qoText("Position per Rechtsklick", "Position by right-click", language: store.config.language),
                                systemImage: "cursorarrow.click.2"
                            )
                        }
                        .font(.caption2.weight(.medium))
                        .foregroundStyle(.secondary)
                    }
                }
            }
            .padding(22)
            .frame(maxWidth: 1120, alignment: .leading)
        }
        .sheet(isPresented: $showsActionOverview, onDismiss: finishActionOverview) {
            MenuBarActionEditorSheet(index: 0) { selected in
                pendingDockAction = selected
            }
        }
        .onReceive(NotificationCenter.default.publisher(for: .quickOrbitOpenMenuDockActionPicker)) { _ in
            openActionOverview()
        }
    }

    private func openActionOverview() {
        guard !showsActionOverview, !dockStore.isFull else { return }
        legacyPickerBackup = OrbitStore.shared.menuBarItem(at: 0)
        pendingDockAction = nil
        dockStore.appInsertionActive = true
        OrbitStore.shared.clearMenuBarItem(0)
        showsActionOverview = true
    }

    private func finishActionOverview() {
        if let backup = legacyPickerBackup {
            OrbitStore.shared.setMenuBarItem(backup, at: 0)
        } else {
            OrbitStore.shared.clearMenuBarItem(0)
        }
        legacyPickerBackup = nil
        if let selected = pendingDockAction, selected.enabled {
            switch selected.type {
            case .app, .file:
                dockStore.insertURL(URL(fileURLWithPath: selected.target), at: dockStore.items.count)
            case .url:
                if let url = URL(string: selected.target) { dockStore.insertURL(url, at: dockStore.items.count) }
            default:
                dockStore.addOrbitAction(selected)
            }
        }
        pendingDockAction = nil
        // Keep direct editing active after adding an item. The user leaves this
        // mode explicitly by double-clicking the active profile dot again or by
        // choosing “Finish editing” from the quick-bar menu.
        dockStore.appInsertionActive = true
    }

}

struct MenuBarArcPreview: View {
    let items: [QuickOrbitMenuDockItem]
    var showsInsertion = false
    @ObservedObject private var dockStore = QuickOrbitMenuDockStore.shared

    var body: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: dockStore.dockSize.spacing) {
                QuickOrbitMenuDockProfileDots(interactive: false)
                ForEach(items.prefix(QuickOrbitMenuDockStore.maximumItemCount)) { item in
                    QuickOrbitMenuDockIcon(item: item, size: dockStore.dockSize.iconSize - 2)
                        .frame(width: dockStore.dockSize.iconSize, height: dockStore.dockSize.iconSize)
                }
                if showsInsertion && items.count < QuickOrbitMenuDockStore.maximumItemCount {
                    QuickOrbitMenuDockInsertionTile(size: dockStore.dockSize.iconSize)
                }
                if items.isEmpty {
                    QuickOrbitMenuDockPlaceholder(height: dockStore.dockSize.iconSize)
                        .fixedSize(horizontal: true, vertical: false)
                }
            }
            .padding(.horizontal, dockStore.dockSize.horizontalPadding)
            .padding(.vertical, max(8, (dockStore.dockSize.panelHeight - dockStore.dockSize.iconSize) / 2))
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background {
            RoundedRectangle(cornerRadius: 32, style: .continuous)
                .fill(Color(red: 0.13, green: 0.13, blue: 0.15).opacity(0.82))
                .overlay {
                    RoundedRectangle(cornerRadius: 32, style: .continuous)
                        .stroke(Color.white.opacity(0.24), lineWidth: 0.9)
                }
        }
        .environment(\.colorScheme, .dark)
    }
}

struct WebsiteQuickPicker: View {
    @Binding var url: String
    @Binding var symbol: String
    @State private var selectedWebsiteGroup = 0
    @State private var showMoreIcons = false

    private var websiteGroups: [(String, [WebsitePreset])] {
        let definitions: [(String, Set<String>)] = [
            (qoText("Unterhaltung", "Entertainment", language: OrbitStore.shared.config.language), ["YouTube", "Netflix", "Spotify", "Twitch", "TikTok", "ARD Mediathek", "Disney+", "Prime Video", "Vimeo", "SoundCloud", "Joyn", "Apple TV+"]),
            (qoText("Kreativität", "Creativity", language: OrbitStore.shared.config.language), ["ChatGPT", "Canva", "Pinterest", "Instagram", "Figma", "Behance", "Dribbble", "Adobe", "Unsplash"]),
            (qoText("Arbeit", "Work", language: OrbitStore.shared.config.language), ["GitHub", "GitLab", "Notion", "Microsoft 365", "Google Drive", "Slack", "Trello", "Zoom", "Asana"]),
            (qoText("Wissen", "Knowledge", language: OrbitStore.shared.config.language), ["Google", "Wikipedia", "Stack Overflow", "Medium", "Coursera", "Khan Academy"]),
            (qoText("Kommunikation", "Communication", language: OrbitStore.shared.config.language), ["Gmail", "Outlook", "Discord", "WhatsApp", "Telegram", "LinkedIn", "X", "XING", "Reddit", "Mastodon", "Messenger", "Signal"]),
            (qoText("Alltag", "Everyday", language: OrbitStore.shared.config.language), ["Amazon", "eBay", "Etsy", "PayPal", "Google Maps", "Booking", "Airbnb", "Apple", "iCloud", "Dropbox", "IKEA", "Zalando"])
        ]
        return definitions.map { title, names in (title, WebsitePreset.popular.filter { names.contains($0.name) }) }
    }

    private var recommendedSites: [WebsitePreset] {
        let names: Set<String> = ["ChatGPT", "YouTube", "Netflix", "Spotify", "Google", "Wikipedia"]
        return WebsitePreset.popular.filter { names.contains($0.name) }
    }

    private var sortedIcons: [String] {
        let media = ["play.rectangle.fill", "play.tv.fill", "film.fill", "music.note", "headphones", "camera.fill", "photo.fill", "gamecontroller.fill", "tv.fill", "radio.fill", "waveform"]
        let communication = ["bubble.left.fill", "bubble.left.and.bubble.right.fill", "message.fill", "envelope.fill", "paperplane.fill", "person.2.fill", "video.fill", "megaphone.fill", "number"]
        let work = ["briefcase.fill", "doc.text.fill", "calendar", "clock.fill", "folder.badge.plus", "chart.bar.fill", "terminal.fill", "chevron.left.forwardslash.chevron.right", "pencil.and.ruler.fill"]
        let selected = Set(media + communication + work)
        let general = WebsitePreset.symbols.filter { !selected.contains($0) }
        return media + communication + work + general
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            VStack(alignment: .leading, spacing: 8) {
                Label(qoText("Empfohlen", "Recommended", language: OrbitStore.shared.config.language), systemImage: "star.fill")
                    .font(.subheadline.weight(.bold)).foregroundStyle(Color.accentColor)
                LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 7), count: 6), spacing: 7) {
                    ForEach(recommendedSites) { site in compactWebsiteButton(site) }
                }
            }
            .padding(12)
            .background(Color.accentColor.opacity(0.075), in: RoundedRectangle(cornerRadius: 17, style: .continuous))
            .overlay { RoundedRectangle(cornerRadius: 17, style: .continuous).stroke(Color.accentColor.opacity(0.22), lineWidth: 0.9) }
            .shadow(color: Color.accentColor.opacity(0.08), radius: 10, y: 4)

            VStack(alignment: .leading, spacing: 8) {
                Text(qoText("Webseiten", "Websites", language: OrbitStore.shared.config.language))
                    .font(.caption.weight(.semibold)).foregroundStyle(.secondary)
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 7) {
                        ForEach(Array(websiteGroups.enumerated()), id: \.offset) { index, group in
                            Button {
                                withAnimation(.easeOut(duration: 0.14)) { selectedWebsiteGroup = index }
                            } label: {
                                Text(group.0)
                                    .font(.caption2.weight(.semibold))
                                    .padding(.horizontal, 10)
                                    .padding(.vertical, 6)
                                    .background(selectedWebsiteGroup == index ? Color.accentColor.opacity(0.13) : Color.primary.opacity(0.035), in: Capsule())
                            }
                            .buttonStyle(.plain)
                            .quickOrbitPickerHover()
                        }
                    }
                }
            }

            if websiteGroups.indices.contains(selectedWebsiteGroup) {
                LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 8), count: 3), spacing: 8) {
                    ForEach(websiteGroups[selectedWebsiteGroup].1) { site in websiteButton(site) }
                }
                .padding(8)
                .background(Color.primary.opacity(0.018), in: RoundedRectangle(cornerRadius: 15, style: .continuous))
                .overlay { RoundedRectangle(cornerRadius: 15, style: .continuous).stroke(Color.primary.opacity(0.07), lineWidth: 0.7) }
            }

            Text("Icon")
                .font(.caption.weight(.semibold))
                .foregroundStyle(.secondary)

            VStack(spacing: 0) {
                LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 8), count: 8), spacing: 8) {
                    ForEach(showMoreIcons ? sortedIcons : Array(sortedIcons.prefix(32)), id: \.self) { icon in
                        iconButton(icon)
                    }
                }
            }
            .padding(8)
            .background(Color.primary.opacity(0.018), in: RoundedRectangle(cornerRadius: 15, style: .continuous))
            .overlay { RoundedRectangle(cornerRadius: 15, style: .continuous).stroke(Color.primary.opacity(0.07), lineWidth: 0.7) }


            Button {
                withAnimation(.easeOut(duration: 0.15)) { showMoreIcons.toggle() }
            } label: {
                Label(
                    showMoreIcons ? qoText("Weniger Icons", "Fewer icons", language: OrbitStore.shared.config.language) : qoText("… Weitere Icons", "… More icons", language: OrbitStore.shared.config.language),
                    systemImage: showMoreIcons ? "chevron.up" : "ellipsis.circle"
                )
            }
            .quickOrbitGlassButton()
        }
    }

    private func websiteButton(_ site: WebsitePreset) -> some View {
        let selected = url == site.url
        return Button {
            url = site.url
            symbol = site.symbol
        } label: {
            VStack(spacing: 6) {
                Image(systemName: site.symbol).font(.system(size: 16, weight: .semibold)).frame(height: 19)
                Text(site.name).font(.caption.weight(.medium)).lineLimit(1).minimumScaleFactor(0.8)
            }
            .frame(maxWidth: .infinity)
            .frame(height: 58)
            .background(selected ? Color.accentColor.opacity(0.12) : Color.primary.opacity(0.025), in: RoundedRectangle(cornerRadius: 11, style: .continuous))
            .overlay { RoundedRectangle(cornerRadius: 11, style: .continuous).stroke(selected ? Color.accentColor.opacity(0.45) : Color.primary.opacity(0.08), lineWidth: 0.8) }
            .contentShape(RoundedRectangle(cornerRadius: 11, style: .continuous))
        }
        .buttonStyle(.plain)
        .quickOrbitPickerHover()
    }

    private func compactWebsiteButton(_ site: WebsitePreset) -> some View {
        Button { url = site.url; symbol = site.symbol } label: {
            VStack(spacing: 5) {
                Image(systemName: site.symbol).font(.system(size: 16, weight: .semibold)).foregroundStyle(Color.accentColor)
                Text(site.name).font(.system(size: 9.5, weight: .medium)).lineLimit(1).minimumScaleFactor(0.7)
            }
            .frame(maxWidth: .infinity).frame(height: 54)
            .background(url == site.url ? Color.accentColor.opacity(0.16) : Color.primary.opacity(0.035), in: RoundedRectangle(cornerRadius: 11, style: .continuous))
            .overlay { RoundedRectangle(cornerRadius: 11, style: .continuous).stroke(url == site.url ? Color.accentColor.opacity(0.36) : Color.primary.opacity(0.07), lineWidth: 0.7) }
        }
        .buttonStyle(.plain)
        .quickOrbitPickerHover()
    }

    private func iconButton(_ icon: String) -> some View {
        Button { symbol = icon } label: {
            Image(systemName: icon)
                .font(.system(size: 16, weight: .semibold))
                .frame(maxWidth: .infinity)
                .frame(height: 34)
                .background(symbol == icon ? Color.accentColor.opacity(0.14) : Color.primary.opacity(0.025), in: RoundedRectangle(cornerRadius: 10, style: .continuous))
        }
        .buttonStyle(.plain)
        .quickOrbitPickerHover()
    }
}

struct MenuBarActionEditorSheet: View {
    @ObservedObject private var store = OrbitStore.shared
    @Environment(\.dismiss) private var systemDismiss
    var onClose: (() -> Void)? = nil
    private func dismiss() { if let onClose { onClose() } else { systemDismiss() } }

    let index: Int
    var onCommit: ((OrbitItem) -> Void)? = nil

    @State private var mode: OrbitActionType = .app
    @State private var apps: [InstalledAppChoice] = InstalledApps.cached()
    @State private var searchText = ""
    @State private var unifiedSearchText = ""
    @State private var draftURL = ""
    @State private var draftURLSymbol = "globe"
    @State private var originalItem: OrbitItem?
    @State private var draftCommandTitle = ""
    @State private var draftShellCommand = ""
    @State private var draftShellCommandTrusted = false

    private var current: OrbitItem { store.menuBarItem(at: index) }

    private var canCommit: Bool {
        if mode == .url {
            return !draftURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        }
        if mode == .shellCommand {
            return !draftCommandTitle.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                && draftShellCommandTrusted
                && QuickOrbitBetaCommandPolicy.status(draftShellCommand, language: store.config.language).valid
        }
        guard current.enabled else { return false }
        switch mode {
        case .app: return current.type == .app
        case .file: return current.type == .file
        case .url: return false
        case .emoji:
            return current.type == .emoji
                || current.target == "emojiPalette"
                || current.target.hasPrefix("emojiInsert:")
        case .timer:
            return current.type == .timer
                || current.target.hasPrefix("timer")
                || current.target == "stopwatch"
        case .systemAction:
            return current.type == .systemAction
                && current.target != "emojiPalette"
                && !current.target.hasPrefix("emojiInsert:")
                && !current.target.hasPrefix("timer")
                && SystemActionPreset.preset(for: current.target)?.isWindowManagement != true
        case .windowManagement:
            return current.type == .windowManagement
        case .screenshot: return current.type == .screenshot
        case .edit: return current.type == .edit
        case .shellCommand: return false
        case .pasteText: return current.type == .pasteText && !current.target.isEmpty
        case .shortcut, .clipboard, .windowLeft, .windowRight: return false
        }
    }

    private var filteredApps: [InstalledAppChoice] {
        let query = searchText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !query.isEmpty else { return Array(apps.prefix(24)) }
        return apps.filter { $0.name.localizedCaseInsensitiveContains(query) }
    }

    var body: some View {
        VStack(spacing: 0) {
            HStack(spacing: 12) {
                FieldIcon(item: current, size: 44)
                VStack(alignment: .leading, spacing: 2) {
                    Text(qoText("Menüleisten-Icon \(index + 1)", "Menu bar icon \(index + 1)", language: store.config.language))
                        .font(.title2.weight(.semibold))
                    Text(current.enabled ? current.title : qoText("Aktion auswählen", "Choose action", language: store.config.language))
                        .foregroundStyle(.secondary)
                }
                Spacer()
                Label(
                    canCommit ? qoText("Auswahl bereit", "Selection ready", language: store.config.language) : qoText("Bitte auswählen", "Choose an item", language: store.config.language),
                    systemImage: canCommit ? "checkmark.circle.fill" : "circle.dashed"
                )
                .font(.caption.weight(.semibold))
                .foregroundStyle(canCommit ? Color.green : Color.secondary)
                .padding(.horizontal, 10)
                .padding(.vertical, 6)
                .background((canCommit ? Color.green : Color.secondary).opacity(0.09), in: Capsule())
                Button(qoText("Abbrechen", "Cancel", language: store.config.language)) {
                    if let originalItem { store.setMenuBarItem(originalItem, at: index) }
                    dismiss()
                }
                .quickOrbitGlassButton()
                .keyboardShortcut(.cancelAction)

                Button {
                    guard canCommit else { return }
                    if mode == .url { applyURL() }
                    if mode == .shellCommand { applyShellCommand() }
                    let selected = store.menuBarItem(at: index)
                    guard selected.enabled else { return }
                    onCommit?(selected)
                    dismiss()
                } label: {
                    Label(qoText("Fertig", "Done", language: store.config.language), systemImage: "checkmark")
                }
                .quickOrbitColorButton(canCommit ? .green : .neutral)
                .keyboardShortcut(.defaultAction)
                .disabled(!canCommit)
            }
            .padding(20)

            Divider()

            HStack(spacing: 10) {
                Image(systemName: "magnifyingglass")
                    .font(.system(size: 17, weight: .semibold))
                    .foregroundStyle(Color.accentColor)
                    .frame(width: 38, height: 38)
                    .background(Color.accentColor.opacity(0.10), in: RoundedRectangle(cornerRadius: 12, style: .continuous))
                TextField(qoText("Apps, Webseiten, Dateien und Werkzeuge suchen", "Search apps, websites, files, and tools", language: store.config.language), text: $unifiedSearchText)
                    .textFieldStyle(.plain)
                    .font(.system(size: 18, weight: .medium, design: .rounded))
                if !unifiedSearchText.isEmpty {
                    Button { unifiedSearchText = "" } label: { Image(systemName: "xmark.circle.fill") }
                        .buttonStyle(.plain)
                        .foregroundStyle(.secondary)
                }
            }
            .padding(.horizontal, 13)
            .frame(maxWidth: 680, minHeight: 58)
            .quickOrbitGlass(cornerRadius: 20, interactive: true)
            .shadow(color: Color.black.opacity(0.08), radius: 12, y: 4)
            .frame(maxWidth: .infinity)
            .padding(.horizontal, 20)
            .padding(.vertical, 9)

            HStack(spacing: 0) {
                ScrollView(.vertical, showsIndicators: false) {
                    VStack(spacing: 8) {
                        specialContainerButton(
                            title: qoText("Dropbox", "Drop box", language: store.config.language),
                            subtitle: qoText("Fotos, Dateien und Ordner ablegen", "Store photos, files, and folders", language: store.config.language),
                            symbol: "tray.and.arrow.down.fill",
                            kind: .dropBoard
                        )
                        Divider().padding(.vertical, 3)
                        ForEach(OrbitActionType.menuBarAvailableCases) { type in
                            Button {
                                mode = type
                                prepareDraft(for: type)
                            } label: {
                                HStack(spacing: 9) {
                                    Image(systemName: type.symbol)
                                        .frame(width: 19)
                                        .foregroundStyle(mode == type ? Color.accentColor : Color.primary)
                                    VStack(alignment: .leading, spacing: 2) {
                                        Text(type.title(language: store.config.language)).font(.subheadline.weight(mode == type ? .semibold : .regular))
                                        Text(type.subtitle(language: store.config.language)).font(.caption2).foregroundStyle(.secondary).lineLimit(1)
                                    }
                                    Spacer()
                                    if mode == type {
                                        Image(systemName: "checkmark.circle.fill")
                                            .foregroundStyle(Color.accentColor)
                                    }
                                }
                                .padding(.horizontal, 11)
                                .frame(maxWidth: .infinity, minHeight: 46, alignment: .leading)
                                .contentShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                                .background(mode == type ? Color.accentColor.opacity(0.11) : Color.clear, in: RoundedRectangle(cornerRadius: 14, style: .continuous))
                                .overlay {
                                    RoundedRectangle(cornerRadius: 14, style: .continuous)
                                        .stroke(mode == type ? Color.accentColor.opacity(0.22) : Color.clear, lineWidth: 0.8)
                                }
                            }
                            .buttonStyle(.plain)
                            .quickOrbitPickerHover()
                        }
                    }
                    .padding(10)
                }
                .frame(width: 236)
                .quickOrbitGlass(cornerRadius: 20)
                .padding(12)

                Divider()

                ScrollView(.vertical, showsIndicators: false) {
                    Group {
                        if unifiedQuery.isEmpty { editorContent }
                        else { unifiedSearchResults }
                    }
                        .padding(24)
                        .frame(maxWidth: .infinity, alignment: .leading)
                }
            }
        }
        .frame(width: 920, height: 680)
        .background(SystemBackdrop())
        .onAppear {
            originalItem = current
            if current.type == .systemAction && (current.target == "emojiPalette" || current.target.hasPrefix("emojiInsert:")) {
                mode = .emoji
            } else {
                mode = OrbitActionType.menuBarAvailableCases.contains(current.type) ? current.type : .app
            }
            prepareDraft(for: mode)
            draftCommandTitle = current.type == .shellCommand ? current.title : ""
            draftShellCommand = current.type == .shellCommand ? current.target : ""
            draftShellCommandTrusted = false
        }
    }

    private var unifiedQuery: String {
        unifiedSearchText.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private var unifiedSearchResults: some View {
        let matchingApps = apps.filter { $0.name.localizedCaseInsensitiveContains(unifiedQuery) }.prefix(10)
        let matchingWebsites = WebsitePreset.popular.filter { $0.name.localizedCaseInsensitiveContains(unifiedQuery) }.prefix(9)
        let matchingControls = SystemActionPreset.all.filter {
            !$0.isWindowManagement && ($0.title(language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery)
                || $0.subtitle(language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery))
        }.prefix(10)
        let matchingWindows = SystemActionPreset.all.filter {
            $0.isWindowManagement && ($0.title(language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery)
                || $0.subtitle(language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery))
        }.prefix(8)
        let fileMatch = qoText("Datei Bild Foto Ordner Dokument", "file image photo folder document", language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery)
        let emojiMatch = qoText("Emoji Smileys Symbole Flaggen", "emoji smileys symbols flags", language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery)
        let timerMatch = qoText("Timer Stoppuhr Zeit", "timer stopwatch time", language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery)
        let dropBoxMatch = qoText("Dropbox Ablage Foto Datei Ordner", "drop box storage photo file folder", language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery)
        let textMatch = qoText("Eigener Text Signatur Adresse Antwort", "custom text signature address reply", language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery)

        return VStack(alignment: .leading, spacing: 14) {
            editorTitle(qoText("Suchergebnisse", "Search results", language: store.config.language), qoText("Alles für die Schnellleiste an einem Ort.", "Everything for the quick bar in one place.", language: store.config.language))

            if textMatch {
                searchResultButton(title: qoText("Eigener Text", "Custom text", language: store.config.language), subtitle: qoText("Textbaustein erstellen", "Create a text snippet", language: store.config.language), symbol: "text.alignleft") {
                    mode = .pasteText
                    unifiedSearchText = ""
                }
            }

            if dropBoxMatch {
                searchResultButton(title: qoText("Dropbox", "Drop box", language: store.config.language), subtitle: qoText("Fotos, Dateien und Ordner", "Photos, files, and folders", language: store.config.language), symbol: "tray.and.arrow.down.fill") {
                    QuickOrbitMenuDockStore.shared.addContainer(.dropBoard); dismiss()
                }
            }

            if fileMatch {
                searchResultButton(title: qoText("Datei, Bild oder Ordner", "File, image, or folder", language: store.config.language), subtitle: qoText("Auswählen und mit Vorschau hinzufügen", "Choose and add with a preview", language: store.config.language), symbol: "photo.on.rectangle.angled") {
                    mode = .file; unifiedSearchText = ""; chooseFile()
                }
            }
            if emojiMatch {
                searchResultButton(title: qoText("Emojis", "Emojis", language: store.config.language), subtitle: qoText("Emoji auswählen", "Choose an emoji", language: store.config.language), symbol: "face.smiling") {
                    mode = .emoji; unifiedSearchText = ""
                }
            }
            if timerMatch {
                searchResultButton(title: qoText("Timer & Stoppuhr", "Timer & stopwatch", language: store.config.language), subtitle: qoText("Live-Aktivität hinzufügen", "Add a live activity", language: store.config.language), symbol: "timer") {
                    mode = .timer; unifiedSearchText = ""
                }
            }
            ForEach(Array(matchingApps)) { app in
                searchResultButton(title: app.name, subtitle: qoText("App", "App", language: store.config.language), symbol: "app.fill") {
                    applyApp(app)
                    mode = .app
                }
            }
            ForEach(Array(matchingWebsites)) { site in
                searchResultButton(title: site.name, subtitle: site.url, symbol: site.symbol) {
                    draftURL = site.url; draftURLSymbol = site.symbol; mode = .url; applyURL()
                }
            }
            ForEach(Array(matchingControls)) { preset in
                searchResultButton(title: preset.title(language: store.config.language), subtitle: preset.subtitle(language: store.config.language), symbol: preset.symbol) {
                    let selected = preset.orbitItem(language: store.config.language)
                    store.setMenuBarItem(selected, at: index)
                    mode = selected.editorCategory
                }
            }
            ForEach(Array(matchingWindows)) { preset in
                searchResultButton(title: preset.title(language: store.config.language), subtitle: preset.subtitle(language: store.config.language), symbol: preset.symbol) {
                    let selected = preset.orbitItem(language: store.config.language)
                    store.setMenuBarItem(selected, at: index)
                    mode = selected.editorCategory
                }
            }
            if !textMatch && !fileMatch && !emojiMatch && !timerMatch && !dropBoxMatch && matchingApps.isEmpty && matchingWebsites.isEmpty && matchingControls.isEmpty && matchingWindows.isEmpty {
                ContentUnavailableView(qoText("Nichts gefunden", "No results", language: store.config.language), systemImage: "magnifyingglass", description: Text(qoText("Versuche einen kürzeren Suchbegriff.", "Try a shorter search term.", language: store.config.language)))
            }
        }
    }

