    @ViewBuilder
    private var editorContent: some View {
        switch mode {
        case .app:
            VStack(alignment: .leading, spacing: 16) {
                editorTitle("App", qoText("Das echte App-Icon erscheint direkt in der Menüleiste.", "The real app icon appears directly in the menu bar.", language: store.config.language))
                TextField(qoText("Apps suchen", "Search apps", language: store.config.language), text: $searchText)
                    .quickOrbitInputField()

                LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 12), count: 6), spacing: 14) {
                    ForEach(filteredApps) { app in
                        Button {
                            applyApp(app)
                        } label: {
                            ZStack(alignment: .topTrailing) {
                            VStack(spacing: 7) {
                                Image(nsImage: app.icon)
                                    .resizable()
                                    .scaledToFit()
                                    .frame(width: 48, height: 48)
                                Text(app.name)
                                    .font(.caption)
                                    .lineLimit(1)
