                        .quickOrbitGlass(cornerRadius: QuickOrbitUI.smallRadius, interactive: true)
                        .overlay {
                            RoundedRectangle(cornerRadius: QuickOrbitUI.smallRadius, style: .continuous)
                                .stroke(current.type == .app && current.target == app.url.path ? Color.green.opacity(0.48) : Color.clear, lineWidth: 1.2)
                        }
