                editorTitle(qoText("Datei oder Ordner", "File or folder", language: store.config.language), qoText("Ein Klick auf das Menüleisten-Icon öffnet das Ziel direkt.", "Clicking the menu bar icon opens the target directly.", language: store.config.language))
                Button(qoText("Datei oder Ordner auswählen …", "Choose file or folder …", language: store.config.language)) { chooseFile() }
                    .quickOrbitGlassButton(prominent: true)
            }

        case .url:
            VStack(alignment: .leading, spacing: 16) {
                editorTitle(qoText("Webseite", "Website", language: store.config.language), qoText("Adresse wählen oder selbst eingeben.", "Choose an address or enter your own.", language: store.config.language))
                WebsiteQuickPicker(url: $draftURL, symbol: $draftURLSymbol)
                TextField("example.com", text: $draftURL)
                    .quickOrbitInputField()
            }

        case .pasteText:
            QuickOrbitCustomTextEditor(item: current, language: store.config.language) {
                store.setMenuBarItem($0, at: index)
            }
        case .shortcut, .clipboard, .windowLeft, .windowRight:
            EmptyView()

        case .emoji:
            EmojiActionPicker(
                language: store.config.language,
                selectedTarget: (current.type == .emoji || (current.type == .systemAction && (current.target == "emojiPalette" || current.target.hasPrefix("emojiInsert:")))) ? current.target : nil
