                store.setMenuBarItem(item, at: index)
            }

        case .timer:
            TimerActionPicker(
                language: store.config.language,
                selectedTarget: (current.type == .timer || (current.type == .systemAction && current.target.hasPrefix("timer"))) ? current.target : nil
            ) { item in
                store.setMenuBarItem(item, at: index)
            }

        case .systemAction:
            SystemActionPicker(
                language: store.config.language,
                selectedTarget: current.type == .systemAction ? current.target : nil
            ) { item in
                store.setMenuBarItem(item, at: index)
            }

        case .windowManagement:
            WindowActionPicker(
                language: store.config.language,
                selectedTarget: current.type == .windowManagement ? current.target : nil
            ) { item in
                store.setMenuBarItem(item, at: index)
            }

        case .screenshot:
            VStack(alignment: .leading, spacing: 16) {
                editorTitle(qoText("Screenshot-Bereich", "Screenshot area", language: store.config.language), qoText("Ein Klick startet direkt die macOS-Bereichsauswahl.", "One click starts the macOS area selection.", language: store.config.language))
                Button(qoText("Screenshot verwenden", "Use screenshot", language: store.config.language)) {
                    var item = current
                    item.type = .screenshot
                    item.target = "area"
                    item.title = "Screenshot"
                    item.symbol = "camera.viewfinder"
                    item.enabled = true
                    store.setMenuBarItem(item, at: index)
                }
                .quickOrbitGlassButton(prominent: true)
            }

        case .edit:
            VStack(alignment: .leading, spacing: 16) {
                editorTitle(
                    qoText("Bearbeiten", "Edit", language: store.config.language),
                    qoText("Öffnet direkt denselben orangefarbenen Bearbeiten-Orbit wie die Control-Geste.", "Opens the same orange Edit orbit as the Control gesture.", language: store.config.language)
                )
                Button(qoText("Bearbeiten als Aktion verwenden", "Use Edit as action", language: store.config.language)) {
                    var item = current
                    item.type = .edit
                    item.target = "profiles"
                    item.title = qoText("Bearbeiten", "Edit", language: store.config.language)
                    item.symbol = "slider.horizontal.3"
                    item.enabled = true
                    store.setMenuBarItem(item, at: index)
                }
                .quickOrbitGlassButton(prominent: true)
            }

        case .shellCommand:
            BetaTerminalCommandEditor(
                language: store.config.language,
                title: $draftCommandTitle,
                command: $draftShellCommand,
                trusted: $draftShellCommandTrusted,
                currentItemID: current.id,
                onDeleteCurrent: {
                    store.clearMenuBarItem(index)
                    dismiss()
                }
            )

        }
    }

    private func editorTitle(_ title: String, _ subtitle: String) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(title).font(.title3.weight(.semibold))
            Text(subtitle).font(.subheadline).foregroundStyle(.secondary)
        }
    }

    private func prepareDraft(for type: OrbitActionType) {
        if current.type == type {
            if type == .url {
                draftURL = current.target
                draftURLSymbol = current.symbol.isEmpty ? "globe" : current.symbol
            }
        }
    }

    private func applyApp(_ app: InstalledAppChoice) {
        var item = current
        item.type = .app
        item.target = app.url.path
        item.securityScopedBookmark = quickOrbitBookmark(for: app.url)
        item.title = app.name
        item.symbol = "app.fill"
        item.enabled = true
        store.setMenuBarItem(item, at: index)
    }

    private func chooseOtherApp() {
        let panel = NSOpenPanel()
        panel.title = qoText("App für die Menüleiste auswählen", "Choose app for menu bar", language: store.config.language)
        panel.canChooseDirectories = false
        panel.canChooseFiles = true
        panel.allowsMultipleSelection = false
        panel.allowedContentTypes = [.application]
        if panel.runModal() == .OK, let url = panel.url {
            applyApp(InstalledAppChoice(id: url.path, name: url.deletingPathExtension().lastPathComponent, url: url))
        }
    }

    private func chooseFile() {
        let panel = NSOpenPanel()
        panel.title = qoText("Datei oder Ordner für die Menüleiste auswählen", "Choose file or folder for menu bar", language: store.config.language)
        panel.canChooseDirectories = true
        panel.canChooseFiles = true
        panel.allowsMultipleSelection = false
        if panel.runModal() == .OK, let url = panel.url {
            var item = current
            item.type = .file
            item.target = url.path
            item.securityScopedBookmark = quickOrbitBookmark(for: url)
            item.title = url.lastPathComponent
            item.symbol = url.hasDirectoryPath ? "folder.fill" : "doc.fill"
            item.enabled = true
            store.setMenuBarItem(item, at: index)
        }
    }

    private func applyURL() {
        var value = draftURL.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !value.isEmpty else { return }
        if !value.contains("://") { value = "https://" + value }
        var item = current
        item.type = .url
        item.target = value
        item.title = WebsitePreset.popular.first(where: { $0.url == value })?.name
            ?? URL(string: value)?.host?.replacingOccurrences(of: "www.", with: "")
            ?? qoText("Webseite", "Website", language: store.config.language)
        item.symbol = draftURLSymbol
        item.enabled = true
        store.setMenuBarItem(item, at: index)
    }

    private func applyShellCommand() {
        guard draftShellCommandTrusted,
              QuickOrbitBetaCommandPolicy.status(draftShellCommand, language: store.config.language).valid else { return }
        var item = current
        item.type = .shellCommand
        item.target = draftShellCommand.trimmingCharacters(in: .whitespacesAndNewlines)
        item.title = draftCommandTitle.trimmingCharacters(in: .whitespacesAndNewlines)
        item.symbol = "terminal.fill"
        item.securityScopedBookmark = nil
        item.enabled = true
        store.setMenuBarItem(item, at: index)
    }

}

struct BehaviorSettingsView: View {
    @ObservedObject private var store = OrbitStore.shared
    @ObservedObject private var dockStore = QuickOrbitMenuDockStore.shared
    @ObservedObject private var controller = OrbitController.shared
    @ObservedObject private var loginItem = LoginItemManager.shared

    private var pairedColumns: [GridItem] {
        [
            GridItem(.flexible(), spacing: 16, alignment: .topLeading),
            GridItem(.flexible(), spacing: 16, alignment: .topLeading)
        ]
    }

    private func profileReturnTimeLabel(_ seconds: Double) -> String {
        let value = min(max(seconds, 0.3), 600)
        if value < 1 {
            return String(format: "%.1f s", value).replacingOccurrences(of: ".", with: ",")
        }
        if value < 60 {
            if abs(value.rounded() - value) < 0.05 {
                return "\(Int(value.rounded())) s"
            }
            return String(format: "%.1f s", value).replacingOccurrences(of: ".", with: ",")
        }
        let minutes = value / 60
        if abs(minutes.rounded() - minutes) < 0.03 {
            return "\(Int(minutes.rounded())) Min"
        }
        return String(format: "%.1f Min", minutes).replacingOccurrences(of: ".", with: ",")
    }

    private func profileReturnSliderValue(for seconds: Double) -> Double {
        let minimum = 0.3
        let maximum = 600.0
        let clamped = min(max(seconds, minimum), maximum)
        return log(clamped / minimum) / log(maximum / minimum)
    }

    private func profileReturnSeconds(from sliderValue: Double) -> Double {
        let minimum = 0.3
        let maximum = 600.0
        let raw = minimum * pow(maximum / minimum, min(max(sliderValue, 0), 1))
        if raw < 1 { return (raw * 10).rounded() / 10 }
        if raw < 10 { return (raw * 2).rounded() / 2 }
        if raw < 60 { return raw.rounded() }
        if raw < 180 { return (raw / 5).rounded() * 5 }
        return (raw / 15).rounded() * 15
    }

    var body: some View {
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: 20) {
                PageHero(
                    title: qoText("Verhalten", "Behavior", language: store.config.language),
                    subtitle: qoText("Öffnen, Bearbeiten und Feedback getrennt und einfach einstellen.", "Configure opening, editing and feedback separately and clearly.", language: store.config.language),
                    symbol: "switch.2"
                ) {
                    Text(store.config.quickEditModifier.display(language: store.config.language))
                        .font(.system(size: 13, weight: .bold, design: .rounded))
                        .padding(.horizontal, 12)
                        .padding(.vertical, 8)
                        .quickOrbitGlass(cornerRadius: 16)
                }

                LazyVGrid(columns: pairedColumns, alignment: .leading, spacing: 16) {
                GlassCard(title: qoText("Auswahl", "Selection", language: store.config.language), symbol: "cursorarrow.click.2", fillsGridRow: true) {
                    QuickOrbitSelectionChoice(
                        title: qoText("Orbit und Schnellleiste", "Orbit and quick bar", language: store.config.language),
                        language: store.config.language,
                        automatic: Binding(
                            get: { store.config.orbitAutoSelect ?? true },
                            set: {
                                store.config.orbitAutoSelect = $0
                                dockStore.autoOpen = $0
                            }
                        ),
                        showPreview: true
                    )
                    .frame(maxWidth: 420, alignment: .leading)
                    Text(qoText("Ein Modus für beide Bereiche. Die Auswahlzeit bleibt je Orbit-Profil individuell; die Schnellleiste hat ihre eigene Zeit.", "One mode for both areas. Selection time remains individual for each Orbit profile; the quick bar has its own time.", language: store.config.language))
                        .font(.caption).foregroundStyle(.secondary)
                }

                VStack(alignment: .leading, spacing: 16) {
                GlassCard(title: qoText("Strom sparen", "Energy Saver", language: store.config.language), symbol: "leaf.fill") {
                    VStack(alignment: .leading, spacing: 12) {
                        Toggle(isOn: Binding(
                            get: { store.config.energySavingMode ?? false },
                            set: { store.config.energySavingMode = $0 }
                        )) {
                            VStack(alignment: .leading, spacing: 3) {
                                Text(qoText("QuickOrbit-Stromsparmodus", "QuickOrbit Energy Saver", language: store.config.language))
                                    .font(.subheadline.weight(.semibold))
                                Text(qoText("Weniger Bewegung, 30 statt 60 Abfragen pro Sekunde und kein haptisches Feedback.", "Less motion, 30 instead of 60 checks per second, and no haptic feedback.", language: store.config.language))
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                            }
                        }
                        .toggleStyle(.switch)
                        .tint(Color.accentColor)

                        Label(
                            qoText("Belegungen, Profile und Timer funktionieren unverändert.", "Assignments, profiles, and timers continue to work as usual.", language: store.config.language),
                            systemImage: "checkmark.circle.fill"
                        )
                        .font(.caption.weight(.medium))
                        .foregroundStyle(.secondary)
                    }
                }

                GlassCard(title: qoText("Animationen", "Animations", language: store.config.language), symbol: "sparkles") {
                    VStack(alignment: .leading, spacing: 9) {
                        Picker(qoText("Stärke", "Intensity", language: store.config.language), selection: Binding(
                            get: { store.config.orbitAnimationLevel ?? .subtle },
                            set: { store.config.orbitAnimationLevel = $0 }
                        )) {
                            ForEach(OrbitAnimationLevel.allCases) { level in
                                Text(level.title(language: store.config.language)).tag(level)
                            }
                        }
                        .pickerStyle(.segmented)

                        if (store.config.orbitAnimationLevel ?? .subtle) != .none {
                            Toggle(qoText("Kreis beim Öffnen drehen", "Rotate circle on opening", language: store.config.language), isOn: Binding(
                                get: { store.config.circleOpeningRotation ?? true },
                                set: { store.config.circleOpeningRotation = $0 }
                            ))
                            HStack(spacing: 12) {
                                Text(qoText("Dauer", "Duration", language: store.config.language))
                                    .font(.caption.weight(.semibold))
                                Slider(value: Binding(
                                    get: { store.config.orbitAnimationDuration ?? 0.38 },
                                    set: { store.config.orbitAnimationDuration = $0 }
                                ), in: 0.16...1.20, step: 0.02)
                                Text(String(format: "%.2f s", store.config.orbitAnimationDuration ?? 0.38))
                                    .font(.caption.monospacedDigit().weight(.semibold))
                                    .foregroundStyle(.secondary)
                                    .frame(width: 52, alignment: .trailing)
                            }
                        }

                        Text(qoText("„Ein wenig“ ist die empfohlene ruhige Einstellung. Sie belebt Orbit, Startseite und Einstellungen nur minimal.", "“A little” is the recommended calm setting. It adds only minimal motion to Orbit, the home page, and Settings.", language: store.config.language))
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                }
                }
                .frame(maxWidth: .infinity, alignment: .topLeading)
                }

                LazyVGrid(columns: pairedColumns, alignment: .leading, spacing: 16) {
                GlassCard(title: qoText("Profil-Rückkehr", "Profile return", language: store.config.language), symbol: "arrow.uturn.backward.circle.fill", fillsGridRow: true) {
                    VStack(alignment: .leading, spacing: 15) {
                        HStack(spacing: 12) {
                            ZStack {
                                Circle()
                                    .fill(Color.yellow.opacity(0.12))
                                Image(systemName: "star.fill")
                                    .font(.system(size: 16, weight: .bold))
                                    .foregroundStyle(Color.yellow)
                            }
                            .frame(width: 38, height: 38)

                            VStack(alignment: .leading, spacing: 2) {
                                Text(qoText("Aktuelles Hauptprofil", "Current main profile", language: store.config.language))
                                    .font(.subheadline.weight(.semibold))
                                Text(qoText("Das Hauptprofil legst du direkt beim jeweiligen Profil fest.", "Choose the main profile directly on that profile's page.", language: store.config.language))
                                    .font(.caption2)
                                    .foregroundStyle(.secondary)
                            }

                            Spacer()

                            Picker("", selection: Binding<UUID?>(
                                get: { store.mainProfileID },
                                set: { store.setMainProfile($0) }
                            )) {
                                Text(qoText("Keins", "None", language: store.config.language)).tag(UUID?.none)
                                ForEach(store.profiles) { profile in
                                    Text(profile.name).tag(Optional(profile.id))
                                }
                            }
                            .labelsHidden()
                            .frame(width: 190)
                        }

                        if store.mainProfileID != nil {
                            Divider().opacity(0.32)

                            VStack(alignment: .leading, spacing: 12) {
                                Toggle(
                                    qoText("Automatisch zum Hauptprofil zurück", "Automatically return to main profile", language: store.config.language),
                                    isOn: Binding(
                                        get: { (store.config.mainProfileReturnDelay ?? 60) > 0 },
                                        set: { enabled in
                                            store.setMainProfileReturnDelay(enabled ? max(store.config.mainProfileReturnDelay ?? 60, 0.3) : 0)
                                        }
                                    )
                                )
                                .font(.caption.weight(.semibold))

                                if (store.config.mainProfileReturnDelay ?? 60) > 0 {
                                    HStack(spacing: 12) {
                                        VStack(alignment: .leading, spacing: 2) {
                                            Text(qoText("Rückkehr nach", "Return after", language: store.config.language))
                                                .font(.caption.weight(.semibold))
                                            Text(qoText("0,3 Sekunden bis 10 Minuten", "0.3 seconds to 10 minutes", language: store.config.language))
                                                .font(.caption2)
                                                .foregroundStyle(.secondary)
                                        }

                                        Slider(value: Binding(
                                            get: { profileReturnSliderValue(for: store.config.mainProfileReturnDelay ?? 60) },
                                            set: { store.setMainProfileReturnDelay(profileReturnSeconds(from: $0)) }
                                        ), in: 0...1)

                                        Text(profileReturnTimeLabel(store.config.mainProfileReturnDelay ?? 60))
                                            .font(.caption.weight(.semibold))
                                            .monospacedDigit()
                                            .frame(width: 64, alignment: .trailing)
                                    }
                                }
                            }

                            Label(
                                qoText("Der Countdown startet erst, nachdem QuickOrbit geschlossen wurde. Während du Profile auswählst oder Einstellungen bearbeitest, springt nichts zurück; App-verknüpfte Profile behalten Vorrang.", "The countdown starts only after QuickOrbit closes. Nothing switches back while you choose profiles or edit Settings; app-linked profiles keep priority.", language: store.config.language),
                                systemImage: "app.badge.checkmark"
                            )
                            .font(.caption2)
                            .foregroundStyle(.secondary)
                        }
                    }
                }

                GlassCard(title: qoText("Bearbeiten", "Editing", language: store.config.language), symbol: "pencil.and.outline", fillsGridRow: true) {
                    VStack(alignment: .leading, spacing: 16) {
                        Toggle(qoText("Quick Edit aktiv", "Quick Edit enabled", language: store.config.language), isOn: store.binding(\.quickEditEnabled))
                            .font(.headline)

                        if store.config.quickEditEnabled {
                            VStack(spacing: 8) {
                                StepPill(number: 1, title: store.config.quickEditModifier.display(language: store.config.language) + qoText(" halten", " hold", language: store.config.language), symbol: "keyboard")
                                StepPill(number: 2, title: qoText("Zum Feld bewegen", "Move to field", language: store.config.language), symbol: "cursorarrow.motionlines")
                                StepPill(number: 3, title: qoText("Loslassen & ersetzen", "Release & replace", language: store.config.language), symbol: "square.and.pencil")
                            }

                            Divider()

                            LabeledContent(qoText("Taste", "Key", language: store.config.language)) {
                                Picker("", selection: store.binding(\.quickEditModifier)) {
                                    ForEach(QuickEditModifier.allCases) { modifier in
                                        Text(modifier.display(language: store.config.language)).tag(modifier)
                                    }
                                }
                                .labelsHidden()
                                .frame(width: 210)
                            }

                            Text(qoText("Wenn du die Taste nur für einen normalen Tastaturbefehl benutzt und eine andere Taste drückst, bricht Quick Edit automatisch ab.", "If you only use the modifier for a normal keyboard shortcut and press another key, Quick Edit cancels automatically.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }
                    }
                }
                }

                HStack(alignment: .top, spacing: 16) {
                    GlassCard(title: qoText("Öffnen", "Open", language: store.config.language), symbol: "computermouse.fill") {
                        VStack(alignment: .leading, spacing: 14) {
                            Toggle(qoText("Mittelklick", "Middle click", language: store.config.language), isOn: store.binding(\.middleClickEnabled))

                            Text(qoText("Empfohlen: einmal klicken und QuickOrbit ist sofort da.", "Recommended: one click opens QuickOrbit immediately.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)

                            Divider().opacity(0.5)

                            Toggle(qoText("Maus & Trackpad halten", "Hold mouse & trackpad", language: store.config.language), isOn: Binding(
                                get: { (store.config.mouseHoldEnabled ?? false) || (store.config.trackpadHoldEnabled ?? false) },
                                set: {
                                    store.config.mouseHoldEnabled = $0
                                    store.config.trackpadHoldEnabled = $0
                                }
                            ))

                            Text(qoText("macOS meldet diese Haltegeste für Maus und Trackpad gemeinsam. Die Einstellung gilt deshalb derzeit für beide.", "macOS reports this hold gesture for mouse and trackpad together, so the setting currently applies to both.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)

                            if (store.config.mouseHoldEnabled ?? false) || (store.config.trackpadHoldEnabled ?? false) {
                                HStack {
                                    Text(qoText("Haltezeit", "Hold time", language: store.config.language))
                                    Spacer()
                                    Text(String(format: "%.1f s", store.config.mouseHoldDuration ?? 2.0))
                                        .font(.caption.monospacedDigit())
                                        .foregroundStyle(.secondary)
                                }
                                Slider(value: Binding(
                                    get: { store.config.mouseHoldDuration ?? 2.0 },
                                    set: {
                                        store.config.mouseHoldDuration = $0
                                        store.config.trackpadHoldDuration = $0
                                    }
                                ), in: 0.8...5.0, step: 0.1)
                            }

                            DisclosureGroup(qoText("Weitere Möglichkeit", "Another option", language: store.config.language)) {
                                VStack(alignment: .leading, spacing: 10) {
                                    Toggle(qoText("Mit einer Taste öffnen", "Open with one key", language: store.config.language), isOn: Binding(
                                        get: { store.config.controlTapOpenEnabled ?? false },
                                        set: { store.config.controlTapOpenEnabled = $0 }
                                    ))

                                    if store.config.controlTapOpenEnabled ?? false {
                                        LabeledContent(qoText("Aktivierungstaste", "Activation key", language: store.config.language)) {
                                            Picker("", selection: Binding(
                                                get: { store.config.tapOpenModifier ?? .control },
                                                set: { store.config.tapOpenModifier = $0 }
                                            )) {
                                                ForEach(OrbitActivationModifier.allCases) { modifier in
                                                    Text(modifier.display(language: store.config.language)).tag(modifier)
                                                }
                                            }
                                            .labelsHidden()
                                            .frame(width: 170)
                                        }

                                        Text(qoText("Control ist der Standard. Tippe die gewählte Taste kurz an; sobald du sie mit einer anderen Taste kombinierst, öffnet sich QuickOrbit nicht.", "Control is the default. Tap the selected key briefly; combining it with another key won't open QuickOrbit.", language: store.config.language))
                                            .font(.caption2)
                                            .foregroundStyle(.secondary)
                                    }
                                }
                                .padding(.top, 8)
                            }
                            .font(.subheadline.weight(.semibold))
                        }
                    }

                    GlassCard(title: qoText("Feedback & Flick", "Feedback & Flick", language: store.config.language), symbol: "hand.tap.fill") {
                        VStack(alignment: .leading, spacing: 14) {
                            Toggle(qoText("Haptisches Feedback", "Haptic feedback", language: store.config.language), isOn: store.binding(\.haptics))

                            Text(qoText("Gibt bei Auswahl und Auslösen ein kurzes macOS-Feedback.", "Provides a short macOS feedback when selecting and triggering an action.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)

                            Divider().opacity(0.5)

                            Toggle(qoText("Adaptive Flick-Aktivierung", "Adaptive Flick activation", language: store.config.language), isOn: Binding(
                                get: { store.smartFlickEnabled },
                                set: { store.config.smartFlickEnabled = $0 }
                            ))

                            Text(qoText("Bei einer schnellen, klaren Bewegung reagiert QuickOrbit früher. Die normale Auswahlzeit stellst du direkt im jeweiligen Profil ein.", "With a fast, clear movement QuickOrbit can react earlier. Set the normal selection time directly in each profile.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }
                    }
                }

            }
            .padding(28)
            .frame(maxWidth: 1120, alignment: .leading)
        }
        .onAppear {
            loginItem.refresh()
        }
    }

}

struct AppearanceSettingsView: View {
    @ObservedObject private var store = OrbitStore.shared

    var body: some View {
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: 20) {
                PageHero(
                    title: qoText("Ruhig und macOS-typisch", "Clean and macOS-like", language: store.config.language),
                    subtitle: qoText("Mehr Liquid Glass, große Icons, klare Abstände und ruhige Apple-Flächen.", "More Liquid Glass, large icons, clear spacing and calm Apple-style surfaces.", language: store.config.language),
                    symbol: "paintbrush.fill"
                ) { EmptyView() }

                HStack(alignment: .top, spacing: 18) {
                    VStack(spacing: 18) {
                        GlassCard(title: qoText("Anordnung", "Layout", language: store.config.language), symbol: "circle.grid.cross") {
                            VStack(alignment: .leading, spacing: 14) {
                                Picker(qoText("Layout", "Layout", language: store.config.language), selection: store.binding(\.layout)) {
                                    ForEach(OrbitLayout.allCases) { layout in
                                        Label(layout.title(language: store.config.language), systemImage: layout.symbol).tag(layout)
                                    }
                                }
                                .pickerStyle(.segmented)

                                Picker(qoText("Größe", "Size", language: store.config.language), selection: Binding(
                                    get: { store.config.sizePreset },
                                    set: { preset in
                                        withAnimation(.easeInOut(duration: 0.34)) {
                                            store.applySizePreset(preset)
                                        }
                                    }
                                )) {
                                    ForEach(OrbitSizePreset.allCases) { size in
                                        Text(size.title(language: store.config.language)).tag(size)
                                    }
                                }
                                .pickerStyle(.segmented)

                                LabeledContent(qoText("Abstand zur Maus", "Distance from pointer", language: store.config.language)) {
                                    Text("\(Int(store.config.radius)) pt")
                                        .monospacedDigit()
                                        .foregroundStyle(.secondary)
                                }
                                Slider(value: store.binding(\.radius), in: 95...260)

                                LabeledContent(qoText("Feldgröße", "Field size", language: store.config.language)) {
                                    Text("\(Int(store.config.tileScale * 100)) %")
                                        .monospacedDigit()
                                        .foregroundStyle(.secondary)
                                }
                                Slider(value: store.binding(\.tileScale), in: 0.72...1.42)

                                LabeledContent(qoText("Feldabstand", "Field spacing", language: store.config.language)) {
                                    Text("\(Int(store.config.itemSpacing * 100)) %")
                                        .monospacedDigit()
                                        .foregroundStyle(.secondary)
                                }
                                Slider(value: store.binding(\.itemSpacing), in: 0.68...1.45)
                            }
                        }

                        GlassCard(title: qoText("Details", "Details", language: store.config.language), symbol: "switch.2") {
                            VStack(alignment: .leading, spacing: 14) {
                                VStack(alignment: .leading, spacing: 7) {
                                    Text(qoText("Orbit-Einblendung", "Orbit entrance", language: store.config.language))
                                        .font(.caption.weight(.semibold))
                                    Picker("", selection: Binding(
                                        get: { store.config.orbitAnimationLevel ?? .subtle },
                                        set: { store.config.orbitAnimationLevel = $0 }
                                    )) {
                                        ForEach(OrbitAnimationLevel.allCases) { level in
                                            Text(level.title(language: store.config.language)).tag(level)
                                        }
                                    }
                                    .labelsHidden()
                                    .pickerStyle(.segmented)
                                    Text(qoText("„Ein wenig“ bewegt die Kacheln nur minimal. „Komplett“ zeigt die volle Bewegung – ohne farbige Spur.", "“A little” moves tiles only minimally. “Full” shows the complete movement without a colored trace.", language: store.config.language))
                                        .font(.caption2)
                                        .foregroundStyle(.secondary)
                                }

                                Divider().opacity(0.35)

                                Toggle(qoText("Namen anzeigen", "Show names", language: store.config.language), isOn: Binding(get: { store.config.showLabels }, set: { store.setShowLabels($0) }))
                                Toggle(qoText("Mittelpunkt anzeigen", "Show center point", language: store.config.language), isOn: store.binding(\.showCenterDot))
                                Toggle(qoText("Richtungs-Kreis anzeigen", "Show direction circle", language: store.config.language), isOn: Binding(get: { store.config.showGuide }, set: { store.setShowGuide($0) }))
                                Toggle(qoText("Tote Zone anzeigen", "Show dead zone", language: store.config.language), isOn: Binding(
                                    get: { store.config.showDeadZone ?? true },
                                    set: { store.config.showDeadZone = $0 }
                                ))
                                Toggle(qoText("Äußeren Kreis anzeigen", "Show outer circle", language: store.config.language), isOn: Binding(
                                    get: { store.config.showOuterGuide ?? false },
                                    set: { store.setShowOuterGuide($0) }
                                ))
                                Toggle(qoText("Runde Glasflächen im Orbit", "Round glass backgrounds in Orbit", language: store.config.language), isOn: Binding(
                                    get: { store.config.orbitTileGlassEnabled ?? true },
                                    set: { store.config.orbitTileGlassEnabled = $0 }
                                ))
                                Text(qoText("Wenn aktiv, haben Aktionen eine runde Glasfläche. App-Icons bleiben normal frei und bekommen die Glasfläche erst bei der Auswahl – wie in der klassischen QuickOrbit-Ansicht.", "When enabled, actions use a round glass background. App icons stay clean normally and gain the glass circle when selected, like the classic QuickOrbit view.", language: store.config.language))
                                    .font(.caption2)
                                    .foregroundStyle(.secondary)

                                Divider().opacity(0.35)

                                Toggle(qoText("Profilpunkte anzeigen", "Show profile dots", language: store.config.language), isOn: Binding(
                                    get: { store.config.showProfileDots ?? true },
                                    set: { store.setShowProfileDots($0) }
                                ))

                                LabeledContent(qoText("Profilpunkte · 0 = Mitte", "Profile dots · 0 = center", language: store.config.language)) {
                                    Text("\(Int(store.config.profileDotsHorizontalOffset ?? 0)) pt")
                                        .monospacedDigit()
                                        .foregroundStyle(.secondary)
                                }
                                Slider(value: Binding(
                                    get: { store.config.profileDotsHorizontalOffset ?? 0.0 },
                                    set: { store.setProfileDotsHorizontalOffset($0) }
                                ), in: -240...240, step: 2)
                                .disabled(!(store.config.showProfileDots ?? true))

                                LabeledContent(qoText("Tote Zone", "Dead zone", language: store.config.language)) {
                                    Text("\(Int(store.config.deadZone)) pt")
                                        .monospacedDigit()
                                        .foregroundStyle(.secondary)
                                }
                                Slider(value: store.binding(\.deadZone), in: 24...90)
                            }
                        }
                    }
                    .frame(width: 430)

                    GlassCard(title: qoText("Live", "Live", language: store.config.language), symbol: "eye.fill") {
                        OrbitPreview()
                            .frame(height: 470)
                    }
                    .frame(minWidth: 500)
                }
            }
            .padding(28)
            .frame(maxWidth: 1120, alignment: .leading)
        }
    }
}

struct QuickOrbitOnboardingView: View {
    private enum InputChoice: String, CaseIterable, Identifiable {
        case button, pointer, all
        var id: String { rawValue }
    }

    @ObservedObject private var store = OrbitStore.shared
    @ObservedObject private var dockStore = QuickOrbitMenuDockStore.shared
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var step = 0
    @State private var advancing = true
    @State private var lastStepChange = Date.distantPast
    @State private var welcomeRevealed = false
    @State private var welcomeTextRevealed = false
    @State private var welcomeButtonRevealed = false
    @State private var acceptedTerms = false
    @State private var onboardingName = ""
    @State private var inputChoice: InputChoice = .button
    @FocusState private var nameFieldFocused: Bool
    @Namespace private var onboardingGlassNamespace

    private var language: AppLanguage? { store.config.language }
    private var motionEnabled: Bool { !reduceMotion && !(store.config.energySavingMode ?? false) && (store.config.orbitAnimationLevel ?? .subtle) != .none }
    private var commonSelectionBinding: Binding<Bool> {
        Binding(
            get: { store.config.orbitAutoSelect ?? true },
            set: {
                store.config.orbitAutoSelect = $0
                dockStore.autoOpen = $0
            }
        )
    }

    private var onboardingStepTitle: String {
        switch step {
        case 0: return qoText("Willkommen", "Welcome", language: language)
        case 1: return qoText("Sprache", "Language", language: language)
        case 2: return qoText("Persönlich", "Personal", language: language)
        case 3: return qoText("Darstellung", "Appearance", language: language)
        case 4: return qoText("Bedienung", "Controls", language: language)
        case 5: return qoText("Kurzanleitung", "Quick guide", language: language)
        default: return qoText("Abschluss", "Finish", language: language)
        }
    }

    private var onboardingStepSymbol: String {
        switch step {
        case 1: return "globe.europe.africa.fill"
        case 2: return "person.crop.circle.fill"
        case 3: return "circle.lefthalf.filled"
        case 4: return "computermouse.fill"
        case 5: return "arrow.up.right.circle.fill"
        default: return "checkmark.shield.fill"
        }
    }

    var body: some View {
        ZStack {
            SystemBackdrop()

            Circle()
                .fill(RadialGradient(colors: [Color.accentColor.opacity(0.10), .clear], center: .center, startRadius: 0, endRadius: 215))
                .frame(width: 430, height: 430)
                .offset(x: 350, y: -270)
                .allowsHitTesting(false)

            QuickOrbitGlassGroup(spacing: 18) {
                VStack(spacing: 22) {
                    onboardingProgress.opacity(step > 0 ? 1 : 0).accessibilityHidden(step == 0)

                    Group {
                        switch step {
                        case 0: welcomeStep
                        case 1: languageStep
                        case 2: nameStep
                        case 3: appearanceStep
                        case 4: mouseStep
                        case 5: trackpadStep
                        default: legalStep
                        }
                    }
                    .id(step)
                    .transition(motionEnabled ? .asymmetric(
                        insertion: .opacity.combined(with: .offset(x: advancing ? 18 : -18)),
                        removal: .opacity.combined(with: .offset(x: advancing ? -8 : 8))
                    ) : .identity)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                }
                .padding(24)
            }
        }
        .frame(width: 900, height: 700)
    }

    private func goToStep(_ newStep: Int) {
        guard (0...6).contains(newStep), newStep != step, Date().timeIntervalSince(lastStepChange) > 0.22 else { return }
        lastStepChange = Date()
        advancing = newStep > step
        nameFieldFocused = false
        if !motionEnabled {
            step = newStep
        } else {
            withAnimation(.easeInOut(duration: 0.22)) {
                step = newStep
            }
        }
    }

    private var onboardingProgress: some View {
        HStack(spacing: 12) {
            QuickOrbitLogoView(size: 34, cornerRadius: 9)
                .frame(width: 42, height: 42)

            VStack(alignment: .leading, spacing: 2) {
                Text(onboardingStepTitle)
                    .font(.subheadline.weight(.bold))
                Text(qoText("Schritt \(step + 1) von 7", "Step \(step + 1) of 7", language: language))
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }

            Spacer()

            HStack(spacing: 7) {
                ForEach(0..<7, id: \.self) { index in
                    Capsule()
                        .fill(index < step
                              ? Color.accentColor.opacity(0.38)
                              : (index == step ? Color.accentColor : Color.primary.opacity(0.09)))
                        .frame(width: index == step ? 32 : 10, height: 6)
                }
            }

            Image(systemName: onboardingStepSymbol)
                .font(.system(size: 15, weight: .semibold))
                .foregroundStyle(Color.accentColor)
                .frame(width: 34, height: 34)
                .background(Color.accentColor.opacity(0.10), in: Circle())
        }
        .padding(.horizontal, 12)
        .padding(.vertical, 9)
        .quickOrbitTutorialGlass(cornerRadius: 17)
    }

    private var welcomeStep: some View {
        VStack(spacing: 0) {
            Spacer(minLength: 18)

            ZStack {
                Circle()
                    .fill(RadialGradient(colors: [Color.accentColor.opacity(0.16), .clear], center: .center, startRadius: 10, endRadius: 135))
                    .frame(width: 270, height: 270)
                Circle()
                    .stroke(Color.accentColor.opacity(0.24), lineWidth: 1)
                    .frame(width: 230, height: 230)
                Circle()
                    .stroke(Color.primary.opacity(0.12), style: StrokeStyle(lineWidth: 1, dash: [3, 8]))
                    .frame(width: 190, height: 190)
                ForEach(0..<4) { index in
                    Circle()
                        .fill(index == 0 ? Color.accentColor : Color.accentColor.opacity(0.48))
                        .frame(width: index == 0 ? 13 : 10, height: index == 0 ? 13 : 10)
                        .offset(x: index == 1 ? 0 : (index == 2 ? -115 : (index == 3 ? 115 : 0)),
                                y: index == 0 ? -115 : (index == 1 ? 115 : 0))
                }
                QuickOrbitLogoView(size: 112, cornerRadius: 27, animated: false)
                    .padding(13)
                    .quickOrbitTutorialGlass(cornerRadius: 38)
                    .offset(y: welcomeRevealed ? 0 : 7)
            }
            .frame(width: 270, height: 270)
            .opacity(welcomeRevealed ? 1 : 0)
            .onAppear {
                guard !welcomeRevealed else { return }
                guard motionEnabled else {
                    welcomeRevealed = true
                    welcomeTextRevealed = true
                    welcomeButtonRevealed = true
                    return
                }
                Task { @MainActor in
                    withAnimation(.easeOut(duration: 0.36)) { welcomeRevealed = true }
                    try? await Task.sleep(nanoseconds: 110_000_000)
                    withAnimation(.easeOut(duration: 0.32)) { welcomeTextRevealed = true }
                    try? await Task.sleep(nanoseconds: 100_000_000)
                    withAnimation(.easeOut(duration: 0.28)) { welcomeButtonRevealed = true }
                }
            }
            .accessibilityHidden(true)

            VStack(spacing: 7) {
                Text("WILLKOMMEN · WELCOME")
                    .font(.system(size: 11, weight: .bold, design: .rounded))
                    .tracking(2.3)
                    .foregroundStyle(Color.accentColor)
                Text("QuickOrbit")
                    .font(.system(size: 49, weight: .bold, design: .rounded))
                Text("Fast. Simple. Native.")
                    .font(.system(size: 18, weight: .medium, design: .rounded))
                    .tracking(0.8)
                    .foregroundStyle(.secondary)
            }
            .opacity(welcomeTextRevealed ? 1 : 0)
            .offset(y: welcomeTextRevealed ? 0 : 5)

            Spacer(minLength: 28)

            Button { goToStep(1) } label: {
                HStack(spacing: 12) {
                    Text("Start").font(.headline)
                    Image(systemName: "arrow.right").font(.headline)
                }
                .frame(width: 220, height: 44)
                .contentShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
            }
            .quickOrbitColorButton(.blue)
            .keyboardShortcut(.defaultAction)
            .opacity(welcomeButtonRevealed ? 1 : 0)
            .disabled(!welcomeButtonRevealed)

            Text("macOS  ·  \(quickOrbitVersionLabel)")
                .font(.caption2.weight(.medium))
                .foregroundStyle(.tertiary)
                .padding(.top, 13)
                .opacity(welcomeButtonRevealed ? 1 : 0)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .padding(34)
        .quickOrbitTutorialGlass(cornerRadius: 30)
    }

