    private var nameStep: some View {
        VStack(spacing: 26) {
            HStack(spacing: 22) {
                ZStack {
                    Circle()
                        .fill(Color.accentColor.opacity(0.12))
                    Text(String(onboardingName.trimmingCharacters(in: .whitespacesAndNewlines).prefix(1)).uppercased().isEmpty ? "👋" : String(onboardingName.trimmingCharacters(in: .whitespacesAndNewlines).prefix(1)).uppercased())
                        .font(.system(size: 34, weight: .bold, design: .rounded))
                        .foregroundStyle(Color.accentColor)
                }
                .frame(width: 82, height: 82)
                .quickOrbitTutorialGlass(cornerRadius: 41)

                VStack(alignment: .leading, spacing: 7) {
                    Text(qoText("Wie möchtest du begrüßt werden?", "How would you like to be greeted?", language: language))
                        .font(.system(size: 29, weight: .bold, design: .rounded))
                    Text(qoText("Optional. Der Name wird nur auf diesem Mac gespeichert.", "Optional. The name is stored only on this Mac.", language: language))
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }

            VStack(alignment: .leading, spacing: 9) {
                Text(qoText("Name (optional)", "Name (optional)", language: language))
                    .font(.caption2.weight(.bold))
                    .foregroundStyle(.secondary)

                HStack(spacing: 10) {
                    Image(systemName: "person.fill")
                        .foregroundStyle(Color.accentColor)
                    TextField(qoText("Wie darf QuickOrbit dich begrüßen?", "How should QuickOrbit greet you?", language: language), text: $onboardingName)
                        .textFieldStyle(.plain)
                        .font(.title3.weight(.semibold))
                        .focused($nameFieldFocused)
                        .onSubmit { saveOnboardingNameAndContinue() }
                    Text("\(onboardingName.count)/24")
                        .font(.caption2.monospacedDigit())
                        .foregroundStyle(.tertiary)
                }
                .padding(.horizontal, 16)
                .frame(height: 52)
                .quickOrbitTutorialGlass(cornerRadius: 16)
                .onChange(of: onboardingName) { _, newValue in
                    if newValue.count > 24 { onboardingName = String(newValue.prefix(24)) }
                }
            }
            .frame(maxWidth: 500)

            VStack(alignment: .leading, spacing: 7) {
                Text(qoText("Vorschau", "Preview", language: language))
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(.secondary)
                Text(onboardingName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                     ? qoText("Guten Tag 👋", "Hello 👋", language: language)
                     : qoText("Guten Tag, \(onboardingName.trimmingCharacters(in: .whitespacesAndNewlines)) 👋", "Hello, \(onboardingName.trimmingCharacters(in: .whitespacesAndNewlines)) 👋", language: language))
                    .font(.system(size: 27, weight: .bold, design: .rounded))
            }
            .padding(18)
            .frame(maxWidth: 500, alignment: .leading)
            .quickOrbitTutorialGlass(cornerRadius: 18)

            Spacer()

            HStack(spacing: 12) {
                Button(qoText("Zurück", "Back", language: language)) { goToStep(1) }
                    .quickOrbitGlassButton()
                Button {
                    saveOnboardingNameAndContinue()
                } label: {
                    Label(qoText("Weiter", "Continue", language: language), systemImage: "arrow.right")
                        .frame(minWidth: 170)
                }
                .quickOrbitColorButton(.blue)
                .keyboardShortcut(.defaultAction)
            }
        }
        .padding(34)
        .quickOrbitTutorialGlass(cornerRadius: 30)
        .onAppear {
            if onboardingName.isEmpty { onboardingName = store.config.userDisplayName ?? "" }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.25) { nameFieldFocused = true }
        }
    }

    private func saveOnboardingNameAndContinue() {
        store.config.userDisplayName = onboardingName.trimmingCharacters(in: .whitespacesAndNewlines)
        nameFieldFocused = false
        goToStep(3)
    }

