    private func inputTitle(_ choice: InputChoice) -> String {
        switch choice {
        case .button: return qoText("Mittelklick + Control", "Middle click + Control", language: language)
        case .pointer: return qoText("Mittelklick & Trackpad", "Middle click & trackpad", language: language)
        case .all: return qoText("Alles verwenden", "Use everything", language: language)
        }
    }

    private func inputSubtitle(_ choice: InputChoice) -> String {
        switch choice {
        case .button: return qoText("Sofort per Mittelklick oder kurzem Control-Tipp", "Instantly with middle click or a quick Control tap", language: language)
        case .pointer: return qoText("Mittelklick oder linke Haltegeste für Maus & Trackpad", "Middle click or primary hold for mouse & trackpad", language: language)
        case .all: return qoText("Alle Auslöser gemeinsam", "All triggers together", language: language)
        }
    }

    private func inputSymbol(_ choice: InputChoice) -> String {
        switch choice {
        case .button: return "computermouse.fill"
        case .pointer: return "rectangle.and.hand.point.up.left.fill"
        case .all: return "switch.2"
        }
    }

    private func applyInputChoice() {
        switch inputChoice {
        case .button:
            store.config.middleClickEnabled = true
            store.config.mouseHoldEnabled = false
            store.config.trackpadHoldEnabled = false
            store.config.controlTapOpenEnabled = true
            store.config.tapOpenModifier = .control
        case .pointer:
            store.config.middleClickEnabled = true
            store.config.mouseHoldEnabled = true
            store.config.trackpadHoldEnabled = true
            store.config.controlTapOpenEnabled = false
        case .all:
            store.config.middleClickEnabled = true
            store.config.mouseHoldEnabled = true
            store.config.trackpadHoldEnabled = true
            store.config.controlTapOpenEnabled = true
        }
    }

    @ViewBuilder
    private var selectedInputInstructions: some View {
        switch inputChoice {
        case .button:
            onboardingInstruction(number: "1", symbol: "computermouse.fill", title: qoText("Mittelklick oder Control", "Middle click or Control", language: language), text: qoText("Drücke die mittlere Maustaste oder tippe Control kurz an.", "Press the middle mouse button or tap Control briefly.", language: language))
            commonSelectionInstructions
        case .pointer:
            onboardingInstruction(number: "1", symbol: "hand.tap.fill", title: qoText("Mittelklick oder halten", "Middle click or hold", language: language), text: qoText("Mittelklick öffnet sofort. Maus oder Trackpad ruhig gedrückt halten öffnet nach der Haltezeit.", "Middle click opens instantly. Holding the mouse or trackpad opens after the hold time.", language: language))
            commonSelectionInstructions
        case .all:
            onboardingInstruction(number: "1", symbol: "switch.2", title: qoText("Alle Auslöser sind aktiv", "All triggers are enabled", language: language), text: qoText("Mittelklick, Maus-Halten, Trackpad-Halten und kurzer Control-Druck stehen gemeinsam bereit.", "Middle click, mouse hold, trackpad hold, and a short Control press are all available.", language: language))
            commonSelectionInstructions
        }
    }

    @ViewBuilder
    private var commonSelectionInstructions: some View {
        onboardingInstruction(number: "2", symbol: store.config.orbitAutoSelect == false ? "cursorarrow.click.2" : "arrow.up.right", title: store.config.orbitAutoSelect == false ? qoText("Feld anklicken", "Click a field", language: language) : qoText("Zum Feld bewegen", "Move toward a field", language: language), text: store.config.orbitAutoSelect == false ? qoText("Klicke die gewünschte Aktion an. Es gibt keinen Auswahlkreis.", "Click the action you want. There is no selection ring.", language: language) : qoText("Bewege den Zeiger zur Aktion und warte auf den Auswahlkreis.", "Move the pointer to an action and wait for the selection ring.", language: language))
        onboardingInstruction(number: "3", symbol: "xmark.circle.fill", title: qoText("Abbrechen", "Cancel", language: language), text: qoText("Gehe zurück in die Mitte, wenn du nichts ausführen möchtest.", "Return to the center if you do not want to run anything.", language: language))
    }

    private var onboardingVisual: some View {
        ZStack {
            RoundedRectangle(cornerRadius: 24, style: .continuous)
                .fill(Color.primary.opacity(0.018))

            VStack(spacing: 13) {
                HStack(spacing: 20) {
                    Circle().fill(Color.accentColor.opacity(0.18)).frame(width: 54, height: 54)
