    private func onboardingInstruction(number: String, symbol: String, title: String, text: String) -> some View {
        HStack(alignment: .top, spacing: 12) {
            ZStack {
                Circle().fill(Color.accentColor.opacity(0.10)).frame(width: 38, height: 38)
                    .quickOrbitTutorialGlass(cornerRadius: 19)
                Text(number).font(.headline).foregroundStyle(Color.accentColor)
            }
            VStack(alignment: .leading, spacing: 4) {
                HStack(spacing: 7) {
                    Image(systemName: symbol).font(.system(size: 14, weight: .semibold))
                    Text(title).font(.headline)
                }
                Text(text).font(.subheadline).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true)
            }
            Spacer(minLength: 0)
        }
        .padding(13)
