    private var legalStep: some View {
        VStack(alignment: .leading, spacing: 16) {
            HStack(spacing: 14) {
                Image(systemName: "checkmark.shield.fill")
                    .font(.system(size: 28, weight: .semibold))
                    .frame(width: 58, height: 58)
                    .quickOrbitTutorialGlass(cornerRadius: 18)
                VStack(alignment: .leading, spacing: 4) {
                    Text(qoText("Rechtliches", "Legal", language: language)).font(.title2.bold())
                    Text(qoText("Bitte kurz lesen und bestätigen.", "Please read and confirm.", language: language)).foregroundStyle(.secondary)
                }
            }

            ScrollView(.vertical, showsIndicators: false) {
                LegalTermsText(language: language)
                    .padding(16)
            }
            .frame(maxHeight: 265)
            .quickOrbitTutorialGlass(cornerRadius: 16)

            Toggle(isOn: $acceptedTerms) {
                Text(qoText("Ich habe die Nutzungsbedingungen gelesen und akzeptiere sie.", "I have read and accept the Terms of Use.", language: language))
                    .font(.subheadline.weight(.semibold))
            }

            HStack {
                Button(qoText("Zurück", "Back", language: language)) { goToStep(5) }
                    .quickOrbitGlassButton()
                Spacer()
                Button(qoText("Akzeptieren & QuickOrbit öffnen", "Accept & open QuickOrbit", language: language)) {
                    var value = store.config
                    value.acceptedTermsVersion = "2026-08-v8"
                    value.onboardingCompleted = true
                    store.config = value
                }
                .quickOrbitColorButton(acceptedTerms ? .green : .neutral)
                .overlay(alignment: .trailing) {
                    if acceptedTerms {
                        Image(systemName: "checkmark.circle.fill")
                            .font(.system(size: 13, weight: .bold))
                            .foregroundStyle(Color.green)
                            .padding(.trailing, 9)
                            .transition(.scale.combined(with: .opacity))
                    }
                }
                .scaleEffect(acceptedTerms ? 1.015 : 1)
                .animation(.easeOut(duration: 0.14), value: acceptedTerms)
                .disabled(!acceptedTerms)
                .keyboardShortcut(.defaultAction)
            }
        }
        .padding(28)
        .quickOrbitTutorialGlass(cornerRadius: 26)
    }

}

