}

struct InfoView: View {
    @ObservedObject private var store = OrbitStore.shared
    @ObservedObject private var loginItem = LoginItemManager.shared
    @ObservedObject private var controller = OrbitController.shared
    @ObservedObject private var navigation = AppNavigation.shared

    @State private var accessibilityTrusted = AXIsProcessTrusted()
    @State private var screenCaptureTrusted = CGPreflightScreenCaptureAccess()
    @State private var showLegalTerms = false
    @State private var showResetConfirmation = false
    @State private var highlightSystemAccess = false

    private let discordURL = URL(string: "https://discord.gg/eJaBXCn77N")!

    private var settingsColumns: [GridItem] {
        [
            GridItem(.flexible(), spacing: 16),
            GridItem(.flexible(), spacing: 16)
        ]
    }

    private var appearanceColumns: [GridItem] {
        Array(repeating: GridItem(.flexible(), spacing: 16, alignment: .topLeading), count: 3)
    }

    var body: some View {
        ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: false) {
                VStack(alignment: .leading, spacing: QuickOrbitUI.sectionSpacing) {
                PageHero(
                    title: qoText("Info", "About", language: store.config.language),
                    subtitle: qoText("QuickOrbit, System und Support an einem Ort.", "QuickOrbit, system settings and support in one place.", language: store.config.language),
                    symbol: "info.circle.fill"
                ) {
                    Text(quickOrbitVersionLabel)
                        .font(.caption.weight(.bold))
                        .padding(.horizontal, 11)
                        .padding(.vertical, 6)
                        .quickOrbitGlass(cornerRadius: 14)
                }

                aboutHero

                QuickOrbitUpdateCard()

                AboutSectionLabel(title: qoText("SPRACHE & DARSTELLUNG", "LANGUAGE & APPEARANCE", language: store.config.language))

                LazyVGrid(columns: appearanceColumns, alignment: .leading, spacing: 16) {
                    GlassCard(title: qoText("Sprache", "Language", language: store.config.language), symbol: "globe", fillsGridRow: true) {
                        VStack(alignment: .leading, spacing: 12) {
                            Text(qoText("Die Oberfläche wechselt sofort.", "The interface switches immediately.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)

                            Picker(qoText("Sprache", "Language", language: store.config.language), selection: Binding(
                                get: { store.config.language ?? .german },
                                set: { store.setLanguage($0) }
                            )) {
                                ForEach(AppLanguage.allCases) { language in
                                    Text(language.symbol + "  " + language.displayName).tag(language)
                                }
                            }
                            .pickerStyle(.segmented)
                            .labelsHidden()

                        }
                    }

                    GlassCard(title: qoText("Darstellung", "Appearance", language: store.config.language), symbol: "circle.lefthalf.filled", fillsGridRow: true) {
                        VStack(alignment: .leading, spacing: 12) {
                            Text(qoText("System folgt automatisch dem macOS-Design.", "System follows the macOS appearance automatically.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)

                            Picker(qoText("Darstellung", "Appearance", language: store.config.language), selection: Binding(
                                get: { store.config.appearance ?? .system },
                                set: { store.config.appearance = $0 }
                            )) {
                                ForEach(QuickOrbitAppearance.allCases) { choice in
                                    Label(choice.title(language: store.config.language), systemImage: choice.symbol).tag(choice)
                                }
                            }
                            .pickerStyle(.segmented)
                            .labelsHidden()
                        }
                    }

                    GlassCard(title: qoText("Flächenstil", "Surface style", language: store.config.language), symbol: "rectangle.3.group.fill", fillsGridRow: true) {
                        VStack(alignment: .leading, spacing: 12) {
                            Text(qoText("Gilt einheitlich in der ganzen App.", "Used consistently throughout the app.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)

                            Picker(qoText("Flächenstil", "Surface style", language: store.config.language), selection: Binding(
                                get: { store.config.designStyle ?? .settings },
                                set: { store.config.designStyle = $0 }
                            )) {
                                ForEach(QuickOrbitDesignStyle.allCases) { style in
                                    Text(style.title(language: store.config.language)).tag(style)
                                }
                            }
                            .pickerStyle(.segmented)
                            .labelsHidden()
                        }
                    }
                }

                AboutSectionLabel(title: qoText("SYSTEMZUGRIFF & START", "SYSTEM ACCESS & STARTUP", language: store.config.language))

                GlassCard(title: qoText("Systemzugriff", "System access", language: store.config.language), symbol: "lock.shield.fill") {
                    VStack(spacing: 14) {
                        HStack(spacing: 14) {
                        ZStack {
                            RoundedRectangle(cornerRadius: 13, style: .continuous)
                                .fill((accessibilityTrusted ? Color.green : Color.orange).opacity(0.12))
                                .frame(width: 48, height: 48)

                            Image(systemName: accessibilityTrusted ? "checkmark.shield.fill" : "exclamationmark.triangle.fill")
                                .font(.system(size: 22, weight: .semibold))
                                .foregroundStyle(accessibilityTrusted ? Color.green : Color.orange)
                        }
                        .quickOrbitGlass(cornerRadius: 13)

                        VStack(alignment: .leading, spacing: 3) {
                            Text(accessibilityTrusted
                                 ? qoText("Bereit", "Ready", language: store.config.language)
                                 : qoText("Bedienungshilfe noch erlauben", "Allow Accessibility access", language: store.config.language))
                                .font(.headline)

                            Text(qoText("Die orange Hand markiert Funktionen, denen die macOS-Bedienungshilfe noch fehlt. Hier kannst du den Zugriff erlauben und anschließend neu prüfen.", "The orange hand marks functions that still need macOS Accessibility access. You can allow access here and then check again.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }

                        Spacer(minLength: 16)

                        if !accessibilityTrusted {
                            Button(qoText("Erlauben", "Allow", language: store.config.language)) {
                                controller.requestAccessibility()
                            }
                            .quickOrbitColorButton(.green)
                        }

                        Button(qoText("Systemeinstellungen", "System Settings", language: store.config.language)) {
                            controller.openAccessibilitySettings()
                        }
                        .quickOrbitSolidButton()

                        Button {
                            accessibilityTrusted = AXIsProcessTrusted()
                            controller.reconnect()
                        } label: {
                            Image(systemName: "arrow.clockwise")
                        }
                        .quickOrbitSolidButton()
                        .help(qoText("Status neu prüfen", "Check status again", language: store.config.language))
                        }

                        Divider().opacity(0.55)

                        HStack(spacing: 14) {
                            ZStack {
                                RoundedRectangle(cornerRadius: 13, style: .continuous)
                                    .fill((screenCaptureTrusted ? Color.green : Color.orange).opacity(0.12))
                                    .frame(width: 48, height: 48)

                                Image(systemName: screenCaptureTrusted ? "checkmark.rectangle.fill" : "display.trianglebadge.exclamationmark")
                                    .font(.system(size: 21, weight: .semibold))
                                    .foregroundStyle(screenCaptureTrusted ? Color.green : Color.orange)
                            }
                            .quickOrbitGlass(cornerRadius: 13)

                            VStack(alignment: .leading, spacing: 3) {
                                Text(screenCaptureTrusted
                                     ? qoText("Bildschirmaufnahme bereit", "Screen Recording ready", language: store.config.language)
                                     : qoText("Für OCR einmal erlauben", "Allow once for OCR", language: store.config.language))
                                    .font(.headline)
                                Text(qoText("Nur der von dir gewählte Bereich wird lokal erkannt und anschließend gelöscht.", "Only the area you select is recognized locally and then deleted.", language: store.config.language))
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                            }

                            Spacer(minLength: 16)

                            if !screenCaptureTrusted {
                                Button(qoText("Erlauben", "Allow", language: store.config.language)) {
                                    screenCaptureTrusted = CGRequestScreenCaptureAccess() || CGPreflightScreenCaptureAccess()
                                }
                                .quickOrbitColorButton(.green)
                            }

                            Button(qoText("Systemeinstellungen", "System Settings", language: store.config.language)) {
                                if let url = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture") {
                                    NSWorkspace.shared.open(url)
                                }
                            }
                            .quickOrbitSolidButton()

                            Button {
                                screenCaptureTrusted = CGPreflightScreenCaptureAccess()
                            } label: {
                                Image(systemName: "arrow.clockwise")
                            }
                            .quickOrbitSolidButton()
                            .help(qoText("Status neu prüfen", "Check status again", language: store.config.language))
                        }
                    }
                }
                .id("system-access")
                .overlay {
                    if highlightSystemAccess {
                        RoundedRectangle(cornerRadius: QuickOrbitUI.cardRadius, style: .continuous)
                            .stroke(Color.orange.opacity(0.72), lineWidth: 2)
                            .shadow(color: Color.orange.opacity(0.18), radius: 10)
                            .allowsHitTesting(false)
                    }
                }
                .animation(.easeOut(duration: 0.20), value: highlightSystemAccess)

                GlassCard(title: qoText("Automatisch starten", "Launch automatically", language: store.config.language), symbol: "power") {
                    HStack(spacing: 14) {
                        VStack(alignment: .leading, spacing: 3) {
                            Text(qoText("QuickOrbit beim Anmelden öffnen", "Open QuickOrbit at login", language: store.config.language))
                                .font(.headline)
                            Text(loginItem.statusText(language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)
                            if let error = loginItem.lastError {
                                Label(error, systemImage: "exclamationmark.triangle.fill")
                                    .font(.caption2)
                                    .foregroundStyle(Color.red)
                                    .lineLimit(2)
                            }
                        }

                        Spacer()

                        Text(loginItem.isRequested ? qoText("Aktiv", "On", language: store.config.language) : qoText("Aus", "Off", language: store.config.language))
                            .font(.caption.weight(.semibold))
                            .foregroundStyle(.secondary)

                        Toggle("", isOn: Binding(
                            get: { loginItem.isRequested },
                            set: { loginItem.setEnabled($0) }
                        ))
                        .labelsHidden()
                    }
                }

                AboutSectionLabel(title: qoText("HILFE & RECHT", "HELP & LEGAL", language: store.config.language))

                LazyVGrid(columns: settingsColumns, alignment: .leading, spacing: 16) {
                    GlassCard(title: qoText("Probleme & Feedback", "Problems & feedback", language: store.config.language), symbol: "bubble.left.and.bubble.right.fill") {
                        VStack(alignment: .leading, spacing: 14) {
                            Text(qoText("Ideen, Fragen oder einen Bug gefunden?", "Ideas, questions or found a bug?", language: store.config.language))
                                .font(.headline)

                            Text(qoText("Du kannst Nico über die eingetragene Website oder Discord erreichen.", "You can reach Nico through the configured website or Discord.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)

                            HStack(spacing: 10) {
                                if let websiteURL = quickOrbitWebsiteURL {
                                    Link(destination: websiteURL) {
                                        Label(qoText("Website", "Website", language: store.config.language), systemImage: "globe")
                                    }
                                    .quickOrbitColorButton(.blue)
                                } else {
                                    Button { } label: {
                                        Label(qoText("Website folgt", "Website coming soon", language: store.config.language), systemImage: "globe")
                                    }
                                    .quickOrbitColorButton(.neutral)
                                    .disabled(true)
                                }

                                Link(destination: discordURL) {
                                    Label("Discord", systemImage: "bubble.left.and.bubble.right.fill")
                                }
                                .quickOrbitDiscordButton()
                            }
                        }
                    }

                    GlassCard(title: qoText("Copyright & Bedingungen", "Copyright & terms", language: store.config.language), symbol: "checkmark.shield.fill") {
                        VStack(alignment: .leading, spacing: 14) {
                            Text("© 2026 Nico")
                                .font(.headline)

                            Text(qoText("Idee, Konzept, Design und Umsetzung bleiben bei Nico.", "Idea, concept, design and implementation remain with Nico.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)

                            Button(qoText("Bedingungen ansehen", "View terms", language: store.config.language)) {
                                showLegalTerms = true
                            }
                            .quickOrbitColorButton(.black)
                        }
                    }
                }

                AboutSectionLabel(title: qoText("DATEN & ZURÜCKSETZEN", "DATA & RESET", language: store.config.language))

                QuickOrbitDiagnosticsView()

                GlassCard(title: qoText("QuickOrbit zurücksetzen", "Reset QuickOrbit", language: store.config.language), symbol: "arrow.counterclockwise") {
                    HStack(spacing: 16) {
                        VStack(alignment: .leading, spacing: 4) {
                            Text(qoText("QuickOrbit vollständig auf den Auslieferungszustand setzen.", "Return QuickOrbit completely to its factory state.", language: store.config.language))
                                .font(.headline)

                            Text(qoText("Profile, Einstellungen, Statistiken, Timer und Stopuhren werden gelöscht.", "Profiles, settings, statistics, timers, and stopwatches will be cleared.", language: store.config.language))
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }

                        Spacer()

                        Button(qoText("Alles zurücksetzen", "Reset everything", language: store.config.language), role: .destructive) {
                            showResetConfirmation = true
                        }
                        .buttonStyle(.plain)
                        .font(.system(size: 12.5, weight: .bold))
                        .foregroundStyle(.white)
                        .padding(.horizontal, 14)
                        .frame(height: 32)
                        .background(Color.red.opacity(0.92), in: RoundedRectangle(cornerRadius: 10, style: .continuous))
                        .overlay { RoundedRectangle(cornerRadius: 10, style: .continuous).stroke(Color.white.opacity(0.15), lineWidth: 0.6) }
                    }
                }
                }
                .padding(QuickOrbitUI.pagePadding)
                .frame(maxWidth: 1060, alignment: .leading)
            }
            .onAppear {
                scrollToRequestedInfoAnchor(with: proxy)
            }
            .onChange(of: navigation.requestedInfoAnchor) { _, _ in
                scrollToRequestedInfoAnchor(with: proxy)
            }
        }
        .sheet(isPresented: $showLegalTerms) {
            VStack(alignment: .leading, spacing: 16) {
                HStack {
                    Text(qoText("Copyright & Nutzungsbedingungen (AGB)", "Copyright & Terms", language: store.config.language))
                        .font(.title2.bold())
                    Spacer()
                    Button(qoText("Fertig", "Done", language: store.config.language)) {
                        showLegalTerms = false
                    }
                    .keyboardShortcut(.defaultAction)
                }

                ScrollView(.vertical, showsIndicators: false) {
                    LegalTermsText(language: store.config.language)
                        .padding(18)
                }
                .quickOrbitGlass(cornerRadius: 18)
            }
            .padding(24)
            .frame(width: 720, height: 560)
        }
        .confirmationDialog(
            qoText("QuickOrbit wirklich komplett zurücksetzen?", "Really reset QuickOrbit completely?", language: store.config.language),
            isPresented: $showResetConfirmation,
            titleVisibility: .visible
        ) {
            Button(qoText("Alles endgültig zurücksetzen", "Reset everything", language: store.config.language), role: .destructive) {
                store.reset()
            }
            Button(qoText("Abbrechen", "Cancel", language: store.config.language), role: .cancel) { }
        } message: {
            Text(qoText("Profile, Einstellungen, Statistiken, Timer und Stopuhren, Sprache, bestätigte Bedingungen und das Tutorial werden gelöscht. Danach startet QuickOrbit wie beim ersten Öffnen.", "Profiles, settings, statistics, timers and stopwatches, language, accepted terms and the tutorial will be cleared. QuickOrbit will then start like the first launch.", language: store.config.language))
        }
        .onAppear {
            accessibilityTrusted = AXIsProcessTrusted()
            screenCaptureTrusted = CGPreflightScreenCaptureAccess()
            loginItem.refresh()
        }
        .onReceive(NSWorkspace.shared.notificationCenter.publisher(for: NSWorkspace.didActivateApplicationNotification)) { _ in
            accessibilityTrusted = AXIsProcessTrusted()
            screenCaptureTrusted = CGPreflightScreenCaptureAccess()
            loginItem.refresh()
        }
    }

    private func scrollToRequestedInfoAnchor(with proxy: ScrollViewProxy) {
        guard let anchor = navigation.requestedInfoAnchor else { return }
        DispatchQueue.main.async {
            withAnimation(.easeOut(duration: 0.22)) {
                proxy.scrollTo(anchor, anchor: .top)
            }
            highlightSystemAccess = anchor == "system-access"
            AppNavigation.shared.requestedInfoAnchor = nil
            DispatchQueue.main.asyncAfter(deadline: .now() + 2.2) {
                withAnimation(.easeOut(duration: 0.28)) {
                    highlightSystemAccess = false
                }
            }
        }
    }

    private var aboutHero: some View {
        HStack(spacing: 22) {
            ZStack {
                Circle()
                    .fill(Color.accentColor.opacity(0.075))
                    .frame(width: 112, height: 112)
                    .blur(radius: 16)

                QuickOrbitLogoView(size: 78, cornerRadius: 19)
                    .frame(width: 96, height: 96)
            }

            VStack(alignment: .leading, spacing: 8) {
                HStack(spacing: 9) {
                    Text("QuickOrbit")
                        .font(.system(size: 28, weight: .bold, design: .rounded))

                    Text(quickOrbitVersionLabel)
                        .font(.caption.weight(.bold))
                        .foregroundStyle(Color.accentColor)
                        .padding(.horizontal, 9)
                        .padding(.vertical, 5)
                        .background(Color.accentColor.opacity(0.10), in: Capsule())
                        .quickOrbitGlass(cornerRadius: 999)
                }

                Text(qoText("Schneller ohne Umwege.", "Faster, without detours.", language: store.config.language))
                    .font(.subheadline.weight(.medium))
                    .foregroundStyle(.secondary)

                Label(qoText("Von Nico · Idee, Design & Entwicklung", "By Nico · idea, design & development", language: store.config.language), systemImage: "person.crop.circle.fill")
                    .font(.caption.weight(.medium))
                    .foregroundStyle(.secondary)
            }

            Spacer(minLength: 20)

            VStack(alignment: .trailing, spacing: 11) {
                HStack(spacing: 8) {
                    AboutBadge(symbol: "macbook", text: "macOS")
                    AboutBadge(
                        symbol: accessibilityTrusted ? "checkmark.circle.fill" : "exclamationmark.circle.fill",
                        text: accessibilityTrusted
                            ? qoText("Bereit", "Ready", language: store.config.language)
                            : qoText("Zugriff fehlt", "Access needed", language: store.config.language)
                    )
                }

                HStack(spacing: 10) {
                    if let websiteURL = quickOrbitWebsiteURL {
                        Link(destination: websiteURL) {
                            Label(qoText("Website", "Website", language: store.config.language), systemImage: "globe")
                        }
                        .quickOrbitColorButton(.blue)
