struct BetaTerminalCommandEditor: View {
    @ObservedObject private var store = OrbitStore.shared
    let language: AppLanguage?
    @Binding var title: String
    @Binding var command: String
    @Binding var trusted: Bool
    let currentItemID: UUID
    let onDeleteCurrent: () -> Void

    @State private var editingReference: SavedBetaCommandReference?
    @State private var editTitle = ""
    @State private var editCommand = ""
    @State private var editTrusted = false
    @State private var pendingDeletion: SavedBetaCommandReference?

    private var status: (valid: Bool, message: String) {
        QuickOrbitBetaCommandPolicy.status(command, language: language)
    }

    private let examples: [(String, String, String, String)] = [
        ("calendar", "Datum", "Date", "date '+%A, %d. %B %Y'"),
        ("speaker.wave.2.fill", "Ansage", "Announcement", "say \"QuickOrbit ist bereit\""),
        ("music.note", "Musik öffnen", "Open Music", "open -a Music"),
        ("forward.end.fill", "Nächster Titel", "Next track", "osascript -e 'tell application \"Music\" to next track'"),
        ("clock.arrow.circlepath", "Laufzeit", "Uptime", "uptime"),
        ("macbook", "macOS-Version", "macOS version", "sw_vers")
    ]

    var body: some View {
        let savedCommands = store.savedBetaCommands
        VStack(alignment: .leading, spacing: 16) {
            HStack(alignment: .top, spacing: 12) {
                Image(systemName: "terminal.fill")
                    .font(.system(size: 24, weight: .semibold))
                    .foregroundStyle(Color.yellow)
                    .frame(width: 46, height: 46)
                    .background(Color.yellow.opacity(0.12), in: RoundedRectangle(cornerRadius: 13, style: .continuous))

                VStack(alignment: .leading, spacing: 5) {
                    HStack(spacing: 8) {
                        Text(qoText("Eigener Befehl", "Custom command", language: language))
                            .font(.title3.weight(.semibold))
                        Text("BETA")
                            .font(.system(size: 9, weight: .black, design: .rounded))
                            .foregroundStyle(Color.black.opacity(0.82))
                            .padding(.horizontal, 8)
                            .padding(.vertical, 4)
                            .background(Color.yellow, in: Capsule())
                    }
                    Text(qoText("Eine Kachel führt genau einen lokalen, nicht interaktiven Befehl aus.", "One tile runs exactly one local, non-interactive command.", language: language))
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
                Spacer()
            }

            VStack(alignment: .leading, spacing: 8) {
                Text(qoText("Name der Kachel", "Tile name", language: language))
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(.secondary)
                TextField(qoText("Zum Beispiel: Musik starten", "For example: Start Music", language: language), text: $title)
                    .quickOrbitInputField()

                Text(qoText("Terminal-Befehl", "Terminal command", language: language))
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(.secondary)
                    .padding(.top, 4)
                TextEditor(text: $command)
                    .scrollContentBackground(.hidden)
                    .padding(10)
                    .frame(minHeight: 92, maxHeight: 118)
                    .quickOrbitGlass(cornerRadius: 14, interactive: true)
                    .overlay {
                        RoundedRectangle(cornerRadius: 14, style: .continuous)
                            .stroke(Color.primary.opacity(0.08), lineWidth: 0.8)
                    }
                    .font(.system(.body, design: .monospaced))
            }

            Label(status.message, systemImage: status.valid ? "checkmark.shield.fill" : "exclamationmark.triangle.fill")
                .font(.caption.weight(.semibold))
                .foregroundStyle(status.valid ? Color.green : Color.orange)
                .padding(11)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background((status.valid ? Color.green : Color.orange).opacity(0.08), in: RoundedRectangle(cornerRadius: 12, style: .continuous))

            Toggle(isOn: $trusted) {
                VStack(alignment: .leading, spacing: 3) {
                    Text(qoText("Ich habe den Befehl geprüft und vertraue ihm", "I reviewed this command and trust it", language: language))
                        .font(.subheadline.weight(.semibold))
                    Text(qoText("Erst nach dieser Bestätigung kann die Beta-Kachel gespeichert werden.", "The beta tile can only be saved after this confirmation.", language: language))
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                }
            }
            .toggleStyle(.checkbox)
            .disabled(!status.valid)
            .padding(12)
            .quickOrbitGlass(cornerRadius: 14, interactive: status.valid)

            if !savedCommands.isEmpty {
                VStack(alignment: .leading, spacing: 10) {
                    HStack {
                        Text(qoText("Meine Befehle", "My commands", language: language))
                            .font(.caption.weight(.bold))
                            .foregroundStyle(.secondary)
                        Spacer()
                        Text("\(savedCommands.count)")
                            .font(.caption2.monospacedDigit().weight(.bold))
                            .foregroundStyle(.secondary)
                    }

                    ForEach(savedCommands) { reference in
                        HStack(spacing: 10) {
                            Image(systemName: "terminal.fill")
                                .foregroundStyle(Color.yellow)
                                .frame(width: 24)
                            VStack(alignment: .leading, spacing: 2) {
                                Text(reference.title)
                                    .font(.caption.weight(.semibold))
                                Text("\(reference.profileName) · \(reference.command)")
                                    .font(.system(size: 9.5, design: .monospaced))
                                    .foregroundStyle(.secondary)
                                    .lineLimit(1)
                            }
                            Spacer(minLength: 8)
                            Button(qoText("Verwenden", "Use", language: language)) {
                                title = reference.title
                                command = reference.command
                                trusted = false
                            }
                            .buttonStyle(.borderless)

                            Button {
                                beginEditing(reference)
                            } label: {
                                Image(systemName: "pencil")
                            }
                            .buttonStyle(.borderless)
                            .help(qoText("Bearbeiten", "Edit", language: language))

                            Button(role: .destructive) {
                                pendingDeletion = reference
                            } label: {
                                Image(systemName: "trash")
                                    .foregroundStyle(Color.red)
                            }
                            .buttonStyle(.borderless)
                            .help(qoText("Löschen", "Delete", language: language))
                        }
                        .padding(10)
                        .quickOrbitGlass(cornerRadius: 12, interactive: true)
                    }

                    if let editingReference {
                        betaCommandEditPanel(editingReference)
                    }
                }
            }

            VStack(alignment: .leading, spacing: 9) {
                Text(qoText("Beispiele", "Examples", language: language))
                    .font(.caption.weight(.bold))
                    .foregroundStyle(.secondary)
                LazyVGrid(columns: [GridItem(.flexible()), GridItem(.flexible())], spacing: 9) {
                    ForEach(Array(examples.enumerated()), id: \.offset) { _, example in
                        Button {
                            title = qoText(example.1, example.2, language: language)
                            command = example.3
                        } label: {
                            HStack(spacing: 9) {
                                Image(systemName: example.0)
                                    .foregroundStyle(Color.yellow)
                                    .frame(width: 22)
                                VStack(alignment: .leading, spacing: 2) {
                                    Text(qoText(example.1, example.2, language: language)).font(.caption.weight(.semibold))
                                    Text(example.3).font(.system(size: 9.5, design: .monospaced)).foregroundStyle(.secondary).lineLimit(1)
                                }
                                Spacer()
                            }
                            .padding(10)
                            .contentShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
                        }
                        .buttonStyle(.plain)
                        .quickOrbitGlass(cornerRadius: 12, interactive: true)
                        .quickOrbitPickerHover()
                    }
                }
            }

            Label(
                qoText("Administrator-, Lösch-, Rechte-, Shell-, Netzwerk- und verkettete Befehle bleiben gesperrt. Die Ausführung endet spätestens nach 60 Sekunden.", "Administrator, destructive, permission, shell, network, and chained commands remain blocked. Execution ends after 60 seconds at the latest.", language: language),
                systemImage: "lock.shield.fill"
            )
            .font(.caption2)
            .foregroundStyle(.secondary)
        }
        .onChange(of: command) { oldValue, newValue in
            if oldValue != newValue { trusted = false }
        }
        .confirmationDialog(
            qoText("Befehl wirklich löschen?", "Delete this command?", language: language),
            isPresented: Binding(
                get: { pendingDeletion != nil },
                set: { if !$0 { pendingDeletion = nil } }
            )
        ) {
            Button(qoText("Befehl löschen", "Delete command", language: language), role: .destructive) {
                if let pendingDeletion {
                    let changesOpenProfile = pendingDeletion.profileID == store.config.activeProfileID
                    _ = store.deleteSavedBetaCommand(id: pendingDeletion.id)
                    if editingReference?.id == pendingDeletion.id { cancelEditing() }
                    if changesOpenProfile {
                        DispatchQueue.main.async { onDeleteCurrent() }
                    }
                }
                self.pendingDeletion = nil
            }
            Button(qoText("Abbrechen", "Cancel", language: language), role: .cancel) {
                pendingDeletion = nil
            }
        } message: {
            Text(pendingDeletion?.title ?? "")
        }
    }

    @ViewBuilder
    private func betaCommandEditPanel(_ reference: SavedBetaCommandReference) -> some View {
        VStack(alignment: .leading, spacing: 10) {
            HStack {
                Label(qoText("Gespeicherten Befehl bearbeiten", "Edit saved command", language: language), systemImage: "pencil.and.outline")
                    .font(.subheadline.weight(.semibold))
                Spacer()
                Text(reference.profileName)
                    .font(.caption2.weight(.semibold))
                    .foregroundStyle(.secondary)
            }

            TextField(qoText("Name", "Name", language: language), text: $editTitle)
                .quickOrbitInputField()
            TextEditor(text: $editCommand)
                .scrollContentBackground(.hidden)
                .font(.system(.callout, design: .monospaced))
                .padding(9)
                .frame(minHeight: 78, maxHeight: 100)
                .quickOrbitGlass(cornerRadius: 13, interactive: true)

            Toggle(qoText("Ich vertraue der geänderten Version", "I trust the edited version", language: language), isOn: $editTrusted)
                .toggleStyle(.checkbox)
                .font(.caption.weight(.semibold))
                .disabled(!QuickOrbitBetaCommandPolicy.status(editCommand, language: language).valid)

            HStack {
                Button(qoText("Abbrechen", "Cancel", language: language)) { cancelEditing() }
                    .quickOrbitGlassButton()
                Spacer()
                Button(qoText("Änderungen speichern", "Save changes", language: language)) {
                    let updatesCurrentDraft = reference.id == currentItemID
                    if store.updateSavedBetaCommand(id: reference.id, title: editTitle, command: editCommand) {
                        if updatesCurrentDraft {
                            title = editTitle.trimmingCharacters(in: .whitespacesAndNewlines)
                            command = editCommand.trimmingCharacters(in: .whitespacesAndNewlines)
                            trusted = false
                        }
                        cancelEditing()
                    }
                }
                .quickOrbitColorButton(.green)
                .disabled(
                    editTitle.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    || !editTrusted
                    || !QuickOrbitBetaCommandPolicy.status(editCommand, language: language).valid
                )
            }
        }
        .padding(13)
        .background(Color.yellow.opacity(0.055), in: RoundedRectangle(cornerRadius: 15, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: 15, style: .continuous)
                .stroke(Color.yellow.opacity(0.24), lineWidth: 1)
        }
        .onChange(of: editCommand) { oldValue, newValue in
            if oldValue != newValue { editTrusted = false }
        }
    }

    private func beginEditing(_ reference: SavedBetaCommandReference) {
        editingReference = reference
        editTitle = reference.title
        editCommand = reference.command
        editTrusted = false
    }

    private func cancelEditing() {
        editingReference = nil
        editTitle = ""
        editCommand = ""
        editTrusted = false
    }
}

// MARK: - Full action editor

struct ActionEditorSheet: View {
    @ObservedObject private var store = OrbitStore.shared
    @Environment(\.dismiss) private var dismiss

    let slot: Int
    var onClose: (() -> Void)? = nil

    @State private var originalItem: OrbitItem?
    @State private var startedAsNewField = false
    // The editor works on a draft. Nothing is written to the real field until Done.
    // This makes one click on an app/action enough and gives Cancel a real rollback.
    @State private var pendingItem: OrbitItem?

    @State private var mode: OrbitActionType = .app
    @State private var apps: [InstalledAppChoice] = InstalledApps.cached()
    @State private var searchText = ""
    @State private var unifiedSearchText = ""
    @State private var draftURL = ""
    @State private var draftURLSymbol = "globe"
    @State private var draftCommandTitle = ""
    @State private var draftShellCommand = ""
    @State private var draftShellCommandTrusted = false
    @Namespace private var editorGlassNamespace

    private var current: OrbitItem {
        guard store.config.items.indices.contains(slot) else { return .empty(slot) }
        return store.config.items[slot]
    }

    private var displayItem: OrbitItem { pendingItem ?? current }

    private var canCommit: Bool {
        if mode == .url, !draftURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { return true }
        if mode == .shellCommand {
            return !draftCommandTitle.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                && draftShellCommandTrusted
                && QuickOrbitBetaCommandPolicy.status(draftShellCommand, language: store.config.language).valid
        }
        guard displayItem.enabled else { return false }
        switch mode {
        case .app: return displayItem.type == .app
        case .file: return displayItem.type == .file
        case .url: return displayItem.type == .url
        case .emoji: return displayItem.type == .emoji || displayItem.target == "emojiPalette" || displayItem.target.hasPrefix("emojiInsert:")
        case .timer: return displayItem.type == .timer || displayItem.target.hasPrefix("timer") || displayItem.target == "stopwatch"
        case .systemAction:
            return displayItem.type == .systemAction
                && displayItem.target != "emojiPalette"
                && !displayItem.target.hasPrefix("emojiInsert:")
                && !displayItem.target.hasPrefix("timer")
                && SystemActionPreset.preset(for: displayItem.target)?.isWindowManagement != true
        case .windowManagement: return displayItem.type == .windowManagement
        case .screenshot: return displayItem.type == .screenshot
        case .edit: return displayItem.type == .edit
        case .shellCommand: return displayItem.type == .shellCommand
        case .pasteText: return displayItem.type == .pasteText && !displayItem.target.isEmpty
        case .shortcut, .clipboard, .windowLeft, .windowRight: return false
        }
    }

    private var filteredApps: [InstalledAppChoice] {
        let query = searchText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !query.isEmpty else { return apps }
        return apps.filter { $0.name.localizedCaseInsensitiveContains(query) }
    }

    var body: some View {
        ZStack {
            SystemBackdrop()

            QuickOrbitGlassGroup(spacing: 16) {
                VStack(spacing: 0) {
            HStack(spacing: 12) {
                FieldIcon(item: displayItem, size: 46)

                VStack(alignment: .leading, spacing: 2) {
                    Text(qoText("Feld \(slot + 1)", "Field \(slot + 1)", language: store.config.language))
                        .font(.title2.weight(.semibold))
                    Text(displayItem.enabled ? displayItem.title : qoText("Neue Aktion auswählen", "Choose a new action", language: store.config.language))
                        .foregroundStyle(.secondary)
                }

                Spacer()

                Label(
                    canCommit ? qoText("Auswahl bereit", "Selection ready", language: store.config.language) : qoText("Bitte auswählen", "Choose an item", language: store.config.language),
                    systemImage: canCommit ? "checkmark.circle.fill" : "circle.dashed"
                )
                .font(.caption.weight(.semibold))
                .foregroundStyle(canCommit ? Color.green : Color.secondary)
                .padding(.horizontal, 10)
                .padding(.vertical, 6)
                .background((canCommit ? Color.green : Color.secondary).opacity(0.09), in: Capsule())

                Button(qoText("Abbrechen", "Cancel", language: store.config.language)) {
                    cancelEditor()
                }
                .quickOrbitGlassButton()
                .keyboardShortcut(.cancelAction)

                Button {
                    prepareDraftForCurrentMode()
                    commitPendingAndClose()
                } label: {
                    Label(qoText("Fertig", "Done", language: store.config.language), systemImage: "checkmark")
                }
                .quickOrbitColorButton(canCommit ? .green : .neutral)
                .keyboardShortcut(.defaultAction)
                .disabled(!canCommit)
            }
            .padding(20)

            Divider()

            HStack(spacing: 10) {
                Image(systemName: "magnifyingglass")
                    .font(.system(size: 17, weight: .semibold))
                    .foregroundStyle(Color.accentColor)
                    .frame(width: 38, height: 38)
                    .background(Color.accentColor.opacity(0.10), in: RoundedRectangle(cornerRadius: 12, style: .continuous))
                TextField(qoText("Apps, Webseiten und Werkzeuge durchsuchen", "Search apps, websites, and tools", language: store.config.language), text: $unifiedSearchText)
                    .textFieldStyle(.plain)
                    .font(.system(size: 18, weight: .medium, design: .rounded))
                if !unifiedSearchText.isEmpty {
                    Button { unifiedSearchText = "" } label: { Image(systemName: "xmark.circle.fill") }
                        .buttonStyle(.plain)
                        .foregroundStyle(.secondary)
                }
            }
            .padding(.horizontal, 13)
            .frame(maxWidth: 680, minHeight: 62)
            .quickOrbitGlass(cornerRadius: 20, interactive: true)
            .shadow(color: Color.black.opacity(0.08), radius: 12, y: 4)
            .frame(maxWidth: .infinity)
            .padding(.horizontal, 20)
            .padding(.vertical, 10)

            HStack(spacing: 0) {
                QuickOrbitGlassGroup(spacing: 10) {
                    ScrollView(.vertical, showsIndicators: false) {
                        VStack(spacing: 9) {
                            ForEach(OrbitActionType.availableCases) { type in
                                Button {
                                    mode = type
                                } label: {
                                    HStack(spacing: 10) {
                                        Image(systemName: type.symbol)
                                            .frame(width: 20)
                                            .foregroundStyle(mode == type ? Color.accentColor : Color.primary)
                                        VStack(alignment: .leading, spacing: 2) {
                                        Text(type.title(language: store.config.language))
                                                .fontWeight(mode == type ? .semibold : .regular)
                                            if type == .shellCommand {
                                                Text("BETA")
                                                    .font(.system(size: 8, weight: .black, design: .rounded))
                                                    .foregroundStyle(Color.black.opacity(0.82))
                                                    .padding(.horizontal, 6)
                                                    .padding(.vertical, 2)
                                                    .background(Color.yellow, in: Capsule())
                                            }
                                            Text(type.subtitle(language: store.config.language))
                                                .font(.caption2)
                                                .foregroundStyle(.secondary)
                                                .lineLimit(1)
                                        }
                                        Spacer()
                                        if mode == type {
                                            Image(systemName: "checkmark.circle.fill")
                                                .foregroundStyle(Color.accentColor)
                                        }
                                    }
                                    .padding(.horizontal, 12)
                                    .frame(maxWidth: .infinity, minHeight: 46, alignment: .leading)
                                    .contentShape(RoundedRectangle(cornerRadius: 15, style: .continuous))
                                    .background {
                                        RoundedRectangle(cornerRadius: 15, style: .continuous)
                                            .fill(mode == type ? Color.accentColor.opacity(0.11) : Color.clear)
                                    }
                                    .overlay {
                                        if mode == type {
                                            RoundedRectangle(cornerRadius: 15, style: .continuous)
                                                .stroke(Color.accentColor.opacity(0.22), lineWidth: 1)
                                        }
                                    }
                                }
                                .buttonStyle(.plain)
                                .quickOrbitPickerHover()
                            }

                        }
                        .padding(12)
                    }
                }
                .frame(width: 236)

                Divider()

                ScrollView(.vertical, showsIndicators: false) {
                    VStack(alignment: .leading, spacing: 18) {
                        if unifiedSearchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                            editorContent
                        } else {
                            unifiedSearchResults
                        }
                    }
                    .padding(24)
                    .frame(maxWidth: .infinity, alignment: .leading)
                }
                    }
                }
                .quickOrbitGlass(cornerRadius: 30)
                .shadow(color: Color.black.opacity(0.10), radius: 16, y: 6)
                .quickOrbitGlassIdentity("action-editor-shell", in: editorGlassNamespace, matched: false)
                .clipShape(RoundedRectangle(cornerRadius: 30, style: .continuous))
            }
            .padding(14)
        }
        .frame(width: 960, height: 680)
        .onAppear {
            store.actionEditorIsOpen = true
            originalItem = current
            pendingItem = current
            startedAsNewField = store.newlyCreatedEditorSlot == slot
            if current.type == .systemAction && (current.target == "emojiPalette" || current.target.hasPrefix("emojiInsert:")) {
                mode = .emoji
            } else {
                mode = OrbitActionType.availableCases.contains(current.type) ? current.type : .app
            }
            draftURL = current.type == .url ? current.target : ""
            draftURLSymbol = current.type == .url && !current.symbol.isEmpty ? current.symbol : "globe"
            draftCommandTitle = current.type == .shellCommand ? current.title : ""
            draftShellCommand = current.type == .shellCommand ? current.target : ""
            draftShellCommandTrusted = false
        }
        .onDisappear {
            store.actionEditorIsOpen = false
            DispatchQueue.main.async {
                store.applyPendingAutomaticProfileIfNeeded()
                store.applyPendingMainProfileReturnForOrbitIfNeeded()
            }
        }
    }

    private var unifiedQuery: String {
        unifiedSearchText.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private var unifiedSearchResults: some View {
        let matchingApps = apps.filter { $0.name.localizedCaseInsensitiveContains(unifiedQuery) }.prefix(12)
        let matchingWebsites = WebsitePreset.popular.filter { $0.name.localizedCaseInsensitiveContains(unifiedQuery) }.prefix(12)
        let matchingControls = SystemActionPreset.all.filter {
            !$0.id.hasPrefix("timer") && !$0.isWindowManagement && ($0.title(language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery) || $0.subtitle(language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery))
        }.prefix(12)
        let matchingWindows = SystemActionPreset.all.filter {
            $0.isWindowManagement && ($0.title(language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery) || $0.subtitle(language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery))
        }.prefix(9)
        let timerMatch = qoText("Timer Stoppuhr Zeit Sekunden Minuten", "timer stopwatch time seconds minutes", language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery)
        let textMatch = qoText("Eigener Text Signatur Adresse Antwort", "custom text signature address reply", language: store.config.language).localizedCaseInsensitiveContains(unifiedQuery)

        return VStack(alignment: .leading, spacing: 18) {
            editorTitle(qoText("Suchergebnisse", "Search results", language: store.config.language), qoText("Apps, Webseiten und Werkzeuge gemeinsam durchsuchen.", "Search apps, websites, and tools together.", language: store.config.language))

            if textMatch {
                searchResultButton(title: qoText("Eigener Text", "Custom text", language: store.config.language), subtitle: qoText("Textbaustein erstellen", "Create a text snippet", language: store.config.language), symbol: "text.alignleft") {
                    mode = .pasteText
                    unifiedSearchText = ""
                }
            }

            if timerMatch {
                searchResultButton(title: qoText("Timer & Stoppuhr", "Timer & stopwatch", language: store.config.language), subtitle: qoText("Sekunden-Timer oder Stoppuhr auswählen", "Choose a seconds timer or stopwatch", language: store.config.language), symbol: "stopwatch.fill") {
                    mode = .timer
                    unifiedSearchText = ""
                }
            }

            if !matchingApps.isEmpty {
                searchSectionTitle(qoText("Apps", "Apps", language: store.config.language))
                ForEach(Array(matchingApps)) { app in
                    searchResultButton(title: app.name, subtitle: qoText("App", "App", language: store.config.language), symbol: "app.fill", selected: displayItem.type == .app && displayItem.target == app.url.path) {
                        apply(app)
                        if let pendingItem { selectSearchResult(pendingItem) }
                    }
                }
            }

            if !matchingWebsites.isEmpty {
                searchSectionTitle(qoText("Webseiten", "Websites", language: store.config.language))
                ForEach(Array(matchingWebsites)) { site in
                    searchResultButton(title: site.name, subtitle: site.url, symbol: site.symbol, selected: displayItem.type == .url && displayItem.target == site.url) {
                        var item = pendingItem ?? current
                        item.type = .url; item.target = site.url; item.title = site.name; item.symbol = site.symbol; item.enabled = true
                        item.securityScopedBookmark = nil
                        selectSearchResult(item)
                    }
                }
            }

            if !matchingControls.isEmpty {
                searchSectionTitle(qoText("Mac-Steuerung", "Mac controls", language: store.config.language))
                ForEach(Array(matchingControls)) { preset in
                    searchResultButton(
                        title: preset.title(language: store.config.language),
                        subtitle: preset.subtitle(language: store.config.language) + (preset.requiresAccessibility && !AXIsProcessTrusted()
                            ? qoText(" · Bedienungshilfe nötig", " · Accessibility required", language: store.config.language)
                            : "") + (preset.requiresScreenRecording && !CGPreflightScreenCaptureAccess()
                                ? qoText(" · Bildschirmfreigabe beim ersten Start", " · Screen access on first use", language: store.config.language)
                                : ""),
                        symbol: preset.symbol,
                        selected: displayItem.type == .systemAction && displayItem.target == preset.id
                    ) {
                        selectSearchResult(preset.orbitItem(language: store.config.language))
                    }
                }
            }

            if !matchingWindows.isEmpty {
                searchSectionTitle(qoText("Fenster", "Windows", language: store.config.language))
                ForEach(Array(matchingWindows)) { preset in
                    searchResultButton(
                        title: preset.title(language: store.config.language),
                        subtitle: preset.subtitle(language: store.config.language) + (!AXIsProcessTrusted()
                            ? qoText(" · Bedienungshilfe nötig", " · Accessibility required", language: store.config.language)
                            : ""),
                        symbol: preset.symbol,
                        selected: displayItem.type == .windowManagement && displayItem.target == preset.id
                    ) {
                        selectSearchResult(preset.orbitItem(language: store.config.language))
                    }
                }
            }

            if !textMatch && !timerMatch && matchingApps.isEmpty && matchingWebsites.isEmpty && matchingControls.isEmpty && matchingWindows.isEmpty {
                ContentUnavailableView(qoText("Nichts gefunden", "No results", language: store.config.language), systemImage: "magnifyingglass", description: Text(qoText("Versuche einen kürzeren Suchbegriff.", "Try a shorter search term.", language: store.config.language)))
            }
        }
    }

    private func searchSectionTitle(_ title: String) -> some View {
        Text(title).font(.caption.weight(.bold)).foregroundStyle(.secondary)
    }

    private func selectSearchResult(_ item: OrbitItem) {
        pendingItem = item
        mode = item.editorCategory
        draftURL = item.type == .url ? item.target : ""
        draftURLSymbol = item.type == .url ? item.symbol : "globe"
    }

    private func searchResultButton(title: String, subtitle: String, symbol: String, selected: Bool = false, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            HStack(spacing: 12) {
                Image(systemName: symbol).font(.system(size: 18, weight: .semibold)).frame(width: 32)
                VStack(alignment: .leading, spacing: 2) {
                    Text(title).font(.subheadline.weight(.semibold))
                    Text(subtitle).font(.caption2).foregroundStyle(.secondary).lineLimit(1)
                }
                Spacer()
                Image(systemName: selected ? "checkmark.circle.fill" : "plus.circle.fill")
                    .foregroundStyle(selected ? Color.green : Color.accentColor)
            }
            .padding(12)
            .contentShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        }
        .buttonStyle(.plain)
        .quickOrbitGlass(cornerRadius: 14, interactive: true)
        .overlay {
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(selected ? Color.green.opacity(0.42) : Color.primary.opacity(0.05), lineWidth: selected ? 1.1 : 0.6)
        }
        .quickOrbitPickerHover()
    }

    @ViewBuilder
    private var editorContent: some View {
        switch mode {
        case .app:
            appEditor
        case .file:
            fileEditor
        case .url:
            urlEditor
        case .shortcut:
            EmptyView()
        case .pasteText:
            QuickOrbitCustomTextEditor(item: displayItem, language: store.config.language) { pendingItem = $0 }
        case .clipboard, .windowLeft, .windowRight:
            EmptyView()
        case .emoji:
            EmojiActionPicker(
                language: store.config.language,
                selectedTarget: (displayItem.type == .emoji || (displayItem.type == .systemAction && (displayItem.target == "emojiPalette" || displayItem.target.hasPrefix("emojiInsert:")))) ? displayItem.target : nil
            ) { item in
                pendingItem = item
            }
        case .timer:
            TimerActionPicker(
                language: store.config.language,
                selectedTarget: (displayItem.type == .timer || (displayItem.type == .systemAction && displayItem.target.hasPrefix("timer"))) ? displayItem.target : nil
            ) { item in
                pendingItem = item
            }
        case .systemAction:
            SystemActionPicker(
                language: store.config.language,
                selectedTarget: displayItem.type == .systemAction ? displayItem.target : nil
            ) { item in
                pendingItem = item
            }
        case .windowManagement:
            WindowActionPicker(
                language: store.config.language,
                selectedTarget: displayItem.type == .windowManagement ? displayItem.target : nil
            ) { item in
                pendingItem = item
            }
        case .screenshot:
            screenshotEditor
        case .edit:
            editActionEditor
        case .shellCommand:
            BetaTerminalCommandEditor(
                language: store.config.language,
                title: $draftCommandTitle,
                command: $draftShellCommand,
                trusted: $draftShellCommandTrusted,
                currentItemID: current.id,
                onDeleteCurrent: { closeEditor() }
            )
        }
    }

