    private var urlEditor: some View {
        VStack(alignment: .leading, spacing: 16) {
            editorTitle(qoText("Webseite", "Website", language: store.config.language), qoText("Beliebte Seite wählen oder eigene Adresse eingeben.", "Choose a popular website or enter your own address.", language: store.config.language))

            WebsiteQuickPicker(url: $draftURL, symbol: $draftURLSymbol)

            TextField("example.com", text: $draftURL)
                .quickOrbitInputField()

            Label(qoText("Auswählen und oben nur noch Fertig drücken.", "Choose it, then just press Done at the top.", language: store.config.language), systemImage: "checkmark.circle")
                .font(.caption)
                .foregroundStyle(.secondary)
        }
    }

    private func applyDraftURL() {
        var value = draftURL.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !value.isEmpty else { return }
        if !value.contains("://") { value = "https://" + value }

        var item = current
        item.type = .url
        item.target = value
        item.title = WebsitePreset.popular.first(where: { $0.url == value })?.name
            ?? URL(string: value)?.host?.replacingOccurrences(of: "www.", with: "")
            ?? qoText("Webseite", "Website", language: store.config.language)
        item.symbol = draftURLSymbol
        item.enabled = true
        pendingItem = item
    }

