    private func editorTitle(_ title: String, _ subtitle: String) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(title)
                .font(.title3.weight(.semibold))
            Text(subtitle)
                .font(.subheadline)
                .foregroundStyle(.secondary)
        }
    }

    private func apply(_ app: InstalledAppChoice) {
        var item = pendingItem ?? current
        item.type = .app
        item.target = app.url.path
        item.securityScopedBookmark = quickOrbitBookmark(for: app.url)
        item.title = app.name
        item.symbol = "app.fill"
        item.enabled = true
        pendingItem = item
    }

    private func chooseOtherApp() {
        let panel = NSOpenPanel()
        panel.title = qoText("App auswählen", "Choose app", language: store.config.language)
        panel.canChooseDirectories = false
        panel.canChooseFiles = true
        panel.allowsMultipleSelection = false
        panel.allowedContentTypes = [.application]

        if panel.runModal() == .OK, let url = panel.url {
            apply(
                InstalledAppChoice(
                    id: url.path,
                    name: url.deletingPathExtension().lastPathComponent,
                    url: url
                )
            )
        }
    }

    private func chooseFile() {
        let panel = NSOpenPanel()
        panel.title = qoText("Datei oder Ordner auswählen", "Choose file or folder", language: store.config.language)
        panel.canChooseDirectories = true
        panel.canChooseFiles = true
        panel.allowsMultipleSelection = false

        if panel.runModal() == .OK, let url = panel.url {
            var item = pendingItem ?? current
            item.type = .file
            item.target = url.path
            item.securityScopedBookmark = quickOrbitBookmark(for: url)
            item.title = url.lastPathComponent
            item.symbol = url.hasDirectoryPath ? "folder.fill" : "doc.fill"
            item.enabled = true
            pendingItem = item
        }
    }
    private func prepareDraftForCurrentMode() {
        if mode == .url, !draftURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            applyDraftURL()
        } else if mode == .shellCommand,
                  draftShellCommandTrusted,
                  QuickOrbitBetaCommandPolicy.status(draftShellCommand, language: store.config.language).valid {
            var item = pendingItem ?? current
            item.type = .shellCommand
            item.target = draftShellCommand.trimmingCharacters(in: .whitespacesAndNewlines)
            item.title = draftCommandTitle.trimmingCharacters(in: .whitespacesAndNewlines)
            item.symbol = "terminal.fill"
            item.securityScopedBookmark = nil
            item.enabled = true
            pendingItem = item
        }
    }

    private func commitPendingAndClose() {
        if let pendingItem, pendingItem.enabled {
            store.setItem(pendingItem, at: slot)
        } else if startedAsNewField && store.newlyCreatedEditorSlot == slot {
            store.removeSlot(slot)
        }
        store.newlyCreatedEditorSlot = nil
        closeEditor()
    }

    private func closeEditor() {
        // The normal editor sheet is controlled by OrbitStore.editorSlot, not only
        // by SwiftUI's dismiss environment. Clear that source of truth first so
        // Done and Cancel always close reliably.
        if let onClose {
            onClose()
        } else {
            store.editorSlot = nil
            DispatchQueue.main.async {
                dismiss()
            }
        }
    }

    private func cancelEditor() {
        if startedAsNewField && store.newlyCreatedEditorSlot == slot {
            // A brand-new field should disappear again when the user cancels.
            store.newlyCreatedEditorSlot = nil
            store.removeSlot(slot)
        } else if let originalItem {
            // Safety net: the editor normally only changes its draft until Done.
            store.setItem(originalItem, at: slot)
        }
        closeEditor()
    }

}

// MARK: - Movable menu-bar dock

enum QuickOrbitMenuDockItemKind: String, Codable {
    case app
    case link
    case file
    case orbitAction
    case appFolder
    case dropBoard
}

@MainActor
private enum QuickOrbitMenuDockTimer {
    static func seconds(for target: String) -> Int? {
        if target == "timerCustom" {
            return min(max(OrbitStore.shared.config.customTimerSeconds ?? 300, 5), 10_800)
        }
        if target.hasPrefix("timerSeconds") {
            return Int(target.dropFirst("timerSeconds".count)).map { min(max($0, 5), 10_800) }
        }
        if target.hasPrefix("timer"), let minutes = Int(target.dropFirst("timer".count)) {
            return min(max(minutes * 60, 5), 10_800)
        }
        return nil
    }
}

enum QuickOrbitMenuDockSize: String, CaseIterable, Identifiable {
    case compact
    case standard
    case large

    var id: String { rawValue }
    var iconSize: CGFloat {
        switch self { case .compact: return 44; case .standard: return 52; case .large: return 60 }
    }
    var spacing: CGFloat {
        switch self { case .compact: return 9; case .standard: return 13; case .large: return 16 }
    }
    var horizontalPadding: CGFloat {
        switch self { case .compact: return 12; case .standard: return 16; case .large: return 20 }
    }
    var panelHeight: CGFloat {
        switch self { case .compact: return 68; case .standard: return 76; case .large: return 88 }
    }
    func title(language: AppLanguage?) -> String {
        switch self {
        case .compact: return qoText("Kompakt", "Compact", language: language)
        case .standard: return qoText("Normal", "Standard", language: language)
        case .large: return qoText("Groß", "Large", language: language)
        }
    }
}

enum QuickOrbitMenuDockVisibility: String, CaseIterable, Identifiable {
    case nearEdge
    case always
    var id: String { rawValue }
    func title(language: AppLanguage?) -> String {
        switch self {
        case .nearEdge: return qoText("Nur am oberen Rand", "Only at the top edge", language: language)
        case .always: return qoText("Immer sichtbar", "Always visible", language: language)
        }
    }
}

enum QuickOrbitMenuDockDisplayMode: String, CaseIterable, Identifiable {
    case followPointer
    case allDisplays

    var id: String { rawValue }
    func title(language: AppLanguage?) -> String {
        switch self {
        case .followPointer: return qoText("Aktivem folgen", "Follow active", language: language)
        case .allDisplays: return qoText("Auf allen", "On all displays", language: language)
        }
    }
}

enum QuickOrbitMenuDockOrientation: String, CaseIterable, Identifiable {
    case horizontal
    case vertical

    var id: String { rawValue }
    var isVertical: Bool { self == .vertical }
    func title(language: AppLanguage?) -> String {
        switch self {
        case .horizontal: return qoText("Waagerecht", "Horizontal", language: language)
        case .vertical: return qoText("Hochkant", "Vertical", language: language)
        }
    }
}

struct QuickOrbitMenuDockItem: Identifiable, Codable, Equatable {
    var id = UUID()
    let kind: QuickOrbitMenuDockItemKind
    let value: String
    var securityScopedBookmark: Data? = nil
    var orbitItem: OrbitItem? = nil
    var children: [QuickOrbitMenuDockItem]? = nil

    var title: String {
        switch kind {
        case .app:
            return URL(fileURLWithPath: value).deletingPathExtension().lastPathComponent
        case .link:
            guard let url = URL(string: value), var host = url.host else { return value }
            if host.hasPrefix("www.") { host.removeFirst(4) }
            return host
        case .file:
            return URL(fileURLWithPath: value).lastPathComponent
        case .orbitAction:
            return orbitItem?.title ?? value
        case .appFolder:
            return value.isEmpty ? "Ordner" : value
        case .dropBoard:
            return value.isEmpty ? "Dropbox" : value
        }
    }
}

struct QuickOrbitMenuDockProfile: Identifiable, Codable, Equatable {
    var id = UUID()
    var name: String
    var items: [QuickOrbitMenuDockItem]
}

enum QuickOrbitMenuDockPosition: String, CaseIterable, Identifiable {
    case topLeft
    case belowCamera
    case topRight
    case bottomLeft
    case bottomCenter
    case bottomRight

    var id: String { rawValue }

    var symbol: String {
        switch self {
        case .topLeft: return "arrow.up.left"
        case .belowCamera: return "web.camera.fill"
        case .topRight: return "arrow.up.right"
        case .bottomLeft: return "arrow.down.left"
        case .bottomCenter: return "arrow.down.to.line"
        case .bottomRight: return "arrow.down.right"
        }
    }

    func title(language: AppLanguage?) -> String {
        switch self {
        case .topLeft: return qoText("Oben links", "Top left", language: language)
        case .belowCamera: return qoText("Unter der Kamera", "Below camera", language: language)
        case .topRight: return qoText("Oben rechts", "Top right", language: language)
        case .bottomLeft: return qoText("Unten links", "Bottom left", language: language)
        case .bottomCenter: return qoText("Unten mittig", "Bottom center", language: language)
        case .bottomRight: return qoText("Unten rechts", "Bottom right", language: language)
        }
    }
}

@MainActor
final class QuickOrbitMenuDockStore: ObservableObject {
    static let shared = QuickOrbitMenuDockStore()
    static let maximumItemCount = 10
    static let profileCount = 3
    static let maximumDropBoardItemCount = 24

    @Published var items: [QuickOrbitMenuDockItem] = [] {
        didSet {
            guard !isSynchronizingProfile else { return }
            if profiles.indices.contains(selectedProfileIndex) {
                profiles[selectedProfileIndex].items = Array(items.prefix(Self.maximumItemCount))
            }
            saveItems()
        }
    }
    @Published private(set) var profiles: [QuickOrbitMenuDockProfile] = []
    @Published private(set) var selectedProfileIndex = 0
    @Published var hoverDelay: Double {
        didSet { UserDefaults.standard.set(hoverDelay, forKey: hoverDelayKey) }
    }
    @Published var autoOpen: Bool {
        didSet { UserDefaults.standard.set(autoOpen, forKey: autoOpenKey) }
    }
    @Published var dockSize: QuickOrbitMenuDockSize {
        didSet { UserDefaults.standard.set(dockSize.rawValue, forKey: dockSizeKey) }
    }
    @Published var visibility: QuickOrbitMenuDockVisibility {
        didSet { UserDefaults.standard.set(visibility.rawValue, forKey: visibilityKey) }
    }
    @Published var displayMode: QuickOrbitMenuDockDisplayMode {
        didSet { UserDefaults.standard.set(displayMode.rawValue, forKey: displayModeKey) }
    }
    @Published var orientation: QuickOrbitMenuDockOrientation {
        didSet { UserDefaults.standard.set(orientation.rawValue, forKey: orientationKey) }
    }
    @Published var hoverMagnification: Double {
        didSet { UserDefaults.standard.set(hoverMagnification, forKey: hoverMagnificationKey) }
    }
    @Published var hideDockInFullscreen: Bool {
        didSet { UserDefaults.standard.set(hideDockInFullscreen, forKey: hideDockInFullscreenKey) }
    }
    @Published var hideDockInNearFullscreen: Bool {
        didSet { UserDefaults.standard.set(hideDockInNearFullscreen, forKey: hideDockInNearFullscreenKey) }
    }
    @Published private(set) var dockVisible = false
    @Published private(set) var dropBoardItems: [QuickOrbitMenuDockItem] = []
    @Published var externalDragActive = false
    @Published var internalDragID: UUID?
    @Published var appInsertionActive = false
    @Published private(set) var payloadExportActive = false
    @Published private(set) var auxiliaryPopoverActive = false
    private var dragCleanupTask: Task<Void, Never>?
    private var payloadExportCleanupTask: Task<Void, Never>?
    private var isSynchronizingProfile = false
    private var suppressOpenUntil = Date.distantPast

    var anyDragActive: Bool { externalDragActive || internalDragID != nil }
    var interactionDragActive: Bool { anyDragActive || payloadExportActive }
    var isFull: Bool { items.count >= Self.maximumItemCount }
    var automaticDropBoxID: UUID? {
        items.first {
            $0.kind == .dropBoard && ($0.children?.count ?? 0) < Self.maximumDropBoardItemCount
        }?.id
    }
    // External files always get one fresh Drop Box for the whole drag. Never
    // silently route them into whichever existing folder happens to be first.
    var canAcceptExternalDrop: Bool { !isFull }
    var externalDropCapacity: Int {
        return isFull ? 0 : Self.maximumDropBoardItemCount
    }

    private let itemsKey = "QuickOrbit.MenuBarDock.Items.v1"
    private let profilesKey = "QuickOrbit.MenuBarDock.Profiles.v2"
    private let selectedProfileKey = "QuickOrbit.MenuBarDock.SelectedProfile.v2"
    private let emojiDefaultsKey = "QuickOrbit.MenuBarDock.EmojiDefaults.v4"
    private let exampleDefaultsKey = "QuickOrbit.MenuBarDock.ExampleDefaults.v1"
    private let hoverDelayKey = "QuickOrbit.MenuBarDock.HoverDelay"
    private let autoOpenKey = "QuickOrbit.MenuBarDock.AutoOpen"
    private let dockSizeKey = "QuickOrbit.MenuBarDock.Size.v1"
    private let visibilityKey = "QuickOrbit.MenuBarDock.Visibility.v1"
    private let displayModeKey = "QuickOrbit.MenuBarDock.DisplayMode.v1"
    private let orientationKey = "QuickOrbit.MenuBarDock.Orientation.v1"
    private let dropBoardKey = "QuickOrbit.MenuBarDock.DropBoard.v1"
    private let hoverMagnificationKey = "QuickOrbit.MenuBarDock.HoverMagnification.v1"
    private let hideDockInFullscreenKey = "QuickOrbit.MenuBarDock.HideInFullscreen.v1"
    private let hideDockInNearFullscreenKey = "QuickOrbit.MenuBarDock.HideInNearFullscreen.v1"

    private init() {
        let defaults = UserDefaults.standard
        hoverDelay = defaults.object(forKey: hoverDelayKey) == nil ? 0.62 : defaults.double(forKey: hoverDelayKey)
        autoOpen = defaults.object(forKey: autoOpenKey) == nil ? true : defaults.bool(forKey: autoOpenKey)
        dockSize = defaults.string(forKey: "QuickOrbit.MenuBarDock.Size.v1").flatMap(QuickOrbitMenuDockSize.init(rawValue:)) ?? .compact
        visibility = defaults.string(forKey: "QuickOrbit.MenuBarDock.Visibility.v1").flatMap(QuickOrbitMenuDockVisibility.init(rawValue:)) ?? .nearEdge
        displayMode = defaults.string(forKey: displayModeKey).flatMap(QuickOrbitMenuDockDisplayMode.init(rawValue:)) ?? .followPointer
        orientation = defaults.string(forKey: "QuickOrbit.MenuBarDock.Orientation.v1").flatMap(QuickOrbitMenuDockOrientation.init(rawValue:)) ?? .horizontal
        hoverMagnification = defaults.object(forKey: hoverMagnificationKey) == nil ? 1.08 : min(max(defaults.double(forKey: hoverMagnificationKey), 1.0), 1.40)
        hideDockInFullscreen = defaults.bool(forKey: hideDockInFullscreenKey)
        hideDockInNearFullscreen = defaults.bool(forKey: hideDockInNearFullscreenKey)
        if let boardData = defaults.data(forKey: "QuickOrbit.MenuBarDock.DropBoard.v1"),
           let boardItems = try? JSONDecoder().decode([QuickOrbitMenuDockItem].self, from: boardData) {
            dropBoardItems = Array(boardItems.filter(Self.isUsable).prefix(Self.maximumDropBoardItemCount))
        }
        let legacyItems: [QuickOrbitMenuDockItem]
        if let data = defaults.data(forKey: itemsKey),
           let decoded = try? JSONDecoder().decode([QuickOrbitMenuDockItem].self, from: data) {
            legacyItems = Array(decoded.filter(Self.isUsable).prefix(Self.maximumItemCount))
        } else {
            legacyItems = []
        }
        if let data = defaults.data(forKey: profilesKey),
           let decoded = try? JSONDecoder().decode([QuickOrbitMenuDockProfile].self, from: data) {
            profiles = Self.normalizedProfiles(decoded, fallbackItems: legacyItems)
        } else {
            profiles = Self.normalizedProfiles([], fallbackItems: legacyItems)
        }
        if !defaults.bool(forKey: emojiDefaultsKey), profiles.indices.contains(1), profiles[1].items.isEmpty {
            profiles[1].name = "Emojis"
            profiles[1].items = Self.defaultEmojiItems
            if let encodedProfiles = try? JSONEncoder().encode(profiles) {
                defaults.set(encodedProfiles, forKey: profilesKey)
            }
            defaults.set(true, forKey: emojiDefaultsKey)
        }
        defaults.set(true, forKey: emojiDefaultsKey)
        if !defaults.bool(forKey: exampleDefaultsKey), profiles.indices.contains(0), profiles[0].items.isEmpty {
            profiles[0].name = "Apps"
            profiles[0].items = Self.defaultAppItems
            if let encodedProfiles = try? JSONEncoder().encode(profiles) {
                defaults.set(encodedProfiles, forKey: profilesKey)
            }
            defaults.set(true, forKey: exampleDefaultsKey)
        }
        selectedProfileIndex = min(max(defaults.integer(forKey: selectedProfileKey), 0), Self.profileCount - 1)
        isSynchronizingProfile = true
        items = profiles[selectedProfileIndex].items
        isSynchronizingProfile = false
    }

    func selectProfile(_ index: Int) {
        guard profiles.indices.contains(index), index != selectedProfileIndex else { return }
        finishDrag()
        isSynchronizingProfile = true
        selectedProfileIndex = index
        items = profiles[index].items
        isSynchronizingProfile = false
        UserDefaults.standard.set(index, forKey: selectedProfileKey)
    }

    func beginEditingProfile(_ index: Int) {
        if index == selectedProfileIndex, appInsertionActive {
            finishDrag()
            appInsertionActive = false
            return
        }
        if index != selectedProfileIndex { selectProfile(index) }
        appInsertionActive = true
    }

    func insertURL(_ url: URL, at index: Int) {
        let fileExtension = url.pathExtension.lowercased()
        if fileExtension == "app" {
            insertApp(url, at: index)
        } else if fileExtension == "webloc" {
            insertWebloc(url, at: index)
        } else if let scheme = url.scheme?.lowercased(), scheme == "http" || scheme == "https" {
            insertLink(url, at: index)
        } else if url.isFileURL, FileManager.default.fileExists(atPath: url.path) {
            insertFile(url, at: index)
        } else {
            QuickOrbitNoticeCenter.shared.show(qoText("Dieses Element kann nicht zur Schnellleiste hinzugefügt werden.", "This item can't be added to the quick bar.", language: OrbitStore.shared.config.language))
        }
    }

    /// Each drag operation supplies one destination ID, so all its files and
    /// images are grouped into exactly one newly-created Drop Box.
    func routeExternalDrop(_ url: URL, at index: Int, dropBoxID: UUID? = nil) {
        let standardized = url.standardizedFileURL
        let isApplication = standardized.pathExtension.lowercased() == "app"
        if url.isFileURL,
           !isApplication,
           FileManager.default.fileExists(atPath: standardized.path),
           let dropBoxID = dropBoxID ?? createAutomaticDropBox(at: index) {
            add(
                QuickOrbitMenuDockItem(
                    kind: .file,
                    value: standardized.path,
                    securityScopedBookmark: quickOrbitBookmark(for: standardized)
                ),
                toContainer: dropBoxID
            )
            QuickOrbitNoticeCenter.shared.show(
                qoText("In der Dropbox abgelegt.", "Added to the Drop Box.", language: OrbitStore.shared.config.language)
            )
            return
        }
        insertURL(url, at: index)
    }

    func createDropBoxForExternalDrag(at index: Int) -> UUID? {
        guard !isFull else { return nil }
        let box = QuickOrbitMenuDockItem(
            kind: .dropBoard,
            value: qoText("Dropbox", "Drop box", language: OrbitStore.shared.config.language),
            children: []
        )
        insert(box, at: index)
        QuickOrbitNoticeCenter.shared.show(qoText("Neue Dropbox für die abgelegten Elemente erstellt.", "Created a new Drop Box for the dropped items.", language: OrbitStore.shared.config.language))
        return box.id
    }

    private func createAutomaticDropBox(at index: Int) -> UUID? {
        createDropBoxForExternalDrag(at: index)
    }

    func remove(_ item: QuickOrbitMenuDockItem) {
        withAnimation(.spring(response: 0.24, dampingFraction: 0.84)) {
            items.removeAll { $0.id == item.id }
        }
    }

    func addOrbitAction(_ action: OrbitItem, at index: Int? = nil) {
        guard action.enabled, !["securePassword", "passwordVault"].contains(action.target) else { return }
        var stored = action
        stored.id = UUID()
        insert(
            QuickOrbitMenuDockItem(kind: .orbitAction, value: stored.target, orbitItem: stored),
            at: index ?? items.count
        )
    }

    func addContainer(_ kind: QuickOrbitMenuDockItemKind, at index: Int? = nil) {
        guard kind == .appFolder || kind == .dropBoard else { return }
        let name = kind == .appFolder
            ? qoText("App-Ordner", "App folder", language: OrbitStore.shared.config.language)
            : qoText("Dropbox", "Drop box", language: OrbitStore.shared.config.language)
        insert(QuickOrbitMenuDockItem(kind: kind, value: name, children: []), at: index ?? items.count)
    }

    func mergeIntoFolder(sourceID: UUID, targetID: UUID) -> Bool {
        guard canMergeIntoFolder(sourceID: sourceID, targetID: targetID) else { return false }
        guard sourceID != targetID,
              let sourceIndex = items.firstIndex(where: { $0.id == sourceID }),
              let targetIndex = items.firstIndex(where: { $0.id == targetID }) else { return false }
        let moving = items[sourceIndex]
        var result = items
        if result[targetIndex].kind == .appFolder {
            guard (result[targetIndex].children?.count ?? 0) < 4 else { return false }
            result[targetIndex].children = (result[targetIndex].children ?? []) + [moving]
            result.remove(at: sourceIndex)
        } else {
            let target = result[targetIndex]
            let folder = QuickOrbitMenuDockItem(
                kind: .appFolder,
                value: qoText("Ordner", "Folder", language: OrbitStore.shared.config.language),
                children: [target, moving]
            )
            let lower = min(sourceIndex, targetIndex)
            let upper = max(sourceIndex, targetIndex)
            result.remove(at: upper)
            result.remove(at: lower)
            result.insert(folder, at: lower)
        }
        withAnimation(.spring(response: 0.25, dampingFraction: 0.88)) { items = result }
        return true
    }

    func canMergeIntoFolder(sourceID: UUID, targetID: UUID) -> Bool {
        guard sourceID != targetID,
              let source = items.first(where: { $0.id == sourceID }),
              let target = items.first(where: { $0.id == targetID }),
              Self.canLiveInFolder(source) else { return false }
        switch target.kind {
        case .app, .link, .file, .orbitAction:
            return Self.canLiveInFolder(target)
        case .appFolder:
            return (target.children?.count ?? 0) < 4
        case .dropBoard:
            return false
        }
    }

    func add(_ child: QuickOrbitMenuDockItem, toContainer containerID: UUID) {
        guard let index = items.firstIndex(where: { $0.id == containerID }) else { return }
        let maximum = items[index].kind == .appFolder ? 4 : Self.maximumDropBoardItemCount
        guard items[index].kind == .appFolder || items[index].kind == .dropBoard else { return }
        guard items[index].kind != .appFolder || Self.canLiveInFolder(child) else { return }
        var children = items[index].children ?? []
        guard children.count < maximum else {
            QuickOrbitNoticeCenter.shared.show(qoText("Dieser Ordner ist voll.", "This folder is full.", language: OrbitStore.shared.config.language))
            return
        }
        guard !children.contains(where: { $0.kind == child.kind && $0.value == child.value }) else { showDuplicateNotice(); return }
        children.append(child)
        items[index].children = children
    }

    func removeChild(_ childID: UUID, from containerID: UUID) {
        guard let index = items.firstIndex(where: { $0.id == containerID }) else { return }
        items[index].children?.removeAll { $0.id == childID }
    }

    @discardableResult
    func extractChild(_ childID: UUID, from containerID: UUID) -> Bool {
        guard let index = items.firstIndex(where: { $0.id == containerID }),
              let child = items[index].children?.first(where: { $0.id == childID }) else { return false }
        let replacesEmptyFolder = items[index].children?.count == 1
        guard !isFull || replacesEmptyFolder else { showCapacityNotice(); return false }
        var updated = items
        if replacesEmptyFolder {
            updated[index] = child
        } else {
            updated[index].children?.removeAll { $0.id == childID }
            updated.insert(child, at: index + 1)
        }
        withAnimation(.spring(response: 0.24, dampingFraction: 0.88)) { items = updated }
        return true
    }

    func beginInternalDrag(_ id: UUID) {
        dragCleanupTask?.cancel()
        suppressOpenUntil = .distantFuture
        internalDragID = id
        dragCleanupTask = Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: 3_000_000_000)
            guard !Task.isCancelled, self?.internalDragID == id else { return }
            self?.finishDrag()
        }
    }

    func beginPayloadExport() {
        payloadExportCleanupTask?.cancel()
        payloadExportActive = true
        payloadExportCleanupTask = Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: 2_500_000_000)
            guard !Task.isCancelled else { return }
            self?.endPayloadExport()
        }
    }

    func setDockVisible(_ visible: Bool) {
        if dockVisible != visible { dockVisible = visible }
    }

    func setAuxiliaryPopoverActive(_ active: Bool) {
        if auxiliaryPopoverActive != active { auxiliaryPopoverActive = active }
    }

    func addToDropBoard(_ url: URL) {
        guard url.isFileURL, FileManager.default.fileExists(atPath: url.path) else { return }
        let standardized = url.standardizedFileURL
        guard !dropBoardItems.contains(where: { URL(fileURLWithPath: $0.value).standardizedFileURL == standardized }) else {
            showDuplicateNotice()
            return
        }
        guard dropBoardItems.count < Self.maximumDropBoardItemCount else {
            QuickOrbitNoticeCenter.shared.show(qoText("Das Dropboard ist voll.", "The drop board is full.", language: OrbitStore.shared.config.language))
            return
        }
        let item = QuickOrbitMenuDockItem(kind: .file, value: standardized.path, securityScopedBookmark: quickOrbitBookmark(for: standardized))
        withAnimation(.spring(response: 0.24, dampingFraction: 0.88)) { dropBoardItems.append(item) }
        saveDropBoard()
    }

    func removeFromDropBoard(_ item: QuickOrbitMenuDockItem) {
        withAnimation(.spring(response: 0.22, dampingFraction: 0.9)) { dropBoardItems.removeAll { $0.id == item.id } }
        saveDropBoard()
    }

    private func saveDropBoard() {
        if let data = try? JSONEncoder().encode(dropBoardItems) { UserDefaults.standard.set(data, forKey: dropBoardKey) }
    }

    func endPayloadExport() {
        payloadExportCleanupTask?.cancel()
        payloadExportCleanupTask = nil
        payloadExportActive = false
        auxiliaryPopoverActive = false
    }

    func keepInternalDragAlive() {
        guard let id = internalDragID else { return }
        beginInternalDrag(id)
    }

    func cancelInternalDragSoon() {
        guard let id = internalDragID else { return }
        dragCleanupTask?.cancel()
        dragCleanupTask = Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: 280_000_000)
            guard !Task.isCancelled, self?.internalDragID == id else { return }
            self?.finishDrag()
        }
    }

    func finishDrag() {
        let wasInternalDrag = internalDragID != nil
        dragCleanupTask?.cancel()
        dragCleanupTask = nil
        internalDragID = nil
        externalDragActive = false
        if wasInternalDrag { suppressOpenUntil = Date().addingTimeInterval(0.45) }
    }

    func moveInternalItem(id: UUID, to insertionIndex: Int) {
        guard let sourceIndex = items.firstIndex(where: { $0.id == id }) else { return }
        var result = items
        let moving = result.remove(at: sourceIndex)
        var target = insertionIndex
        if sourceIndex < target { target -= 1 }
        target = min(max(target, 0), result.count)
        guard target != sourceIndex else { return }
        result.insert(moving, at: target)
        withAnimation(.spring(response: 0.23, dampingFraction: 0.82)) { items = result }
    }

    func moveItem(at index: Int, by offset: Int) {
        let destination = index + offset
        guard items.indices.contains(index), items.indices.contains(destination), index != destination else { return }
        withAnimation(.spring(response: 0.22, dampingFraction: 0.84)) {
            items.swapAt(index, destination)
        }
    }

    func open(_ item: QuickOrbitMenuDockItem) {
        guard !appInsertionActive, OrbitStore.shared.editorSlot == nil,
              Date() >= suppressOpenUntil, internalDragID == nil else { return }
        switch item.kind {
        case .app:
            let resource: QuickOrbitResolvedResource?
            if let bookmark = item.securityScopedBookmark {
                var stale = false
                if let url = try? URL(resolvingBookmarkData: bookmark, options: [.withSecurityScope, .withoutUI], relativeTo: nil, bookmarkDataIsStale: &stale) {
                    resource = QuickOrbitResolvedResource(url: url, isSecurityScopeActive: url.startAccessingSecurityScopedResource())
                } else {
                    resource = QuickOrbitResolvedResource(url: URL(fileURLWithPath: item.value), isSecurityScopeActive: false)
                }
            } else {
                let url = URL(fileURLWithPath: item.value)
                resource = QuickOrbitResolvedResource(url: url, isSecurityScopeActive: false)
            }
            guard let resource, FileManager.default.fileExists(atPath: resource.url.path) else {
                QuickOrbitNoticeCenter.shared.show(qoText("Diese App wurde nicht mehr gefunden.", "This app could no longer be found.", language: OrbitStore.shared.config.language))
                return
            }
            let configuration = NSWorkspace.OpenConfiguration()
            configuration.activates = true
            NSWorkspace.shared.openApplication(at: resource.url, configuration: configuration) { _, error in
                resource.stopAccessing()
                if error != nil {
                    Task { @MainActor in
                        QuickOrbitNoticeCenter.shared.show(qoText("Die App konnte nicht geöffnet werden.", "The app couldn't be opened.", language: OrbitStore.shared.config.language))
                    }
                }
            }
        case .link:
            guard let url = URL(string: item.value), ["http", "https"].contains(url.scheme?.lowercased() ?? "") else { return }
            if !NSWorkspace.shared.open(url) {
                QuickOrbitNoticeCenter.shared.show(qoText("Die Webseite konnte nicht geöffnet werden.", "The website couldn't be opened.", language: OrbitStore.shared.config.language))
            }
        case .file:
            let resource: QuickOrbitResolvedResource?
            if let bookmark = item.securityScopedBookmark {
                var stale = false
                if let url = try? URL(resolvingBookmarkData: bookmark, options: [.withSecurityScope, .withoutUI], relativeTo: nil, bookmarkDataIsStale: &stale) {
                    resource = QuickOrbitResolvedResource(url: url, isSecurityScopeActive: url.startAccessingSecurityScopedResource())
                } else { resource = QuickOrbitResolvedResource(url: URL(fileURLWithPath: item.value), isSecurityScopeActive: false) }
            } else {
                resource = QuickOrbitResolvedResource(url: URL(fileURLWithPath: item.value), isSecurityScopeActive: false)
            }
            guard let resource, FileManager.default.fileExists(atPath: resource.url.path) else {
                QuickOrbitNoticeCenter.shared.show(qoText("Diese Datei wurde nicht mehr gefunden.", "This file could no longer be found.", language: OrbitStore.shared.config.language))
                return
            }
            if !NSWorkspace.shared.open(resource.url) {
                QuickOrbitNoticeCenter.shared.show(qoText("Die Datei konnte nicht geöffnet werden.", "The file couldn't be opened.", language: OrbitStore.shared.config.language))
            }
            resource.stopAccessing()
        case .orbitAction:
            guard let action = item.orbitItem, action.enabled else { return }
            OrbitRunner.run(action)
        case .appFolder, .dropBoard:
            break
        }
    }

    func reset() {
        let defaults = UserDefaults.standard
        defaults.removeObject(forKey: itemsKey)
        defaults.removeObject(forKey: hoverDelayKey)
        defaults.removeObject(forKey: autoOpenKey)
        defaults.removeObject(forKey: dockSizeKey)
        defaults.removeObject(forKey: visibilityKey)
        defaults.removeObject(forKey: displayModeKey)
        defaults.removeObject(forKey: orientationKey)
        defaults.removeObject(forKey: hoverMagnificationKey)
        defaults.removeObject(forKey: hideDockInFullscreenKey)
        defaults.removeObject(forKey: hideDockInNearFullscreenKey)
        defaults.removeObject(forKey: dropBoardKey)
        items = []
        profiles = Self.normalizedProfiles([], fallbackItems: [])
        selectedProfileIndex = 0
        defaults.removeObject(forKey: profilesKey)
        defaults.removeObject(forKey: selectedProfileKey)
        defaults.removeObject(forKey: emojiDefaultsKey)
        defaults.removeObject(forKey: exampleDefaultsKey)
        profiles[0].name = "Apps"
        profiles[0].items = Self.defaultAppItems
        profiles[1].name = "Emojis"
        profiles[1].items = Self.defaultEmojiItems
        isSynchronizingProfile = true
        items = profiles[0].items
        isSynchronizingProfile = false
        saveItems()
        defaults.set(true, forKey: emojiDefaultsKey)
        defaults.set(true, forKey: exampleDefaultsKey)
        hoverDelay = 0.62
        autoOpen = true
        dockSize = .compact
        visibility = .nearEdge
        displayMode = .followPointer
        orientation = .horizontal
        hoverMagnification = 1.08
        hideDockInFullscreen = false
        hideDockInNearFullscreen = false
        dropBoardItems = []
        finishDrag()
        payloadExportActive = false
        payloadExportCleanupTask?.cancel()
        payloadExportCleanupTask = nil
    }

    private func insertApp(_ url: URL, at index: Int) {
        let standardized = url.standardizedFileURL
        guard FileManager.default.fileExists(atPath: standardized.path) else { return }
        guard !items.contains(where: { $0.kind == .app && URL(fileURLWithPath: $0.value).standardizedFileURL == standardized }) else {
            showDuplicateNotice()
            return
        }
        let item = QuickOrbitMenuDockItem(kind: .app, value: standardized.path, securityScopedBookmark: quickOrbitBookmark(for: standardized))
        insert(item, at: index)
    }

    private func insertLink(_ url: URL, at index: Int) {
        let value = url.absoluteString
        guard !items.contains(where: { $0.kind == .link && $0.value == value }) else { showDuplicateNotice(); return }
        insert(QuickOrbitMenuDockItem(kind: .link, value: value), at: index)
    }

    private func insertFile(_ url: URL, at index: Int) {
        let standardized = url.standardizedFileURL
        guard !items.contains(where: { $0.kind == .file && URL(fileURLWithPath: $0.value).standardizedFileURL == standardized }) else { showDuplicateNotice(); return }
        insert(
            QuickOrbitMenuDockItem(kind: .file, value: standardized.path, securityScopedBookmark: quickOrbitBookmark(for: standardized)),
            at: index
        )
    }

    private func insertWebloc(_ url: URL, at index: Int) {
        let scoped = url.startAccessingSecurityScopedResource()
        defer { if scoped { url.stopAccessingSecurityScopedResource() } }
        guard let data = try? Data(contentsOf: url),
              let plist = try? PropertyListSerialization.propertyList(from: data, options: [], format: nil) as? [String: Any],
              let string = plist["URL"] as? String,
              let webURL = URL(string: string) else { return }
        insertLink(webURL, at: index)
    }

    private func insert(_ item: QuickOrbitMenuDockItem, at index: Int) {
        guard !isFull else {
            showCapacityNotice()
            return
        }
        let target = min(max(index, 0), items.count)
        withAnimation(.spring(response: 0.27, dampingFraction: 0.82)) { items.insert(item, at: target) }
    }

    private func saveItems() {
        guard let data = try? JSONEncoder().encode(items) else { return }
        UserDefaults.standard.set(data, forKey: itemsKey)
        if let profileData = try? JSONEncoder().encode(profiles) {
            UserDefaults.standard.set(profileData, forKey: profilesKey)
        }
    }

    private func showDuplicateNotice() {
        QuickOrbitNoticeCenter.shared.show(qoText("Dieses Element ist bereits in der Schnellleiste.", "This item is already in the quick bar.", language: OrbitStore.shared.config.language))
    }

    func showCapacityNotice() {
        QuickOrbitNoticeCenter.shared.show(qoText("Dieses Profil hat bereits zehn Belegungen.", "This profile already has ten assignments.", language: OrbitStore.shared.config.language))
    }

    private static func isUsable(_ item: QuickOrbitMenuDockItem) -> Bool {
        switch item.kind {
        case .app:
            if item.securityScopedBookmark != nil { return true }
            return FileManager.default.fileExists(atPath: item.value)
        case .link:
            guard let url = URL(string: item.value) else { return false }
            return ["http", "https"].contains(url.scheme?.lowercased() ?? "")
        case .file:
            if item.securityScopedBookmark != nil { return true }
            return FileManager.default.fileExists(atPath: item.value)
        case .orbitAction:
            guard let action = item.orbitItem else { return false }
            return action.enabled && !["securePassword", "passwordVault"].contains(action.target)
        case .appFolder:
            let children = item.children ?? []
            return children.count <= 4 && children.contains { canLiveInFolder($0) && isUsable($0) }
        case .dropBoard:
            return (item.children ?? []).count <= Self.maximumDropBoardItemCount
        }
    }

    private static func normalizedProfiles(_ decoded: [QuickOrbitMenuDockProfile], fallbackItems: [QuickOrbitMenuDockItem]) -> [QuickOrbitMenuDockProfile] {
        var result = Array(decoded.prefix(profileCount)).enumerated().map { index, profile in
            QuickOrbitMenuDockProfile(
                id: profile.id,
                name: profile.name.isEmpty ? "\(index + 1)" : profile.name,
                items: Array(profile.items.filter(isUsable).map(normalizedContainer).prefix(maximumItemCount))
            )
        }
        if result.isEmpty {
            result.append(QuickOrbitMenuDockProfile(name: "1", items: fallbackItems.map(normalizedContainer)))
        }
        while result.count < profileCount {
            result.append(QuickOrbitMenuDockProfile(name: "\(result.count + 1)", items: []))
        }
        return result
    }

    private static func normalizedContainer(_ item: QuickOrbitMenuDockItem) -> QuickOrbitMenuDockItem {
        guard item.kind == .appFolder || item.kind == .dropBoard else { return item }
        var normalized = item
        let limit = item.kind == .appFolder ? 4 : maximumDropBoardItemCount
        normalized.children = Array((item.children ?? []).filter { canLiveInFolder($0) && isUsable($0) }.prefix(limit))
        return normalized
    }

    private static func canLiveInFolder(_ item: QuickOrbitMenuDockItem) -> Bool {
        switch item.kind {
        case .app, .link, .file, .orbitAction: return true
        case .appFolder, .dropBoard: return false
        }
    }

    private static var defaultAppItems: [QuickOrbitMenuDockItem] {
        [
            "/System/Applications/Messages.app",
            "/System/Applications/Calendar.app",
            "/System/Applications/Notes.app",
            "/System/Applications/Photos.app"
        ].filter { FileManager.default.fileExists(atPath: $0) }
            .map { QuickOrbitMenuDockItem(kind: .app, value: $0) }
    }

    private static var defaultEmojiItems: [QuickOrbitMenuDockItem] {
        QuickOrbitEmojiTemplate.items.map { action in
            return QuickOrbitMenuDockItem(kind: .orbitAction, value: action.target, orbitItem: action)
        }
    }
}

// MARK: - Menu bar and app window

@MainActor
final class FloatingActionEditorController {
    static let shared = FloatingActionEditorController()
    private var panel: NSPanel?

    func show(slot: Int) {
        close()
        let size = CGSize(width: 930, height: 650)
        let visible = NSScreen.main?.visibleFrame ?? CGRect(x: 0, y: 0, width: 1200, height: 800)
        let origin = CGPoint(x: visible.midX - size.width / 2, y: visible.midY - size.height / 2)
        let panel = NSPanel(contentRect: CGRect(origin: origin, size: size), styleMask: [.titled, .closable, .fullSizeContentView], backing: .buffered, defer: false)
        panel.titleVisibility = .hidden
        panel.titlebarAppearsTransparent = true
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = true
        panel.level = .floating
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]
        panel.contentView = NSHostingView(rootView: ActionEditorSheet(slot: slot, onClose: { [weak self] in self?.close() }))
        self.panel = panel
        NSApp.activate(ignoringOtherApps: true)
        panel.makeKeyAndOrderFront(nil)
    }

    func close() { panel?.orderOut(nil); panel = nil }
}

private final class QuickOrbitDockPanel: NSPanel {
    override var canBecomeKey: Bool { true }
    override var canBecomeMain: Bool { false }
}

@MainActor
final class StatusBarController: NSObject {
    static let shared = StatusBarController()

    private var mainStatusItem: NSStatusItem?
    private var arcPanel: NSPanel?
    private var secondaryDockPanels: [CGDirectDisplayID: NSPanel] = [:]
    private var primaryDockScreenID: CGDirectDisplayID?
    private var lastPointerScreenID: CGDirectDisplayID?
    private var fullscreenHiddenScreenIDs: Set<CGDirectDisplayID> = []
    private var screenObserver: NSObjectProtocol?
    private var lastSignature = ""
    private var lastProximityCheck = Date.distantPast
    private var lastFullscreenCheck = Date.distantPast
    private var proximityCloseWorkItem: DispatchWorkItem?
    private var lastProximityPoint: CGPoint?
    private var proximityEnteredAt: Date?
    private var proximityArmed = true
    private var dockItemsCancellable: AnyCancellable?
    private var dockDragCancellable: AnyCancellable?
    private var dockTimerCancellable: AnyCancellable?
    private var dockVisibilityCancellable: AnyCancellable?
    private var dockDisplayModeCancellable: AnyCancellable?
    private var dockOrientationCancellable: AnyCancellable?
    private let dockPositionKey = "QuickOrbit.MenuBarDock.Position"

    private var dockPosition: QuickOrbitMenuDockPosition {
        get {
            guard let raw = UserDefaults.standard.string(forKey: dockPositionKey),
                  let value = QuickOrbitMenuDockPosition(rawValue: raw) else { return .belowCamera }
            return value
        }
        set { UserDefaults.standard.set(newValue.rawValue, forKey: dockPositionKey) }
    }

    private func displayID(_ screen: NSScreen) -> CGDirectDisplayID {
        (screen.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")] as? NSNumber)?.uint32Value ?? 0
    }

    private func screen(at point: CGPoint) -> NSScreen? {
        NSScreen.screens.first(where: { $0.frame.contains(point) }) ?? NSScreen.main
    }

    private var allDockPanels: [NSPanel] {
        (arcPanel.map { [$0] } ?? []) + Array(secondaryDockPanels.values)
    }

    private var visibleDockPanels: [NSPanel] { allDockPanels.filter(\.isVisible) }

    private func hideDockPanels() {
        proximityCloseWorkItem?.cancel()
        proximityCloseWorkItem = nil
        allDockPanels.forEach { $0.orderOut(nil) }
        QuickOrbitMenuDockStore.shared.setDockVisible(false)
    }

    func install() {
        QuickOrbitMenuDockStore.shared.orientation = orientation(for: dockPosition)
        screenObserver = NotificationCenter.default.addObserver(
            forName: NSApplication.didChangeScreenParametersNotification,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor [weak self] in self?.handleScreenParametersChanged() }
        }
        dockDisplayModeCancellable = QuickOrbitMenuDockStore.shared.$displayMode
            .removeDuplicates()
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                guard let self, let button = self.mainStatusItem?.button else { return }
                if !self.visibleDockPanels.isEmpty || QuickOrbitMenuDockStore.shared.visibility == .always {
                    self.showArcPanel(from: button)
                } else {
                    self.removeSecondaryDockPanels()
                }
            }
        dockItemsCancellable = QuickOrbitMenuDockStore.shared.$items
            .removeDuplicates()
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                self?.resizeDockPanelForContents()
                self?.refresh(force: true)
            }
        dockDragCancellable = Publishers.CombineLatest4(
            QuickOrbitMenuDockStore.shared.$externalDragActive.removeDuplicates(),
            QuickOrbitMenuDockStore.shared.$internalDragID.removeDuplicates(),
            QuickOrbitMenuDockStore.shared.$appInsertionActive.removeDuplicates(),
            QuickOrbitMenuDockStore.shared.$dockSize.removeDuplicates()
        )
        .receive(on: RunLoop.main)
        .sink { [weak self] _, _, appInsertionActive, _ in
            self?.resizeDockPanelForContents(includesInsertion: appInsertionActive)
        }
        dockTimerCancellable = QuickOrbitTimerCenter.shared.$states
            .combineLatest(QuickOrbitTimerCenter.shared.$stopwatchStates)
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                guard QuickOrbitMenuDockStore.shared.dockVisible else { return }
                self?.resizeDockPanelForContents()
            }
        dockVisibilityCancellable = QuickOrbitMenuDockStore.shared.$visibility
            .removeDuplicates()
            .receive(on: RunLoop.main)
            .sink { [weak self] mode in
                guard let self, let button = self.mainStatusItem?.button else { return }
                if mode == .always { self.showArcPanel(from: button) }
                else if !self.visibleDockPanels.isEmpty { self.hideDockPanels() }
            }
        dockOrientationCancellable = QuickOrbitMenuDockStore.shared.$orientation
            .removeDuplicates()
            .receive(on: RunLoop.main)
            .sink { [weak self] _ in
                self?.resizeDockPanelForContents()
                self?.refresh(force: true)
            }
        refresh(force: true)
    }

    func refresh(force: Bool = false) {
        let store = OrbitStore.shared
        let items = QuickOrbitMenuDockStore.shared.items
        let signature = ([store.config.menuBarEnabled ? "1" : "0", store.config.menuBarMainSymbol ?? "circle.grid.cross"] + items.map {
            "\($0.kind.rawValue)|\($0.value)|\($0.id.uuidString)"
        }).joined(separator: "#")

        guard force || signature != lastSignature else { return }
        lastSignature = signature

        if store.config.menuBarEnabled {
            if mainStatusItem == nil {
                mainStatusItem = makeMainStatusItem()
            } else {
                updateMainStatusItemAppearance()
            }
            if QuickOrbitMenuDockStore.shared.visibility == .always,
               let button = mainStatusItem?.button,
               visibleDockPanels.isEmpty {
                DispatchQueue.main.async { [weak self, weak button] in
                    guard let self, let button else { return }
                    self.showArcPanel(from: button)
                }
            }
        } else if let mainStatusItem {
            hideDockPanels()
            removeSecondaryDockPanels()
            NSStatusBar.system.removeStatusItem(mainStatusItem)
            self.mainStatusItem = nil
        }

        // Quick actions live in the popover below this one status item. Creating
        // one NSStatusItem per action made QuickOrbit look like several apps.
    }

    private func makeMainStatusItem() -> NSStatusItem {
        let item = NSStatusBar.system.statusItem(withLength: 28)
        if let button = item.button { configureMainStatusButton(button) }
        return item
    }

    private func updateMainStatusItemAppearance() {
        guard let button = mainStatusItem?.button else { return }
        configureMainStatusButton(button)
    }

    private func configureMainStatusButton(_ button: NSStatusBarButton) {
        let symbol = OrbitStore.shared.config.menuBarMainSymbol ?? "circle.grid.cross"
        if let symbolImage = NSImage(systemSymbolName: symbol, accessibilityDescription: "QuickOrbit") {
            let config = NSImage.SymbolConfiguration(pointSize: 12.5, weight: .semibold)
            button.image = symbolImage.withSymbolConfiguration(config)
            button.image?.isTemplate = true
        } else {
            button.image = makeQuickOrbitMenuBarImage()
        }
        button.imageScaling = .scaleProportionallyDown
        button.imagePosition = .imageOnly
        button.toolTip = qoText(
            "Klick: Schnellaktionen · Rechtsklick: Menü",
            "Click: quick actions · Right-click: menu",
            language: OrbitStore.shared.config.language
        )
        button.target = self
        button.action = #selector(clickedMain(_:))
        button.sendAction(on: [.leftMouseUp, .rightMouseUp])
    }

    private func makeQuickOrbitMenuBarImage() -> NSImage {
        let size = NSSize(width: 18, height: 18)
        let image = NSImage(size: size, flipped: false) { _ in
            NSColor.black.setFill()

            let dots: [(CGPoint, CGFloat)] = [
                (CGPoint(x: 4.0, y: 10.8), 2.25),
                (CGPoint(x: 9.0, y: 13.4), 2.45),
                (CGPoint(x: 14.0, y: 10.8), 2.25)
            ]

            for (point, diameter) in dots {
                let rect = NSRect(
                    x: point.x - diameter / 2,
                    y: point.y - diameter / 2,
                    width: diameter,
                    height: diameter
                )
                NSBezierPath(ovalIn: rect).fill()
            }

            let centerRect = NSRect(x: 7.15, y: 4.0, width: 3.7, height: 3.7)
            NSBezierPath(ovalIn: centerRect).fill()
            return true
        }
        image.isTemplate = true
        image.accessibilityDescription = "QuickOrbit"
        return image
    }

    private func statusImage(for item: OrbitItem) -> NSImage? {
        if let icon = IconHelper.image(for: item) {
            let copy = (icon.copy() as? NSImage) ?? icon
            copy.size = NSSize(width: 17, height: 17)
            copy.isTemplate = false
            return copy
        }

        let image = NSImage(systemSymbolName: item.symbol.isEmpty ? item.type.symbol : item.symbol, accessibilityDescription: item.title)
        image?.isTemplate = true
        return image
    }

    @objc private func clickedMain(_ sender: NSStatusBarButton) {
        guard let event = NSApp.currentEvent else { return }
        if event.type == .rightMouseUp {
            showMainMenu()
        } else {
            toggleArcPanel(from: sender)
        }
    }

    private func toggleArcPanel(from button: NSStatusBarButton) {
        if !visibleDockPanels.isEmpty {
            hideDockPanels()
            return
        }
        showArcPanel(from: button)
    }

    func handlePointerProximity(at point: CGPoint) {
        guard !QuickOrbitOCRCenter.shared.isSelecting else { return }
        guard OrbitStore.shared.config.menuBarEnabled,
              let button = mainStatusItem?.button,
              let window = button.window else { return }

        let now = Date()
        guard now.timeIntervalSince(lastProximityCheck) >= 0.03 else { return }
        lastProximityCheck = now
        let pointerScreen = screen(at: point)
        let pointerScreenID = pointerScreen.map(displayID)
        let screenChanged = pointerScreenID != lastPointerScreenID
        if screenChanged {
            lastPointerScreenID = pointerScreenID
            lastProximityPoint = nil
            proximityEnteredAt = nil
        }
        if now.timeIntervalSince(lastFullscreenCheck) >= 0.35 {
            lastFullscreenCheck = now
            let hidden = fullscreenScreensForFrontmostWindow()
            if hidden != fullscreenHiddenScreenIDs {
                fullscreenHiddenScreenIDs = hidden
                if !visibleDockPanels.isEmpty || QuickOrbitMenuDockStore.shared.visibility == .always {
                    showArcPanel(from: button)
                }
            }
        }
        let previousPoint = lastProximityPoint
        lastProximityPoint = point

        let buttonRect = window.convertToScreen(button.convert(button.bounds, to: nil))
        let dockStore = QuickOrbitMenuDockStore.shared
        if dockStore.visibility == .always {
            if dockStore.displayMode == .followPointer,
               pointerScreenID != primaryDockScreenID,
               !dockStore.interactionDragActive,
               !dockStore.auxiliaryPopoverActive {
                showArcPanel(from: button)
            }
            return
        }

        if !visibleDockPanels.isEmpty {
            if QuickOrbitMenuDockStore.shared.auxiliaryPopoverActive {
                proximityCloseWorkItem?.cancel()
                proximityCloseWorkItem = nil
                return
            }
            let insideDock = visibleDockPanels.contains { $0.frame.insetBy(dx: -12, dy: -14).contains(point) }
            let insideButton = buttonRect.insetBy(dx: -8, dy: -8).contains(point)
            if insideDock || insideButton || dockStore.interactionDragActive {
                proximityCloseWorkItem?.cancel()
                proximityCloseWorkItem = nil
            } else if proximityCloseWorkItem == nil {
                let work = DispatchWorkItem { [weak self] in
                    self?.hideDockPanels()
                    self?.proximityEnteredAt = nil
                }
                proximityCloseWorkItem = work
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.16, execute: work)
            }
            return
        }

        guard let pointerScreen, !fullscreenHiddenScreenIDs.contains(displayID(pointerScreen)) else { return }
        let visible = pointerScreen.visibleFrame
        let isBottom = dockPosition == .bottomLeft || dockPosition == .bottomCenter || dockPosition == .bottomRight
        let hotspotX: CGFloat
        switch dockPosition {
        case .topLeft, .bottomLeft: hotspotX = visible.minX + 12
        case .topRight, .bottomRight: hotspotX = visible.maxX - 152
        case .belowCamera, .bottomCenter: hotspotX = visible.midX - 70
        }
        let proximityRect = CGRect(x: hotspotX, y: isBottom ? visible.minY : visible.maxY - 32, width: 140, height: 40)
        if isBottom ? point.y > visible.minY + 48 : point.y < visible.maxY - 48 {
            proximityArmed = true
        }
        guard proximityArmed else { return }

        let movingTowardEdge = previousPoint.map { isBottom ? point.y < $0.y - 0.25 : point.y > $0.y + 0.25 } ?? false
        if proximityRect.contains(point), movingTowardEdge {
            if proximityEnteredAt == nil { proximityEnteredAt = now }
            guard now.timeIntervalSince(proximityEnteredAt ?? now) >= 0.14 else { return }
            proximityCloseWorkItem?.cancel()
            proximityCloseWorkItem = nil
            showArcPanel(from: button)
        } else if !proximityRect.contains(point) {
            proximityEnteredAt = nil
        }
    }

    private func fullscreenScreensForFrontmostWindow() -> Set<CGDirectDisplayID> {
        let dockStore = QuickOrbitMenuDockStore.shared
        guard dockStore.hideDockInFullscreen || dockStore.hideDockInNearFullscreen,
              let frontmost = NSWorkspace.shared.frontmostApplication,
              frontmost.processIdentifier != ProcessInfo.processInfo.processIdentifier else { return [] }
        let options: CGWindowListOption = [.optionOnScreenOnly, .excludeDesktopElements]
        guard let windows = CGWindowListCopyWindowInfo(options, kCGNullWindowID) as? [[String: Any]] else { return [] }
        var hidden: Set<CGDirectDisplayID> = []
        for window in windows {
            guard (window[kCGWindowOwnerPID as String] as? pid_t) == frontmost.processIdentifier,
                  (window[kCGWindowLayer as String] as? Int ?? 1) == 0,
                  let bounds = window[kCGWindowBounds as String] as? [String: Any],
                  let frame = CGRect(dictionaryRepresentation: bounds as CFDictionary),
                  frame.width > 200, frame.height > 160 else { continue }
            for screen in NSScreen.screens where screen.frame.intersects(frame) {
                let overlap = screen.frame.intersection(frame)
                let widthRatio = overlap.width / screen.frame.width
                let heightRatio = overlap.height / screen.frame.height
                let isFullscreen = widthRatio >= 0.97 && heightRatio >= 0.94
                let isNearFullscreen = widthRatio >= 0.88 && heightRatio >= 0.84
                if (dockStore.hideDockInFullscreen && isFullscreen)
                    || (dockStore.hideDockInNearFullscreen && isNearFullscreen) {
                    hidden.insert(displayID(screen))
                }
            }
        }
        return hidden
    }

    private func showArcPanel(from button: NSStatusBarButton) {
        guard !QuickOrbitOCRCenter.shared.isSelecting else { return }
        proximityArmed = false
        proximityEnteredAt = nil
        proximityCloseWorkItem?.cancel()
        proximityCloseWorkItem = nil

        let dockStore = QuickOrbitMenuDockStore.shared
        guard let screen = screen(at: NSEvent.mouseLocation) else { return }
        let targetScreens = dockStore.displayMode == .allDisplays ? NSScreen.screens : [screen]
        let targetIDs = Set(targetScreens.map(displayID))
        for (id, panel) in secondaryDockPanels where !targetIDs.contains(id) {
            panel.orderOut(nil)
            secondaryDockPanels.removeValue(forKey: id)
        }
        if dockStore.displayMode == .followPointer { removeSecondaryDockPanels() }
        guard let primaryScreen = targetScreens.first else { return }
        if arcPanel == nil {
            arcPanel = makeDockPanel()
            configureDockContent(arcPanel!)
        }
        primaryDockScreenID = displayID(primaryScreen)
        if let panel = arcPanel { updateDockPanel(panel, on: primaryScreen) }
        if dockStore.displayMode == .allDisplays {
            for other in targetScreens.dropFirst() {
                let id = displayID(other)
                if secondaryDockPanels[id] == nil {
                    let panel = makeDockPanel()
                    configureDockContent(panel)
                    secondaryDockPanels[id] = panel
                }
                if let panel = secondaryDockPanels[id] { updateDockPanel(panel, on: other) }
            }
        }
        dockStore.setDockVisible(!visibleDockPanels.isEmpty)
    }

    private func makeDockPanel() -> NSPanel {
        let panel = QuickOrbitDockPanel(contentRect: CGRect(x: 0, y: 0, width: 230, height: 80), styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
        panel.level = .floating
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = false
        panel.hidesOnDeactivate = false
        panel.becomesKeyOnlyIfNeeded = true
        panel.isMovable = false
        panel.isMovableByWindowBackground = false
        panel.animationBehavior = .none
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .ignoresCycle]
        return panel
    }

    private func configureDockContent(_ panel: NSPanel) {
        panel.contentView = NSHostingView(rootView: MenuBarArcPopoverView(
            selectedPosition: dockPosition,
            onSelectPosition: { [weak self] position in self?.setQuickDockPosition(position) }
        ))
    }

    private func updateDockPanel(_ panel: NSPanel, on screen: NSScreen) {
        let store = QuickOrbitMenuDockStore.shared
        let size = dockPanelSize(for: store.items.count, includesInsertion: store.appInsertionActive, screen: screen)
        positionDock(panel, screen: screen, position: dockPosition, size: size)
        if fullscreenHiddenScreenIDs.contains(displayID(screen)) { panel.orderOut(nil) }
        else if !panel.isVisible { panel.orderFrontRegardless() }
    }

    private func removeSecondaryDockPanels() {
        secondaryDockPanels.values.forEach { $0.orderOut(nil) }
        secondaryDockPanels.removeAll()
    }

    private func handleScreenParametersChanged() {
        let wasVisible = !visibleDockPanels.isEmpty
        let validIDs = Set(NSScreen.screens.map(displayID))
        for (id, panel) in secondaryDockPanels where !validIDs.contains(id) {
            panel.orderOut(nil)
            secondaryDockPanels.removeValue(forKey: id)
        }
        if wasVisible || QuickOrbitMenuDockStore.shared.visibility == .always,
           let button = mainStatusItem?.button { showArcPanel(from: button) }
    }

    func resetQuickDockPosition() {
        UserDefaults.standard.removeObject(forKey: dockPositionKey)
        QuickOrbitMenuDockStore.shared.orientation = .horizontal
        resizeDockPanelForContents()
    }

    func closeQuickDockAfterPayloadDrag() {
        hideDockPanels()
    }

    func setQuickDockPosition(_ position: QuickOrbitMenuDockPosition) {
        dockPosition = position
        QuickOrbitMenuDockStore.shared.orientation = orientation(for: position)
        for panel in allDockPanels { configureDockContent(panel) }
        resizeDockPanelForContents()
        if let button = mainStatusItem?.button {
            if visibleDockPanels.isEmpty { showArcPanel(from: button) }
        }
    }

    private func orientation(for position: QuickOrbitMenuDockPosition) -> QuickOrbitMenuDockOrientation {
        switch position {
        case .topLeft, .topRight, .bottomLeft, .bottomRight:
            return .vertical
        case .belowCamera, .bottomCenter:
            return .horizontal
        }
    }

    private func positionDock(
        _ panel: NSPanel,
        screen: NSScreen?,
        position: QuickOrbitMenuDockPosition,
        size requestedSize: CGSize? = nil,
        animate: Bool = false
    ) {
        guard let screen else { return }
        let visible = screen.visibleFrame
        let margin: CGFloat = 12
        let panelSize = requestedSize ?? panel.frame.size
        let x: CGFloat
        let y: CGFloat
        switch position {
        case .topLeft:
            x = visible.minX + margin
            y = visible.maxY - panelSize.height - margin
        case .belowCamera:
            x = visible.midX - panelSize.width / 2
            y = visible.maxY - panelSize.height - margin
        case .topRight:
            x = visible.maxX - panelSize.width - margin
            y = visible.maxY - panelSize.height - margin
        case .bottomLeft:
            x = visible.minX + margin
            y = visible.minY + margin
        case .bottomCenter:
            x = visible.midX - panelSize.width / 2
            y = visible.minY + margin
        case .bottomRight:
            x = visible.maxX - panelSize.width - margin
            y = visible.minY + margin
        }
        let frame = CGRect(
            x: x,
            y: y,
            width: panelSize.width,
            height: panelSize.height
        )
        panel.setFrame(clampedDockFrame(frame, inside: visible), display: true, animate: animate)
    }

    private func clampedDockFrame(_ frame: CGRect, inside visible: CGRect) -> CGRect {
        let safeWidth = min(frame.width, max(138, visible.width - 16))
        let safeHeight = min(frame.height, max(138, visible.height - 16))
        return CGRect(
            x: min(max(frame.minX, visible.minX + 8), visible.maxX - safeWidth - 8),
            y: min(max(frame.minY, visible.minY + 8), visible.maxY - safeHeight - 8),
            width: safeWidth,
            height: safeHeight
        )
    }

    private func dockPanelSize(for itemCount: Int, includesInsertion: Bool = false, screen: NSScreen? = nil) -> CGSize {
        let metrics = QuickOrbitMenuDockStore.shared.dockSize
        let orientation = QuickOrbitMenuDockStore.shared.orientation
        let assignedItems = min(itemCount, QuickOrbitMenuDockStore.maximumItemCount)
        let showsInsertion = includesInsertion && assignedItems < QuickOrbitMenuDockStore.maximumItemCount
        let showsTimer = QuickOrbitTimerCenter.shared.states.values.contains { $0.endDate > Date() }
        let liveCount = (showsTimer ? 1 : 0) + (QuickOrbitTimerCenter.shared.stopwatchStates.isEmpty ? 0 : 1)
        let visibleItems = assignedItems + (showsInsertion ? 1 : 0)
        let boardAreaWidth = 20 + metrics.spacing
        let liveAreaWidth: CGFloat = liveCount > 0 ? CGFloat(liveCount) * (metrics.iconSize * 1.55 + metrics.spacing) + 1 + metrics.spacing : 0
        let fixedWidth: CGFloat = boardAreaWidth + liveAreaWidth + metrics.horizontalPadding * 2
        let itemWidth = CGFloat(visibleItems) * metrics.iconSize + CGFloat(max(visibleItems - 1, 0)) * metrics.spacing
        let contentWidth = fixedWidth + itemWidth
        let maximumWidth = max(180, (screen?.visibleFrame.width ?? NSScreen.main?.visibleFrame.width ?? 900) - 32)
        let emptyWidth: CGFloat = showsInsertion ? max(contentWidth, 148) : max(230, contentWidth)
        let resolvedWidth = itemCount == 0 ? emptyWidth : contentWidth
        if orientation.isVertical {
            let visibleRows = max(visibleItems, itemCount == 0 ? 1 : 0) + 1 + liveCount
            let contentHeight = metrics.horizontalPadding * 2
                + CGFloat(visibleRows) * metrics.iconSize
                + CGFloat(max(visibleRows - 1, 0)) * metrics.spacing
            let maximumHeight = max(180, (screen?.visibleFrame.height ?? NSScreen.main?.visibleFrame.height ?? 700) - 32)
            return CGSize(
                width: metrics.panelHeight,
                height: min(max(contentHeight, 138), maximumHeight)
            )
        }
        return CGSize(width: min(max(resolvedWidth, 138), maximumWidth), height: metrics.panelHeight)
    }

    private func resizeDockPanelForContents(includesInsertion: Bool? = nil) {
        let store = QuickOrbitMenuDockStore.shared
        for panel in allDockPanels {
            let id = panel === arcPanel ? primaryDockScreenID : secondaryDockPanels.first(where: { $0.value === panel })?.key
            guard let screen = NSScreen.screens.first(where: { displayID($0) == id }) ?? panel.screen else { continue }
            let size = dockPanelSize(for: store.items.count, includesInsertion: includesInsertion ?? store.appInsertionActive, screen: screen)
            if panel.frame.size != size {
                positionDock(panel, screen: screen, position: dockPosition, size: size, animate: panel.isVisible)
            }
        }
    }

    private func showMainMenu() {
        guard let statusItem = mainStatusItem else { return }

        let menu = NSMenu(title: "QuickOrbit")
        let open = NSMenuItem(title: qoText("QuickOrbit öffnen", "Open QuickOrbit", language: OrbitStore.shared.config.language), action: #selector(openApp), keyEquivalent: "")
        open.target = self
        let appImage = (quickOrbitAppIcon.copy() as? NSImage) ?? quickOrbitAppIcon
        appImage.size = NSSize(width: 18, height: 18)
        open.image = appImage
        menu.addItem(open)

        let test = NSMenuItem(title: qoText("Quick-Menü anzeigen", "Show quick menu", language: OrbitStore.shared.config.language), action: #selector(showOrbit), keyEquivalent: "")
        test.target = self
        test.image = NSImage(systemSymbolName: "circle.grid.cross", accessibilityDescription: test.title)
        menu.addItem(test)

        let positionItem = NSMenuItem(title: qoText("Position der Schnellleiste", "Quick bar position", language: OrbitStore.shared.config.language), action: nil, keyEquivalent: "")
        positionItem.image = NSImage(systemSymbolName: "rectangle.inset.filled.and.person.filled", accessibilityDescription: positionItem.title)
        let positionMenu = NSMenu(title: positionItem.title)
        for (index, position) in QuickOrbitMenuDockPosition.allCases.enumerated() {
            let choice = NSMenuItem(title: position.title(language: OrbitStore.shared.config.language), action: #selector(selectDockPositionFromMenu(_:)), keyEquivalent: "")
            choice.target = self
            choice.tag = index
            choice.state = position == dockPosition ? .on : .off
            choice.image = NSImage(systemSymbolName: position.symbol, accessibilityDescription: choice.title)
            positionMenu.addItem(choice)
        }
        positionItem.submenu = positionMenu
        menu.addItem(positionItem)

        let quickActions = Array(QuickOrbitMenuDockStore.shared.items.enumerated())
        if !quickActions.isEmpty {
            menu.addItem(.separator())
            for (index, action) in quickActions.prefix(8) {
                let item = NSMenuItem(title: action.title, action: #selector(runMenuBarMenuAction(_:)), keyEquivalent: "")
                item.target = self
                item.tag = index
                if action.kind == .app || action.kind == .file {
                    let icon = AppIconCache.shared.icon(for: action.value)
                    let copy = (icon.copy() as? NSImage) ?? icon
                    copy.size = NSSize(width: 17, height: 17)
                    item.image = copy
                } else if let orbitItem = action.orbitItem {
                    item.image = statusImage(for: orbitItem)
                } else {
                    item.image = NSImage(systemSymbolName: action.kind == .link ? "globe" : "doc", accessibilityDescription: action.title)
                }
                menu.addItem(item)
            }
        }

        menu.addItem(.separator())

        let permission = NSMenuItem(title: qoText("Berechtigung prüfen", "Check permission", language: OrbitStore.shared.config.language), action: #selector(permission), keyEquivalent: "")
        permission.target = self
        permission.image = NSImage(systemSymbolName: "hand.raised.fill", accessibilityDescription: permission.title)
        menu.addItem(permission)

        menu.addItem(.separator())

        let quit = NSMenuItem(title: qoText("Beenden", "Quit", language: OrbitStore.shared.config.language), action: #selector(quit), keyEquivalent: "q")
        quit.target = self
        quit.image = NSImage(systemSymbolName: "power", accessibilityDescription: quit.title)
        menu.addItem(quit)

        statusItem.menu = menu
        statusItem.button?.performClick(nil)
        statusItem.menu = nil
    }

    @objc private func runMenuBarMenuAction(_ sender: NSMenuItem) {
        let items = QuickOrbitMenuDockStore.shared.items
        guard items.indices.contains(sender.tag) else { return }
        QuickOrbitMenuDockStore.shared.open(items[sender.tag])
    }

    @objc private func openApp() {
        AppWindow.show()
    }

    @objc private func showOrbit() {
        OrbitController.shared.testMenu()
    }

    @objc private func resetDockPositionFromMenu() {
        resetQuickDockPosition()
        if let button = mainStatusItem?.button { showArcPanel(from: button) }
    }

    @objc private func selectDockPositionFromMenu(_ sender: NSMenuItem) {
        guard QuickOrbitMenuDockPosition.allCases.indices.contains(sender.tag) else { return }
        setQuickDockPosition(QuickOrbitMenuDockPosition.allCases[sender.tag])
    }

    @objc private func permission() {
        OrbitController.shared.requestAccessibility()
    }

    @objc private func quit() {
        NSApp.terminate(nil)
    }
}

struct MenuBarArcPopoverView: View {
    @ObservedObject private var store = QuickOrbitMenuDockStore.shared
    @ObservedObject private var timerCenter = QuickOrbitTimerCenter.shared
    var selectedPosition: QuickOrbitMenuDockPosition = .belowCamera
    var onSelectPosition: (QuickOrbitMenuDockPosition) -> Void = { _ in }
    var embeddedEditing = false
    var onAdd: (() -> Void)? = nil
    @State private var hoveringDock = false
    @State private var insertionIndex: Int?
    @State private var tileFrames: [UUID: CGRect] = [:]
    @State private var dragStartFrames: [UUID: CGRect] = [:]
    @State private var draggedTileID: UUID?
    @State private var targetTileID: UUID?
    @State private var tileDragTranslation: CGSize = .zero
    @State private var folderMergeTargetID: UUID?
    @State private var folderMergeStartedAt = Date.distantPast
    @State private var folderMergeReadyID: UUID?
    @State private var folderMergeProgress: CGFloat = 0

    private var iconSize: CGFloat { store.dockSize.iconSize }
    private var spacing: CGFloat { store.dockSize.spacing }
    private var horizontalPadding: CGFloat { store.dockSize.horizontalPadding }
    private var hasLiveTimer: Bool {
        !embeddedEditing && store.dockVisible && timerCenter.states.values.contains { $0.endDate > Date() }
    }
    private var hasLiveStopwatch: Bool {
        !embeddedEditing && store.dockVisible && !timerCenter.stopwatchStates.isEmpty
    }
    private var editing: Bool { embeddedEditing || store.appInsertionActive }
    private var dockLayout: AnyLayout {
        store.orientation.isVertical
            ? AnyLayout(VStackLayout(spacing: spacing))
            : AnyLayout(HStackLayout(spacing: spacing))
    }

    var body: some View {
        ScrollView(store.orientation.isVertical ? .vertical : .horizontal, showsIndicators: false) {
            dockLayout {
                if hasLiveTimer || hasLiveStopwatch {
                    if hasLiveTimer { QuickOrbitMenuDockLiveTimerTile(size: iconSize) }
                    if hasLiveStopwatch { QuickOrbitMenuDockLiveTimerTile(size: iconSize, stopwatch: true) }
                    Capsule()
                        .fill(Color.white.opacity(0.17))
                        .frame(
                            width: store.orientation.isVertical ? iconSize * 0.56 : 1,
                            height: store.orientation.isVertical ? 1 : iconSize * 0.56
                        )
                        .accessibilityHidden(true)
                }
                QuickOrbitMenuDockProfileDots(interactive: true)
                ForEach(Array(store.items.enumerated()), id: \.element.id) { index, item in
                    QuickOrbitMenuDockItemView(item: item, index: index, totalCount: store.items.count, size: iconSize, editing: editing)
                        .modifier(QuickOrbitMenuDockReorderGesture(
                            itemID: item.id,
                            // Apps may be dragged directly in the visible Dock.
                            // Previously this gesture only existed in the editor,
                            // so holding one live app over another did nothing.
                            enabled: editing || item.kind == .app || draggedTileID != nil,
                            frames: $tileFrames,
                            dragStartFrames: $dragStartFrames,
                            draggedID: $draggedTileID,
                            targetID: $targetTileID,
                            dragTranslation: $tileDragTranslation,
                            folderTargetID: $folderMergeTargetID,
                            folderTargetStartedAt: $folderMergeStartedAt,
                            folderReadyID: $folderMergeReadyID,
                            folderProgress: $folderMergeProgress,
                            isVertical: store.orientation.isVertical
                        ))
                        .transition(.scale(scale: 0.88).combined(with: .opacity))
                }
                if editing && !store.isFull {
                    Button {
                        if let onAdd { onAdd() }
                        else {
                            QuickOrbitDockPickerController.shared.show()
                        }
                    } label: {
                        QuickOrbitMenuDockInsertionTile(size: iconSize)
                    }
                    .buttonStyle(.plain)
                    .help(qoText("Aktion hinzufügen", "Add an action", language: OrbitStore.shared.config.language))
                    .transition(.scale(scale: 0.78).combined(with: .opacity))
                }
                if store.items.isEmpty && !store.anyDragActive && !editing {
                    QuickOrbitMenuDockPlaceholder(height: iconSize)
                        .help(qoText("Belegungen in QuickOrbit verwalten", "Manage assignments in QuickOrbit", language: OrbitStore.shared.config.language))
                }
            }
            .padding(store.orientation.isVertical ? .vertical : .horizontal, horizontalPadding)
            .padding(store.orientation.isVertical ? .horizontal : .vertical, max(8, (store.dockSize.panelHeight - iconSize) / 2))
        }
        .scrollClipDisabled()
        .background {
            ZStack {
                HUDGlass(emphasized: true, blendingMode: .behindWindow)
                Color(red: 0.08, green: 0.08, blue: 0.10).opacity(0.28)
            }
            .clipShape(RoundedRectangle(cornerRadius: 32, style: .continuous))
            .overlay {
                RoundedRectangle(cornerRadius: 32, style: .continuous)
                    .stroke(Color.white.opacity(hoveringDock ? 0.30 : 0.22), lineWidth: 0.9)
            }
            .overlay {
                RoundedRectangle(cornerRadius: 30, style: .continuous)
                    .stroke(Color.white.opacity(hoveringDock ? 0.11 : 0.055), lineWidth: 0.7)
                    .padding(2)
            }
        }
        .overlay {
            if store.anyDragActive {
                QuickOrbitMenuDockDropGlow(external: store.externalDragActive)
                    .allowsHitTesting(false)
            }
        }
        .environment(\.colorScheme, .dark)
        .environment(\.quickOrbitLiveSurface, !embeddedEditing && store.dockVisible)
        .contentShape(RoundedRectangle(cornerRadius: 32, style: .continuous))
        .onHover { hoveringDock = $0 }
        .onPreferenceChange(QuickOrbitMenuDockFramePreferenceKey.self) { value in
            if draggedTileID == nil, tileFrames != value {
                tileFrames = value
            } else if draggedTileID != nil, value.count > tileFrames.count {
                tileFrames = value
            }
        }
        .onDrop(
            of: [.fileURL, .url, .image, .plainText],
            delegate: QuickOrbitMenuDockDropDelegate(
                store: store,
                insertionIndex: $insertionIndex,
                iconSize: iconSize,
                spacing: spacing,
                leadingPadding: horizontalPadding + 20 + spacing + (hasLiveTimer || hasLiveStopwatch ? CGFloat((hasLiveTimer ? 1 : 0) + (hasLiveStopwatch ? 1 : 0)) * ((store.orientation.isVertical ? iconSize : iconSize * 1.55) + spacing) + 1 + spacing : 0),
                isVertical: store.orientation.isVertical
            )
        )
        .animation(.interactiveSpring(response: 0.20, dampingFraction: 0.90), value: insertionIndex)
        .animation(.easeOut(duration: 0.14), value: store.externalDragActive)
        .animation(.interactiveSpring(response: 0.20, dampingFraction: 0.90), value: store.internalDragID)
        .animation(.interactiveSpring(response: 0.22, dampingFraction: 0.91), value: store.items)
        .animation(.easeInOut(duration: 0.18), value: hasLiveTimer)
        .animation(.easeInOut(duration: 0.18), value: hasLiveStopwatch)
        .contextMenu {
            Toggle(qoText("Automatisch auswählen", "Select automatically", language: OrbitStore.shared.config.language), isOn: Binding(
                get: { store.autoOpen },
                set: {
                    store.autoOpen = $0
                    OrbitStore.shared.config.orbitAutoSelect = $0
                }
            ))
            Menu(qoText("Öffnungsgeschwindigkeit", "Opening speed", language: OrbitStore.shared.config.language)) {
                delayButton(qoText("Schnell", "Fast", language: OrbitStore.shared.config.language), 0.35)
                delayButton(qoText("Normal", "Normal", language: OrbitStore.shared.config.language), 0.62)
                delayButton(qoText("Ruhig", "Relaxed", language: OrbitStore.shared.config.language), 0.90)
                delayButton(qoText("Langsam", "Slow", language: OrbitStore.shared.config.language), 1.25)
            }
            .disabled(!store.autoOpen)
            Menu(qoText("Größe", "Size", language: OrbitStore.shared.config.language)) {
                ForEach(QuickOrbitMenuDockSize.allCases) { size in
                    Button {
                        store.dockSize = size
                    } label: {
                        if store.dockSize == size {
                            Label(size.title(language: OrbitStore.shared.config.language), systemImage: "checkmark")
                        } else {
                            Text(size.title(language: OrbitStore.shared.config.language))
                        }
                    }
                }
            }
            Menu(qoText("Anzeige", "Visibility", language: OrbitStore.shared.config.language)) {
                ForEach(QuickOrbitMenuDockVisibility.allCases) { visibility in
                    Button {
                        store.visibility = visibility
                    } label: {
                        if store.visibility == visibility {
                            Label(visibility.title(language: OrbitStore.shared.config.language), systemImage: "checkmark")
                        } else {
                            Text(visibility.title(language: OrbitStore.shared.config.language))
                        }
                    }
                }
            }
            Divider()
            Menu(qoText("Position", "Position", language: OrbitStore.shared.config.language)) {
                ForEach(QuickOrbitMenuDockPosition.allCases) { position in
                    Button { onSelectPosition(position) } label: {
                        if position == selectedPosition {
                            Label(position.title(language: OrbitStore.shared.config.language), systemImage: "checkmark")
                        } else {
                            Label(position.title(language: OrbitStore.shared.config.language), systemImage: position.symbol)
                        }
                    }
                }
            }
            if editing && !embeddedEditing {
                Divider()
                Button(qoText("Bearbeitung beenden", "Finish editing", language: OrbitStore.shared.config.language)) {
                    store.appInsertionActive = false
                }
            }
        }
    }

    @ViewBuilder
    private func delayButton(_ title: String, _ value: Double) -> some View {
        Button { store.hoverDelay = value } label: {
            if abs(store.hoverDelay - value) < 0.01 {
                Label("\(title) · \(value, specifier: "%.2f") s", systemImage: "checkmark")
            } else {
                Text("\(title) · \(value, specifier: "%.2f") s")
            }
        }
    }
}

private struct QuickOrbitMenuDockDropGlow: View {
    let external: Bool
    @State private var pulse = false

    var body: some View {
        ZStack {
            RoundedRectangle(cornerRadius: 32, style: .continuous)
                .stroke(Color.white.opacity(pulse ? 0.76 : 0.38), lineWidth: pulse ? 1.5 : 1)
                .padding(1)
                .scaleEffect(pulse ? 1.004 : 0.998)
                .shadow(color: Color.white.opacity(pulse ? 0.20 : 0.07), radius: pulse ? 10 : 4)
            if external {
                Label(
                    qoText("In Dropbox ablegen", "Drop into Drop Box", language: OrbitStore.shared.config.language),
                    systemImage: "tray.and.arrow.down.fill"
                )
                .font(.caption.weight(.bold))
                .foregroundStyle(Color.white)
                .padding(.horizontal, 12)
                .frame(height: 30)
                .background(Color.black.opacity(0.68), in: Capsule())
                .overlay { Capsule().stroke(Color.white.opacity(0.24), lineWidth: 0.8) }
            }
        }
        .onAppear {
            withAnimation(.easeInOut(duration: 0.70).repeatForever(autoreverses: true)) { pulse = true }
        }
    }
}

private final class QuickOrbitUncheckedItemProvider: @unchecked Sendable {
    let value: NSItemProvider
    init(_ value: NSItemProvider) { self.value = value }
}

@MainActor
private struct QuickOrbitMenuDockDropDelegate: DropDelegate {
    let store: QuickOrbitMenuDockStore
    @Binding var insertionIndex: Int?
    let iconSize: CGFloat
    let spacing: CGFloat
    let leadingPadding: CGFloat
    let isVertical: Bool

    func dropEntered(info: DropInfo) {
        if store.internalDragID == nil {
            guard store.canAcceptExternalDrop else { return }
            store.externalDragActive = true
            // External files belong to the Drop Box regardless of the pointer's
            // exact tile position. Only internal tile drags show an insertion gap.
            insertionIndex = nil
        } else {
            store.keepInternalDragAlive()
            updateIndex(info)
        }
    }

    func dropUpdated(info: DropInfo) -> DropProposal? {
        if store.internalDragID != nil {
            updateIndex(info)
            store.keepInternalDragAlive()
            return DropProposal(operation: .move)
        }
        guard store.canAcceptExternalDrop else { return DropProposal(operation: .cancel) }
        store.externalDragActive = true
        insertionIndex = nil
        return DropProposal(operation: .copy)
    }

    func dropExited(info: DropInfo) {
        insertionIndex = nil
        if store.internalDragID != nil {
            store.cancelInternalDragSoon()
        } else {
            store.externalDragActive = false
        }
    }

    func performDrop(info: DropInfo) -> Bool {
        if let id = store.internalDragID {
            let target = insertionIndex ?? store.items.count
            store.moveInternalItem(id: id, to: target)
            store.finishDrag()
            insertionIndex = nil
            return true
        }
        guard store.canAcceptExternalDrop else {
            store.showCapacityNotice()
            finishExternalDrop()
            return false
        }
        let providers = info.itemProviders(for: [.fileURL, .url, .image, .plainText])
        guard !providers.isEmpty else { finishExternalDrop(); return false }
        let identifiers = [UTType.fileURL.identifier, UTType.url.identifier, UTType.image.identifier, UTType.plainText.identifier]
        var accepted = false
        let availableSlots = store.externalDropCapacity
        if providers.count > availableSlots { store.showCapacityNotice() }
        let target = store.items.count
        let needsDropBox = providers.contains { provider in
            let isAppBundle = provider.suggestedName?.lowercased().hasSuffix(".app") == true
            if isAppBundle { return false }
            if provider.hasItemConformingToTypeIdentifier(UTType.image.identifier) { return true }
            guard provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) else { return false }
            // App bundles remain normal app tiles; all other file drops from
            // this gesture are collected into one new Dropbox.
            return true
        }
        let dropBoxID = needsDropBox ? store.createDropBoxForExternalDrag(at: target) : nil
        if needsDropBox && dropBoxID == nil {
            store.showCapacityNotice()
            finishExternalDrop()
            return false
        }
        for (offset, provider) in providers.prefix(availableSlots).enumerated() {
            guard let identifier = identifiers.first(where: { provider.hasItemConformingToTypeIdentifier($0) }) else { continue }
            accepted = true
            if identifier == UTType.image.identifier {
                let suggestedName = provider.suggestedName
                let providerBox = QuickOrbitUncheckedItemProvider(provider)
                provider.loadFileRepresentation(forTypeIdentifier: identifier) { temporaryURL, _ in
                    if let temporaryURL,
                       let persistedURL = Self.persistTemporaryDrop(temporaryURL, suggestedName: suggestedName) {
                        Task { @MainActor in store.routeExternalDrop(persistedURL, at: target + offset, dropBoxID: dropBoxID) }
                        return
                    }
                    // Some apps provide an in-memory image instead of a promised
                    // file. Accept that representation as well.
                    providerBox.value.loadDataRepresentation(forTypeIdentifier: identifier) { data, _ in
                        guard let data,
                              let persistedURL = Self.persistImageData(data, suggestedName: suggestedName) else {
                            Task { @MainActor in
                                QuickOrbitNoticeCenter.shared.show(qoText("Das Bild konnte nicht übernommen werden.", "The image couldn't be imported.", language: OrbitStore.shared.config.language))
                            }
                            return
                        }
                        Task { @MainActor in store.routeExternalDrop(persistedURL, at: target + offset, dropBoxID: dropBoxID) }
                    }
                }
                continue
            }
            provider.loadItem(forTypeIdentifier: identifier, options: nil) { item, _ in
                Self.resolveDroppedItem(item) { url in
                    Task { @MainActor in
                        if let url {
                            store.routeExternalDrop(url, at: target + offset, dropBoxID: dropBoxID)
                        } else {
                            QuickOrbitNoticeCenter.shared.show(qoText("Das gezogene Element wurde nicht erkannt.", "The dragged item wasn't recognized.", language: OrbitStore.shared.config.language))
                        }
                    }
                }
            }
        }
        finishExternalDrop()
        return accepted
    }

    private func updateIndex(_ info: DropInfo) {
        let step = iconSize + spacing
        let location = isVertical ? info.location.y : info.location.x
        let raw = Int(floor((location - leadingPadding + step / 2) / step))
        insertionIndex = min(max(raw, 0), store.items.count)
    }

    private func finishExternalDrop() {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.04) {
            store.externalDragActive = false
            insertionIndex = nil
        }
    }

    nonisolated private static func resolveDroppedItem(_ item: NSSecureCoding?, completion: @escaping (URL?) -> Void) {
        if let url = item as? URL { completion(url); return }
        if let url = item as? NSURL { completion(url as URL); return }
        if let data = item as? Data {
            if let url = URL(dataRepresentation: data, relativeTo: nil) { completion(url); return }
            if let text = String(data: data, encoding: .utf8) { completion(normalizedURL(from: text)); return }
        }
        if let text = item as? String { completion(normalizedURL(from: text)); return }
        if let text = item as? NSString { completion(normalizedURL(from: text as String)); return }
        completion(nil)
    }

    nonisolated private static func normalizedURL(from text: String) -> URL? {
        let firstLine = text
            .split(whereSeparator: \.isNewline)
            .map(String.init)
            .first(where: { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty })?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        guard !firstLine.isEmpty else { return nil }
        if let url = URL(string: firstLine), url.isFileURL || url.scheme != nil { return url }
        if firstLine.lowercased().hasPrefix("www.") { return URL(string: "https://\(firstLine)") }
        return nil
    }

    nonisolated fileprivate static func persistTemporaryDrop(_ source: URL, suggestedName: String?) -> URL? {
        let manager = FileManager.default
        guard let applicationSupport = manager.urls(for: .applicationSupportDirectory, in: .userDomainMask).first else { return nil }
        let directory = applicationSupport
            .appendingPathComponent("QuickOrbit", isDirectory: true)
            .appendingPathComponent("Dropped Items", isDirectory: true)
        do {
            try manager.createDirectory(at: directory, withIntermediateDirectories: true)
            let originalName = (suggestedName?.isEmpty == false ? suggestedName! : source.lastPathComponent)
            let stem = URL(fileURLWithPath: originalName).deletingPathExtension().lastPathComponent
            let pathExtension = source.pathExtension.isEmpty ? "png" : source.pathExtension
            let safeStem = stem.replacingOccurrences(of: "/", with: "-")
            let destination = directory.appendingPathComponent("\(safeStem)-\(UUID().uuidString.prefix(8)).\(pathExtension)")
            try manager.copyItem(at: source, to: destination)
            return destination
        } catch {
            return nil
        }
    }

    nonisolated static func persistImageData(_ data: Data, suggestedName: String?) -> URL? {
        let manager = FileManager.default
        guard let applicationSupport = manager.urls(for: .applicationSupportDirectory, in: .userDomainMask).first else { return nil }
        let directory = applicationSupport
            .appendingPathComponent("QuickOrbit", isDirectory: true)
            .appendingPathComponent("Dropped Items", isDirectory: true)
        do {
            try manager.createDirectory(at: directory, withIntermediateDirectories: true)
            let rawName = suggestedName?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "Bild"
            let sourceURL = URL(fileURLWithPath: rawName)
            let stem = sourceURL.deletingPathExtension().lastPathComponent.replacingOccurrences(of: "/", with: "-")
            let pathExtension = sourceURL.pathExtension.isEmpty ? "png" : sourceURL.pathExtension
            let destination = directory.appendingPathComponent("\(stem)-\(UUID().uuidString.prefix(8)).\(pathExtension)")
            try data.write(to: destination, options: .atomic)
            return destination
        } catch {
            return nil
        }
    }
}

private struct QuickOrbitMenuDockFramePreferenceKey: PreferenceKey {
    static var defaultValue: [UUID: CGRect] = [:]
    static func reduce(value: inout [UUID: CGRect], nextValue: () -> [UUID: CGRect]) {
        value.merge(nextValue(), uniquingKeysWith: { _, latest in latest })
    }
}

@MainActor
enum QuickOrbitDockFolderTargeting {
    static let holdDuration: TimeInterval = 1.2

    static func candidate(
        pointer: CGPoint,
        sourceID: UUID,
        frames: [UUID: CGRect],
        currentTarget: UUID?,
        canMerge: (UUID) -> Bool
    ) -> UUID? {
        frames
            .filter { entry in
                guard entry.key != sourceID, canMerge(entry.key) else { return false }
                let tolerance: CGFloat = currentTarget == entry.key ? 18 : 10
                return entry.value.insetBy(dx: -tolerance, dy: -tolerance).contains(pointer)
            }
            .min { lhs, rhs in
                hypot(lhs.value.midX - pointer.x, lhs.value.midY - pointer.y)
                    < hypot(rhs.value.midX - pointer.x, rhs.value.midY - pointer.y)
            }?.key
    }

    static func shouldMerge(
        releaseTarget: UUID?,
        previewTarget: UUID?,
        readyTarget: UUID?,
        hoverStartedAt: Date,
        now: Date
    ) -> Bool {
        guard let releaseTarget else { return false }
        return readyTarget == releaseTarget
            || (previewTarget == releaseTarget && now.timeIntervalSince(hoverStartedAt) >= holdDuration)
    }
}

/// Uses the same direct gesture model as the Orbit field editor: the grabbed
/// tile follows the pointer and its neighbours preview their final positions.
private struct QuickOrbitMenuDockReorderGesture: ViewModifier {
    @ObservedObject private var store = QuickOrbitMenuDockStore.shared
    let itemID: UUID
    let enabled: Bool
    @Binding var frames: [UUID: CGRect]
    @Binding var dragStartFrames: [UUID: CGRect]
    @Binding var draggedID: UUID?
    @Binding var targetID: UUID?
    @Binding var dragTranslation: CGSize
    @Binding var folderTargetID: UUID?
    @Binding var folderTargetStartedAt: Date
    @Binding var folderReadyID: UUID?
    @Binding var folderProgress: CGFloat
    let isVertical: Bool
    @State private var folderReadyTask: Task<Void, Never>?

    @ViewBuilder
    func body(content: Content) -> some View {
        if enabled {
            content
            .background {
                GeometryReader { proxy in
                    Color.clear.preference(
                        key: QuickOrbitMenuDockFramePreferenceKey.self,
                        value: [itemID: proxy.frame(in: .global)]
                    )
                }
            }
            .offset(currentOffset)
            .background {
                if targetID == itemID, draggedID != itemID, folderTargetID == nil,
                   let moving = store.items.first(where: { $0.id == draggedID }) {
                    RoundedRectangle(cornerRadius: 15)
                        .stroke(Color.white.opacity(0.8), style: StrokeStyle(lineWidth: 1.2, dash: [4, 3]))
                        .overlay { QuickOrbitMenuDockIcon(item: moving, size: store.dockSize.iconSize * 0.72).opacity(0.28) }
                        .allowsHitTesting(false)
                }
            }
            .background {
                if isFolderCandidate {
                    Circle()
                        .fill(Color.white.opacity(isFolderReady ? 0.15 : 0.07))
                        .overlay {
                            Circle()
                                .stroke(Color.white.opacity(isFolderReady ? 0.34 : 0.12), lineWidth: 0.9)
                        }
                        .scaleEffect(isFolderReady ? 1.10 : 0.78)
                        .shadow(color: Color.black.opacity(isFolderReady ? 0.28 : 0.08), radius: 12)
                        .allowsHitTesting(false)
                }
            }
            .scaleEffect(tileScale)
            .opacity(draggedID != nil && draggedID != itemID ? 0.96 : 1)
            .shadow(color: .black.opacity(draggedID == itemID ? 0.32 : 0), radius: 13, y: 6)
            .overlay {
                if isFolderCandidate {
                    RoundedRectangle(cornerRadius: 15, style: .continuous)
                        .stroke(
                            Color.accentColor.opacity(isFolderReady ? 0.94 : 0.66),
                            style: StrokeStyle(lineWidth: isFolderReady ? 1.8 : 1.25, dash: isFolderReady ? [] : [4, 3])
                        )
                        .overlay {
                            RoundedRectangle(cornerRadius: 15, style: .continuous)
                                .trim(from: 0, to: folderProgress)
                                .stroke(Color.accentColor, style: StrokeStyle(lineWidth: 2.4, lineCap: .round))
                                .padding(-3)
                                .allowsHitTesting(false)
                        }
                        .frame(width: store.dockSize.iconSize + 6, height: store.dockSize.iconSize + 6)
                        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .center)
                        .allowsHitTesting(false)
                }
            }
            .zIndex(draggedID == itemID ? 10_000 : 0)
            .animation(.interactiveSpring(response: 0.16, dampingFraction: 0.94), value: targetID)
            .animation(.interactiveSpring(response: 0.22, dampingFraction: 0.88, blendDuration: 0.02), value: folderReadyID)
            .highPriorityGesture(
                DragGesture(minimumDistance: QuickOrbitUI.reorderMinimumDistance, coordinateSpace: .global)
                    .onChanged(handleChanged)
                    .onEnded(handleEnded)
            )
            .onDisappear { cancelFolderReadyTask() }
        } else {
            content
                .background {
                    GeometryReader { proxy in
                        Color.clear.preference(
                            key: QuickOrbitMenuDockFramePreferenceKey.self,
                            value: [itemID: proxy.frame(in: .global)]
                        )
                    }
                }
        }
    }

    private var isFolderCandidate: Bool {
        folderTargetID == itemID && draggedID != nil && draggedID != itemID &&
        store.canMergeIntoFolder(sourceID: draggedID!, targetID: itemID)
    }

    private var isFolderReady: Bool { folderReadyID == itemID }

    private var tileScale: CGFloat {
        if draggedID == itemID { return folderReadyID == nil ? 1.035 : 0.91 }
        if isFolderCandidate { return 1 }
        return 1
    }

    private var currentOffset: CGSize {
        if draggedID == itemID { return dragTranslation }
        // While a folder is being prepared the target must stay directly under
        // the dragged app instead of sliding aside like a reorder preview.
        if folderTargetID != nil { return .zero }
        guard enabled, let sourceID = draggedID, let targetID, sourceID != targetID else { return .zero }
        let ids = store.items.map(\.id)
        guard let source = ids.firstIndex(of: sourceID),
              let target = ids.firstIndex(of: targetID),
              let original = ids.firstIndex(of: itemID) else { return .zero }
        var preview = ids
        let moved = preview.remove(at: source)
        preview.insert(moved, at: target)
        guard let destinationIndex = preview.firstIndex(of: itemID), destinationIndex != original,
              ids.indices.contains(destinationIndex),
              let from = dragStartFrames[itemID],
              let destination = dragStartFrames[ids[destinationIndex]] else { return .zero }
        return isVertical
            ? CGSize(width: 0, height: destination.midY - from.midY)
            : CGSize(width: destination.midX - from.midX, height: 0)
    }

    private func handleChanged(_ value: DragGesture.Value) {
        guard enabled else { return }
        if draggedID == nil {
            dragStartFrames = frames
            draggedID = itemID
            store.beginInternalDrag(itemID)
            NSHapticFeedbackManager.defaultPerformer.perform(.generic, performanceTime: .now)
        }
        guard draggedID == itemID else { return }
        let availableFrames = dragStartFrames[itemID] != nil && dragStartFrames.count == store.items.count
            ? dragStartFrames : frames
        guard let sourceFrame = availableFrames[itemID] else { return }
        let union = availableFrames.values.reduce(CGRect.null) { $0.union($1) }
        let desiredPosition = isVertical
            ? sourceFrame.midY + value.translation.height
            : sourceFrame.midX + value.translation.width
        let minimum = isVertical ? union.minY : union.minX
        let maximum = isVertical ? union.maxY : union.maxX
        let clampedPosition = union.isNull ? desiredPosition : min(max(desiredPosition, minimum), maximum)
        dragTranslation = isVertical
            ? CGSize(width: 0, height: clampedPosition - sourceFrame.midY)
            : CGSize(width: clampedPosition - sourceFrame.midX, height: 0)
        let candidate = availableFrames
            .filter { $0.key != itemID }
            .min {
                let first = isVertical ? $0.value.midY : $0.value.midX
                let second = isVertical ? $1.value.midY : $1.value.midX
                return abs(first - clampedPosition) < abs(second - clampedPosition)
            }
        guard let candidate else {
            cancelFolderReadyTask()
            targetID = nil
            folderTargetID = nil
            folderReadyID = nil
            folderProgress = 0
            return
        }
        let candidatePosition = isVertical ? candidate.value.midY : candidate.value.midX
        let candidateExtent = isVertical ? candidate.value.height : candidate.value.width
        let threshold = max(candidateExtent * 0.85, 28)
        // The pointer, not the dragged tile's centre, determines folder intent.
        // Grabbing an icon near its edge must not make a one-second hold fail.
        let nextFolder = QuickOrbitDockFolderTargeting.candidate(
            pointer: value.location,
            sourceID: itemID,
            frames: availableFrames,
            currentTarget: folderTargetID,
            canMerge: { store.canMergeIntoFolder(sourceID: itemID, targetID: $0) }
        )
        let nextTarget = nextFolder ?? (abs(candidatePosition - clampedPosition) <= threshold ? candidate.key : nil)
        if nextTarget != targetID || nextFolder != folderTargetID {
            cancelFolderReadyTask()
            targetID = nextTarget
            folderReadyID = nil
            folderProgress = 0
            folderTargetID = nextFolder
            folderTargetStartedAt = Date()
            NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
            if let candidateID = folderTargetID {
                folderReadyTask = Task { @MainActor in
                    await Task.yield()
                    guard !Task.isCancelled else { return }
                    withAnimation(.linear(duration: QuickOrbitDockFolderTargeting.holdDuration)) { folderProgress = 1 }
                    try? await Task.sleep(nanoseconds: 1_200_000_000)
                    guard !Task.isCancelled,
                          draggedID == itemID,
                          targetID == candidateID,
                          folderTargetID == candidateID,
                          store.canMergeIntoFolder(sourceID: itemID, targetID: candidateID) else { return }
                    withAnimation(.interactiveSpring(response: 0.22, dampingFraction: 0.88, blendDuration: 0.02)) {
                        folderReadyID = candidateID
                    }
                    NSHapticFeedbackManager.defaultPerformer.perform(.levelChange, performanceTime: .now)
                }
            }
        }
    }

    private func handleEnded(_ value: DragGesture.Value) {
        guard enabled, draggedID == itemID else { return }
        cancelFolderReadyTask()
        // Re-evaluate the actual drop point. A stationary pointer can end a drag
        // without one final onChanged event, so the preview state alone is not
        // reliable enough to decide whether a one-second hold made a folder.
        let availableFrames = dragStartFrames[itemID] != nil && dragStartFrames.count == store.items.count
            ? dragStartFrames : frames
        let releaseTarget = QuickOrbitDockFolderTargeting.candidate(
            pointer: value.location,
            sourceID: itemID,
            frames: availableFrames,
            currentTarget: folderTargetID,
            canMerge: { store.canMergeIntoFolder(sourceID: itemID, targetID: $0) }
        )
        let shouldMerge = QuickOrbitDockFolderTargeting.shouldMerge(
            releaseTarget: releaseTarget,
            previewTarget: folderTargetID,
            readyTarget: folderReadyID,
            hoverStartedAt: folderTargetStartedAt,
            now: Date()
        )
        if shouldMerge, let releaseTarget,
           store.mergeIntoFolder(sourceID: itemID, targetID: releaseTarget) {
            NSHapticFeedbackManager.defaultPerformer.perform(.levelChange, performanceTime: .now)
        } else if let targetID,
           let source = store.items.firstIndex(where: { $0.id == itemID }),
           let target = store.items.firstIndex(where: { $0.id == targetID }),
           source != target {
            store.moveInternalItem(id: itemID, to: target + (source < target ? 1 : 0))
            NSHapticFeedbackManager.defaultPerformer.perform(.levelChange, performanceTime: .now)
        }
        store.finishDrag()
        draggedID = nil
        targetID = nil
        folderTargetID = nil
        folderReadyID = nil
        folderProgress = 0
        folderTargetStartedAt = .distantPast
        dragStartFrames = [:]
        withAnimation(.spring(response: 0.17, dampingFraction: 0.96)) { dragTranslation = .zero }
    }

    private func cancelFolderReadyTask() {
        folderReadyTask?.cancel()
        folderReadyTask = nil
    }
}

private struct QuickOrbitMenuDockDragBehavior: ViewModifier {
    @ObservedObject private var store = QuickOrbitMenuDockStore.shared
    let item: QuickOrbitMenuDockItem
    let size: CGFloat
    let editing: Bool

    @ViewBuilder
    func body(content: Content) -> some View {
        if editing {
            content
        } else {
            switch item.kind {
            case .file:
                content.onDrag {
                    store.beginPayloadExport()
                    let url = URL(fileURLWithPath: item.value)
                    return NSItemProvider(contentsOf: url) ?? NSItemProvider(object: url as NSURL)
                } preview: {
                    QuickOrbitMenuDockIcon(item: item, size: min(size, 52))
                        .frame(width: min(size, 52), height: min(size, 52))
                        .shadow(color: .black.opacity(0.32), radius: 6, y: 3)
                }
            case .app:
                // Launchable apps are actions, not useful exported payloads.
                // Keeping them non-draggable also prevents accidental app copies.
                content
            case .link:
                content.onDrag {
                    store.beginPayloadExport()
                    guard let url = URL(string: item.value) else { return NSItemProvider() }
                    return NSItemProvider(object: url as NSURL)
                } preview: {
                    QuickOrbitMenuDockIcon(item: item, size: min(size, 52))
                        .frame(width: min(size, 52), height: min(size, 52))
                }
            case .orbitAction:
                if let action = item.orbitItem, QuickOrbitNativeDragPayload.canExport(action) {
                    content.onDrag {
                        guard let payload = QuickOrbitNativeDragPayload.payload(for: action) else { return NSItemProvider() }
                        store.beginPayloadExport()
                        return NSItemProvider(object: payload as NSString)
                    } preview: {
                        Text(QuickOrbitNativeDragPayload.preview(for: action))
                            .font(.system(size: action.insertedEmoji == nil ? 13 : 24, weight: .semibold))
                            .foregroundStyle(Color.white)
                            .shadow(color: Color.black.opacity(0.55), radius: 4, y: 1)
                            .padding(6)
                    }
                } else {
                    content
                }
            case .appFolder, .dropBoard:
                content
            }
        }
    }
}

private struct QuickOrbitMenuDockItemView: View {
    @ObservedObject private var store = QuickOrbitMenuDockStore.shared
    let item: QuickOrbitMenuDockItem
    let index: Int
    let totalCount: Int
    let size: CGFloat
    let editing: Bool
    @State private var hovering = false
    @State private var loading = false
    @State private var hoverTask: Task<Void, Never>?
    @State private var containerPresented = false
    @State private var timerPresented = false
    @State private var schedulePresented = false
    @State private var hoveringPopover = false
    @State private var popoverCloseTask: Task<Void, Never>?

    var body: some View {
        Button {
            guard !store.interactionDragActive else { return }
            if item.kind == .appFolder || item.kind == .dropBoard { containerPresented.toggle() }
            else if editing { return }
            else if isTimerItem { runTimerAction() }
            else if isScheduleItem { schedulePresented.toggle() }
            else { store.open(item) }
        } label: {
            ZStack {
                QuickOrbitMenuDockIcon(item: item, size: size)
                    .scaleEffect(hovering && !store.anyDragActive ? store.hoverMagnification : baseScale)
                    .rotationEffect(.degrees(hovering && !store.anyDragActive ? 0 : baseRotation))
                    .offset(y: hovering && !store.anyDragActive ? 0 : baseYOffset)
                    .shadow(color: Color.black.opacity(hovering ? 0.34 : 0.22), radius: hovering ? 12 : 7, y: hovering ? 7 : 4)
                if let duration = timerDurationTitle {
                    Text(duration)
                        .font(.system(size: max(7, size * 0.15), weight: .bold, design: .rounded))
                        .monospacedDigit()
                        .lineLimit(1)
                        .minimumScaleFactor(0.7)
                        .foregroundStyle(.white)
                        .padding(.horizontal, 4)
                        .padding(.vertical, 2)
                        .background(Color.black.opacity(0.74), in: Capsule())
                        .overlay { Capsule().stroke(Color.white.opacity(0.18), lineWidth: 0.6) }
                        .frame(maxWidth: size - 4, maxHeight: .infinity, alignment: .bottom)
                        .offset(y: size * 0.18)
                        .allowsHitTesting(false)
                }
                if loading {
                    QuickOrbitMenuDockProgressRing(duration: hoverProgressDuration)
                        .frame(width: size + 6, height: size + 6)
                        .allowsHitTesting(false)
                }
                if editing {
                    Image(systemName: "line.3.horizontal")
                        .font(.system(size: 8, weight: .bold))
                        .foregroundStyle(Color.white.opacity(0.90))
                        .frame(width: 20, height: 16)
                        .background(Color.black.opacity(0.54), in: Capsule())
                        .offset(x: size * 0.33, y: -size * 0.33)
                        .allowsHitTesting(false)
                }
            }
            .frame(width: size, height: size)
            .contentShape(RoundedRectangle(cornerRadius: size * 0.30, style: .continuous))
            .opacity(store.internalDragID == item.id ? (editing ? 0.92 : 0.36) : 1)
        }
        .buttonStyle(.plain)
        .animation(.interactiveSpring(response: 0.18, dampingFraction: 0.90, blendDuration: 0.02), value: hovering)
        .help(item.title)
        .onHover { inside in
            if inside, !hovering, !store.interactionDragActive, !editing,
               item.kind == .app || item.kind == .appFolder {
                NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
            }
            hovering = inside
            scheduleHoverOpen(inside)
            schedulePopoverClose()
        }
        .onChange(of: store.anyDragActive) { _, active in if active { cancelHover() } }
        .onChange(of: store.payloadExportActive) { _, active in if active { cancelHover() } }
        .onChange(of: editing) { _, active in
            if active {
                cancelHover()
                timerPresented = false
                schedulePresented = false
            }
        }
        .onDisappear {
            cancelHover()
            popoverCloseTask?.cancel()
            if containerPresented || timerPresented || schedulePresented {
                store.setAuxiliaryPopoverActive(false)
            }
        }
        .modifier(QuickOrbitMenuDockDragBehavior(item: item, size: size, editing: editing))
        .popover(isPresented: $containerPresented, arrowEdge: .bottom) {
            QuickOrbitContainerPopover(containerID: item.id, editing: editing)
                .onHover(perform: popoverHoverChanged)
        }
        .popover(isPresented: $timerPresented, arrowEdge: .bottom) {
            QuickOrbitTimerControlPopover(initialStopwatch: item.orbitItem?.target == "stopwatch")
                .onHover(perform: popoverHoverChanged)
        }
        .popover(isPresented: $schedulePresented, arrowEdge: .bottom) {
            QuickOrbitAgendaPopover()
                .onHover(perform: popoverHoverChanged)
        }
        .onChange(of: containerPresented) { _, _ in updateAuxiliaryPopoverState() }
        .onChange(of: timerPresented) { _, _ in updateAuxiliaryPopoverState() }
        .onChange(of: schedulePresented) { _, _ in updateAuxiliaryPopoverState() }
        .contextMenu {
            Button { store.open(item) } label: {
                Label(openTitle, systemImage: item.kind == .app ? "arrow.up.forward.app" : (item.kind == .link ? "globe" : "doc"))
            }
            .disabled(editing)
            let folderTargets = store.items.filter { store.canMergeIntoFolder(sourceID: item.id, targetID: $0.id) }
            if !folderTargets.isEmpty {
                Menu(qoText("Ordner erstellen mit …", "Make a folder with…", language: OrbitStore.shared.config.language)) {
                    ForEach(folderTargets) { target in
                        Button(target.title) { _ = store.mergeIntoFolder(sourceID: item.id, targetID: target.id) }
                    }
                }
            }
            Divider()
            Button(role: .destructive) { store.remove(item) } label: {
                Label(qoText("Entfernen", "Remove", language: OrbitStore.shared.config.language), systemImage: "trash")
            }
        }
    }

    private var distanceFromCenter: Double { Double(index) - Double(max(totalCount - 1, 0)) / 2 }
    private var isTimerItem: Bool { item.kind == .orbitAction && item.orbitItem?.type == .timer }
    private var timerDurationTitle: String? {
        guard isTimerItem, let target = item.orbitItem?.target, target != "stopwatch" else { return nil }
        return QuickOrbitMenuDockTimer.seconds(for: target).map { quickOrbitCompactDurationLabel(seconds: $0) }
    }
    private var isScheduleItem: Bool {
        guard item.kind == .orbitAction else { return false }
        return item.orbitItem?.target == "showAgenda"
    }
    private var hoverProgressDuration: Double {
        max(store.hoverDelay, 0.24)
    }
    private var openTitle: String {
        switch item.kind {
        case .app: return qoText("App öffnen", "Open app", language: OrbitStore.shared.config.language)
        case .link: return qoText("Link öffnen", "Open link", language: OrbitStore.shared.config.language)
        case .file: return qoText("Datei öffnen", "Open file", language: OrbitStore.shared.config.language)
        case .orbitAction: return qoText("Aktion ausführen", "Run action", language: OrbitStore.shared.config.language)
        case .appFolder: return qoText("Ordner öffnen", "Open folder", language: OrbitStore.shared.config.language)
        case .dropBoard: return qoText("Dropbox öffnen", "Open drop box", language: OrbitStore.shared.config.language)
        }
    }
    private var baseRotation: Double {
        guard distanceFromCenter != 0 else { return 0 }
        return (distanceFromCenter < 0 ? -1 : 1) * min(abs(distanceFromCenter) * 0.55, 1.8)
    }
    private var baseYOffset: CGFloat { CGFloat(min(abs(distanceFromCenter) * 0.55, 2.2)) }
    private var baseScale: CGFloat { CGFloat(max(0.985, 1 - abs(distanceFromCenter) * 0.003)) }

    private func runTimerAction() {
        guard let target = item.orbitItem?.target else { return }
        if target == "timerCustom" {
            timerPresented = true
            return
        }
        guard let profileID = OrbitStore.shared.config.activeProfileID else {
            QuickOrbitNoticeCenter.shared.show(qoText("Wähle zuerst ein Profil aus.", "Choose a profile first.", language: OrbitStore.shared.config.language))
            return
        }
        let profileName = OrbitStore.shared.activeProfile?.name ?? qoText("Profil", "Profile", language: OrbitStore.shared.config.language)
        if target == "stopwatch" {
            QuickOrbitTimerCenter.shared.toggleStopwatch(profileID: profileID)
        } else if let seconds = QuickOrbitMenuDockTimer.seconds(for: target) {
            QuickOrbitTimerCenter.shared.start(seconds: seconds, profileID: profileID, profileName: profileName)
        } else {
            timerPresented = true
        }
    }

    private func scheduleHoverOpen(_ inside: Bool) {
        hoverTask?.cancel()
        loading = false
        guard inside, store.autoOpen, !store.interactionDragActive, !editing else { return }
        hoverTask = Task { @MainActor in
            if item.kind == .appFolder || item.kind == .dropBoard {
                loading = true
                try? await Task.sleep(nanoseconds: UInt64(hoverProgressDuration * 1_000_000_000))
                guard !Task.isCancelled, hovering, !store.interactionDragActive, !editing else { loading = false; return }
                loading = false
                containerPresented = true
                NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
                return
            }
            guard !Task.isCancelled, hovering, !store.interactionDragActive, !editing else { return }
            loading = true
            try? await Task.sleep(nanoseconds: UInt64(hoverProgressDuration * 1_000_000_000))
            guard !Task.isCancelled, hovering, !store.interactionDragActive, !editing, store.autoOpen else { loading = false; return }
            loading = false
            store.open(item)
        }
    }

    private func cancelHover() {
        hoverTask?.cancel()
        hoverTask = nil
        loading = false
    }

    private func updateAuxiliaryPopoverState() {
        store.setAuxiliaryPopoverActive(containerPresented || timerPresented || schedulePresented)
    }

    private func popoverHoverChanged(_ inside: Bool) {
        hoveringPopover = inside
        schedulePopoverClose()
    }

    private func schedulePopoverClose() {
        popoverCloseTask?.cancel()
        guard !hovering, !hoveringPopover else { return }
        popoverCloseTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 450_000_000)
            guard !Task.isCancelled, !hovering, !hoveringPopover,
                  !store.interactionDragActive, NSApp.modalWindow == nil else { return }
            containerPresented = false
            timerPresented = false
            schedulePresented = false
            updateAuxiliaryPopoverState()
        }
    }

    private func acceptContainerDrop(_ providers: [NSItemProvider]) -> Bool {
        guard item.kind == .appFolder || item.kind == .dropBoard else { return false }
        var accepted = false
        let maximum = item.kind == .dropBoard ? QuickOrbitMenuDockStore.maximumDropBoardItemCount : 4
        for provider in providers.prefix(maximum) {
            if item.kind == .dropBoard,
               provider.hasItemConformingToTypeIdentifier(UTType.image.identifier),
               !provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier),
               !provider.hasItemConformingToTypeIdentifier(UTType.url.identifier) {
                accepted = true
                let suggestedName = provider.suggestedName
                let providerBox = QuickOrbitUncheckedItemProvider(provider)
                provider.loadFileRepresentation(forTypeIdentifier: UTType.image.identifier) { temporaryURL, _ in
                    if let temporaryURL,
                       let persistedURL = QuickOrbitMenuDockDropDelegate.persistTemporaryDrop(temporaryURL, suggestedName: suggestedName) {
                        Task { @MainActor in
                            let child = QuickOrbitMenuDockItem(kind: .file, value: persistedURL.path, securityScopedBookmark: quickOrbitBookmark(for: persistedURL))
                            store.add(child, toContainer: item.id)
                            containerPresented = true
                        }
                        return
                    }
                    providerBox.value.loadDataRepresentation(forTypeIdentifier: UTType.image.identifier) { data, _ in
                        guard let data,
                              let persistedURL = QuickOrbitMenuDockDropDelegate.persistImageData(data, suggestedName: suggestedName) else {
                            Task { @MainActor in
                                QuickOrbitNoticeCenter.shared.show(qoText("Das Bild konnte nicht übernommen werden.", "The image couldn't be imported.", language: OrbitStore.shared.config.language))
                            }
                            return
                        }
                        Task { @MainActor in
                            let child = QuickOrbitMenuDockItem(kind: .file, value: persistedURL.path, securityScopedBookmark: quickOrbitBookmark(for: persistedURL))
                            store.add(child, toContainer: item.id)
                            containerPresented = true
                        }
                    }
                }
                continue
            }
            let type = provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) ? UTType.fileURL.identifier : UTType.url.identifier
            guard provider.hasItemConformingToTypeIdentifier(type) else { continue }
            accepted = true
            provider.loadItem(forTypeIdentifier: type, options: nil) { value, _ in
                let resolved: URL?
                if let url = value as? URL { resolved = url }
                else if let url = value as? NSURL { resolved = url as URL }
                else if let data = value as? Data { resolved = URL(dataRepresentation: data, relativeTo: nil) }
                else if let text = value as? String { resolved = URL(string: text) }
                else { resolved = nil }
                guard let url = resolved else { return }
                Task { @MainActor in
                    let child: QuickOrbitMenuDockItem
                    if url.isFileURL {
                        let kind: QuickOrbitMenuDockItemKind = url.pathExtension.lowercased() == "app" ? .app : .file
                        child = QuickOrbitMenuDockItem(kind: kind, value: url.standardizedFileURL.path, securityScopedBookmark: quickOrbitBookmark(for: url))
                    } else {
                        child = QuickOrbitMenuDockItem(kind: .link, value: url.absoluteString)
                    }
                    store.add(child, toContainer: item.id)
                    containerPresented = true
                }
            }
        }
        return accepted
    }
}

private struct QuickOrbitContainerPopover: View {
    @ObservedObject private var store = QuickOrbitMenuDockStore.shared
    @Environment(\.dismiss) private var dismiss
    let containerID: UUID
    var editing = false

    private var container: QuickOrbitMenuDockItem? { store.items.first { $0.id == containerID } }
    private var children: [QuickOrbitMenuDockItem] { container?.children ?? [] }
    private var columnCount: Int { min(max(children.count, 1), 4) }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack {
                Image(systemName: container?.kind == .dropBoard ? "tray.full.fill" : "folder.fill")
                    .foregroundStyle(container?.kind == .dropBoard ? Color.cyan : Color.accentColor)
                Spacer()
                Button(action: chooseContents) {
                    Image(systemName: "plus")
                        .font(.system(size: 11, weight: .bold))
                        .frame(width: 26, height: 26)
                        .background(Color.primary.opacity(0.07), in: Circle())
                }
                .buttonStyle(.plain)
                .disabled(children.count >= (container?.kind == .dropBoard ? QuickOrbitMenuDockStore.maximumDropBoardItemCount : 4))
                Button { dismiss() } label: {
                    Image(systemName: "chevron.down")
                        .font(.system(size: 11, weight: .bold))
                        .frame(width: 26, height: 26)
                        .background(Color.primary.opacity(0.07), in: Circle())
                }
                .buttonStyle(.plain)
                .help(qoText("Ordner schließen", "Close folder", language: OrbitStore.shared.config.language))
            }

            if children.isEmpty {
                Image(systemName: "square.dashed")
                    .font(.system(size: 40, weight: .ultraLight))
                    .foregroundStyle(.secondary)
                    .frame(width: 224, height: 90)
                    .accessibilityLabel(qoText("Leerer Ordner", "Empty folder", language: OrbitStore.shared.config.language))
            } else {
                LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 9), count: columnCount), spacing: 9) {
                    ForEach(children) { child in
                        QuickOrbitContainerChildTile(item: child, editing: editing) {
                            dismiss()
                        }
                        .overlay(alignment: .topTrailing) {
                            if editing {
                                Button {
                                    if store.extractChild(child.id, from: containerID) { dismiss() }
                                } label: {
                                    Image(systemName: "arrow.up.forward")
                                        .font(.system(size: 11, weight: .bold)).padding(7)
                                        .background(.ultraThinMaterial, in: Circle())
                                }.buttonStyle(.plain)
                                .help(qoText("In die Leiste verschieben", "Move to bar", language: OrbitStore.shared.config.language))
                            }
                        }
                        .contextMenu {
                            Button {
                                if store.extractChild(child.id, from: containerID) { dismiss() }
                            } label: {
                                Label(qoText("In die Leiste verschieben", "Move to bar", language: OrbitStore.shared.config.language), systemImage: "arrow.up.forward.square")
                            }
                            Button(role: .destructive) { store.removeChild(child.id, from: containerID) } label: {
                                Label(qoText("Aus Ordner entfernen", "Remove from folder", language: OrbitStore.shared.config.language), systemImage: "trash")
                            }
                        }
                    }
                }
                .frame(width: max(236, CGFloat(columnCount) * 82))
            }

        }
        .padding(15)
        .background(SystemBackdrop())
    }

    private func chooseContents() {
        guard let container else { return }
        let panel = NSOpenPanel()
        panel.allowsMultipleSelection = true
        panel.canChooseDirectories = container.kind == .dropBoard
        panel.canChooseFiles = true
        panel.title = container.kind == .appFolder
            ? qoText("Apps oder Dateien für den Ordner auswählen", "Choose apps or files for the folder", language: OrbitStore.shared.config.language)
            : qoText("Fotos, Dateien oder Ordner auswählen", "Choose photos, files, or folders", language: OrbitStore.shared.config.language)
        guard panel.runModal() == .OK else { return }
        for url in panel.urls {
            let kind: QuickOrbitMenuDockItemKind = url.pathExtension.lowercased() == "app" ? .app : .file
            store.add(
                QuickOrbitMenuDockItem(kind: kind, value: url.standardizedFileURL.path, securityScopedBookmark: quickOrbitBookmark(for: url)),
                toContainer: containerID
            )
        }
    }
}

private struct QuickOrbitContainerChildTile: View {
    @ObservedObject private var store = QuickOrbitMenuDockStore.shared
    let item: QuickOrbitMenuDockItem
    var editing = false
    let onRun: () -> Void
    @State private var hovering = false
    @State private var selecting = false
    @State private var hoverTask: Task<Void, Never>?

    var body: some View {
        Button(action: run) {
            VStack(spacing: 5) {
                ZStack {
                    QuickOrbitMenuDockIcon(item: item, size: 42)
                        .frame(width: 42, height: 42)
                    if selecting {
                        QuickOrbitMenuDockProgressRing(duration: max(store.hoverDelay, 0.24))
                            .frame(width: 50, height: 50)
                    }
                }
                .frame(width: 52, height: 52)
            }
            .frame(maxWidth: .infinity, minHeight: 68)
            .contentShape(RoundedRectangle(cornerRadius: 15, style: .continuous))
        }
        .buttonStyle(.plain)
        .scaleEffect(hovering ? 1.025 : 1)
        .animation(.easeOut(duration: 0.14), value: hovering)
        .help(item.title)
        .accessibilityLabel(item.title)
        .modifier(QuickOrbitMenuDockDragBehavior(item: item, size: 46, editing: editing))
        .onChange(of: editing) { _, _ in hoverTask?.cancel(); selecting = false }
        .onChange(of: store.appInsertionActive) { _, _ in hoverTask?.cancel(); selecting = false }
        .onHover(perform: hoverChanged)
        .onDisappear { hoverTask?.cancel() }
    }

    private func hoverChanged(_ inside: Bool) {
        hoverTask?.cancel()
        hovering = inside
        selecting = false
        guard inside, !editing, !store.appInsertionActive, store.autoOpen, !store.interactionDragActive else { return }
        NSHapticFeedbackManager.defaultPerformer.perform(.alignment, performanceTime: .now)
        hoverTask = Task { @MainActor in
            guard !Task.isCancelled, hovering else { return }
            selecting = true
            try? await Task.sleep(nanoseconds: UInt64(max(store.hoverDelay, 0.24) * 1_000_000_000))
            guard !Task.isCancelled, hovering, !store.interactionDragActive else { selecting = false; return }
            run()
        }
    }

    private func run() {
        hoverTask?.cancel()
        selecting = false
        guard !editing, !store.appInsertionActive, !store.interactionDragActive else { return }
        store.open(item)
        NSHapticFeedbackManager.defaultPerformer.perform(.levelChange, performanceTime: .now)
        onRun()
    }
}

private struct QuickOrbitMenuDockProgressRing: View {
    let duration: Double
    @State private var progress: CGFloat = 0

    var body: some View {
        Circle()
            .trim(from: 0, to: progress)
            .stroke(Color.white.opacity(0.92), style: StrokeStyle(lineWidth: 2, lineCap: .round))
            .rotationEffect(.degrees(-90))
            .shadow(color: Color.white.opacity(0.34), radius: 3)
            .onAppear {
                progress = 0
                withAnimation(.linear(duration: duration)) { progress = 1 }
            }
    }
}

struct QuickOrbitMenuDockIcon: View {
    let item: QuickOrbitMenuDockItem
    let size: CGFloat

    var body: some View {
        switch item.kind {
        case .app:
            if FileManager.default.fileExists(atPath: item.value) {
                Image(nsImage: AppIconCache.shared.icon(for: item.value))
                    .resizable()
                    .interpolation(.high)
                    .scaledToFit()
                    .frame(width: size, height: size)
            } else {
                dockSymbolTile(symbol: "app.dashed", label: item.title)
            }
        case .link:
            dockSymbolTile(symbol: websiteSymbol, label: websiteLabel)
        case .file:
            if let preview = QuickOrbitFilePreviewCache.shared.image(for: item.value) {
                Image(nsImage: preview)
                    .resizable()
                    .interpolation(.high)
                    .scaledToFill()
                    .frame(width: size, height: size)
                    .clipShape(RoundedRectangle(cornerRadius: size * 0.22, style: .continuous))
                    .overlay { RoundedRectangle(cornerRadius: size * 0.22, style: .continuous).stroke(Color.white.opacity(0.20), lineWidth: 0.8) }
            } else {
                Image(nsImage: AppIconCache.shared.icon(for: item.value))
                    .resizable()
                    .interpolation(.high)
                    .scaledToFit()
                    .frame(width: size, height: size)
            }
        case .orbitAction:
            if let action = item.orbitItem {
                FieldIcon(item: action, size: size)
            } else {
                dockSymbolTile(symbol: "bolt.fill", label: item.title)
            }
        case .appFolder, .dropBoard:
            ZStack {
                Circle()
                    .fill(Color.white.opacity(item.kind == .appFolder ? 0.095 : 0.075))
                    .overlay { Circle().stroke(Color.white.opacity(0.19), lineWidth: 0.8) }
                if (item.children ?? []).isEmpty {
                    Image(systemName: item.kind == .appFolder ? "folder.fill" : "tray.and.arrow.down.fill")
                        .font(.system(size: size * 0.38, weight: .semibold))
                        .foregroundStyle(item.kind == .appFolder ? Color.accentColor : Color.cyan)
                } else {
                    LazyVGrid(columns: Array(repeating: GridItem(.fixed(size * 0.30), spacing: 2), count: 2), spacing: 2) {
                        ForEach(Array((item.children ?? []).prefix(4))) { child in
                            QuickOrbitContainerMiniIcon(item: child, size: size * 0.30)
                        }
                    }
                }
            }
            .frame(width: size, height: size)
            .shadow(color: Color.black.opacity(0.18), radius: 5, y: 2)
        }
    }

    private func dockSymbolTile(symbol: String, label: String) -> some View {
        RoundedRectangle(cornerRadius: size * 0.24, style: .continuous)
            .fill(Color.black.opacity(0.62))
            .overlay {
                VStack(spacing: 3) {
                    Image(systemName: symbol).font(.system(size: size * 0.38, weight: .semibold))
                    Text(label.uppercased())
                        .font(.system(size: max(7, size * 0.105), weight: .bold, design: .rounded))
                        .lineLimit(1)
                        .minimumScaleFactor(0.7)
                }
                .foregroundStyle(Color.white.opacity(0.95))
                .padding(6)
            }
            .overlay { RoundedRectangle(cornerRadius: size * 0.24, style: .continuous).stroke(Color.white.opacity(0.20), lineWidth: 0.8) }
            .frame(width: size, height: size)
    }

    private var websiteLabel: String {
        guard let host = URL(string: item.value)?.host else { return "WEB" }
        return String(host.replacingOccurrences(of: "www.", with: "").split(separator: ".").first ?? "WEB")
    }

    private var websiteSymbol: String {
        let host = URL(string: item.value)?.host?.lowercased() ?? ""
        if host.contains("youtube") || host.contains("youtu.be") { return "play.fill" }
        if host.contains("github") { return "chevron.left.forwardslash.chevron.right" }
        if host.contains("google") { return "magnifyingglass" }
        if host.contains("mail") { return "envelope.fill" }
        return "globe"
    }
}

private struct QuickOrbitContainerMiniIcon: View {
    let item: QuickOrbitMenuDockItem
    let size: CGFloat
    var body: some View {
        ZStack {
            Circle()
                .fill(Color.black.opacity(0.22))
                .overlay { Circle().stroke(Color.white.opacity(0.18), lineWidth: 0.55) }
            Group {
                switch item.kind {
                case .app:
                    Image(nsImage: AppIconCache.shared.icon(for: item.value)).resizable().scaledToFit()
                case .file:
                    if let image = QuickOrbitFilePreviewCache.shared.image(for: item.value) {
                        Image(nsImage: image).resizable().scaledToFill()
                    } else {
                        Image(nsImage: AppIconCache.shared.icon(for: item.value)).resizable().scaledToFit()
                    }
                case .link:
                    Image(systemName: "globe").resizable().scaledToFit().padding(2)
                case .orbitAction:
                    if let action = item.orbitItem {
                        FieldIcon(item: action, size: size * 0.8)
                    } else {
                        Image(systemName: "bolt.fill").resizable().scaledToFit().padding(2)
                    }
                case .appFolder, .dropBoard:
                    Image(systemName: "folder.fill").resizable().scaledToFit().padding(2)
                }
            }
            .padding(size * 0.08)
        }
        .frame(width: size, height: size)
        .clipShape(Circle())
    }
}

@MainActor
private final class QuickOrbitFilePreviewCache {
    static let shared = QuickOrbitFilePreviewCache()
    private let cache = NSCache<NSString, NSImage>()
    private let imageExtensions: Set<String> = ["png", "jpg", "jpeg", "heic", "heif", "gif", "tiff", "tif", "webp", "bmp"]

    func image(for path: String) -> NSImage? {
        guard imageExtensions.contains(URL(fileURLWithPath: path).pathExtension.lowercased()) else { return nil }
        let key = path as NSString
        if let cached = cache.object(forKey: key) { return cached }
        guard let image = NSImage(contentsOfFile: path) else { return nil }
        cache.setObject(image, forKey: key)
        return image
    }
}

private struct QuickOrbitDropBoardTile: View {
    @ObservedObject private var store = QuickOrbitMenuDockStore.shared
    let size: CGFloat
    @State private var presented = false
    @State private var dropTargeted = false

    var body: some View {
        Button { presented.toggle() } label: {
            ZStack {
                RoundedRectangle(cornerRadius: size * 0.28, style: .continuous)
                    .fill(Color.cyan.opacity(dropTargeted ? 0.30 : 0.14))
                if store.dropBoardItems.isEmpty {
                    Image(systemName: "folder.badge.plus")
                        .font(.system(size: size * 0.39, weight: .semibold))
                        .foregroundStyle(Color.cyan)
                } else {
                    LazyVGrid(columns: Array(repeating: GridItem(.fixed(size * 0.27), spacing: 3), count: 2), spacing: 3) {
                        ForEach(Array(store.dropBoardItems.prefix(4))) { item in
                            QuickOrbitMenuDockIcon(item: item, size: size * 0.27)
                                .frame(width: size * 0.27, height: size * 0.27)
                        }
                    }
                }
            }
            .frame(width: size, height: size)
            .overlay {
                RoundedRectangle(cornerRadius: size * 0.28, style: .continuous)
                    .stroke(Color.cyan.opacity(dropTargeted ? 0.78 : 0.30), lineWidth: dropTargeted ? 1.5 : 0.9)
            }
            .scaleEffect(dropTargeted ? 1.055 : 1)
            .animation(.spring(response: 0.20, dampingFraction: 0.80), value: dropTargeted)
        }
        .buttonStyle(.plain)
        .help(qoText("Dropboard · Dateien hier ablegen", "Drop board · Drop files here", language: OrbitStore.shared.config.language))
        .onDrop(of: [.fileURL], isTargeted: $dropTargeted, perform: acceptDrop)
        .popover(isPresented: $presented, arrowEdge: .bottom) {
            QuickOrbitDropBoardPopover()
        }
    }

    private func acceptDrop(_ providers: [NSItemProvider]) -> Bool {
        let available = max(QuickOrbitMenuDockStore.maximumDropBoardItemCount - store.dropBoardItems.count, 0)
        guard available > 0 else { return false }
        var accepted = false
        for provider in providers.prefix(available) where provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) {
            accepted = true
            provider.loadItem(forTypeIdentifier: UTType.fileURL.identifier, options: nil) { value, _ in
                let url: URL?
                if let direct = value as? URL { url = direct }
                else if let bridged = value as? NSURL { url = bridged as URL }
                else if let data = value as? Data { url = URL(dataRepresentation: data, relativeTo: nil) }
                else { url = nil }
                guard let url else { return }
                Task { @MainActor in
                    store.addToDropBoard(url)
                    presented = true
                }
            }
        }
        return accepted
    }
}

@MainActor
private final class QuickOrbitDockPickerController: NSObject, NSWindowDelegate {
    static let shared = QuickOrbitDockPickerController()
    private var panel: NSPanel?
    private var backup: OrbitItem?
    private var selection: OrbitItem?
    func show() {
        if let panel { panel.makeKeyAndOrderFront(nil); return }
        backup = OrbitStore.shared.menuBarItem(at: 0)
        selection = nil
        OrbitStore.shared.clearMenuBarItem(0)
        QuickOrbitMenuDockStore.shared.setAuxiliaryPopoverActive(true)
        let view = MenuBarActionEditorSheet(onClose: { [weak self] in self?.panel?.close() }, index: 0, onCommit: { [weak self] in self?.selection = $0 })
        let panel = NSPanel(contentRect: NSRect(x: 0, y: 0, width: 900, height: 680), styleMask: [.titled, .closable, .fullSizeContentView], backing: .buffered, defer: false)
        panel.titleVisibility = .hidden
        panel.titlebarAppearsTransparent = true
        panel.contentView = NSHostingView(rootView: view)
        panel.delegate = self
        self.panel = panel
        panel.center()
        panel.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
    }
    func windowWillClose(_ notification: Notification) {
        if let backup { OrbitStore.shared.setMenuBarItem(backup, at: 0) }
        else { OrbitStore.shared.clearMenuBarItem(0) }
        if let selection {
            let store = QuickOrbitMenuDockStore.shared
            switch selection.type {
            case .app, .file: store.insertURL(URL(fileURLWithPath: selection.target), at: store.items.count)
            case .url:
                if let url = URL(string: selection.target) { store.insertURL(url, at: store.items.count) }
            default: store.addOrbitAction(selection)
            }
        }
        backup = nil; selection = nil; panel = nil
        QuickOrbitMenuDockStore.shared.setAuxiliaryPopoverActive(false)
    }
}

@MainActor
private final class QuickOrbitDropBoxController {
    static let shared = QuickOrbitDropBoxController()
    private var panel: NSPanel?

    func show() {
        panel?.close()
        let panel = NSPanel(contentRect: NSRect(x: 0, y: 0, width: 440, height: 580), styleMask: [.titled, .closable, .fullSizeContentView], backing: .buffered, defer: false)
        panel.titleVisibility = .hidden
        panel.titlebarAppearsTransparent = true
        panel.isMovableByWindowBackground = false
        panel.level = .floating
        panel.hidesOnDeactivate = false
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]
        panel.contentView = NSHostingView(rootView: QuickOrbitDropBoardPopover().frame(width: 440, height: 580).background(SystemBackdrop()))
        let point = NSEvent.mouseLocation
        let bounds = (NSScreen.screens.first { $0.frame.contains(point) } ?? NSScreen.main)?.visibleFrame ?? .zero
        panel.setFrameOrigin(NSPoint(x: min(max(point.x - 220, bounds.minX), max(bounds.minX, bounds.maxX - 440)), y: min(max(point.y - 600, bounds.minY), max(bounds.minY, bounds.maxY - 580))))
        self.panel = panel
        if NSEvent.pressedMouseButtons & 1 != 0 {
            panel.orderFrontRegardless()
        } else {
            panel.makeKeyAndOrderFront(nil)
            NSApp.activate(ignoringOtherApps: true)
        }
    }
}

private struct QuickOrbitDropBoardPopover: View {
    @ObservedObject private var store = QuickOrbitMenuDockStore.shared
    @State private var dropTargeted = false

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack {
                Label(qoText("Dropboard", "Drop board", language: OrbitStore.shared.config.language), systemImage: "folder.fill")
                    .font(.headline)
                    .foregroundStyle(Color.cyan)
                Spacer()
                Button {
                    let picker = NSOpenPanel()
                    picker.canChooseFiles = true
                    picker.canChooseDirectories = true
                    picker.allowsMultipleSelection = true
                    if picker.runModal() == .OK { picker.urls.forEach { store.addToDropBoard($0) } }
                } label: { Image(systemName: "plus").frame(width: 28, height: 28) }
                .quickOrbitGlassButton()
                .help(qoText("Dateien hinzufügen", "Add files", language: OrbitStore.shared.config.language))
                Text("\(store.dropBoardItems.count)/\(QuickOrbitMenuDockStore.maximumDropBoardItemCount)")
                    .font(.caption.monospacedDigit().weight(.semibold))
                    .foregroundStyle(.secondary)
            }
            Text(qoText("Fotos, Dateien und Ordner hier ablegen oder wieder herausziehen.", "Drop photos, files, and folders here or drag them back out.", language: OrbitStore.shared.config.language))
                .font(.caption)
                .foregroundStyle(.secondary)

            if store.dropBoardItems.isEmpty {
                ContentUnavailableView(qoText("Noch leer", "Nothing here yet", language: OrbitStore.shared.config.language), systemImage: "arrow.down.doc", description: Text(qoText("Ziehe etwas auf die Ordnerkachel.", "Drag something onto the folder tile.", language: OrbitStore.shared.config.language)))
                    .frame(width: 270, height: 150)
            } else {
                ScrollView(.vertical, showsIndicators: false) {
                    LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 10), count: 2), spacing: 10) {
                        ForEach(store.dropBoardItems) { item in
                            QuickOrbitDropBoardItemTile(item: item)
                        }
                    }
                }
                .frame(width: 386, height: min(CGFloat((store.dropBoardItems.count + 1) / 2) * 112, 400))
            }
        }
        .padding(16)
        .frame(width: 440, height: 580, alignment: .top)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
        .background(SystemBackdrop())
        .overlay { RoundedRectangle(cornerRadius: 18).stroke(dropTargeted ? Color.accentColor : Color.white.opacity(0.12), style: StrokeStyle(lineWidth: dropTargeted ? 2 : 0.8, dash: dropTargeted ? [6, 4] : [])).allowsHitTesting(false) }
        .contentShape(Rectangle())
        .onDrop(of: [.fileURL, .image], isTargeted: $dropTargeted) { providers in
            let matching = providers.filter { $0.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) || $0.hasItemConformingToTypeIdentifier(UTType.image.identifier) }
            for provider in matching {
                if !provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) {
                    provider.loadDataRepresentation(forTypeIdentifier: UTType.image.identifier) { data, _ in
                        guard let data, let url = QuickOrbitMenuDockDropDelegate.persistImageData(data, suggestedName: nil) else { return }
                        Task { @MainActor in QuickOrbitMenuDockStore.shared.addToDropBoard(url) }
                    }
                    continue
                }
                provider.loadItem(forTypeIdentifier: UTType.fileURL.identifier, options: nil) { value, _ in
                    let url: URL?
                    if let direct = value as? URL { url = direct }
                    else if let string = value as? String { url = URL(string: string) }
                    else if let data = value as? Data { url = URL(dataRepresentation: data, relativeTo: nil) }
                    else { url = nil }
                    guard let url else { return }
                    Task { @MainActor in QuickOrbitMenuDockStore.shared.addToDropBoard(url) }
                }
            }
            return !matching.isEmpty
        }
    }
}

private struct QuickOrbitDropBoardItemTile: View {
    @ObservedObject private var store = QuickOrbitMenuDockStore.shared
    let item: QuickOrbitMenuDockItem
    @State private var hovering = false
    @State private var showPreview = false
    @State private var previewText: String?
    @State private var previewTask: Task<Void, Never>?
    @State private var closeTask: Task<Void, Never>?
    @State private var hoveringPreview = false

    private var previewImage: NSImage? { QuickOrbitFilePreviewCache.shared.image(for: item.value) }

    var body: some View {
        Button { store.open(item) } label: {
            VStack(spacing: 7) {
                QuickOrbitMenuDockIcon(item: item, size: 64)
                    .frame(width: 64, height: 64)
                Text(item.title)
                    .font(.caption.weight(.medium))
                    .lineLimit(1)
                    .minimumScaleFactor(0.72)
            }
            .frame(maxWidth: .infinity, minHeight: 102)
            .contentShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        }
        .buttonStyle(.plain)
        .quickOrbitGlass(cornerRadius: 16, interactive: true)
        .onHover(perform: hoverChanged)
        .onDrag {
            let url = URL(fileURLWithPath: item.value)
            return NSItemProvider(contentsOf: url) ?? NSItemProvider(object: url as NSURL)
        } preview: {
            QuickOrbitMenuDockIcon(item: item, size: 58)
        }
        .contextMenu {
            Button(role: .destructive) { store.removeFromDropBoard(item) } label: {
                Label(qoText("Entfernen", "Remove", language: OrbitStore.shared.config.language), systemImage: "trash")
            }
        }
        .popover(isPresented: $showPreview, arrowEdge: .trailing) {
            previewContent
                .onHover { inside in
                    hoveringPreview = inside
                    if inside { closeTask?.cancel() }
                    else { scheduleClose() }
                }
        }
        .onDisappear { previewTask?.cancel(); closeTask?.cancel() }
    }

    @ViewBuilder
    private var previewContent: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text(item.title)
                .font(.subheadline.weight(.semibold))
                .lineLimit(1)
            if let image = previewImage {
                Image(nsImage: image)
                    .resizable()
                    .scaledToFit()
                    .frame(maxWidth: 300, maxHeight: 220)
                    .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
            } else if let previewText {
                ScrollView {
                    Text(previewText)
                        .font(.system(.caption, design: .monospaced))
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .textSelection(.enabled)
                }
                .frame(width: 300, height: 200)
            } else {
                Label(qoText("Vorschau für diesen Dateityp nicht verfügbar.", "Preview isn't available for this file type.", language: OrbitStore.shared.config.language), systemImage: "doc")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .frame(width: 280, height: 100)
            }
            Text(qoText("Klick zum Öffnen · Ziehen zum Herausnehmen", "Click to open · drag to take out", language: OrbitStore.shared.config.language))
                .font(.caption2)
                .foregroundStyle(.secondary)
        }
        .padding(14)
        .background(SystemBackdrop())
    }

    private func hoverChanged(_ inside: Bool) {
        hovering = inside
        if inside {
            closeTask?.cancel()
            previewTask?.cancel()
            previewTask = Task { @MainActor in
                try? await Task.sleep(nanoseconds: 2_000_000_000)
                guard !Task.isCancelled, hovering else { return }
                if previewImage == nil { previewText = Self.loadTextPreview(path: item.value) }
                showPreview = true
            }
        } else {
            previewTask?.cancel()
            scheduleClose()
        }
    }

    private func scheduleClose() {
        closeTask?.cancel()
        closeTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 450_000_000)
            guard !Task.isCancelled, !hovering, !hoveringPreview else { return }
            showPreview = false
        }
    }

    nonisolated private static func loadTextPreview(path: String) -> String? {
        let allowed = Set(["txt", "md", "csv", "json", "log", "html", "xml"])
        guard allowed.contains(URL(fileURLWithPath: path).pathExtension.lowercased()),
              let file = FileHandle(forReadingAtPath: path) else { return nil }
        defer { try? file.close() }
        guard let data = try? file.read(upToCount: 12_000),
              let text = String(data: data, encoding: .utf8), !text.isEmpty else { return nil }
        return String(text.prefix(8_000))
    }
}

struct QuickOrbitMenuDockEmptyTile: View {
    let dragging: Bool
    @State private var pulse = false

    var body: some View {
        RoundedRectangle(cornerRadius: 20, style: .continuous)
            .fill(Color.white.opacity(dragging ? 0.12 : 0.045))
            .overlay {
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .stroke(Color.white.opacity(dragging ? 0.72 : 0.28), style: StrokeStyle(lineWidth: dragging ? 1.4 : 1, dash: [5, 5]))
                    .padding(5)
            }
            .overlay {
                Image(systemName: dragging ? "arrow.down" : "plus")
                    .font(.system(size: 24, weight: .medium))
                    .foregroundStyle(Color.white.opacity(dragging ? 0.94 : 0.52))
                    .scaleEffect(dragging && pulse ? 1.10 : 1)
            }
            .frame(width: 68, height: 68)
            .onAppear { updatePulse(dragging) }
            .onChange(of: dragging) { _, active in updatePulse(active) }
    }

    private func updatePulse(_ active: Bool) {
        if active {
            pulse = false
            withAnimation(.easeInOut(duration: 0.62).repeatForever(autoreverses: true)) { pulse = true }
        } else {
            withAnimation(.easeOut(duration: 0.12)) { pulse = false }
        }
    }
}

