private struct QuickOrbitTimerControlPopover: View {
    var selectedProfileID: UUID? = nil
    var initialStopwatch = false
    private enum Mode: String, CaseIterable, Identifiable {
        case timer, stopwatch
        var id: String { rawValue }
    }

    @ObservedObject private var timerCenter = QuickOrbitTimerCenter.shared
    @ObservedObject private var store = OrbitStore.shared
    @State private var mode: Mode = .timer
    @State private var hours = 0
    @State private var minutes = 5
    @State private var seconds = 0

    private var profileID: UUID? { selectedProfileID ?? store.config.activeProfileID }
    private var profileName: String { store.profiles.first(where: { $0.id == profileID })?.name ?? qoText("Profil", "Profile", language: store.config.language) }
    private var chosenSeconds: Int { min(max(hours * 3600 + minutes * 60 + seconds, 5), 10_800) }

    var body: some View {
        VStack(alignment: .leading, spacing: 15) {
            HStack {
                Label(qoText("Timer & Stoppuhr", "Timer & Stopwatch", language: store.config.language), systemImage: "timer")
                    .font(.headline.weight(.bold))
                Spacer()
                if let profileID, timerCenter.states[profileID] != nil {
                    Button(role: .destructive) { timerCenter.cancel(profileID: profileID, showNotice: true) } label: {
                        Label(qoText("Stoppen", "Stop", language: store.config.language), systemImage: "stop.fill")
                            .font(.subheadline.weight(.bold))
                            .frame(minWidth: 104, minHeight: 44)
                            .contentShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
                    }
                    .buttonStyle(.plain)
                    .foregroundStyle(Color.red.opacity(0.96))
                    .background(Color.red.opacity(0.14), in: RoundedRectangle(cornerRadius: 12, style: .continuous))
                    .overlay {
                        RoundedRectangle(cornerRadius: 12, style: .continuous)
                            .stroke(Color.red.opacity(0.28), lineWidth: 0.8)
                            .allowsHitTesting(false)
                    }
                    .help(qoText("Timer stoppen", "Stop timer", language: store.config.language))
                }
            }

            Picker("", selection: $mode) {
                Text(qoText("Timer", "Timer", language: store.config.language)).tag(Mode.timer)
                Text(qoText("Stoppuhr", "Stopwatch", language: store.config.language)).tag(Mode.stopwatch)
            }
            .pickerStyle(.segmented)
            .labelsHidden()

            if mode == .timer {
                HStack(spacing: 10) {
                    timeUnit(qoText("Std", "Hrs", language: store.config.language), value: $hours, range: 0...3)
                    timeUnit(qoText("Min", "Min", language: store.config.language), value: $minutes, range: 0...59)
                    timeUnit(qoText("Sek", "Sec", language: store.config.language), value: $seconds, range: 0...59)
                }

                LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 8), count: 4), spacing: 8) {
                    ForEach([300, 600, 900, 1_500, 1_800, 2_700, 3_600], id: \.self) { value in
                        Button(quickOrbitCompactDurationLabel(seconds: value)) { setDuration(value) }
                            .buttonStyle(.plain)
                            .font(.caption.weight(.bold))
                            .frame(maxWidth: .infinity, minHeight: 34)
                            .background(Color.white.opacity(chosenSeconds == value ? 0.14 : 0.065), in: RoundedRectangle(cornerRadius: 10, style: .continuous))
                    }
                }

                Button(action: startTimer) {
                    Label(qoText("Timer starten", "Start timer", language: store.config.language), systemImage: "play.fill")
                        .font(.headline)
                        .frame(maxWidth: .infinity, minHeight: 44)
                }
                .buttonStyle(.plain)
                .foregroundStyle(Color.black)
                .background(Color.orange, in: RoundedRectangle(cornerRadius: 13, style: .continuous))
                .disabled(profileID == nil)
            } else {
                TimelineView(.periodic(from: .now, by: 1)) { context in
                    let elapsed = profileID.flatMap { timerCenter.stopwatchStates[$0]?.total(at: context.date) } ?? 0
                    Text(String(format: "%02d:%02d:%02d", Int(elapsed) / 3600, (Int(elapsed) / 60) % 60, Int(elapsed) % 60))
                        .font(.system(size: 34, weight: .bold, design: .rounded))
                        .monospacedDigit()
                        .frame(maxWidth: .infinity)
                        .padding(.vertical, 12)
                        .quickOrbitGlass(cornerRadius: 15)
                }
                HStack(spacing: 9) {
                    Button {
                        if let profileID { timerCenter.resetStopwatch(profileID: profileID) }
                    } label: {
                        Label(qoText("Zurücksetzen", "Reset", language: store.config.language), systemImage: "arrow.counterclockwise")
                            .frame(maxWidth: .infinity, minHeight: 40)
                    }
                    .buttonStyle(.plain)
                    .quickOrbitGlass(cornerRadius: 12, interactive: true)

                    Button {
                        if let profileID { timerCenter.toggleStopwatch(profileID: profileID) }
                    } label: {
                        let running = profileID.flatMap { timerCenter.stopwatchStates[$0]?.isRunning } ?? false
                        Label(running ? qoText("Pause", "Pause", language: store.config.language) : qoText("Start", "Start", language: store.config.language), systemImage: running ? "pause.fill" : "play.fill")
                            .frame(maxWidth: .infinity, minHeight: 40)
                    }
                    .buttonStyle(.plain)
                    .foregroundStyle(Color.black)
                    .background(Color.orange, in: RoundedRectangle(cornerRadius: 12, style: .continuous))
                }
            }
        }
        .padding(17)
        .frame(width: 390)
        .background(SystemBackdrop())
        .onAppear {
            mode = initialStopwatch ? .stopwatch : .timer
            loadRunningTimer()
            if !initialStopwatch, profileID.flatMap({ timerCenter.states[$0] }) == nil {
                setDuration(store.config.customTimerSeconds ?? 300)
            }
        }
    }

    private func timeUnit(_ title: String, value: Binding<Int>, range: ClosedRange<Int>) -> some View {
        VStack(spacing: 7) {
            Text(title).font(.caption.weight(.semibold)).foregroundStyle(.secondary)
            Stepper(value: value, in: range) {
                Text(String(format: "%02d", value.wrappedValue))
                    .font(.title3.bold().monospacedDigit())
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
        }
        .padding(10)
        .frame(maxWidth: .infinity)
        .quickOrbitGlass(cornerRadius: 13)
    }

    private func setDuration(_ total: Int) {
        hours = total / 3600
        minutes = (total / 60) % 60
        seconds = total % 60
    }

    private func startTimer() {
        guard let profileID else { return }
        timerCenter.start(seconds: chosenSeconds, profileID: profileID, profileName: profileName)
    }

    private func loadRunningTimer() {
        guard let profileID, let state = timerCenter.states[profileID], state.endDate > Date() else { return }
        setDuration(max(5, Int(ceil(state.endDate.timeIntervalSinceNow))))
    }
}

