private struct QuickOrbitMenuDockLiveTimerTile: View {
    let size: CGFloat
    var stopwatch = false
    @ObservedObject private var timerCenter = QuickOrbitTimerCenter.shared
    @ObservedObject private var orbitStore = OrbitStore.shared
    @ObservedObject private var dockStore = QuickOrbitMenuDockStore.shared
    @State private var presented = false

    private var tileWidth: CGFloat { dockStore.orientation.isVertical ? size : size * 1.55 }

    @ViewBuilder
    var body: some View {
        if let profileID = activityProfileID {
            TimelineView(.periodic(from: .now, by: 1)) { context in
                let remaining = stopwatch
                    ? max(0, Int(timerCenter.stopwatchStates[profileID]?.total(at: context.date) ?? 0))
                    : max(0, Int(ceil(timerCenter.states[profileID]?.endDate.timeIntervalSince(context.date) ?? 0)))
                Button { presented.toggle() } label: {
                    HStack(spacing: 5) {
                        Image(systemName: stopwatch ? "stopwatch" : "timer")
                            .font(.system(size: size * 0.23, weight: .semibold))
                            .foregroundStyle(Color.orange)
                        VStack(alignment: .leading, spacing: 2) {
                            if !dockStore.orientation.isVertical {
                                Text(stopwatch ? qoText("Stoppuhr", "Stopwatch", language: orbitStore.config.language) : qoText("Timer", "Timer", language: orbitStore.config.language))
                                    .font(.system(size: 8, weight: .semibold))
                                    .foregroundStyle(.secondary)
                            }
                            Text(String(format: "%d:%02d", remaining / 60, remaining % 60))
                                .font(.system(size: max(9, size * 0.17), weight: .bold, design: .rounded))
                                .monospacedDigit()
                                .foregroundStyle(Color.primary)
                        }
                    }
                    .frame(width: tileWidth, height: size)
                    .background(Color.orange.opacity(0.10), in: RoundedRectangle(cornerRadius: size * 0.30, style: .continuous))
                    .overlay { RoundedRectangle(cornerRadius: size * 0.30, style: .continuous).stroke(Color.orange.opacity(0.32), lineWidth: 0.9) }
                }
                .buttonStyle(.plain)
                .help(stopwatch ? qoText("Stoppuhr öffnen", "Open stopwatch", language: orbitStore.config.language) : qoText("Timer öffnen", "Open timer", language: orbitStore.config.language))
                .popover(isPresented: $presented, arrowEdge: .bottom) {
                    QuickOrbitTimerControlPopover(selectedProfileID: profileID, initialStopwatch: stopwatch)
                }
                .onChange(of: presented) { _, active in
                    QuickOrbitMenuDockStore.shared.setAuxiliaryPopoverActive(active)
                }
            }
        }
    }

    private var activityProfileID: UUID? {
        if stopwatch {
            if let id = orbitStore.config.activeProfileID, timerCenter.stopwatchStates[id] != nil { return id }
            return timerCenter.stopwatchStates.keys.sorted { $0.uuidString < $1.uuidString }.first
        }
        let active = timerCenter.states.filter { $0.value.endDate > Date() }
        if let profileID = orbitStore.config.activeProfileID, active[profileID] != nil {
            return profileID
        }
        return active.min(by: { $0.value.endDate < $1.value.endDate })?.key
    }
}

