                    .buttonStyle(.plain)
                    .keyboardShortcut(.cancelAction)
                    .help(qoText("Schließen", "Close", language: store.config.language))
                }

                QuickOrbitLogoView(size: 96, cornerRadius: 23)
                    .padding(.top, 2)

                HStack(spacing: 9) {
                    Text("QuickOrbit")
                        .font(.system(size: 30, weight: .bold, design: .rounded))
                    Text(quickOrbitVersionLabel)
                        .font(.caption.weight(.bold))
                        .foregroundStyle(Color.accentColor)
                        .padding(.horizontal, 9)
                        .padding(.vertical, 5)
                        .background(Color.accentColor.opacity(0.10), in: Capsule())
                }
                .padding(.top, 12)

                Text(qoText("Schneller ohne Umwege.", "Faster, without detours.", language: store.config.language))
                    .font(.subheadline.weight(.medium))
                    .foregroundStyle(.secondary)
                    .padding(.top, 3)

                HStack(spacing: 8) {
                    AboutBadge(symbol: "macbook", text: "macOS")
                    AboutBadge(
                        symbol: accessibilityTrusted ? "checkmark.circle.fill" : "exclamationmark.circle.fill",
                        text: accessibilityTrusted
                            ? qoText("Bereit", "Ready", language: store.config.language)
                            : qoText("Zugriff fehlt", "Access needed", language: store.config.language)
                    )
                }
                .padding(.top, 18)

                Text(qoText("Von Nico · Idee, Design & Entwicklung", "By Nico · idea, design & development", language: store.config.language))
                    .font(.caption.weight(.medium))
                    .foregroundStyle(.secondary)
                    .padding(.top, 14)

                HStack(spacing: 10) {
                    Button(action: onOpenApp) {
                        Label(qoText("Info öffnen", "Open Info", language: store.config.language), systemImage: "info.circle.fill")
                    }
                    .quickOrbitColorButton(.blue)
                    .controlSize(.large)

                    if let websiteURL = quickOrbitWebsiteURL {
                        Link(destination: websiteURL) {
                            Label(qoText("Website", "Website", language: store.config.language), systemImage: "globe")
                        }
                        .quickOrbitGlassButton()
                        .controlSize(.large)
                    }

                    Link(destination: discordURL) {
                        Label("Discord", systemImage: "bubble.left.and.bubble.right.fill")
                    }
                    .quickOrbitDiscordButton()
                    .controlSize(.large)
                }
                .padding(.top, 20)

                Text("© 2026 QuickOrbit")
                    .font(.caption2)
                    .foregroundStyle(.tertiary)
                    .padding(.top, 16)
            }
            .padding(22)
        }
        .frame(width: 560, height: 430)
        .onAppear { accessibilityTrusted = AXIsProcessTrusted() }
    }
}

@MainActor
final class QuickOrbitAboutWindowController {
    static let shared = QuickOrbitAboutWindowController()
    private var panel: NSPanel?

    func show() {
        if let panel {
            panel.center()
            panel.makeKeyAndOrderFront(nil)
            NSApp.activate(ignoringOtherApps: true)
            return
        }

        let panel = NSPanel(
            contentRect: CGRect(origin: .zero, size: CGSize(width: 560, height: 430)),
            styleMask: [.titled, .closable, .fullSizeContentView],
            backing: .buffered,
            defer: false
        )
        panel.title = qoText("Über QuickOrbit", "About QuickOrbit", language: OrbitStore.shared.config.language)
        panel.titleVisibility = .hidden
        panel.titlebarAppearsTransparent = true
        panel.isMovableByWindowBackground = true
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.isReleasedWhenClosed = false
        panel.standardWindowButton(.zoomButton)?.isHidden = true
        panel.standardWindowButton(.miniaturizeButton)?.isHidden = true
        panel.contentView = NSHostingView(rootView: QuickOrbitMenuAboutView(
            onOpenApp: { [weak panel] in
                panel?.orderOut(nil)
                AppWindow.show(section: .info)
            },
            onClose: { [weak panel] in panel?.orderOut(nil) }
        ))
        panel.center()
        panel.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        self.panel = panel
    }
}

enum AppWindow {
    @MainActor
    static func show(section: MainSection? = nil, menuBarEditorIndex: Int? = nil) {
        if let section {
            AppNavigation.shared.open(section, menuBarEditorIndex: menuBarEditorIndex)
        }
        NSApp.activate(ignoringOtherApps: true)

        if let window = NSApp.windows.first(where: { !($0 is NSPanel) && $0.canBecomeKey }) {
            window.makeKeyAndOrderFront(nil)
            return
        }

        NSApp.sendAction(#selector(NSWindow.newWindowForTab(_:)), to: nil, from: nil)
    }
}

// MARK: - GitHub releases and signed application updates

enum QuickOrbitUpdateStatus {
    case idle, checking, current, available, unavailable, error

    var symbol: String {
        switch self {
        case .idle: return "arrow.triangle.2.circlepath"
        case .checking: return "arrow.triangle.2.circlepath"
        case .current: return "checkmark.circle.fill"
        case .available: return "arrow.down.circle.fill"
        case .unavailable: return "info.circle.fill"
        case .error: return "exclamationmark.triangle.fill"
        }
    }

    var color: Color {
        switch self {
        case .current: return .green
        case .available: return .accentColor
        case .error: return .orange
        default: return .secondary
        }
    }
}

@MainActor
final class QuickOrbitUpdateCenter: NSObject, ObservableObject {
    static let shared = QuickOrbitUpdateCenter()
    @Published private(set) var checking = false
    @Published private(set) var status: QuickOrbitUpdateStatus = .idle
    @Published private(set) var availableVersion: String?
    @Published private(set) var releaseNotes = ""
    @Published private(set) var lastChecked: Date?
    @Published private(set) var messageDE = "Noch nicht geprüft"
    @Published private(set) var messageEN = "Not checked yet"
    @Published private(set) var automaticChecks = true
    @Published private(set) var automaticInstallation = false
    @Published private(set) var canCheck = true
    private var releaseURL: URL?
    private var checkTask: Task<Void, Never>?
    private var manualCheck = false
    private var fallbackTimer: Timer?
    private var started = false
    private var observations = Set<AnyCancellable>()
    private let releaseSession: URLSession = {
        let configuration = URLSessionConfiguration.ephemeral
        configuration.timeoutIntervalForRequest = 25
        configuration.timeoutIntervalForResource = 30
        return URLSession(configuration: configuration)
    }()
    #if canImport(Sparkle)
    private var updaterController: SPUStandardUpdaterController?
    #endif

    var signedUpdatesConfigured: Bool {
        #if canImport(Sparkle)
        guard let key = Bundle.main.object(forInfoDictionaryKey: "SUPublicEDKey") as? String,
              Data(base64Encoded: key)?.count == 32,
              let feed = Bundle.main.object(forInfoDictionaryKey: "SUFeedURL") as? String,
              URL(string: feed)?.scheme == "https" else { return false }
        return true
        #else
        return false
        #endif
    }

    func start() {
        guard !started else { return }
        started = true
        lastChecked = UserDefaults.standard.object(forKey: "QuickOrbit.UpdateLastChecked") as? Date
        automaticChecks = UserDefaults.standard.object(forKey: "SUEnableAutomaticChecks") as? Bool ?? true
        #if canImport(Sparkle)
        if signedUpdatesConfigured {
            let controller = SPUStandardUpdaterController(startingUpdater: false, updaterDelegate: self, userDriverDelegate: nil)
            updaterController = controller
            let updater = controller.updater
            updater.publisher(for: \.canCheckForUpdates).receive(on: RunLoop.main)
                .sink { [weak self] value in self?.canCheck = value }.store(in: &observations)
            updater.publisher(for: \.automaticallyChecksForUpdates).receive(on: RunLoop.main)
                .sink { [weak self] value in self?.automaticChecks = value }.store(in: &observations)
            updater.publisher(for: \.automaticallyDownloadsUpdates).receive(on: RunLoop.main)
                .sink { [weak self] value in self?.automaticInstallation = value }.store(in: &observations)
            do {
                try updater.start()
                return
            } catch {
                updaterController = nil
                observations.removeAll()
                canCheck = true
                setMessage("Signierte Updates konnten nicht gestartet werden. GitHub-Releases werden weiterhin geprüft.", "Signed updates could not start. GitHub releases will still be checked.")
            }
        }
        #endif
        // If Sparkle is unavailable, show release information from the same
        // GitHub repository. This path never downloads or executes code.
        fallbackTimer = Timer.scheduledTimer(withTimeInterval: 6 * 60 * 60, repeats: true) { _ in
            Task { @MainActor in QuickOrbitUpdateCenter.shared.checkIfDue() }
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 12) { [weak self] in self?.checkIfDue() }
    }

    func setAutomaticChecks(_ value: Bool) {
        automaticChecks = value
        UserDefaults.standard.set(value, forKey: "SUEnableAutomaticChecks")
        #if canImport(Sparkle)
        updaterController?.updater.automaticallyChecksForUpdates = value
        #endif
        #if canImport(Sparkle)
        if value && updaterController == nil { checkIfDue() }
        #else
        if value { checkIfDue() }
        #endif
    }

    func setAutomaticInstallation(_ value: Bool) {
        #if canImport(Sparkle)
        guard updaterController != nil else { return }
        #else
        return
        #endif
        automaticInstallation = value
        #if canImport(Sparkle)
        updaterController?.updater.automaticallyDownloadsUpdates = value
        #endif
    }

    private func checkIfDue() {
        guard automaticChecks, Date().timeIntervalSince(lastChecked ?? .distantPast) >= 6 * 60 * 60 else { return }
        checkForUpdates(manual: false)
    }

    func checkForUpdates(manual: Bool = true) {
        guard !checking, canCheck else { return }
        manualCheck = manual
        status = .checking
        #if canImport(Sparkle)
        if let updaterController {
            checking = true
            setMessage("Suche nach Updates …", "Checking for updates …")
            updaterController.checkForUpdates(nil)
            return
        }
        #endif
        checking = true
        setMessage("Suche nach Updates …", "Checking for updates …")
        checkTask = Task { [weak self] in
            guard let self else { return }
            defer { checking = false; checkTask = nil }
            do {
                let url = URL(string: "https://api.github.com/repos/\(quickOrbitReleaseRepository)/releases/latest")!
                var request = URLRequest(url: url, cachePolicy: .reloadIgnoringLocalCacheData, timeoutInterval: 25)
                request.setValue("application/vnd.github+json", forHTTPHeaderField: "Accept")
                request.setValue("QuickOrbit/\(Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? "56")", forHTTPHeaderField: "User-Agent")
                let (data, response) = try await releaseSession.data(for: request)
                guard let response = response as? HTTPURLResponse else { throw URLError(.badServerResponse) }
                guard response.statusCode == 200 else {
                    if response.statusCode == 404 {
                        setMessage("Noch kein öffentliches GitHub-Release verfügbar.", "No public GitHub release is available yet.")
                        status = .unavailable
                    } else if response.statusCode == 403 || response.statusCode == 429 {
                        setMessage("GitHub ist vorübergehend ausgelastet. Später erneut versuchen.", "GitHub is temporarily busy. Try again later.")
                        status = .error
                    } else {
                        setMessage("Updates konnten nicht geprüft werden.", "Could not check for updates.")
                        status = .error
                    }
                    if response.statusCode == 404 { recordCheck() }
                    return
                }
                guard data.count <= 1_000_000 else { throw URLError(.dataLengthExceedsMaximum) }
                let release = try JSONDecoder().decode(GitHubRelease.self, from: data)
                let version = release.tag_name.hasPrefix("v") ? String(release.tag_name.dropFirst()) : release.tag_name
                let current = Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? "56"
                guard !release.draft, !release.prerelease,
                      version.range(of: "^[0-9]+(\\.[0-9]+){0,3}$", options: .regularExpression) != nil,
                      release.assets.contains(where: { $0.name == "appcast.xml" }),
                      release.assets.contains(where: { $0.name == "QuickOrbit-v\(version).zip" }),
                      let link = URL(string: release.html_url), link.scheme == "https",
                      link.host?.lowercased() == "github.com",
                      link.path.lowercased() == "/\(quickOrbitReleaseRepository.lowercased())/releases/tag/\(release.tag_name.lowercased())" else { throw URLError(.cannotParseResponse) }
                if version.compare(current, options: .numeric) == .orderedDescending {
                    let firstNotice = availableVersion != version
                    availableVersion = version
                    releaseURL = link
                    releaseNotes = String((release.body ?? "").prefix(1500))
                    setMessage("QuickOrbit \(version) ist verfügbar.", "QuickOrbit \(version) is available.")
                    status = .available
                    if firstNotice && !manualCheck { notifyAvailableUpdate(version: version) }
                } else {
                    availableVersion = nil
                    releaseURL = nil
                    releaseNotes = ""
                    setMessage("QuickOrbit ist auf dem neuesten Stand.", "QuickOrbit is up to date.")
                    status = .current
                }
                recordCheck()
            } catch {
                setMessage("Keine Verbindung zum Update-Server. Bitte erneut versuchen.", "Cannot reach the update server. Please try again.")
                status = .error
            }
        }
    }

    func showUpdate() {
        #if canImport(Sparkle)
        if let updaterController, updaterController.updater.canCheckForUpdates {
            updaterController.checkForUpdates(nil)
            return
        }
        #endif
        if let releaseURL { NSWorkspace.shared.open(releaseURL) }
    }

    fileprivate func setMessage(_ german: String, _ english: String) {
        messageDE = german; messageEN = english
    }

    fileprivate func recordCheck() {
        lastChecked = Date()
        UserDefaults.standard.set(lastChecked, forKey: "QuickOrbit.UpdateLastChecked")
    }

    fileprivate func notifyAvailableUpdate(version: String) {
        let content = UNMutableNotificationContent()
        content.title = "QuickOrbit \(version)"
        content.body = "Ein Update ist verfügbar. Öffne QuickOrbit → Info → Updates."
        content.sound = .default
        UNUserNotificationCenter.current().add(UNNotificationRequest(identifier: "quickorbit-update-\(version)", content: content, trigger: nil))
    }

    private struct GitHubRelease: Decodable {
        let tag_name: String
        let html_url: String
        let body: String?
        let draft: Bool
        let prerelease: Bool
        let assets: [GitHubAsset]
    }

    private struct GitHubAsset: Decodable {
        let name: String
    }
}

#if canImport(Sparkle)
extension QuickOrbitUpdateCenter: SPUUpdaterDelegate {
    func updater(_ updater: SPUUpdater, didFindValidUpdate item: SUAppcastItem) {
        let firstNotice = availableVersion != item.displayVersionString
        availableVersion = item.displayVersionString
        setMessage("QuickOrbit \(item.displayVersionString) ist verfügbar.", "QuickOrbit \(item.displayVersionString) is available.")
        status = .available
        if firstNotice && automaticChecks && !checking { notifyAvailableUpdate(version: item.displayVersionString) }
        recordCheck()
    }

    func updater(_ updater: SPUUpdater, didFinishUpdateCycleFor updateCheck: SPUUpdateCheck, error: Error?) {
        checking = false
        recordCheck()
        if let error {
            let code = (error as NSError).code
            if code == SUError.noUpdateError.rawValue {
                availableVersion = nil
                setMessage("QuickOrbit ist auf dem neuesten Stand.", "QuickOrbit is up to date.")
                status = .current
            } else {
                setMessage("Update-Prüfung nicht abgeschlossen. Bitte erneut versuchen.", "Update check did not complete. Please try again.")
                status = .error
            }
        }
    }
}
#endif

struct QuickOrbitCheckForUpdatesButton: View {
    @ObservedObject private var updates = QuickOrbitUpdateCenter.shared
    @ObservedObject private var store = OrbitStore.shared
    var body: some View {
        Button {
            updates.checkForUpdates()
        } label: {
            HStack(spacing: 7) {
                if updates.checking { ProgressView().controlSize(.small) }
                else { Image(systemName: "arrow.triangle.2.circlepath") }
                Text(updates.checking
                     ? qoText("Suche läuft …", "Checking …", language: store.config.language)
                     : qoText("Nach Updates suchen", "Check for Updates", language: store.config.language))
            }
        }
        .disabled(updates.checking || !updates.canCheck)
    }
}

struct QuickOrbitUpdateCard: View {
    @ObservedObject private var updates = QuickOrbitUpdateCenter.shared
    @ObservedObject private var store = OrbitStore.shared
    var body: some View {
        GlassCard(title: qoText("Updates", "Updates", language: store.config.language), symbol: "arrow.triangle.2.circlepath") {
            VStack(alignment: .leading, spacing: 12) {
                HStack(spacing: 10) {
                    if updates.checking { ProgressView().controlSize(.small) }
                    else { Image(systemName: updates.status.symbol).foregroundStyle(updates.status.color) }
                    Text(qoText(updates.messageDE, updates.messageEN, language: store.config.language))
                        .font(.subheadline.weight(.semibold)).fixedSize(horizontal: false, vertical: true)
                }
                Toggle(qoText("Automatisch nach Updates suchen", "Check for updates automatically", language: store.config.language), isOn: Binding(get: { updates.automaticChecks }, set: { updates.setAutomaticChecks($0) }))
                if updates.signedUpdatesConfigured {
                    Toggle(qoText("Updates automatisch laden und installieren", "Download and install updates automatically", language: store.config.language), isOn: Binding(get: { updates.automaticInstallation }, set: { updates.setAutomaticInstallation($0) }))
                }
                Text(updates.signedUpdatesConfigured
                     ? qoText("Neue Versionen und Änderungen erscheinen direkt hier und im Update-Fenster.", "New versions and changes appear here and in the update window.", language: store.config.language)
                     : qoText("Die automatische Installation ist noch nicht eingerichtet. Verfügbare Versionen können über GitHub geöffnet werden.", "Automatic installation is not set up yet. Available versions can be opened on GitHub.", language: store.config.language))
                    .font(.caption).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true)
                if let date = updates.lastChecked {
                    HStack(spacing: 4) {
                        Text(qoText("Zuletzt geprüft:", "Last checked:", language: store.config.language))
                        Text(date, style: .date)
                        Text(date, style: .time)
                    }.font(.caption2).foregroundStyle(.secondary)
                }
                if !updates.releaseNotes.isEmpty {
                    DisclosureGroup(qoText("Was ist neu?", "What's new?", language: store.config.language)) {
                        Text(updates.releaseNotes).font(.caption).textSelection(.enabled)
                            .frame(maxWidth: .infinity, alignment: .leading)
                    }
                }
                HStack(spacing: 10) {
                    QuickOrbitCheckForUpdatesButton().quickOrbitSolidButton()
                    if updates.availableVersion != nil {
                        Button(updates.signedUpdatesConfigured
                               ? qoText("Update laden", "Download update", language: store.config.language)
                               : qoText("Release öffnen", "Open release", language: store.config.language)) { updates.showUpdate() }
                            .quickOrbitSolidButton()
                    }
                }
            }
        }
    }
}

