@MainActor
final class AppDelegate: NSObject, NSApplicationDelegate {
    func applicationDidFinishLaunching(_ notification: Notification) {
        // Use the same custom icon everywhere macOS asks the running app for its icon:
        // Dock, About, alerts and all QuickOrbit views.
        NSApp.applicationIconImage = quickOrbitAppIcon
        QuickOrbitUpdateCenter.shared.start()

        // Older versions stored Orbit and quick-bar selection modes separately.
        // The current setting is shared; keep the existing Orbit preference on migration.
        let selectionMigrationKey = "QuickOrbit.CommonSelectionModeMigration"
        if UserDefaults.standard.object(forKey: selectionMigrationKey) == nil {
            QuickOrbitMenuDockStore.shared.autoOpen = OrbitStore.shared.config.orbitAutoSelect ?? true
            UserDefaults.standard.set(true, forKey: selectionMigrationKey)
        }

        OrbitController.shared.start()
        StatusBarController.shared.install()
        LoginItemManager.shared.enableByDefaultOnce()
        QuickOrbitBatteryWarningCenter.shared.start()
        QuickOrbitClipboardHistoryCenter.shared.start()

    }

    func applicationWillTerminate(_ notification: Notification) {
        OrbitStore.shared.flushPendingSave()
        QuickOrbitUsageStatsCenter.shared.flushPendingSave()
        OrbitController.shared.stop()
    }

    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool {
        false
    }

    func applicationShouldHandleReopen(
        _ sender: NSApplication,
        hasVisibleWindows flag: Bool
    ) -> Bool {
        AppWindow.show()
        return true
    }

    func applicationDockMenu(_ sender: NSApplication) -> NSMenu? {
        let menu = NSMenu(title: "QuickOrbit")

        let open = NSMenuItem(title: qoText("QuickOrbit öffnen", "Open QuickOrbit", language: OrbitStore.shared.config.language), action: #selector(openFromDock), keyEquivalent: "")
        open.target = self
        menu.addItem(open)

        let quick = NSMenuItem(title: qoText("Quick-Menü anzeigen", "Show quick menu", language: OrbitStore.shared.config.language), action: #selector(showFromDock), keyEquivalent: "")
        quick.target = self
        menu.addItem(quick)

        menu.addItem(.separator())
        let about = NSMenuItem(title: qoText("Über QuickOrbit", "About QuickOrbit", language: OrbitStore.shared.config.language), action: #selector(showAboutFromDock), keyEquivalent: "")
        about.target = self
        menu.addItem(about)

        let website = NSMenuItem(title: qoText("QuickOrbit-Webseite", "QuickOrbit Website", language: OrbitStore.shared.config.language), action: #selector(openWebsiteFromDock), keyEquivalent: "")
        website.target = self
        website.isEnabled = quickOrbitWebsiteURL != nil
        menu.addItem(website)

        return menu
    }

    @objc private func openFromDock() {
        Task { @MainActor in AppWindow.show() }
    }

    @objc private func showFromDock() {
        Task { @MainActor in OrbitController.shared.testMenu() }
    }

    @objc private func showAboutFromDock() {
        Task { @MainActor in QuickOrbitAboutWindowController.shared.show() }
    }

    @objc private func openWebsiteFromDock() {
        guard let url = quickOrbitWebsiteURL else { return }
        NSWorkspace.shared.open(url)
    }
}
